INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('islamu-ngo/Event/prd', 'community', 'islamu-ngo', 'Event', 'islamu-ngo/Event', 'prd', 5, 1, 54, '2026-02-22T16:34:32Z', '2026-03-06T06:55:48.588Z', '829c13908ab1360f7c18c029da2e3149bc778a0816ff5f0ccc9265ea959a01ed', '{"id":"islamu-ngo/Event/prd","name":"prd","description":{"en":"The prd skill generates structured Product Requirements Documents for event management and decentralized platforms, benefiting developers and project managers. It creates clear and actionable documents based on user input and saves them to dev/active/prd.md.","zh":"PRD 生成器是一种基于 Web 的工具，用于创建详细的产品需求文档，支持 ASP.NET Core Web API、Blazor 和 Atproto。","ja":"PRD Generator は Web ベースのツールで、ASP.NET Core Web API、Blazor、Atproto をサポートする詳細な製品要件文書を作成するために使用されます。","ko":"PRD 생성기는 ASP.NET Core Web API, Blazor 및 Atproto를 지원하는詳細한 제품 요구 사항 문서를 생성하는 웹 기반 도구입니다.","es":"El generador de PRD es una herramienta de desarrollo que crea documentos de requisitos de producto claros y acciónables con tecnologías como ASP.NET Core Web API y Blazor","fr":"Le générateur de PRD est un outil de développement qui crée des documents d''exigences de produit clairs et actionnables avec des technologies comme ASP.NET Core Web API et Blazor","de":"Der PRD-Generator ist ein Entwicklungstool, das klare und umsetzbare Produktanforderungsdokumente mit Technologien wie ASP.NET Core Web API und Blazor erstellt","pt":"O PRD é uma plataforma de gerenciamento de eventos em desenvolvimento, que utiliza tecnologias como ASP.NET Core Web API e Blazor para criar uma experiência de usuário personalizada","ru":"PRD - это платформа управления событиями в разработке, использующая технологии ASP.NET Core Web API и Blazor для создания индивидуального пользовательского опыта - ИИ Агенты","ar":"PRD هي منصة إدارة الأحداث قيد التطوير، وتستخدم تقنيات مثل ASP.NET Core Web API و Blazor لإنشاء تجربة مستخدم مخصصة - أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"prd: Event Platform Management System Setup Guide | AI Ag...","zh":"PRD 生成器设置指南 - AIエージェント","ja":"PRD Generator Setup Guide - AIエージェント","ko":"PRD 생성기 설정 가이드 - AI 에이전트","es":"Guía de configuración de PRD: Generador de documentos de ...","fr":"Guide de configuration de PRD : Générateur de documents d...","de":"PRD-Setup-Anleitung: Ersteller von Produktanforderungsdok...","pt":"Guia de Configuração do PRD: Plataforma de Gerenciamento ...","ru":"Настройка PRD: Платформа управления событиями - ИИ Агенты","ar":"إعداد_PRD: منصة إدارة الأحداث - أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to create detailed Product Requirements Documents with prd, the AI agent skill for event management and decentralized platforms. Get started now!","zh":"使用 PRD 生成器创建详细的产品需求文档，支持 ASP.NET Core Web API、Blazor 和 Atproto","ja":"PRD Generator を使用して詳細な製品要件文書を作成します。ASP.NET Core Web API、Blazor、Atproto をサポート","ko":"PRD 생성기를 사용하여詳細한 제품 요구 사항 문서를 생성하십시오. ASP.NET Core Web API, Blazor 및 Atproto 지원","es":"Aprende a configurar el generador de PRD para crear documentos de requisitos de producto claros y acciónables con tecnologías como ASP.NET Core Web API y Blazor","fr":"Découvrez comment configurer le générateur de PRD pour créer des documents d''exigences de produit clairs et actionnables avec des technologies comme ASP.NET ...","de":"Erfahren Sie, wie Sie den PRD-Generator konfigurieren, um klare und umsetzbare Produktanforderungsdokumente mit Technologien wie ASP.NET Core Web API und Bla...","pt":"Desenvolva uma plataforma de gerenciamento de eventos personalizada com o PRD, utilizando tecnologias como ASP.NET Core Web API e Blazor","ru":"Разработайте платформу управления событиями с помощью PRD, используя технологии ASP.NET Core Web API и Blazor - ИИ Агенты","ar":"أنشئ منصة إدارة الأحداث المخصصة مع_PRD، باستخدام تقنيات مثل ASP.NET Core Web API و Blazor - أدوات الذكاء الاصطناعي"},"definition":{"en":"prd is an AI agent skill for generating Product Requirements Documents, specifically designed for event platform and management system development using technologies like ASP.NET Core Web API and Atproto.","zh":"PRD 生成器是一种工具，用于创建详细的产品需求文档","ja":"PRD Generator は詳細な製品要件文書を作成するツールです","ko":"PRD 생성기는詳細한 제품 요구 사항 문서를 생성하는 도구입니다","es":"Un generador de PRD es una herramienta que crea documentos de requisitos de producto estructurados y claros","fr":"Un générateur de PRD est un outil qui crée des documents d''exigences de produit structurés et clairs","de":"Ein PRD-Generator ist ein Tool, das strukturierte und klare Produktanforderungsdokumente erstellt","pt":"O PRD é uma plataforma de gerenciamento de eventos que utiliza tecnologias de código aberto para criar uma experiência de usuário personalizada","ru":"PRD - это платформа управления событиями, использующая открытые технологии для создания индивидуального пользовательского опыта - ИИ Агенты","ar":"PRD هي منصة إدارة الأحداث التي تستخدم تقنيات مفتوحة المصدر لإنشاء تجربة مستخدم مخصصة - أدوات الذكاء الاصطناعي"},"features":{"en":["Generates structured PRD based on user input and clarifying questions","Saves documents to dev/active/prd.md for easy access","Utilizes ASP.NET Core Web API for robust event management","Integrates with Atproto for decentralized platform development","Creates clear and actionable documents for implementation","Supports self-hosting and PWA deployment"],"zh":["支持 ASP.NET Core Web API","集成 Blazor 和 Atproto","生成详细的产品需求文档","支持自定义问答","保存到 dev/active/prd.md"],"ja":["ASP.NET Core Web API をサポート","Blazor と Atproto を統合","詳細な製品要件文書を生成","カスタム質問をサポート","dev/active/prd.md に保存"],"ko":["ASP.NET Core Web API 지원","Blazor 및 Atproto 통합","詳細한 제품 요구 사항 문서 생성","사용자 정의 질문 지원","dev/active/prd.md에 저장"],"es":["Generación de documentos de requisitos de producto con ASP.NET Core Web API","Creación de documentos de requisitos de producto con Blazor","Compatibilidad con tecnologías descentralizadas como Atproto y Fediverse","Generación de documentos de requisitos de producto para aplicaciones web progresivas (PWA)","Soporte para hospedaje autónomo con tecnologías de código abierto como FLOSS y FOSS"],"fr":["Génération de documents d''exigences de produit avec ASP.NET Core Web API","Création de documents d''exigences de produit avec Blazor","Compatibilité avec des technologies décentralisées comme Atproto et Fediverse","Génération de documents d''exigences de produit pour des applications web progresives (PWA)","Prise en charge de l''hébergement autonome avec des technologies de code ouvert comme FLOSS et FOSS"],"de":["Erstellung von Produktanforderungsdokumenten mit ASP.NET Core Web API","Erstellung von Produktanforderungsdokumenten mit Blazor","Unterstützung für dezentrale Technologien wie Atproto und Fediverse","Erstellung von Produktanforderungsdokumenten für progressive Webanwendungen (PWA)","Unterstützung für Selbsthosting mit Open-Source-Technologien wie FLOSS und FOSS"],"pt":["Utiliza ASP.NET Core Web API para criar uma API robusta","Integração com Blazor para criar uma experiência de usuário personalizada","Suporte a tecnologias de código aberto, como Atproto e Fediverse","Permite a criação de documentos de requisitos de produto personalizados","Suporte a aplicativos web progressivos (PWA) e hospedagem auto-suficiente"],"ru":["Использует ASP.NET Core Web API для создания прочного API","Интеграция с Blazor для создания индивидуального пользовательского опыта","Поддержка открытых технологий, таких как Atproto и Fediverse - ИИ Агенты","Позволяет создавать индивидуальные документы требований продукта","Поддержка прогрессивных веб-приложений (PWA) и само-хостинга"],"ar":["تستخدم ASP.NET Core Web API لإنشاء واجهة برمجة تطبيقات قوية","التكامل مع Blazor لإنشاء تجربة مستخدم مخصصة","دعم تقنيات مفتوحة المصدر، مثل Atproto و Fediverse - أدوات الذكاء الاصطناعي","السماح بإنشاء مستندات متطلبات المنتج المخصصة","دعم تطبيقات الويب التقدمية (PWA) والاستضافة الذاتية"]},"keywords":{"en":["how to use prd for event management","prd vs traditional project management tools","prd setup guide for AI agents","what is prd and its benefits","prd alternative for decentralized platforms","prd install and configuration","asp net core web api for prd","atproto integration with prd","prd for self-hosted event management"],"zh":["PRD 生成器","AIエージェント","ASP.NET Core Web API","Blazor","Atproto","产品需求文档","Web 开发工具"],"ja":["PRD Generator","AIエージェント","ASP.NET Core Web API","Blazor","Atproto","製品要件文書","Web開発ツール"],"ko":["PRD 생성기","AI 에이전트","ASP.NET Core Web API","Blazor","Atproto","제품 요구 사항 문서","웹 개발 도구"],"es":["generador de PRD","documentos de requisitos de producto","ASP.NET Core Web API","Blazor","tecnologías descentralizadas","aplicaciones web progresivas","hospedaje autónomo","código abierto","FLOSS","FOSS"],"fr":["générateur de PRD","documents d''exigences de produit","ASP.NET Core Web API","Blazor","technologies décentralisées","applications web progresives","hébergement autonome","code ouvert","FLOSS","FOSS"],"de":["PRD-Generator","Produktanforderungsdokumente","ASP.NET Core Web API","Blazor","dezentrale Technologien","progressive Webanwendungen","Selbsthosting","Open-Source","FLOSS","FOSS"],"pt":["PRD","plataforma de gerenciamento de eventos","ASP.NET Core Web API","Blazor","Atproto","Fediverse","código aberto","PWA","hospedagem auto-suficiente"],"ru":["PRD","платформа управления событиями","ASP.NET Core Web API","Blazor","Atproto","Fediverse","открытые технологии","PWA","само-хостинг","ИИ Агенты"],"ar":["PRD","منصة إدارة الأحداث","ASP.NET Core Web API","Blazor","Atproto","Fediverse","مفتوح المصدر","PWA","الاستضافة الذاتية","أدوات الذكاء الاصطناعي"]}},"owner":"islamu-ngo","repo":"Event","repoPath":"islamu-ngo/Event","stars":5,"forks":1,"updatedAt":"2026-02-22T16:34:32Z","topics":["asp-net-core-web-api","atproto","blazor","decentralized","event-management","event-management-app","event-management-platform","event-management-system","event-platform","events","fediverse","floss","foss","open-source","pwa","self-host","w3c","webapp"],"category":"community","skillMd":{"name":"prd","description":"Generate a Product Requirements Document (PRD) for a new feature. Use when planning a feature, starting a new project, or when asked to create a PRD. Triggers on: create a prd, write prd for, plan this feature, requirements for, spec out.","bodyPreview":"# PRD Generator\n\nCreate detailed Product Requirements Documents that are clear, actionable, and suitable for implementation.\n\n---\n\n## The Job\n\n1. Receive a feature description from the user\n2. Ask 3-5 essential clarifying questions (with lettered options)\n3. Generate a structured PRD based on answers\n4. Save to `dev/active/prd.md`\n\n**Important:** Do NOT start implementing. Just create the PRD.\n\n---\n\n## Step 1: Clarifying Questions\n\nAsk only critical questions where the initial prompt is ambiguou","body":"# PRD Generator\n\nCreate detailed Product Requirements Documents that are clear, actionable, and suitable for implementation.\n\n---\n\n## The Job\n\n1. Receive a feature description from the user\n2. Ask 3-5 essential clarifying questions (with lettered options)\n3. Generate a structured PRD based on answers\n4. Save to `dev/active/prd.md`\n\n**Important:** Do NOT start implementing. Just create the PRD.\n\n---\n\n## Step 1: Clarifying Questions\n\nAsk only critical questions where the initial prompt is ambiguous. Focus on:\n\n- **Problem/Goal:** What problem does this solve?\n- **Core Functionality:** What are the key actions?\n- **Scope/Boundaries:** What should it NOT do?\n- **Success Criteria:** How do we know it''s done?\n\n### Format Questions Like This:\n\n```\n1. What is the primary goal of this feature?\n   A. Improve user onboarding experience\n   B. Increase user retention\n   C. Reduce support burden\n   D. Other: [please specify]\n\n2. Who is the target user?\n   A. New users only\n   B. Existing users only\n   C. All users\n   D. Admin users only\n\n3. What is the scope?\n   A. Minimal viable version\n   B. Full-featured implementation\n   C. Just the backend/API\n   D. Just the UI\n```\n\nThis lets users respond with \"1A, 2C, 3B\" for quick iteration.\n\n---\n\n## Step 2: PRD Structure\n\nGenerate the PRD with these sections:\n\n### 1. Introduction/Overview\n\nBrief description of the feature and the problem it solves.\n\n### 2. Goals\n\nSpecific, measurable objectives (bullet list).\n\n### 3. User Stories\n\nEach story needs:\n\n- **Title:** Short descriptive name\n- **Description:** \"As a [user], I want [feature] so that [benefit]\"\n- **Acceptance Criteria:** Verifiable checklist of what \"done\" means\n\nEach story should be small enough to implement in one focused session.\n\n**Format:**\n\n```markdown\n### US-001: [Title]\n\n**Description:** As a [user], I want [feature] so that [benefit].\n\n**Acceptance Criteria:**\n\n- [ ] Specific verifiable criterion\n- [ ] Another criterion\n- [ ] Typecheck/lint passes\n- [ ] **[UI stories only]** Verify in browser using dev-browser skill\n```\n\n**Important:**\n\n- Acceptance criteria must be verifiable, not vague. \"Works correctly\" is bad. \"Button shows confirmation dialog before deleting\" is good.\n- **For any story with UI changes:** Always include \"Verify in browser using dev-browser skill\" as acceptance criteria. This ensures visual verification of frontend work.\n\n### 4. Functional Requirements\n\nNumbered list of specific functionalities:\n\n- \"FR-1: The system must allow users to...\"\n- \"FR-2: When a user clicks X, the system must...\"\n\nBe explicit and unambiguous.\n\n### 5. Non-Goals (Out of Scope)\n\nWhat this feature will NOT include. Critical for managing scope.\n\n### 6. Design Considerations (Optional)\n\n- UI/UX requirements\n- Link to mockups if available\n- Relevant existing components to reuse\n\n### 7. Technical Considerations (Optional)\n\n- Known constraints or dependencies\n- Integration points with existing systems\n- Performance requirements\n\n### 8. Success Metrics\n\nHow will success be measured?\n\n- \"Reduce time to complete X by 50%\"\n- \"Increase conversion rate by 10%\"\n\n### 9. Open Questions\n\nRemaining questions or areas needing clarification.\n\n---\n\n## Writing for Junior Developers\n\nThe PRD reader may be a junior developer or AI agent. Therefore:\n\n- Be explicit and unambiguous\n- Avoid jargon or explain it\n- Provide enough detail to understand purpose and core logic\n- Number requirements for easy reference\n- Use concrete examples where helpful\n\n---\n\n## Archiving Previous PRDs\n\n**Before writing a new `dev/active/prd.md`, check if there is an existing one from a different feature:**\n\n1. Read the current `dev/active/prd.md` if it exists\n2. Check if it''s for a different feature than what you''re about to create\n3. If different:\n   - Extract feature name from PRD title/intro\n   - Check if archive folder already exists: look for `dev/archive/*-feature-name/`\n   - If found, use existing folder; if not, create `dev/archive/YYYY-MM-DD-feature-name/`\n   - Copy current `dev/active/prd.md` to archive folder\n   - Write the new PRD to `dev/active/prd.md`\n\n**Shared archive folders:** Multiple runs of same feature (across dates) share one archive folder. Prevents duplicate archives when PRD skill and task skill run on different days.\n\n---\n\n## Output\n\n- **Format:** Markdown (`.md`)\n- **Location:** `dev/active/`\n- **Filename:** `dev/active/prd.md`\n\n---\n\n## Example PRD\n\n```markdown\n# PRD: Task Priority System\n\n## Introduction\n\nAdd priority levels to tasks so users can focus on what matters most. Tasks can be marked as high, medium, or low priority, with visual indicators and filtering to help users manage their workload effectively.\n\n## Goals\n\n- Allow assigning priority (high/medium/low) to any task\n- Provide clear visual differentiation between priority levels\n- Enable filtering and sorting by priority\n- Default new tasks to medium priority\n\n## User Stories\n\n### US-001: Add priority field to database\n\n**Description:** As a developer, I need to store task priority so it persists across sessions.\n\n**Acceptance Criteria:**\n\n- [ ] Add priority column to tasks table: ''high'' | ''medium'' | ''low'' (default ''medium'')\n- [ ] Generate and run migration successfully\n- [ ] Typecheck passes\n\n### US-002: Display priority indicator on task cards\n\n**Description:** As a user, I want to see task priority at a glance so I know what needs attention first.\n\n**Acceptance Criteria:**\n\n- [ ] Each task card shows colored priority badge (red=high, yellow=medium, gray=low)\n- [ ] Priority visible without hovering or clicking\n\n### US-003: Add priority selector to task edit\n\n**Description:** As a user, I want to change a task''s priority when editing it.\n\n**Acceptance Criteria:**\n\n- [ ] Priority dropdown in task edit modal\n- [ ] Shows current priority as selected\n- [ ] Saves immediately on selection change\n\n### US-004: Filter tasks by priority\n\n**Description:** As a user, I want to filter the task list to see only high-priority items when I''m focused.\n\n**Acceptance Criteria:**\n\n- [ ] Filter dropdown with options: All | High | Medium | Low\n- [ ] Filter persists in URL params\n- [ ] Empty state message when no tasks match filter\n\n## Functional Requirements\n\n- FR-1: Add `priority` field to tasks table (''high'' | ''medium'' | ''low'', default ''medium'')\n- FR-2: Display colored priority badge on each task card\n- FR-3: Include priority selector in task edit modal\n- FR-4: Add priority filter dropdown to task list header\n- FR-5: Sort by priority within each status column (high to medium to low)\n\n## Non-Goals\n\n- No priority-based notifications or reminders\n- No automatic priority assignment based on due date\n- No priority inheritance for subtasks\n\n## Technical Considerations\n\n- Reuse existing badge component with color variants\n- Filter state managed via URL search params\n- Priority stored in database, not computed\n\n## Success Metrics\n\n- Users can change priority in under 2 clicks\n- High-priority tasks immediately visible at top of lists\n- No regression in task list performance\n\n## Open Questions\n\n- Should priority affect task ordering within a column?\n- Should we add keyboard shortcuts for priority changes?\n```\n\n---\n\n## Checklist\n\nBefore saving the PRD:\n\n- [ ] **Archived previous PRD** (if `dev/active/prd.md` exists for a different feature, archive it first)\n- [ ] Asked clarifying questions with lettered options\n- [ ] Incorporated user''s answers\n- [ ] User stories are small and specific\n- [ ] Functional requirements are numbered and unambiguous\n- [ ] Non-goals section defines clear boundaries\n- [ ] Saved to `dev/active/prd.md`"},"lastSynced":"2026-03-06T06:55:48.588Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing structured Product Requirements Document generation for event management and decentralized platforms.","zh":"非常适合需要为事件管理和去中心化平台生成结构化产品需求文档的开发代理。","ja":"イベント管理および分散型プラットフォーム向けに構造化された製品要件文書を生成する必要がある開発エージェントに最適です。","ko":"이벤트 관리 및 분산 플랫폼을 위한 구조화된 제품 요구 사항 문서 생성이 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan generación de documentos de requisitos de producto estructurados para gestión de eventos y plataformas descentralizadas.","fr":"Parfait pour les agents de développement ayant besoin de génération de documents de spécifications de produit structurés pour la gestion d''événements et les plateformes décentralisées.","de":"Perfekt für Entwicklungssagenten, die eine strukturierte Generierung von Produktanforderungsdokumenten für Ereignisverwaltung und dezentrale Plattformen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que precisam de geração de Documentos de Requisitos de Produto estruturados para gerenciamento de eventos e plataformas descentralizadas.","ru":"Идеально подходит для агентов разработки, которым необходима структурированная генерация документов требований к продукту для управления событиями и децентрализованных платформ.","ar":"مثالي لعميل التطوير الذين يحتاجون إلى توليد مستندات متطلبات المنتج المنظمة لإدارة الأحداث والمنصات الموزعة."},"recommendation":{"en":"Empowers agents to create clear and actionable PRDs based on user input, utilizing markdown file formats like .md, and saving them to specific directories such as dev/active/prd.md, streamlining project management and implementation.","zh":"赋予代理创建明确且可执行的PRD的能力，基于用户输入，利用类似.md的markdown文件格式，并将其保存到特定的目录中，例如dev/active/prd.md，从而简化项目管理和实施，利用React、Python、CLI、API等技术。","ja":"ユーザー入力に基づいて明確で実行可能なPRDを作成するエージェントの能力を付与します。.mdなどのマークダウンファイル形式を利用し、dev/active/prd.mdなどの特定のディレクトリに保存します。プロジェクト管理と実装を簡素化します。React、Python、CLI、APIなどの技術を利用します。","ko":"사용자 입력에 기반하여 명확하고 실행 가능한 PRD를 생성할 수 있는 에이전트의 능력을 부여합니다. .md와 같은 마크다운 파일 형식을 사용하여 dev/active/prd.md와 같은 특정 디렉토리에 저장하여 프로젝트 관리와 구현을 간소화합니다. React, Python, CLI, API 등의 기술을 활용합니다.","es":"Habilita a los agentes a crear PRDs claros y ejecutables basados en la entrada del usuario, utilizando formatos de archivo markdown como .md, y guardándolos en directorios específicos como dev/active/prd.md, simplificando la gestión de proyectos y la implementación.","fr":"Permet aux agents de créer des PRDs clairs et exécutables basés sur les entrées de l''utilisateur, en utilisant des formats de fichiers markdown comme .md, et en les enregistrant dans des répertoires spécifiques tels que dev/active/prd.md, simplifiant la gestion de projet et la mise en œuvre.","de":"Ermöglicht es den Agenten, klare und ausführbare PRDs basierend auf der Benutzereingabe zu erstellen, indem sie Markdown-Dateiformate wie .md verwenden und sie in spezifische Verzeichnisse wie dev/active/prd.md speichern, wodurch die Projektverwaltung und -implementierung gestreamt wird.","pt":"Habilita os agentes a criar PRDs claros e ações baseados na entrada do usuário, utilizando formatos de arquivo markdown como .md, e salvando-os em diretórios específicos, como dev/active/prd.md, racionalizando o gerenciamento e implementação do projeto.","ru":"Наделяет агентов возможностью создавать четкие и действенные PRD на основе ввода пользователя, используя форматы файлов markdown, такие как .md, и сохраняя их в определенные директории, такие как dev/active/prd.md, оптимизируя управление и реализацию проекта.","ar":"يمنح الوكلاء القدرة على إنشاء وثائق متطلبات المنتج واضحة وقابلة للتنفيذ بناءً على إدخال المستخدم، باستخدام تنسيقات الملفات مثل .md، وحفظها في دلائل محددة مثل dev/active/prd.md، مما يُبسّط إدارة المشروع وتنفيذه."},"useCases":{"en":["Generating detailed PRDs for new feature development","Creating structured documents for decentralized platform projects","Automating PRD creation for event management applications"],"zh":["为新功能开发生成详细的PRD","为去中心化平台项目创建结构化文档","为事件管理应用程序自动化PRD创建"],"ja":["新機能開発の詳細なPRDを生成する","分散型プラットフォームプロジェクトの構造化ドキュメントを作成する","イベント管理アプリケーションのPRD作成を自動化する"],"ko":["새로운 기능 개발을 위한詳細한 PRD 생성","분산 플랫폼 프로젝트를 위한 구조화된 문서 생성","이벤트 관리 애플리케이션을 위한 PRD 생성 자동화"],"es":["Generación de PRDs detallados para el desarrollo de nuevas características","Creación de documentos estructurados para proyectos de plataformas descentralizadas","Automatización de la creación de PRDs para aplicaciones de gestión de eventos"],"fr":["Génération de PRDs détaillés pour le développement de nouvelles fonctionnalités","Création de documents structurés pour les projets de plateformes décentralisées","Automatisation de la création de PRDs pour les applications de gestion d''événements"],"de":["Erstellung detaillierter PRDs für die Entwicklung neuer Funktionen","Erstellung strukturierter Dokumente für dezentrale Plattformprojekte","Automatisierung der PRD-Erstellung für Ereignisverwaltungsanwendungen"],"pt":["Gerar PRDs detalhados para desenvolvimento de novos recursos","Criar documentos estruturados para projetos de plataformas descentralizadas","Automatizar a criação de PRDs para aplicações de gerenciamento de eventos"],"ru":["Генерировать подробные PRD для разработки новых функций","Создавать структурированные документы для проектов децентрализованных платформ","Автоматизировать создание PRD для приложений управления событиями"],"ar":["توليد وثائق متطلبات المنتج مفصلة لتنمية ميزات جديدة","إنشاء مستندات منظمّة لمشاريع المنصّات الموزعة","أتمتة إنشاء وثائق متطلبات المنتج لتطبيقات إدارة الأحداث"]},"limitations":{"en":["Requires user input for feature description","Limited to generating PRDs, does not implement features"],"zh":["需要用户输入以描述功能","仅限于生成PRD，不实现功能"],"ja":["機能の説明のためにユーザー入力が必要","PRDの生成のみに限定され、機能を実装しません"],"ko":["기능을 설명하기 위해 사용자 입력이 필요","PRD 생성만으로 제한되며, 기능을 구현하지 않음"],"es":["Requiere la entrada del usuario para la descripción de características","Limitado a la generación de PRDs, no implementa características"],"fr":["Nécessite l''entrée de l''utilisateur pour la description des fonctionnalités","Limité à la génération de PRDs, n''implémente pas les fonctionnalités"],"de":["Benutzereingabe für die Funktionsbeschreibung erforderlich","Begrenzt auf die Generierung von PRDs, implementiert keine Funktionen"],"pt":["Requer entrada do usuário para descrição de recursos","Limitado a gerar PRDs, não implementa recursos"],"ru":["Требует ввода пользователя для описания функций","Ограничен генерацией PRD, не реализует функции"],"ar":["يتطلب إدخال المستخدم لوصف الميزات","محدود بتوليد وثائق متطلبات المنتج، ولا يُ実ّمن الميزات"]},"version":4},"contentHash":"829c13908ab1360f7c18c029da2e3149bc778a0816ff5f0ccc9265ea959a01ed","qualityScore":54}');
