INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('islamu-ngo/Event/prd', 'prd', 'islamu-ngo', 'Event', 'community', 'prd islamu-ngo Event community asp-net-core-web-api atproto blazor decentralized event-management event-management-app event-management-platform event-management-system event-platform events fediverse floss foss open-source pwa self-host w3c webapp The prd skill generates structured Product Requirements Documents for event management and decentralized platforms, benefiting developers and project managers. It creates clear and actionable documents based on user input and saves them to dev/active/prd.md. PRD 生成器是一种基于 Web 的工具，用于创建详细的产品需求文档，支持 ASP.NET Core Web API、Blazor 和 Atproto。 PRD Generator は Web ベースのツールで、ASP.NET Core Web API、Blazor、Atproto をサポートする詳細な製品要件文書を作成するために使用されます。 PRD 생성기는 ASP.NET Core Web API, Blazor 및 Atproto를 지원하는詳細한 제품 요구 사항 문서를 생성하는 웹 기반 도구입니다. El generador de PRD es una herramienta de desarrollo que crea documentos de requisitos de producto claros y acciónables con tecnologías como ASP.NET Core Web API y Blazor Le générateur de PRD est un outil de développement qui crée des documents d''exigences de produit clairs et actionnables avec des technologies comme ASP.NET Core Web API et Blazor Der PRD-Generator ist ein Entwicklungstool, das klare und umsetzbare Produktanforderungsdokumente mit Technologien wie ASP.NET Core Web API und Blazor erstellt O PRD é uma plataforma de gerenciamento de eventos em desenvolvimento, que utiliza tecnologias como ASP.NET Core Web API e Blazor para criar uma experiência de usuário personalizada PRD - это платформа управления событиями в разработке, использующая технологии ASP.NET Core Web API и Blazor для создания индивидуального пользовательского опыта - ИИ Агенты PRD هي منصة إدارة الأحداث قيد التطوير، وتستخدم تقنيات مثل ASP.NET Core Web API و Blazor لإنشاء تجربة مستخدم مخصصة - أدوات الذكاء الاصطناعي how to use prd for event management prd vs traditional project management tools prd setup guide for AI agents what is prd and its benefits prd alternative for decentralized platforms prd install and configuration asp net core web api for prd atproto integration with prd prd for self-hosted event management PRD 生成器 AIエージェント ASP.NET Core Web API Blazor Atproto 产品需求文档 Web 开发工具 Generates structured PRD based on user input and clarifying questions Saves documents to dev/active/prd.md for easy access Utilizes ASP.NET Core Web API for robust event management Integrates with Atproto for decentralized platform development Creates clear and actionable documents for implementation Supports self-hosting and PWA deployment prd is an AI agent skill for generating Product Requirements Documents, specifically designed for event platform and management system development using technologies like ASP.NET Core Web API and Atproto.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rckim77/Daydream/github', 'community', 'rckim77', 'Daydream', 'rckim77/Daydream', 'github', 4, 0, 54, '2026-02-27T03:27:57Z', '2026-03-06T06:58:27.615Z', '51b28818a6f0359287d5c8244a6fdc59a4ac5504596deb193b28b81832221c86', '{"id":"rckim77/Daydream/github","name":"github","description":{"en":"The Github skill enables developers to interact with Github using the gh CLI, automating tasks such as checking CI status and viewing workflow runs. It benefits developers working with Git repositories.","zh":"使用gh CLI与GitHub交互，包括检查CI状态和查看运行日志等功能","ja":"gh CLIを使用してGitHubと交互し、CIステータスの確認や実行ログの表示などを行う","ko":"gh CLI를 사용하여 GitHub와 상호작용하며 CI 상태 확인, 실행 로그 보기 등","es":"El skill de GitHub permite a los desarrolladores interactuar con sus repositorios y flujos de trabajo utilizando el CLI de GitHub","fr":"Le skill de GitHub permet aux développeurs d''interagir avec leurs référentiels et flux de travail en utilisant le CLI de GitHub","de":"Das GitHub-Skill ermöglicht es Entwicklern, mit ihren Repositories und Workflows über den GitHub-CLI zu interagieren","pt":"O GitHub é uma plataforma de desenvolvimento colaborativo que oferece ferramentas para gerenciar PRs e fluxos de trabalho. Aprenda a usá-las com eficiência.","ru":"GitHub - это платформа для совместного развития, которая предоставляет инструменты для управления PR и рабочими процессами. Узнайте, как использовать их эффективно с помощью ИИ Агентов.","ar":"GitHub هو منصة تطوير تعاونية تقدم أدوات لإدارة الطلبات السحابية وعمليات العمل. تعلم كيفية استخدامها بفعالية."},"seo":{"title":{"en":"Github Skill: Master Git Workflow Automation | AI Agent","zh":"GitHub AI工具：使用gh CLI进行交互","ja":"GitHub AIエージェント：gh CLIを使用した操作","ko":"GitHub AI 에이전트: gh CLI를 사용한 상호작용","es":"Guía de configuración de GitHub para desarrolladores","fr":"Guide de mise en route de GitHub pour les développeurs","de":"GitHub-Setup-Leitfaden für Entwickler","pt":"Guia de Configuração do GitHub: Ferramentas de Desenvolvi...","ru":"Настройка GitHub: Лучшие Практики для Разработчиков ИИ Аг...","ar":"دليل إعداد GitHub: أدوات تطوير متقدمة"},"description":{"en":"Unlock efficient Git workflow management with Github AI Agent Skill - learn how to automate tasks and boost productivity now!","zh":"了解如何使用gh CLI与GitHub交互，包括检查CI状态、列出最近的工作流程运行和查看运行日志","ja":"gh CLIを使用してGitHubと交互する方法について説明します。CIステータスの確認、最近のワークフロー実行のリスト表示、実行ログの表示など","ko":"gh CLI를 사용하여 GitHub와 상호작용하는 방법을 알아보세요. CI 상태 확인, 최근 워크플로우 실행 목록 및 실행 로그 보기 등","es":"Aprende a utilizar el CLI de GitHub para interactuar con tus repositorios y flujos de trabajo","fr":"Découvrez comment utiliser le CLI de GitHub pour interagir avec vos référentiels et flux de travail","de":"Erfahren Sie, wie Sie den GitHub-CLI verwenden, um mit Ihren Repositories und Workflows zu interagieren","pt":"Aprenda a usar o GitHub com eficiência, incluindo PRs e fluxos de trabalho, para melhorar seu fluxo de desenvolvimento","ru":"Узнайте, как использовать GitHub эффективно, включая PR и рабочие процессы, для улучшения вашего процесса разработки с помощью ИИ Агентов","ar":"تعرف على كيفية استخدام GitHub بفعالية، بما في ذلك الطلبات السحابية وعمليات العمل، لتحسين تدفق التطوير الخاص بك"},"definition":{"en":"Github is a skill that utilizes the gh CLI to automate Git workflow tasks, including pull requests and workflow runs.","zh":"GitHub AI工具是一种使用gh CLI与GitHub交互的工具","ja":"GitHub AIエージェントは、gh CLIを使用してGitHubと交互するツールです","ko":"GitHub AI 에이전트는 gh CLI를 사용하여 GitHub와 상호작용하는 도구입니다","es":"¿Qué es el skill de GitHub? Un conjunto de comandos para interactuar con GitHub mediante el CLI","fr":"Qu''est-ce que le skill de GitHub? Un ensemble de commandes pour interagir avec GitHub via le CLI","de":"Was ist das GitHub-Skill? Eine Sammlung von Befehlen, um über den CLI mit GitHub zu interagieren","pt":"O GitHub é uma plataforma de desenvolvimento que oferece ferramentas para gerenciar projetos e colaborar com outros desenvolvedores","ru":"GitHub - это платформа для разработки, которая предоставляет инструменты для управления проектами и сотрудничества с другими разработчиками ИИ Агентов","ar":"GitHub هو منصة تطوير تقدم أدوات لإدارة المشاريع والتعاون مع مبرمجين آخرين"},"features":{"en":["Checks CI status on pull requests using `gh pr checks` command","Lists recent workflow runs with `gh run list` command","Views specific runs and failed steps using `gh run view` command","Supports log viewing for failed steps with `--log-failed` option","Automates tasks using the `gh` CLI with repository specification via `--repo owner/repo`"],"zh":["使用gh CLI检查CI状态","列出最近的工作流程运行","查看运行日志","使用--repo选项指定仓库","使用--log-failed选项查看失败步骤的日志"],"ja":["gh CLIを使用してCIステータスを確認","最近のワークフロー実行をリスト表示","実行ログを表示","--repoオプションを使用してリポジトリを指定","実行ログの表示"],"ko":["gh CLI를 사용하여 CI 상태 확인","최근 워크플로우 실행 목록 보기","실행 로그 보기","--repo 옵션을 사용하여 저장소 지정","실행 로그의 표시"],"es":["Utiliza el comando `gh pr checks` para verificar el estado de los PR","Lista las ejecuciones recientes de flujos de trabajo con `gh run list`","Visualiza una ejecución y los pasos que fallaron con `gh run view`","Verifica los logs de los pasos fallidos con `gh run view --log-failed`","Especifica el repositorio con `--repo owner/repo` cuando no estés en un directorio Git"],"fr":["Utilisez la commande `gh pr checks` pour vérifier l''état des PR","Listez les exécutions récentes de flux de travail avec `gh run list`","Visualisez une exécution et les étapes qui ont échoué avec `gh run view`","Vérifiez les logs des étapes échouées avec `gh run view --log-failed`","Spécifiez le référentiel avec `--repo owner/repo` lorsque vous n''êtes pas dans un répertoire Git"],"de":["Verwenden Sie den Befehl `gh pr checks`, um den Status von PR zu überprüfen","Listen Sie die kürzlichen Ausführungen von Workflows mit `gh run list` auf","Visualisieren Sie eine Ausführung und die fehlgeschlagenen Schritte mit `gh run view`","Überprüfen Sie die Logs der fehlgeschlagenen Schritte mit `gh run view --log-failed`","Geben Sie das Repository mit `--repo owner/repo` an, wenn Sie nicht in einem Git-Verzeichnis sind"],"pt":["Use o CLI do GitHub para interagir com a plataforma","Verifique o status do CI em PRs","Liste execuções recentes de fluxos de trabalho","Visualize detalhes de execuções de fluxos de trabalho","Veja logs de etapas com falha"],"ru":["Используйте CLI GitHub для взаимодействия с платформой","Проверьте статус CI в PR","Перечислите недавние запуски рабочих процессов","Просмотрите подробности запусков рабочих процессов","Просмотрите журналы неудавшихся шагов"],"ar":["استخدم واجهة سطر الأوامر في GitHub للتفاعل مع المنصة","تحقق من حالة CI في الطلبات السحابية","قائمة تشغيل عمليات العمل الأخيرة","عرض تفاصيل تشغيل عمليات العمل","عرض سجلات الخطوات الفاشلة"]},"keywords":{"en":["how to use github cli","github workflow automation","github vs gitlab","github install guide","github setup for developers","what is github cli","github alternative tools","github automation scripts"],"zh":["GitHub AI工具","gh CLI","CI状态检查","工作流程运行","运行日志","GitHub交互","仓库管理"],"ja":["GitHub AIエージェント","gh CLI","CIステータスの確認","ワークフロー実行","実行ログ","GitHubと交互","リポジトリ管理"],"ko":["GitHub AI 에이전트","gh CLI","CI 상태 확인","워크플로우 실행","실행 로그","GitHub와 상호작용","저장소 관리"],"es":["github cli","github skill","desarrollo de software","integración continua","flujos de trabajo","gestión de repositorios","herramientas de desarrollo","github para desarrolladores","_guias de configuración de github"],"fr":["github cli","github skill","développement de logiciels","intégration continue","flux de travail","gestion de référentiels","outils de développement","github pour les développeurs","guides de configuration de github"],"de":["github cli","github skill","softwareentwicklung","kontinuierliche integration","workflows","repository management","entwicklungstools","github für entwickler","github setup anleitungen"],"pt":["github","desenvolvimento colaborativo","ferramentas de desenvolvimento","PRs","fluxos de trabalho","CLI","status do CI","execuções de fluxos de trabalho"],"ru":["github","совместное развитие","инструменты разработки","PR","рабочие процессы","CLI","статус CI","запуски рабочих процессов","ИИ Агенты"],"ar":["github","تطوير تعاوني","أدوات تطوير","طلبات سحابية","عمليات عمل","واجهة سطر الأوامر","حالة CI","تشغيل عمليات العمل","أدوات التطوير"]}},"owner":"rckim77","repo":"Daydream","repoPath":"rckim77/Daydream","stars":4,"forks":0,"updatedAt":"2026-02-27T03:27:57Z","topics":["app","explore","ios","travel"],"category":"community","skillMd":{"name":"github","description":"Interact with GitHub using the `gh` CLI. Use `gh issue`, `gh pr`, `gh run`, and `gh api` for issues, PRs, CI runs, and advanced queries.","bodyPreview":"# GitHub Skill\n\nUse the `gh` CLI to interact with GitHub. Always specify `--repo owner/repo` when not in a git directory, or use URLs directly.\n\n## Pull Requests\n\nCheck CI status on a PR:\n```bash\ngh pr checks 55 --repo owner/repo\n```\n\nList recent workflow runs:\n```bash\ngh run list --repo owner/repo --limit 10\n```\n\nView a run and see which steps failed:\n```bash\ngh run view <run-id> --repo owner/repo\n```\n\nView logs for failed steps only:\n```bash\ngh run view <run-id> --repo owner/repo --log-failed","body":"# GitHub Skill\n\nUse the `gh` CLI to interact with GitHub. Always specify `--repo owner/repo` when not in a git directory, or use URLs directly.\n\n## Pull Requests\n\nCheck CI status on a PR:\n```bash\ngh pr checks 55 --repo owner/repo\n```\n\nList recent workflow runs:\n```bash\ngh run list --repo owner/repo --limit 10\n```\n\nView a run and see which steps failed:\n```bash\ngh run view <run-id> --repo owner/repo\n```\n\nView logs for failed steps only:\n```bash\ngh run view <run-id> --repo owner/repo --log-failed\n```\n\n## API for Advanced Queries\n\nThe `gh api` command is useful for accessing data not available through other subcommands.\n\nGet PR with specific fields:\n```bash\ngh api repos/owner/repo/pulls/55 --jq ''.title, .state, .user.login''\n```\n\n## JSON Output\n\nMost commands support `--json` for structured output.  You can use `--jq` to filter:\n\n```bash\ngh issue list --repo owner/repo --json number,title --jq ''.[] | \"\\(.number): \\(.title)\"''\n```\n"},"lastSynced":"2026-03-06T06:58:27.615Z","agentAnalysis":{"suitability":{"en":"Ideal for DevOps Agents requiring automated Github interactions and CI/CD pipeline management.","zh":"适用于需要自动化Github交互和CI/CD流水线管理的DevOps代理。","ja":"DevOpsエージェントがGithubの相互作用とCI/CDパイプライン管理を自動化する必要がある場合に最適です。","ko":"Github 상호 작용 및 CI/CD 파이프라인 관리를 자동화해야 하는 DevOps 에이전트에 적합합니다.","es":"Ideal para Agentes de DevOps que requieren interacciones automatizadas con Github y administración de pipelines CI/CD.","fr":"Idéal pour les agents DevOps nécessitant des interactions automatisées avec Github et une gestion de pipeline CI/CD.","de":"Ideal für DevOps-Agents, die automatisierte Interaktionen mit Github und CI/CD-Pipeline-Verwaltung erfordern.","pt":"Ideal para Agentes DevOps que exigem interações automatizadas com o Github e gestão de pipeline CI/CD.","ru":"Идеально для агентов DevOps, требующих автоматизированного взаимодействия с Github и управления конвейером CI/CD.","ar":"مثالي لعميل DevOps الذي يتطلب تفاعلات أوتوماتيكية مع Github وإدارة خط أنابيب CI/CD."},"recommendation":{"en":"Empowers agents to automate tasks such as checking CI status, viewing workflow runs, and debugging failed steps using the gh CLI, facilitating seamless interaction with Github repositories and workflows via URLs or the --repo owner/repo syntax.","zh":"赋予代理人使用gh CLI自动执行任务的能力，例如检查CI状态、查看工作流运行情况以及调试失败的步骤，从而实现与Github仓库和工作流的无缝交互，通过URL或--repo所有者/仓库语法。","ja":"エージェントがgh CLIを使用してタスクを自動化できるようにすることで、CI状態の確認、ワークフロー実行の表示、失敗したステップのデバッグなどが行え、Githubリポジトリやワークフローとのシームレスなやり取りがURLまたは--repo所有者/リポジトリ構文を使用して可能になります。","ko":"에이전트가 gh CLI를 사용하여 작업을 자동화할 수 있도록 하여 CI 상태 확인, 워크플로 실행 보기, 실패한 단계 디버깅 등이 가능하며, URL 또는 --repo 소유자/저장소 구문을 사용하여 Github 저장소 및 워크플로와의 무결점 상호 작용을 가능하게 합니다.","es":"Habilita a los agentes a automatizar tareas como comprobar el estado de CI, ver ejecuciones de flujo de trabajo y depurar pasos fallidos usando el CLI de gh, facilitando una interacción fluida con los repositorios y flujos de trabajo de Github a través de URLs o la sintaxis --repo dueño/repo.","fr":"Permet aux agents d''automatiser des tâches telles que la vérification de l''état de CI, l''affichage des exécutions de workflow et le débogage des étapes ayant échoué en utilisant le CLI gh, facilitant une interaction fluide avec les référentiels et les flux de travail Github via des URLs ou la syntaxe --repo propriétaire/repo.","de":"Ermöglicht es den Agenten, Aufgaben wie das Überprüfen des CI-Status, das Anzeigen von Workflow-Ausführungen und das Debuggen fehlgeschlagener Schritte mithilfe des gh-CLI zu automatisieren, wodurch eine nahtlose Interaktion mit Github-Repositorys und Workflows über URLs oder die --repo-Besitzer/Repository-Syntax erleichtert wird.","pt":"Habilita os agentes a automatizar tarefas como verificar o status do CI, visualizar execuções de fluxo de trabalho e depurar etapas com falha usando o gh CLI, facilitando a interação transparente com repositórios e fluxos de trabalho do Github via URLs ou a sintaxe --repo dono/repo.","ru":"Позволяет агентам автоматизировать задачи, такие как проверка статуса CI, просмотр выполнения рабочих процессов и отладка неудачных шагов с помощью gh CLI, обеспечивая бесшовное взаимодействие с репозиториями и рабочими процессами Github через URL-адреса или синтаксис --repo владелец/репозиторий.","ar":"تمكّن الوكيل من توفير مهام مثل التحقق من حالة CI ومراجعة تشغيل سير العمل وتصحيح خطوات الفشل باستخدام gh CLI، و تسهيل التفاعل السلس مع مستودعات Github وسلاسل العمل عبر URLs أو بناء الجملة --repo مالك/مستودع."},"useCases":{"en":["Automating CI status checks on pull requests","Debugging failed workflow runs","Listing recent workflow runs for audit and monitoring purposes"],"zh":["在拉取请求上自动检查CI状态","调试失败的工作流运行","列出最近的工作流运行以进行审计和监控"],"ja":["プルリクエストでCI状態を自動的に確認する","失敗したワークフロー実行のデバッグ","監査および監視の目的で最近のワークフロー実行をリストする"],"ko":["풀 요청에서 CI 상태를 자동으로 확인하는 것","실패한 워크플로 실행의 디버깅","감사 및 모니터링 목적으로 최근 워크플로 실행을 나열하는 것"],"es":["Automatizar las comprobaciones de estado de CI en solicitudes de incorporación","Depurar ejecuciones de flujo de trabajo fallidas","Listar ejecuciones de flujo de trabajo recientes para fines de auditoría y supervisión"],"fr":["Automatiser les vérifications de l''état de CI sur les demandes d''intégration","Déboguer les exécutions de workflow ayant échoué","Lister les exécutions de workflow récentes à des fins d''audit et de surveillance"],"de":["Automatisierung von CI-Status-Prüfungen auf Pull-Requests","Fehlerhafte Workflow-Ausführungen debuggen","Auflisten der kürzlichen Workflow-Ausführungen zu Prüfungszwecken und zur Überwachung"],"pt":["Automatizar verificações de status do CI em solicitações de pull","Depurar execuções de fluxo de trabalho com falha","Listar execuções de fluxo de trabalho recentes para fins de auditoria e monitoramento"],"ru":["Автоматизировать проверку статуса CI в запросах на включение","Отладить неудачные выполнения рабочего процесса","Перечислить недавние выполнения рабочего процесса для аудита и целей мониторинга"],"ar":["توفير عمليات التحقق من حالة CI على طلبات السحب","تصحيح عمليات تشغيل سير العمل الفاشلة","استعراض عمليات تشغيل سير العمل الأخيرة لأغراض التدقيق والرصد"]},"limitations":{"en":["Requires gh CLI installation and configuration","Needs --repo owner/repo specification or URL when not in a git directory"],"zh":["需要安装和配置gh CLI","需要--repo所有者/仓库规范或URL，当不在git目录中时"],"ja":["gh CLIのインストールと構成が必要","--repo所有者/リポジトリ構文またはURLが必要です。gitディレクトリ内にない場合"],"ko":["gh CLI 설치 및 구성이 필요함","--repo 소유자/저장소 구문 또는 URL이 필요함. git 디렉토리 내에 없을 때"],"es":["Requiere la instalación y configuración del CLI de gh","Necesita la especificación --repo dueño/repo o la URL cuando no se encuentra en un directorio de git"],"fr":["Nécessite l''installation et la configuration du CLI gh","Nécessite la spécification --repo propriétaire/repo ou l''URL lorsqu''il n''est pas dans un répertoire git"],"de":["Erfordert die Installation und Konfiguration des gh-CLI","Benötigt die Angabe --repo-Besitzer/Repository oder die URL, wenn nicht in einem Git-Verzeichnis"],"pt":["Exige a instalação e configuração do gh CLI","Necessita de especificação --repo dono/repo ou URL quando não estiver em um diretório git"],"ru":["Требует установки и настройки gh CLI","Требует указания --repo владелец/репозиторий или URL-адреса, когда не находится в каталоге git"],"ar":["يتطلب تثبيت وتهيئة gh CLI","يحتاج إلى تحديد --repo مالك/مستودع أو URL عند عدم وجوده في دليل git"]},"version":4},"contentHash":"51b28818a6f0359287d5c8244a6fdc59a4ac5504596deb193b28b81832221c86","qualityScore":54}');
