INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('onevcat/MeetCat/change-log', 'community', 'onevcat', 'MeetCat', 'onevcat/MeetCat', 'change-log', 4, 0, 54, '2026-03-03T02:37:57Z', '2026-03-06T06:59:00.141Z', 'eb12e6d26eafd7f5855f9333ad51d3ce808d4850959cbbcaef9af6df72b315ec', '{"id":"onevcat/MeetCat/change-log","name":"change-log","description":{"en":"The change-log skill generates a complete, user-facing changelog for the current in-development app version, including all changes since the previous release tag. It benefits developers by automating the changelog update process.","zh":"Change-Log是一种自动加入Google Meet的工具，通过更新CHANGELOG.md文件来提高开发效率","ja":"Change-LogはGoogle Meetの自動参加ツールで、CHANGELOG.mdファイルを更新して開発効率を向上させます","ko":"Change-Log는 Google Meet 자동참가 도구로 CHANGELOG.md 파일을 업데이트하여 개발 효율성을 높입니다","es":"El change-log es una herramienta que ayuda a los desarrolladores a generar un registro de cambios completo para su aplicación. Utiliza la versión de la aplicación desde `tauri.conf.json` para crear un resumen de cambios.","fr":"Le change-log est un outil qui aide les développeurs à générer un journal des modifications complet pour leur application. Il utilise la version de l''application depuis `tauri.conf.json` pour créer un résumé des modifications.","de":"Das Change-log ist ein Tool, das Entwicklern hilft, ein vollständiges Änderungsprotokoll für ihre Anwendung zu erstellen. Es verwendet die Anwendungsversion aus `tauri.conf.json`, um eine Zusammenfassung der Änderungen zu erstellen.","pt":"O change-log é uma ferramenta essencial para desenvolvedores, permitindo gerar um registro de alterações completo para o app em desenvolvimento.","ru":"Change-log - это важнейший инструмент для разработчиков, позволяющий генерировать полный журнал изменений для приложения в разработке.","ar":"سجل التعديلات هو أداة أساسية للمطورين، مما يسمح بإنشاء سجل تعديلات كامل للتطبيق قيد التطوير."},"seo":{"title":{"en":"change-log: Automated Changelog Generation for AI Agents ...","zh":"Change-Log.setup指南：自动加入Google Meet","ja":"Change-Logセットアップガイド：Google Meetの自動参加","ko":"Change-Log 설정 가이드: Google Meet 자동참加","es":"Guía de configuración de change-log para desarrolladores","fr":"Configurer le change-log pour les développeurs","de":"Change-log Einrichtungsleitfaden für Entwickler","pt":"Guia de Configuração do Change-Log: Ferramentas de Desenv...","ru":"Настройка Change-Log: Лучшие Практики для ИИ Агентов","ar":"دليل إعداد سجل التعديلات: أدوات تطوير الإجينات الذكية"},"description":{"en":"Discover how to automate changelog updates with change-log. Learn how to generate complete changelogs for your app versions and get started today!","zh":"了解Change-Log的工作原理，自动加入Google Meet，提高开发效率。查看我们的设置指南和最佳实践","ja":"Change-Logの機能を解説します。Google Meetの自動参加を実現し、開発効率を向上させます。セットアップガイドとベストプラクティスを参照してください","ko":"Change-Log의 작동 방식을 알아보세요. Google Meet 자동참加를 통해 개발 효율성을 높일 수 있습니다. 설정 가이드 및 최선의 방법을 확인하세요","es":"Aprende a generar un registro de cambios completo para tu aplicación con nuestra guía de change-log para desarrolladores de AI Agent","fr":"Découvrez comment créer un journal des modifications complet pour votre application avec notre guide de change-log pour les développeurs d''outils IA","de":"Erfahren Sie, wie Sie ein vollständiges Änderungsprotokoll für Ihre Anwendung mit unserem Change-log-Leitfaden für Entwickler von KI-Tools erstellen","pt":"Aprenda a configurar o change-log para o seu app em desenvolvimento, incluindo a geração de um registro de alterações completo e atualização do arquivo CHANG...","ru":"Узнайте, как настроить change-log для вашего приложения в разработке, включая генерацию полного журнала изменений и обновление файла CHANGELOG.md","ar":"تعرف على كيفية إعداد سجل التعديلات لتطوير تطبيقك، بما في ذلك إنشاء سجل تعديلات كامل وتحديث ملف CHANGELOG.md"},"definition":{"en":"change-log is a skill that automates the generation of changelogs for app versions, utilizing data from tauri.conf.json files and including uncommitted work.","zh":"Change-Log是一种AIエージェント工具，用于生成和更新CHANGELOG.md文件","ja":"Change-LogはAIエージェントの一種で、CHANGELOG.mdファイルを生成および更新するために使用されます","ko":"Change-Log는 CHANGELOG.md 파일을 생성 및 업데이트하는 데 사용되는 AI 도구입니다","es":"Un change-log es un registro de cambios que muestra las actualizaciones y modificaciones realizadas en una aplicación","fr":"Un journal des modifications est un registre des changements qui affiche les mises à jour et les modifications apportées à une application","de":"Ein Änderungsprotokoll ist ein Protokoll der Änderungen, das die Aktualisierungen und Modifikationen an einer Anwendung anzeigt","pt":"O change-log é um registro de alterações feitas no app em desenvolvimento, incluindo atualizações e melhorias.","ru":"Change-log - это журнал изменений, сделанных в приложении в разработке, включая обновления и улучшения.","ar":"سجل التعديلات هو سجل التعديلات التي أجريت على التطبيق قيد التطوير، بما في ذلك التحديثات والتحسينات."},"features":{"en":["Generates changelogs based on app version data from tauri.conf.json files","Includes all changes since the previous release tag, including uncommitted work","Updates the CHANGELOG.md file accordingly","Utilizes heuristic approaches to determine the app version","Supports data retrieval from crates/app/tauri.conf.json and packages/tauri/src-tauri/tauri.conf.json"],"zh":["自动加入Google Meet","更新CHANGELOG.md文件","支持tauri.conf.json文件","包含未提交的工作","支持多语言"],"ja":["Google Meetの自動参加","CHANGELOG.mdファイルの更新","tauri.conf.jsonファイルのサポート","未コミットの作業の含み","多言語サポート"],"ko":["Google Meet 자동참가","CHANGELOG.md 파일 업데이트","tauri.conf.json 파일 지원","미提交 작업 포함","다국어 지원"],"es":["Genera un registro de cambios completo desde la versión de la aplicación en `tauri.conf.json`","Incluye un resumen de cambios desde la última etiqueta de lanzamiento","Soporta la inclusión de trabajo no comprometido","Utiliza la versión de la aplicación desde `crates/app/tauri.conf.json` o `packages/tauri/src-tauri/tauri.conf.json`"],"fr":["Génère un journal des modifications complet depuis la version de l''application dans `tauri.conf.json`","Inclut un résumé des modifications depuis la dernière étiquette de version","Prend en charge l''inclusion de travail non validé","Utilise la version de l''application depuis `crates/app/tauri.conf.json` ou `packages/tauri/src-tauri/tauri.conf.json`"],"de":["Erstellt ein vollständiges Änderungsprotokoll seit der Anwendungsversion in `tauri.conf.json`","Enthält eine Zusammenfassung der Änderungen seit dem letzten Release-Tag","Unterstützt die Einbeziehung von nicht committetem Arbeit","Verwendet die Anwendungsversion aus `crates/app/tauri.conf.json` oder `packages/tauri/src-tauri/tauri.conf.json`"],"pt":["Geração de registro de alterações completo","Atualização do arquivo CHANGELOG.md","Inclusão de alterações não comprometidas","Suporte ao app em desenvolvimento","Leitura de versão do app em `tauri.conf.json`"],"ru":["Генерация полного журнала изменений","Обновление файла CHANGELOG.md","Включение нефиксированных изменений","Поддержка приложения в разработке","Чтение версии приложения из `tauri.conf.json`"],"ar":["إنشاء سجل تعديلات كامل","تحديث ملف CHANGELOG.md","إضافة التعديلات غير الملتزمة","دعم التطبيق قيد التطوير","قراءة إصدار التطبيق من `tauri.conf.json`"]},"keywords":{"en":["how to use change-log","change-log setup guide","automated changelog generation","change-log alternative","change-log vs manual updates","change-log install","what is change-log","change-log for AI agents","change-log and tauri.conf.json"],"zh":["Change-Log","Google Meet","自动加入","CHANGELOG.md","tauri.conf.json","AIエージェント","开发工具","效率提高"],"ja":["Change-Log","Google Meet","自動参加","CHANGELOG.md","tauri.conf.json","AIエージェント","開発ツール","効率向上"],"ko":["Change-Log","Google Meet","자동참가","CHANGELOG.md","tauri.conf.json","AI 도구","개발 도구","효율성 향상"],"es":["change-log","registro de cambios","generar change-log","tauri.conf.json","desarrollo de aplicaciones","herramientas de desarrollo","AI Agent","Herramientas de IA"],"fr":["change-log","journal des modifications","générer un journal des modifications","tauri.conf.json","développement d''applications","outils de développement","outils IA","Agent IA"],"de":["Change-log","Änderungsprotokoll","erstellen von Änderungsprotokollen","tauri.conf.json","Anwendungsentwicklung","Entwicklungstools","KI-Tools","KI-Agent"],"pt":["change-log","ferramentas de desenvolvimento de IAs","geração de registro de alterações","atualização de CHANGELOG.md","desenvolvimento de app","tauri.conf.json","versão do app"],"ru":["change-log","ИИ Агенты","генерация журнала изменений","обновление CHANGELOG.md","разработка приложения","tauri.conf.json","версия приложения"],"ar":["سجل التعديلات","أدوات تطوير الإجينات الذكية","إنشاء سجل تعديلات","تحديث CHANGELOG.md","تطوير التطبيقات","tauri.conf.json","إصدار التطبيق"]}},"owner":"onevcat","repo":"MeetCat","repoPath":"onevcat/MeetCat","stars":4,"forks":0,"updatedAt":"2026-03-03T02:37:57Z","topics":["auto-join","extension","google-meet","meet"],"category":"community","skillMd":{"name":"change-log","description":"Generate a full, user-facing changelog for the current in-development app version by comparing with the previous release tag (including uncommitted changes), and update the appropriate CHANGELOG.md accordingly.","bodyPreview":"## Goal\nProduce a complete, user-facing changelog for the current in-development app version and update the appropriate `CHANGELOG.md` accordingly.\n\n## When to use\n- You need to generate or refresh the changelog for the current dev version.\n- The summary must include all changes since the previous release tag, including uncommitted work.\n\n## Inputs and sources\n- App version (heuristic):\n  1) `crates/app/tauri.conf.json` (`version`).\n  2) `packages/tauri/src-tauri/tauri.conf.json` (`version`).","body":"## Goal\nProduce a complete, user-facing changelog for the current in-development app version and update the appropriate `CHANGELOG.md` accordingly.\n\n## When to use\n- You need to generate or refresh the changelog for the current dev version.\n- The summary must include all changes since the previous release tag, including uncommitted work.\n\n## Inputs and sources\n- App version (heuristic):\n  1) `crates/app/tauri.conf.json` (`version`).\n  2) `packages/tauri/src-tauri/tauri.conf.json` (`version`).\n  3) `tauri.conf.json` (repo root or first match via search).\n  4) `package.json` (`version`) as a fallback when no Tauri config exists.\n- Previous release tag: the latest reachable release tag in git history.\n- Changes since tag: commit logs + file diffs + uncommitted working tree changes.\n- Changelog file (heuristic):\n  1) `crates/app/CHANGELOG.md`.\n  2) `CHANGELOG.md` at repo root.\n  3) `packages/tauri/CHANGELOG.md` or `packages/app/CHANGELOG.md` if present.\n\n## Workflow\n1. Read the current app version using the heuristic order above. This is the target section in the changelog.\n2. Identify the previous release tag.\n   - Preferred: `git describe --tags --abbrev=0`.\n   - If ambiguous or no tag is found, list tags with `git tag --sort=-creatordate` and ask the user to pick the correct release tag.\n3. Collect the full change set (including uncommitted changes).\n   - Commit log: `git log <tag>..HEAD --reverse`.\n   - File-level changes: `git log <tag>..HEAD --name-status`.\n   - Diff for details: `git diff <tag>..HEAD`.\n   - Uncommitted changes: `git status --porcelain`, `git diff`, `git diff --staged`.\n4. Summarize changes into user-facing items only.\n   - Include only changes that impact users (features, UI, behavior, fixes).\n   - Exclude internal-only work (tests, refactors without behavior change, tooling, CI, internal-only docs).\n5. Update the selected `CHANGELOG.md`.\n   - If the target version section already exists, replace it with a full, up-to-date section. Each invocation must be a full refresh for that version.\n   - Keep the version order descending (newest first) and follow the existing formatting style.\n\n## Categorization rules\nUse these sections in this order and omit any empty section:\n1. Added\n2. Changed\n3. Fixed\n\nGuidance:\n- Added: new capabilities, new screens, new features users can now use.\n- Changed: behavior or UX changes, settings changes, performance improvements users can notice.\n- Fixed: bug fixes or incorrect behavior users might have experienced.\n- If a change cannot be clearly categorized, ask the user to choose the section.\n\n## Highlight rule\nIf there is a major milestone or standout feature, add a short highlight paragraph directly under the version header and above any section headers.\n\n## Output format\nFollow the existing Markdown style in the selected `CHANGELOG.md`.\n\nExample skeleton:\n\n```\n## 0.0.x\n\nA short highlight paragraph (only if truly major).\n\n### Added\n\n- User-facing addition.\n\n### Changed\n\n- User-facing change.\n\n### Fixed\n\n- User-facing fix.\n```\n\n## Links\nUse Markdown links if an item needs more explanation. The update dialog supports links.\n\n## Notes\n- Always include uncommitted changes in the summary. If the inclusion is uncertain, confirm with the user.\n- Do not invent changes. Every bullet must be traceable to the collected logs/diffs.\n"},"lastSynced":"2026-03-06T06:59:00.141Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring automated changelog generation and version control integration.","zh":"适合需要自动化变更日志生成和版本控制集成的开发代理。","ja":"自動化された変更ログの生成およびバージョン管理の統合を必要とする開発エージェントに最適です。","ko":"자동화된 변경 로그 생성 및 버전 관리 통합이 필요한 개발 에이전트에 적합합니다.","es":"Ideal para agentes de desarrollo que requieren generación automática de registros de cambios y integración de control de versiones.","fr":"Idéal pour les agents de développement nécessitant une génération automatique de journal des modifications et une intégration de contrôle de version.","de":"Ideal für Entwicklungsmittel, die eine automatische Änderungsprotokollgenerierung und eine Versionskontrollintegration erfordern.","pt":"Ideal para Agentes de Desenvolvimento que exigem geração automática de registro de alterações e integração de controle de versão.","ru":"Идеально подходит для агентов разработки, требующих автоматизированного создания журнала изменений и интеграции с системой контроля версий.","ar":"مثالي للوكلاء النمطية الذين يتطلبون إنشاء سجل التعديلات الآلي وتكامل التحكم في الإصدار."},"recommendation":{"en":"Empowers agents to generate comprehensive, user-facing changelogs for in-development app versions, including uncommitted work, by parsing version information from files like `tauri.conf.json` and updating `CHANGELOG.md` accordingly.","zh":"赋予代理生成全面、面向用户的变更日志的能力，适用于开发中的应用版本，包括未提交的工作，方法是解析版本信息来自如 `tauri.conf.json` 的文件，并相应地更新 `CHANGELOG.md`。","ja":"開発中のアプリバージョン、包括未コミットの作業に対して、`tauri.conf.json` のようなファイルからのバージョン情報を解析し、`CHANGELOG.md` を適宜更新することにより、包括的かつユーザー向けの変更ログを生成するエージェントの能力を付与します。","ko":"개발 중인 애플리케이션 버전에 대한 포괄적이고 사용자 중심의 변경 로그를 생성할 수 있는 에이전트의 능력을 부여하며, 이는 `tauri.conf.json`과 같은 파일에서 버전 정보를 파싱하고 `CHANGELOG.md`를 적절하게 업데이트함으로써 이루어집니다.","es":"Habilita a los agentes a generar registros de cambios completos y orientados al usuario para versiones de aplicaciones en desarrollo, incluyendo trabajo no confirmado, analizando la información de versión desde archivos como `tauri.conf.json` y actualizando `CHANGELOG.md` en consecuencia.","fr":"Permet aux agents de générer des journaux de modifications complets et orientés vers l''utilisateur pour les versions d''applications en développement, y compris les modifications non validées, en analysant les informations de version à partir de fichiers comme `tauri.conf.json` et en mettant à jour `CHANGELOG.md` en conséquence.","de":"Ermächtigt die Mittel, umfassende, benutzerorientierte Änderungsprotokolle für in Entwicklung befindliche App-Versionen, einschließlich nicht committeter Arbeit, zu generieren, indem sie Versionsinformationen aus Dateien wie `tauri.conf.json` parsen und `CHANGELOG.md` entsprechend aktualisieren.","pt":"Permite que os agentes gerem registros de alterações abrangentes e orientados ao usuário para versões de aplicativos em desenvolvimento, incluindo trabalhos não comprometidos, analisando informações de versão de arquivos como `tauri.conf.json` e atualizando `CHANGELOG.md` conforme necessário.","ru":"Позволяет агентам создавать полные и ориентированные на пользователя журналы изменений для версий приложений в разработке, включая незафиксированную работу, путем анализа информации о версии из файлов, таких как `tauri.conf.json`, и обновления `CHANGELOG.md` соответственно.","ar":"تمكن الوكلاء من إنشاء سجلات تعديلات شاملة وموجهة للمستخدم لنسخ التطبيقات قيد التطوير، بما في ذلك الأعمال غير الملتزمة، من خلال تحليل معلومات الإصدار من الملفات مثل `tauri.conf.json` وتحديث `CHANGELOG.md` وفقًا لذلك."},"useCases":{"en":["Automating changelog updates for new app releases","Generating changelogs for development versions with uncommitted changes","Updating `CHANGELOG.md` files based on version tags"],"zh":["自动更新新应用发布的变更日志","为开发版本生成包含未提交更改的变更日志","根据版本标签更新 `CHANGELOG.md` 文件"],"ja":["新しいアプリのリリースの変更ログを自動的に更新する","未コミットの変更を含む開発バージョンの変更ログを生成する","バージョンタグに基づいて `CHANGELOG.md` ファイルを更新する"],"ko":["새 애플리케이션 릴리스의 변경 로그를 자동으로 업데이트하는 것","커밋되지 않은 변경 사항을 포함하는 개발 버전에 대한 변경 로그를 생성하는 것","버전 태그를 기준으로 `CHANGELOG.md` 파일을 업데이트하는 것"],"es":["Automatizar las actualizaciones del registro de cambios para nuevos lanzamientos de aplicaciones","Generar registros de cambios para versiones de desarrollo con cambios no confirmados","Actualizar archivos `CHANGELOG.md` en función de etiquetas de versión"],"fr":["Automatiser les mises à jour du journal des modifications pour les nouveaux lancements d''applications","Générer des journaux de modifications pour les versions de développement avec des modifications non validées","Mettre à jour les fichiers `CHANGELOG.md` en fonction des balises de version"],"de":["Automatisieren von Änderungsprotokoll-Updates für neue App-Veröffentlichungen","Generieren von Änderungsprotokollen für Entwicklungsversionen mit nicht committeter Arbeit","Aktualisieren von `CHANGELOG.md`-Dateien basierend auf Versions-Tags"],"pt":["Automatizar atualizações de registros de alterações para novas versões de aplicativos","Gerar registros de alterações para versões de desenvolvimento com alterações não comprometidas","Atualizar arquivos `CHANGELOG.md` com base em tags de versão"],"ru":["Автоматизировать обновления журналов изменений для новых версий приложений","Генерировать журналы изменений для версий разработки с незафиксированными изменениями","Обновлять файлы `CHANGELOG.md` на основе тегов версий"],"ar":["تحديث سجلات التعديلات تلقائيًا للنسخ الجديدة من التطبيقات","إنشاء سجلات التعديلات لنسخ التطوير ذات التعديلات غير الملتزمة","تحديث ملفات `CHANGELOG.md` بالاعتماد على علامات الإصدار"]},"limitations":{"en":["Requires access to `tauri.conf.json` and `CHANGELOG.md` files","Limited to parsing version information from specific file formats and locations"],"zh":["需要访问 `tauri.conf.json` 和 `CHANGELOG.md` 文件","仅限解析特定文件格式和位置的版本信息"],"ja":["`tauri.conf.json` と `CHANGELOG.md` ファイルへのアクセスが必要","特定のファイル形式と場所からのバージョン情報の解析のみ"],"ko":["`tauri.conf.json` 및 `CHANGELOG.md` 파일에 대한 액세스가 필요합니다","특정 파일 형식 및 위치에서 버전 정보를 파싱하는 것만 해당"],"es":["Requiere acceso a los archivos `tauri.conf.json` y `CHANGELOG.md`","Limitado a analizar información de versión desde formatos y ubicaciones de archivos específicos"],"fr":["Nécessite l''accès aux fichiers `tauri.conf.json` et `CHANGELOG.md`","Limité à l''analyse des informations de version à partir de formats et d''emplacements de fichiers spécifiques"],"de":["Erfordert Zugriff auf die Dateien `tauri.conf.json` und `CHANGELOG.md`","Begrenzt auf das Parsen von Versionsinformationen aus bestimmten Dateiformaten und -speicherorten"],"pt":["Exige acesso aos arquivos `tauri.conf.json` e `CHANGELOG.md`","Limitado à análise de informações de versão de formatos e locais de arquivo específicos"],"ru":["Требует доступа к файлам `tauri.conf.json` и `CHANGELOG.md`","Ограничен анализом информации о версии из определенных форматов и местонахождений файлов"],"ar":["يتطلب الوصول إلى الملفات `tauri.conf.json` و `CHANGELOG.md`","محدود بتحليل معلومات الإصدار من تنسيقات ومواقع ملفات محددة"]},"version":4},"contentHash":"eb12e6d26eafd7f5855f9333ad51d3ce808d4850959cbbcaef9af6df72b315ec","qualityScore":54}');
