INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('onevcat/MeetCat/change-log', 'change-log', 'onevcat', 'MeetCat', 'community', 'change-log onevcat MeetCat community auto-join extension google-meet meet The change-log skill generates a complete, user-facing changelog for the current in-development app version, including all changes since the previous release tag. It benefits developers by automating the changelog update process. Change-Log是一种自动加入Google Meet的工具，通过更新CHANGELOG.md文件来提高开发效率 Change-LogはGoogle Meetの自動参加ツールで、CHANGELOG.mdファイルを更新して開発効率を向上させます Change-Log는 Google Meet 자동참가 도구로 CHANGELOG.md 파일을 업데이트하여 개발 효율성을 높입니다 El change-log es una herramienta que ayuda a los desarrolladores a generar un registro de cambios completo para su aplicación. Utiliza la versión de la aplicación desde `tauri.conf.json` para crear un resumen de cambios. Le change-log est un outil qui aide les développeurs à générer un journal des modifications complet pour leur application. Il utilise la version de l''application depuis `tauri.conf.json` pour créer un résumé des modifications. Das Change-log ist ein Tool, das Entwicklern hilft, ein vollständiges Änderungsprotokoll für ihre Anwendung zu erstellen. Es verwendet die Anwendungsversion aus `tauri.conf.json`, um eine Zusammenfassung der Änderungen zu erstellen. O change-log é uma ferramenta essencial para desenvolvedores, permitindo gerar um registro de alterações completo para o app em desenvolvimento. Change-log - это важнейший инструмент для разработчиков, позволяющий генерировать полный журнал изменений для приложения в разработке. سجل التعديلات هو أداة أساسية للمطورين، مما يسمح بإنشاء سجل تعديلات كامل للتطبيق قيد التطوير. how to use change-log change-log setup guide automated changelog generation change-log alternative change-log vs manual updates change-log install what is change-log change-log for AI agents change-log and tauri.conf.json Change-Log Google Meet 自动加入 CHANGELOG.md tauri.conf.json AIエージェント 开发工具 效率提高 Generates changelogs based on app version data from tauri.conf.json files Includes all changes since the previous release tag, including uncommitted work Updates the CHANGELOG.md file accordingly Utilizes heuristic approaches to determine the app version Supports data retrieval from crates/app/tauri.conf.json and packages/tauri/src-tauri/tauri.conf.json change-log is a skill that automates the generation of changelogs for app versions, utilizing data from tauri.conf.json files and including uncommitted work.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('thesobercoder/ralphzilla/prd', 'community', 'thesobercoder', 'ralphzilla', 'thesobercoder/ralphzilla', 'prd', 4, 2, 54, '2026-02-02T07:08:29Z', '2026-03-06T13:05:53.677Z', '38d738eb1c6b127ab034983e67650e5d13024450edfefc05db762c9f642334db', '{"id":"thesobercoder/ralphzilla/prd","name":"prd","description":{"en":"The prd skill creates detailed Product Requirements Documents for implementation. It receives feature descriptions, asks clarifying questions, and generates PRDs saved to docs/prd.md.","zh":"PRD Generator是一种使用Ralph方法ology的自动AI编码循环，创建详细的产品需求文档","ja":"PRDジェネレーターは、Ralph方法ologyによる自動AIコーディングループであり、詳細な製品要件文書を作成する","ko":"PRD 생성기는 Ralph 방법론을 사용한 자동 AI 코딩 루프로서, 상세한 제품 요구 사항 문서를 생성합니다","es":"El generador de PRD crea documentos de requisitos de producto claros y precisos utilizando la metodología de Ralph y herramientas de AI","fr":"L''outil de création de PRD génère des documents de spécifications de produit clairs et précis en utilisant la méthodologie de Ralph et les outils d''IA","de":"Der PRD-Generator erstellt detaillierte und präzise Produktanforderungsdokumente mithilfe der Ralph-Methode und KI-Tools","pt":"O PRD é uma ferramenta de automação de codificação AI que cria documentos de requisitos de produto claros e açãoaveis. Ele recebe uma descrição de recurso do usuário e gera um documento estruturado","ru":"PRD - это инструмент автоматизации кодирования ИИ, который создает четкие и действенные документы требований к продукту. Он получает описание функции от пользователя и генерирует структурированный документ","ar":"مرجع التطبيق PRD هو أداة ترميز آلي للوكلاء الذكية التي تنشئ وثائق متطلبات المنتج واضحة وقابلة للتنفيذ. يتلقى وصف الميزة من المستخدم وينشئ وثيقة منظمّة"},"seo":{"title":{"en":"prd: PRD Generator Setup Guide | AI Agent Skill","zh":"PRD Generator Setup Guide - 使用Ralph方法ology创建自动AI编码循环","ja":"PRDジェネレーターセットアップガイド - Ralph方法ologyによる自動AIコーディングループ","ko":"PRD 생성기 설정 가이드 - Ralph 방법론을 사용한 자동 AI 코딩 루프","es":"Generador de PRD: Crea documentos de requisitos de produc...","fr":"Outil de création de PRD: Générez des documents de spécif...","de":"PRD-Generator: Erstelle detaillierte Produktanforderungsd...","pt":"Guia de Configuração do PRD: Ferramenta de Automação de C...","ru":"Настройка PRD: ИИ Агенты для Автоматизации Кодирования","ar":"إعداد مرجع التطبيق PRD: أداة الترميز الآلي للوكلاء الذكية"},"description":{"en":"Discover how to create detailed Product Requirements Documents with prd. Learn to generate structured PRDs and streamline your development process. Get start...","zh":"使用PRD Generator创建详细的产品需求文档，实现清晰、可行、适合实现的AI编码循环","ja":"PRDジェネレーターを使用して、明確で実行可能な製品要件文書を作成し、AIコーディングループを実現する","ko":"PRD 생성기를 사용하여 상세한 제품 요구 사항 문서를 생성하고, 명확하고 실행 가능하며 구현에 적합한 AI 코딩 루프를 구현합니다","es":"Aprende a crear documentos de requisitos de producto claros y precisos con el generador de PRD y las herramientas de AI de Ralph","fr":"Découvrez comment créer des documents de spécifications de produit clairs et précis avec l''outil de création de PRD et les outils d''IA de Ralph","de":"Erfahren Sie, wie Sie mit dem PRD-Generator und den KI-Tools von Ralph detaillierte und präzise Produktanforderungsdokumente erstellen","pt":"Aprenda a configurar o PRD, uma ferramenta de automação de codificação AI que cria documentos de requisitos de produto claros e açãoaveis","ru":"Узнайте, как настроить PRD, инструмент автоматизации кодирования ИИ, создающий четкие и действенные документы требований к продукту","ar":"تعرف على إعداد مرجع التطبيق PRD، أداة الترميز الآلي للوكلاء الذكية التي تنشئ وثائق متطلبات المنتج واضحة وقابلة للتنفيذ"},"definition":{"en":"prd is a starter kit for building apps using the Ralph methodology, generating autonomous AI coding loops that ship features while you sleep.","zh":"PRD Generator是使用Ralph方法ology创建自动AI编码循环的工具","ja":"PRDジェネレーターは、Ralph方法ologyによる自動AIコーディングループを作成するツール","ko":"PRD 생성기는 Ralph 방법론을 사용하여 자동 AI 코딩 루프를 생성하는 도구입니다","es":"Un generador de PRD es una herramienta de AI que crea documentos de requisitos de producto claros y precisos","fr":"Un outil de création de PRD est un outil d''IA qui génère des documents de spécifications de produit clairs et précis","de":"Ein PRD-Generator ist ein KI-Tool, das detaillierte und präzise Produktanforderungsdokumente erstellt","pt":"O que é PRD? É uma ferramenta de automação de codificação AI que cria documentos de requisitos de produto","ru":"Что такое PRD? Это инструмент автоматизации кодирования ИИ, который создает документы требований к продукту","ar":"ما هو مرجع التطبيق PRD؟ هو أداة ترميز آلي للوكلاء الذكية التي تنشئ وثائق متطلبات المنتج"},"features":{"en":["Receives feature descriptions from users","Asks 3-5 essential clarifying questions with lettered options","Generates structured PRDs based on user answers","Saves PRDs to docs/prd.md file","Creates detailed Product Requirements Documents for implementation"],"zh":["创建详细的产品需求文档","使用Ralph方法ology实现自动AI编码循环","支持用户输入和clarifying问题","生成结构化的PRD文档","保存至docs/prd.md文件"],"ja":["詳細な製品要件文書を作成する","Ralph方法ologyによる自動AIコーディングループを実現する","ユーザー入力とclarifying問題をサポートする","構造化されたPRD文書を生成する","docs/prd.mdファイルに保存する"],"ko":["상세한 제품 요구 사항 문서를 생성합니다","Ralph 방법론을 사용하여 자동 AI 코딩 루프를 구현합니다","사용자 입력과 명확화 질문을 지원합니다","구조화된 PRD 문서를 생성합니다","docs/prd.md 파일에 저장합니다"],"es":["Crea documentos de requisitos de producto claros y precisos","Utiliza la metodología de Ralph para generar PRD","Hace preguntas de aclaración para garantizar la precisión","Genera PRD en formato Markdown","Guarda los PRD en el directorio ''docs/prd.md''"],"fr":["Génère des documents de spécifications de produit clairs et précis","Utilise la méthodologie de Ralph pour générer des PRD","Pose des questions de clarification pour assurer la précision","Génère des PRD au format Markdown","Enregistre les PRD dans le répertoire ''docs/prd.md''"],"de":["Erstellt detaillierte und präzise Produktanforderungsdokumente","Verwendet die Ralph-Methode zur Generierung von PRD","Stellt Klarstellungsfragen, um die Genauigkeit zu gewährleisten","Generiert PRD im Markdown-Format","Speichert die PRD im Verzeichnis ''docs/prd.md''"],"pt":["Recebe descrição de recurso do usuário","Gera documento de requisitos de produto estruturado","Salva documento em `docs/prd.md`","Perguntas clarificadoras essenciais","Criação de documentos de requisitos de produto claros e açãoaveis"],"ru":["Получает описание функции от пользователя","Генерирует структурированный документ требований к продукту","Сохраняет документ в `docs/prd.md`","Критические вопросы для уточнения","Создает четкие и действенные документы требований к продукту"],"ar":["يتلقي وصف الميزة من المستخدم","ينشئ وثيقة متطلبات المنتج منظمّة","يحفظ الوثيقة في `docs/prd.md`","أسئلة توضيحية أساسية","ينشئ وثائق متطلبات المنتج واضحة وقابلة للتنفيذ"]},"keywords":{"en":["how to use prd","prd setup guide","prd alternative","what is prd","prd vs ralph methodology","prd install","prd generator","product requirements document template","autonomous ai coding loops"],"zh":["PRD Generator","Ralph方法ology","自动AI编码循环","产品需求文档","AIエージェント","AI工具","产品开发","软件开发"],"ja":["PRDジェネレーター","Ralph方法ology","自動AIコーディングループ","製品要件文書","AIエージェント","AIツール","製品開発","ソフトウェア開発"],"ko":["PRD 생성기","Ralph 방법론","자동 AI 코딩 루프","제품 요구 사항 문서","AI 에이전트","AI 도구","제품 개발","소프트웨어 개발"],"es":["generador de PRD","herramientas de AI para desarrollo","metodología de Ralph","creación de documentos de requisitos de producto","desarrollo de software con AI","PRD en Markdown","gestión de requisitos de producto con AI"],"fr":["outil de création de PRD","outils d''IA pour le développement","méthodologie de Ralph","création de documents de spécifications de produit","développement de logiciels avec l''IA","PRD au format Markdown","gestion des spécifications de produit avec l''IA"],"de":["PRD-Generator","KI-Tools für die Entwicklung","Ralph-Methode","Erstellung von Produktanforderungsdokumenten","Software-Entwicklung mit KI","PRD im Markdown-Format","Produktanforderungsmanagement mit KI"],"pt":["PRD","ferramenta de automação de codificação AI","documentos de requisitos de produto","automação de codificação","desenvolvimento de software","ferramentas de desenvolvimento","AI para desenvolvedores","PRD generator"],"ru":["PRD","инструмент автоматизации кодирования ИИ","документы требований к продукту","автоматизация кодирования","разработка программного обеспечения","инструменты разработки","ИИ для разработчиков","PRD генератор"],"ar":["مرجع التطبيق PRD","أداة الترميز الآلي للوكلاء الذكية","وثائق متطلبات المنتج","الترميز الآلي","تطوير البرمجيات","أدوات التطوير","الوكلاء الذكية للمطورين","مرجع التطبيق PRD مولد"]}},"owner":"thesobercoder","repo":"ralphzilla","repoPath":"thesobercoder/ralphzilla","stars":4,"forks":2,"updatedAt":"2026-02-02T07:08:29Z","topics":[],"category":"community","skillMd":{"name":"prd","description":"Generate a Product Requirements Document (PRD) for a new feature. Use when planning a feature, starting a new project, or when asked to create a PRD. Triggers on: create a prd, write prd for, plan this feature, requirements for, spec out.","bodyPreview":"# PRD Generator\n\nCreate detailed Product Requirements Documents that are clear, actionable, and suitable for implementation.\n\n---\n\n## The Job\n\n1. Receive a feature description from the user\n2. Ask 3-5 essential clarifying questions (with lettered options)\n3. Generate a structured PRD based on answers\n4. Save to `docs/prd.md`\n\n**Important:** Do NOT start implementing. Just create the PRD.\n\n---\n\n## Step 1: Clarifying Questions\n\nAsk only critical questions where the initial prompt is ambiguous. Foc","body":"# PRD Generator\n\nCreate detailed Product Requirements Documents that are clear, actionable, and suitable for implementation.\n\n---\n\n## The Job\n\n1. Receive a feature description from the user\n2. Ask 3-5 essential clarifying questions (with lettered options)\n3. Generate a structured PRD based on answers\n4. Save to `docs/prd.md`\n\n**Important:** Do NOT start implementing. Just create the PRD.\n\n---\n\n## Step 1: Clarifying Questions\n\nAsk only critical questions where the initial prompt is ambiguous. Focus on:\n\n- **Problem/Goal:** What problem does this solve?\n- **Core Functionality:** What are the key actions?\n- **Scope/Boundaries:** What should it NOT do?\n- **Success Criteria:** How do we know it''s done?\n\n### Format Questions Like This:\n\n```\n1. What is the primary goal of this feature?\n   A. Improve user onboarding experience\n   B. Increase user retention\n   C. Reduce support burden\n   D. Other: [please specify]\n\n2. Who is the target user?\n   A. New users only\n   B. Existing users only\n   C. All users\n   D. Admin users only\n\n3. What is the scope?\n   A. Minimal viable version\n   B. Full-featured implementation\n   C. Just the backend/API\n   D. Just the UI\n```\n\nThis lets users respond with \"1A, 2C, 3B\" for quick iteration.\n\n---\n\n## Step 2: PRD Structure\n\nGenerate the PRD with these sections:\n\n### 1. Introduction/Overview\n\nBrief description of the feature and the problem it solves.\n\n### 2. Goals\n\nSpecific, measurable objectives (bullet list).\n\n### 3. User Stories\n\nEach story needs:\n\n- **Title:** Short descriptive name\n- **Description:** \"As a [user], I want [feature] so that [benefit]\"\n- **Acceptance Criteria:** Verifiable checklist of what \"done\" means\n\nEach story should be small enough to implement in one focused session.\n\n**Format:**\n\n```markdown\n### US-001: [Title]\n\n**Description:** As a [user], I want [feature] so that [benefit].\n\n**Acceptance Criteria:**\n\n- [ ] Specific verifiable criterion\n- [ ] Another criterion\n- [ ] Typecheck/lint passes\n- [ ] **[UI stories only]** Verify in browser using dev-browser skill\n```\n\n**Important:**\n\n- Acceptance criteria must be verifiable, not vague. \"Works correctly\" is bad. \"Button shows confirmation dialog before deleting\" is good.\n- **For any story with UI changes:** Always include \"Verify in browser using dev-browser skill\" as acceptance criteria. This ensures visual verification of frontend work.\n\n### 4. Functional Requirements\n\nNumbered list of specific functionalities:\n\n- \"FR-1: The system must allow users to...\"\n- \"FR-2: When a user clicks X, the system must...\"\n\nBe explicit and unambiguous.\n\n### 5. Non-Goals (Out of Scope)\n\nWhat this feature will NOT include. Critical for managing scope.\n\n### 6. Design Considerations (Optional)\n\n- UI/UX requirements\n- Link to mockups if available\n- Relevant existing components to reuse\n\n### 7. Technical Considerations (Optional)\n\n- Known constraints or dependencies\n- Integration points with existing systems\n- Performance requirements\n\n### 8. Success Metrics\n\nHow will success be measured?\n\n- \"Reduce time to complete X by 50%\"\n- \"Increase conversion rate by 10%\"\n\n### 9. Open Questions\n\nRemaining questions or areas needing clarification.\n\n---\n\n## Writing for Junior Developers\n\nThe PRD reader may be a junior developer or AI agent. Therefore:\n\n- Be explicit and unambiguous\n- Avoid jargon or explain it\n- Provide enough detail to understand purpose and core logic\n- Number requirements for easy reference\n- Use concrete examples where helpful\n\n---\n\n## Archiving Previous PRDs\n\n**Before writing a new `docs/prd.md`, check if there is an existing one from a different feature:**\n\n1. Read the current `docs/prd.md` if it exists\n2. Check if it''s for a different feature than what you''re about to create\n3. If different:\n   - Extract feature name from PRD title/intro\n   - Check if archive folder already exists: look for `archive/*-feature-name/`\n   - If found, use existing folder; if not, create `archive/YYYY-MM-DD-feature-name/`\n   - Copy current `docs/prd.md` to archive folder\n   - Write the new PRD to `docs/prd.md`\n\n**Shared archive folders:** Multiple runs of same feature (across dates) share one archive folder. Prevents duplicate archives when PRD skill and task skill run on different days.\n\n---\n\n## Output\n\n- **Format:** Markdown (`.md`)\n- **Location:** `docs/`\n- **Filename:** `docs/prd.md`\n\n---\n\n## Example PRD\n\n```markdown\n# PRD: Task Priority System\n\n## Introduction\n\nAdd priority levels to tasks so users can focus on what matters most. Tasks can be marked as high, medium, or low priority, with visual indicators and filtering to help users manage their workload effectively.\n\n## Goals\n\n- Allow assigning priority (high/medium/low) to any task\n- Provide clear visual differentiation between priority levels\n- Enable filtering and sorting by priority\n- Default new tasks to medium priority\n\n## User Stories\n\n### US-001: Add priority field to database\n\n**Description:** As a developer, I need to store task priority so it persists across sessions.\n\n**Acceptance Criteria:**\n\n- [ ] Add priority column to tasks table: ''high'' | ''medium'' | ''low'' (default ''medium'')\n- [ ] Generate and run migration successfully\n- [ ] Typecheck passes\n\n### US-002: Display priority indicator on task cards\n\n**Description:** As a user, I want to see task priority at a glance so I know what needs attention first.\n\n**Acceptance Criteria:**\n\n- [ ] Each task card shows colored priority badge (red=high, yellow=medium, gray=low)\n- [ ] Priority visible without hovering or clicking\n- [ ] Typecheck passes\n- [ ] Verify in browser using dev-browser skill\n\n### US-003: Add priority selector to task edit\n\n**Description:** As a user, I want to change a task''s priority when editing it.\n\n**Acceptance Criteria:**\n\n- [ ] Priority dropdown in task edit modal\n- [ ] Shows current priority as selected\n- [ ] Saves immediately on selection change\n- [ ] Typecheck passes\n- [ ] Verify in browser using dev-browser skill\n\n### US-004: Filter tasks by priority\n\n**Description:** As a user, I want to filter the task list to see only high-priority items when I''m focused.\n\n**Acceptance Criteria:**\n\n- [ ] Filter dropdown with options: All | High | Medium | Low\n- [ ] Filter persists in URL params\n- [ ] Empty state message when no tasks match filter\n- [ ] Typecheck passes\n- [ ] Verify in browser using dev-browser skill\n\n## Functional Requirements\n\n- FR-1: Add `priority` field to tasks table (''high'' | ''medium'' | ''low'', default ''medium'')\n- FR-2: Display colored priority badge on each task card\n- FR-3: Include priority selector in task edit modal\n- FR-4: Add priority filter dropdown to task list header\n- FR-5: Sort by priority within each status column (high to medium to low)\n\n## Non-Goals\n\n- No priority-based notifications or reminders\n- No automatic priority assignment based on due date\n- No priority inheritance for subtasks\n\n## Technical Considerations\n\n- Reuse existing badge component with color variants\n- Filter state managed via URL search params\n- Priority stored in database, not computed\n\n## Success Metrics\n\n- Users can change priority in under 2 clicks\n- High-priority tasks immediately visible at top of lists\n- No regression in task list performance\n\n## Open Questions\n\n- Should priority affect task ordering within a column?\n- Should we add keyboard shortcuts for priority changes?\n```\n\n---\n\n## Checklist\n\nBefore saving the PRD:\n\n- [ ] **Archived previous PRD** (if `docs/prd.md` exists for a different feature, archive it first)\n- [ ] Asked clarifying questions with lettered options\n- [ ] Incorporated user''s answers\n- [ ] User stories are small and specific\n- [ ] Functional requirements are numbered and unambiguous\n- [ ] Non-goals section defines clear boundaries\n- [ ] Saved to `docs/prd.md`\n"},"lastSynced":"2026-03-06T13:05:53.677Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing structured Product Requirements Document generation.","zh":"非常适合需要生成结构化产品需求文档的开发代理","ja":"開発エージェントが構造化された製品要件文書を生成する必要がある場合は最適","ko":"구조화된 제품 요구 사항 문서를 생성해야 하는 개발 에이전트에게 적합","es":"Perfecto para agentes de desarrollo que necesitan generación de documentos de requisitos de producto estructurados.","fr":"Parfait pour les agents de développement ayant besoin de génération de documents de spécifications de produit structurés.","de":"Perfekt für Entwicklungsmittel, die eine strukturierte Generierung von Produktanforderungsdokumenten benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de geração de Documento de Requisitos de Produto estruturado.","ru":"Идеально подходит для агентов разработки, которым необходима структурированная генерация документа требований к продукту.","ar":"مثالي ليعملاء التطوير الذين يحتاجون إلى إنتاج وثيقة متطلبات المنتج المنظمة."},"recommendation":{"en":"Empowers agents to create detailed PRDs with clarifying questions, feature descriptions, and documentation in Markdown format, saved to docs/prd.md, utilizing essential product development protocols.","zh":"赋予代理创建详细的PRD文档的能力，包括澄清问题、功能描述和Markdown格式的文档，保存到docs/prd.md，并利用基本的产品开发协议","ja":"エージェントが詳細なPRDを作成できるようにし、明確化する質問、機能の説明、およびMarkdown形式のドキュメントを保存し、docs/prd.mdに保存し、基本的な製品開発プロトコルを利用","ko":"에이전트가 PRD 문서를 자세히 생성할 수 있도록 하며, 명확화하는 질문, 기능 설명 및 Markdown 형식의 문서를 저장하고 docs/prd.md에 저장하며 필수적인 제품 개발 프로토콜을 활용","es":"Habilita a los agentes a crear PRDs detallados con preguntas aclaratorias, descripciones de características y documentación en formato Markdown, guardados en docs/prd.md, utilizando protocolos esenciales de desarrollo de productos.","fr":"Permet aux agents de créer des PRDs détaillés avec des questions éclaircissantes, des descriptions de fonctionnalités et une documentation au format Markdown, enregistrés dans docs/prd.md, en utilisant des protocoles de développement de produits essentiels.","de":"Ermächtigt Agenten, detaillierte PRDs mit klärenden Fragen, Funktionsbeschreibungen und Dokumentation im Markdown-Format zu erstellen, die in docs/prd.md gespeichert werden, unter Verwendung wesentlicher Produktentwicklungsprotokolle.","pt":"Habilita os agentes a criar PRDs detalhados com perguntas esclarecedoras, descrições de recursos e documentação no formato Markdown, salvo em docs/prd.md, utilizando protocolos essenciais de desenvolvimento de produtos.","ru":"Наделяет агентов возможностью создавать подробные PRD с разъясняющими вопросами, описаниями функций и документацией в формате Markdown, сохраняемыми в docs/prd.md, используя необходимые протоколы разработки продукта.","ar":"يمنح الوكلاء إمكانية إنشاء وثائق متطلبات المنتج المفصلة مع أسئلة توضيحية وصفات الميزات والوثائق بالتنسيق Markdown، محفوظة في docs/prd.md، باستخدام بروتوكولات أساسية لتطوير المنتج."},"useCases":{"en":["Generating PRDs for new feature implementations","Creating structured product documentation","Asking critical clarifying questions for product requirements"],"zh":["为新功能实现生成PRD","创建结构化的产品文档","提出关键的明确化问题以获取产品需求"],"ja":["新しい機能の実装のためのPRDを生成","構造化された製品ドキュメントを作成","製品要件を取得するための重要な明確化の質問を出す"],"ko":["새로운 기능 구현을 위한 PRD 생성","구조화된 제품 문서 생성","제품 요구 사항을 얻기 위한 중요한 澄清 질문"],"es":["Generación de PRDs para nuevas implementaciones de características","Creación de documentación de producto estructurada","Hacer preguntas críticas para aclarar los requisitos del producto"],"fr":["Génération de PRDs pour de nouvelles mises en œuvre de fonctionnalités","Création de documentation de produit structurée","Poser des questions critiques pour clarifier les exigences du produit"],"de":["Generierung von PRDs für neue Funktionsimplementierungen","Erstellung von strukturierter Produkt-Dokumentation","Stellen kritischer Fragen zur Klärung der Produktanforderungen"],"pt":["Geração de PRDs para implementações de novos recursos","Criação de documentação de produto estruturada","Formulação de perguntas críticas esclarecedoras para requisitos de produto"],"ru":["Генерация PRD для реализации новых функций","Создание структурированной документации продукта","Формулирование критических разъясняющих вопросов для требований продукта"],"ar":["إنشاء وثائق متطلبات المنتج لتنفيذ ميزات جديدة","إنشاء توثيق منتج منظم","صياغة أسئلة توضيحية حاسمة لمتطلبات المنتج"]},"limitations":{"en":["Does not support implementation, only PRD generation","Requires user input for feature descriptions and clarifying question answers"],"zh":["不支持实现，只支持PRD生成","需要用户输入功能描述和明确化问题的答案"],"ja":["実装はサポートせず、PRDの生成のみをサポート","機能の説明と明確化の質問の回答についてはユーザーの入力を必要とする"],"ko":["구현을 지원하지 않으며, PRD 생성만을 지원","기능 설명 및 명확화 질문에 대한 답변에 대해 사용자 입력이 필요"],"es":["No admite la implementación, solo la generación de PRD","Requiere la entrada del usuario para las descripciones de características y las respuestas a las preguntas aclaratorias"],"fr":["Ne prend pas en charge la mise en œuvre, uniquement la génération de PRD","Nécessite une entrée utilisateur pour les descriptions de fonctionnalités et les réponses aux questions éclaircissantes"],"de":["Unterstützt keine Implementierung, nur die Generierung von PRD","Benötigt Benutzereingaben für Funktionsbeschreibungen und Antworten auf klärende Fragen"],"pt":["Não suporta implementação, apenas geração de PRD","Requer entrada do usuário para descrições de recursos e respostas a perguntas esclarecedoras"],"ru":["Не поддерживает реализацию, только генерацию PRD","Требует ввода пользователя для описаний функций и ответов на разъясняющие вопросы"],"ar":["لا يدعم التنفيذ، بل فقط إنشاء وثيقة متطلبات المنتج","يتطلب إدخال المستخدم لوصف الميزات وإجابات الأسئلة التوضيحية"]},"version":4},"contentHash":"38d738eb1c6b127ab034983e67650e5d13024450edfefc05db762c9f642334db","qualityScore":54}');
