INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('MeshJS/governance/journey', 'journey', 'MeshJS', 'governance', 'community', 'journey MeshJS governance community The Journey skill provides information about Mesh''s participation in Cardano''s governance ecosystem, allowing developers to create or read session learning logs that persist across Claude Code sessions. Journey 技术允许您创建和管理学习日志，记录开发过程中的重要事件和决定 Journey AIエージェントは、セッション学習ログを作成と管理することで、開発プロセスにおける重要なイベントと決定を記録します Journey 개발자 가이드는 세션 학습 기록을 생성하고 관리하여 개발 과정中的 주요 이벤트와 결정들을 기록합니다 Journey permite a los desarrolladores crear y leer registros de aprendizaje de sesiones para preservar la memoria institucional en Claude Code Journey permet aux développeurs de créer et de lire des journaux d''apprentissage de session pour préserver la mémoire institutionnelle dans Claude Code Journey ermöglicht es Entwicklern, Lernprotokolle von Sitzungen zu erstellen und zu lesen, um das institutionelle Gedächtnis in Claude Code zu bewahren O Journey é um skill que permite criar ou ler logs de aprendizado de sessão, preservando a memória institucional em Claude Code Навык Journey позволяет создавать или читать журналы обучения сессии, сохраняя институциональную память в Claude Code الjourney هو مهارة يسمح بإنشاء أو قراءة سجلات التعلم للجلسة، للحفاظ على الذاكرة المؤسسية في Claude Code how to use journey what is journey journey alternative journey vs cardano journey install journey setup guide persistent session learning logs cardano governance ecosystem claude code sessions Journey 技术 学习日志 开发工作流程 CLI 命令行操作 开发过程记录 重要事件记录 决定记录 journey 文件管理 AI 工具 开发者工具 Creates new journey files with a summary of the current session using the `/journey {title}` command Persists institutional memory across Claude Code sessions Allows developers to record important patterns or learnings Enables the documentation of architectural decisions and non-trivial bug fixes Supports the creation of a knowledge base for future reference Journey is a skill that enables the creation and reading of session learning logs, persisting institutional memory across Claude Code sessions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('OctavianTocan/ai-nexus/ai-elements', 'community', 'OctavianTocan', 'ai-nexus', 'OctavianTocan/ai-nexus', 'ai-elements', 2, 0, 54, '2026-02-27T15:55:40Z', '2026-03-06T13:07:13.892Z', '7e36e211495cf1ecfa6791c1e91cc53e253375cc5ee939d98656cc5a44d41fda', '{"id":"OctavianTocan/ai-nexus/ai-elements","name":"ai-elements","description":{"en":"ai-elements is a component library for building AI-native applications. It provides pre-built components for conversations and messages, integrating with Next.js and FastAPI.","zh":"AI Elements是一个基于shadcn/ui的组件库和自定义注册表，用于快速构建AI原生应用","ja":"AI Elementsは、shadcn/uiに基づいたコンポーネントライブラリとカスタムレジストリであり、AIエージェントの構築を迅速化します","ko":"AI 요소는 shadcn/ui를 기반으로 하는 컴포넌트 라이브러리 및 사용자 정의 레지스트리로서 AI 네이티브 애플리케이션을 빠르게 구축하는 데 도움이 됩니다","es":"ai-elements es una biblioteca de componentes y registro personalizado para aplicaciones AI-native, que proporciona componentes preconstruidos como conversaciones y mensajes","fr":"ai-elements est une bibliothèque de composants et un registre personnalisé pour les applications AI-native, qui fournit des composants préconstruits tels que des conversations et des messages","de":"ai-elements ist eine Komponentenbibliothek und ein benutzerdefiniertes Registry für AI-native-Anwendungen, die vorgefertigte Komponenten wie Konversationen und Nachrichten bietet","pt":"O ai-elements é uma biblioteca de componentes e registro personalizado para construir aplicações de IA nativas mais rápido","ru":"ai-elements — это библиотека компонентов и собственный реестр для более быстрого создания приложений ИИ","ar":"ai-elements هو مكتبة مكونات وسجل مخصص لإنشاء تطبيقات ذكاء اصطناعي أصلية بشكل أسرع"},"seo":{"title":{"en":"ai-elements: Fast AI Chatbot Setup Guide | AI Agent Skill","zh":"AI元素集成指南 - 快速构建AI原生应用","ja":"AIエージェントのためのAI Elements Setup Guide","ko":"AI 요소 통합 가이드 - 빠른 AI 네이티브 애플리케이션 구축","