INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('crafter-station/cs.chat/ai-elements', 'ai-elements', 'crafter-station', 'cs.chat', 'community', 'ai-elements crafter-station cs.chat community ai-elements is a component library for building AI-native applications faster, providing pre-built components like conversations and messages. It benefits developers looking to streamline their workflow. AI元素是一个基于shadcn/ui的组件库和自定义注册表，提供预构建的对话、消息等组件 AI Elementsは、shadcn/uiを基盤としたコンポーネントライブラリとカスタムレジストリで、事前に構築されたコンポーネントを提供します AI 요소는 shadcn/ui를 기반으로 하는 컴포넌트 라이브러리와 커스텀 레지스트리로, 사전 구축된 컴포넌트를 제공합니다 ai-elements es una biblioteca de componentes y registro personalizado para aplicaciones de inteligencia artificial ai-elements est une bibliothèque de composants et un registre personnalisé pour les applications d''intelligence artificielle ai-elements ist eine Komponentenbibliothek und ein benutzerdefinierter Register für künstliche Intelligenz-Anwendungen O ai-elements é uma biblioteca de componentes e registro personalizado construída sobre o shadcn/ui para ajudar a construir aplicativos AI-nativos mais rapidamente Ai-elements - это библиотека компонентов и пользовательский реестр, построенная на основе shadcn/ui для ускорения разработки приложений с поддержкой ИИ ai-elements هي مكتبة مكونات وسجل مخصص مبنية على shadcn/ui لمساعدتك على بناء تطبيقات ذكية بالاعتماد على الإنسان الاصطناعي بشكل أسرع how to use ai-elements ai-elements setup guide ai-elements alternative ai-elements vs shadcn/ui ai-elements install what is ai-elements ai-elements documentation ai-elements tutorial ai-elements integration AI元素 AI原生应用 组件库 自定义注册表 shadcn/ui CLI命令 快速安装 AI开发工具 Provides pre-built components like conversations and messages Built on top of shadcn/ui for seamless integration Supports dedicated CLI command for fastest setup Integrates via standard shadcn/ui CLI for existing users Offers a custom registry for AI-native applications Includes components for building AI-native applications faster ai-elements is a custom registry built on top of shadcn/ui, offering a component library for AI-native applications');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MinhNhut05/doan2_DH22Tin08_LeMinhNhut_lo_trinh_hoc_it/debug', 'community', 'MinhNhut05', 'doan2_DH22Tin08_LeMinhNhut_lo_trinh_hoc_it', 'MinhNhut05/doan2_DH22Tin08_LeMinhNhut_lo_trinh_hoc_it', 'debug', 2, 0, 54, '2026-02-15T18:01:07Z', '2026-03-06T07:09:46.085Z', 'ceb1b54e633940593af121f6e0e42c298f4aa4c3f9ff831126bfc8dd8f0e9b72', '{"id":"MinhNhut05/doan2_DH22Tin08_LeMinhNhut_lo_trinh_hoc_it/debug","name":"debug","description":{"en":"The debug skill provides an AI-assisted personalized learning path for IT learners in Vietnam, helping them analyze bugs and suggest fixes with explanations.","zh":"Debug 助手是一种 AI 辅助调试工具，通过系统分析和错误信息，提供详细的 Bug 解决方案","ja":"デバッグ ヘルパーは、AI エージェントを使用したバグ解決ツールで、エラーメッセージとファイルパスを分析して解決策を提示します","ko":"디버그 헬퍼는 AI 도구를 사용한 오류 분석과 해결을 위한 도구로، 에러 메시지와 파일 경로를 분석하여 문제 해결을 지원합니다","es":"Nuestra herramienta de depuración utiliza un enfoque sistemático para analizar y solucionar errores, proporcionando explicaciones detalladas","fr":"Notre outil de débogage utilise une approche systématique pour analyser et résoudre les erreurs, en fournissant des explications détaillées","de":"Unser Debugging-Tool verwendet einen systematischen Ansatz, um Fehler zu analysieren und zu beheben, mit detaillierten Erklärungen","pt":"O debug é uma ferramenta de aprendizado personalizado que ajuda a identificar e corrigir erros de forma sistemática com explicações claras","ru":"Отладка - это инструмент персонализированного обучения, который помогает систематически выявлять и исправлять ошибки с четкими объяснениями для ИИ Агентов","ar":"التصحيح هو أداة تعلم شخصية تساعد على تحديد وتصحيح الأخطاء بشكل منهجي مع توضيحات واضحة للوكلاء الذكيين"},"seo":{"title":{"en":"Debug: AI-Assisted Bug Fixing Setup Guide | AI Agent Skill","zh":"Debug 助手设置指南 - AI 辅助调试工具","ja":"デバッグ ヘルパー設定ガイド - AI エージェントを使用したバグ解決","ko":"디버그 헬퍼 설정 가이드 - AI 도구를 