INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('MinhNhut05/doan2_DH22Tin08_LeMinhNhut_lo_trinh_hoc_it/debug', 'debug', 'MinhNhut05', 'doan2_DH22Tin08_LeMinhNhut_lo_trinh_hoc_it', 'community', 'debug MinhNhut05 doan2_DH22Tin08_LeMinhNhut_lo_trinh_hoc_it community The debug skill provides an AI-assisted personalized learning path for IT learners in Vietnam, helping them analyze bugs and suggest fixes with explanations. Debug 助手是一种 AI 辅助调试工具，通过系统分析和错误信息，提供详细的 Bug 解决方案 デバッグ ヘルパーは、AI エージェントを使用したバグ解決ツールで、エラーメッセージとファイルパスを分析して解決策を提示します 디버그 헬퍼는 AI 도구를 사용한 오류 분석과 해결을 위한 도구로، 에러 메시지와 파일 경로를 분석하여 문제 해결을 지원합니다 Nuestra herramienta de depuración utiliza un enfoque sistemático para analizar y solucionar errores, proporcionando explicaciones detalladas Notre outil de débogage utilise une approche systématique pour analyser et résoudre les erreurs, en fournissant des explications détaillées Unser Debugging-Tool verwendet einen systematischen Ansatz, um Fehler zu analysieren und zu beheben, mit detaillierten Erklärungen O debug é uma ferramenta de aprendizado personalizado que ajuda a identificar e corrigir erros de forma sistemática com explicações claras Отладка - это инструмент персонализированного обучения, который помогает систематически выявлять и исправлять ошибки с четкими объяснениями для ИИ Агентов التصحيح هو أداة تعلم شخصية تساعد على تحديد وتصحيح الأخطاء بشكل منهجي مع توضيحات واضحة للوكلاء الذكيين how to use debug debug setup guide debug alternative debug vs traditional debugging methods debug install what is debug debug tutorial debug for IT learners AI-powered debug tools Debug 助手 AI 辅助调试 错误解决 Bug 解决 IT 项目调试 代码分析工具 AI 学习平台 Analyzes bugs systematically using error messages, file paths, or descriptions Asks for specific information such as error messages, file/endpoint, and reproduction steps Provides explanations for suggested fixes Follows the Learning Mode guidelines outlined in `_templates/learning-mode.md` Supports user input via the `/debug <problem>` command debug is an AI-assisted tool that helps IT learners systematically analyze bugs and provides step-by-step fixing guidance');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tae0y/python-project-template/worklog', 'community', 'tae0y', 'python-project-template', 'tae0y/python-project-template', 'worklog', 1, 0, 54, '2026-02-24T05:31:35Z', '2026-03-06T07:10:16.507Z', '682e9e38108b4b931bbeec44898d70ae7ed1c4ba327993d5d6317561beb2bb54', '{"id":"tae0y/python-project-template/worklog","name":"worklog","description":{"en":"The worklog skill is designed for developers using Claude Python Vibecoding workflow, enabling them to update task states in worklog files efficiently. It supports explicit arguments for marking tasks as done.","zh":"Worklog 是一个项目模板，用于更新任务状态和 Claude Python Vibecoding 工作流","ja":"Worklog は、タスク状態を更新し、Claude Python Vibecoding ワークフローを実現するプロジェクトテンプレートです","ko":"Worklog는 태스크 상태를 업데이트하고 Claude Python Vibecoding 작업 흐름을 구현하는 프로젝트 템플릿입니다","es":"Worklog es una plantilla de proyecto para flujos de trabajo de Vibecoding en Python que actualiza el estado de las tareas en archivos de trabajo","fr":"Worklog est un modèle de projet pour les flux de travail Vibecoding en Python qui met à jour l''état des tâches dans les fichiers de travail","de":"Worklog ist eine Projektvorlage für Vibecoding-Workflows in Python, die den Status von Aufgaben in Arbeitsdateien aktualisiert","pt":"O worklog é um projeto de modelo para o fluxo de trabalho Python do Claude, permitindo atualizar o estado das tarefas em arquivos de trabalho.","ru":"Worklog - это проект шаблона для потока работы Python от Claude, позволяющий обновлять состояние задач в файлах работы - ИИ Агенты","ar":"سجل العمل هو مشروع نموذج للتدفق البرمجي بايثون من كلود، يسمح بتحديث حالة المهام في ملفات العمل - أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"worklog: Project Template Setup Guide for AI Agents","zh":"Worklog Setup Guide: 使用 Claude Python Vibecoding 工作流","ja":"Worklog セットアップガイド: Claude Python Vibecoding ワークフロー","ko":"Worklog 설