INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tae0y/python-project-template/worklog', 'worklog', 'tae0y', 'python-project-template', 'community', 'worklog tae0y python-project-template community claude python vibecoding workflow The worklog skill is designed for developers using Claude Python Vibecoding workflow, enabling them to update task states in worklog files efficiently. It supports explicit arguments for marking tasks as done. Worklog 是一个项目模板，用于更新任务状态和 Claude Python Vibecoding 工作流 Worklog は、タスク状態を更新し、Claude Python Vibecoding ワークフローを実現するプロジェクトテンプレートです Worklog는 태스크 상태를 업데이트하고 Claude Python Vibecoding 작업 흐름을 구현하는 프로젝트 템플릿입니다 Worklog es una plantilla de proyecto para flujos de trabajo de Vibecoding en Python que actualiza el estado de las tareas en archivos de trabajo Worklog est un modèle de projet pour les flux de travail Vibecoding en Python qui met à jour l''état des tâches dans les fichiers de travail Worklog ist eine Projektvorlage für Vibecoding-Workflows in Python, die den Status von Aufgaben in Arbeitsdateien aktualisiert O worklog é um projeto de modelo para o fluxo de trabalho Python do Claude, permitindo atualizar o estado das tarefas em arquivos de trabalho. Worklog - это проект шаблона для потока работы Python от Claude, позволяющий обновлять состояние задач в файлах работы - ИИ Агенты سجل العمل هو مشروع نموذج للتدفق البرمجي بايثون من كلود، يسمح بتحديث حالة المهام في ملفات العمل - أدوات الذكاء الاصطناعي how to use worklog worklog setup guide worklog alternative worklog vs todo list worklog install for Claude worklog project template what is worklog worklog for Python developers worklog workflow management Worklog Claude Python Vibecoding 工作流 任务状态更新 AIエージェント Python 开发 CLI 工具 Updates task state in worklog files using explicit arguments Supports marking tasks as done with the ''done [description]'' command Utilizes specific worklog files for backlog, in-progress, and completed tasks Integrates with Claude Python Vibecoding workflow for seamless project management Requires explicit arguments in the format ''[state] [description]'' worklog is a project template for managing task states in local worklog files, including backlog, in-progress, and completed tasks.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('estebandegetau/Fiscal-shocks/review-iteration', 'community', 'estebandegetau', 'Fiscal-shocks', 'estebandegetau/Fiscal-shocks', 'review-iteration', 1, 0, 54, '2026-02-25T20:19:58Z', '2026-03-06T07:12:08.457Z', 'afc9cb6f418165b7a41391effcc68e32f627aceaa85267f01fb58ec5a704c2a8', '{"id":"estebandegetau/Fiscal-shocks/review-iteration","name":"review-iteration","description":{"en":"The review-iteration skill provides a structured, read-only analysis of pipeline results, helping users understand what happened in their workflow. This skill is ideal for developers and AI agents looking to fill the gap between result generation and user understanding.","zh":"Review Iteration Skill提供结构化的读取和分析管道结果的能力，填补了结果存在与用户理解之间的差距","ja":"Review Iteration Skillは、パイプライン結果を構造化して読み解く機能を提供し、結果の存在とユーザーの理解のギャップを埋めます","ko":"Review Iteration Skill은 파이프라인 결과를 구조화하여 읽고 분석하는 기능을 제공하여 결과의 존재와 사용자의 이해 사이의 간격을 메웁니다","es":"Review-iteration es una habilidad que permite analizar resultados de pipelines de manera estructurada y de solo lectura","fr":"Review-iteration est une compétence qui permet d''analyser les résultats de pipelines de manière structurée et en lecture seule","de":"Review-iteration ist eine Fähigkeit, die die Analyse von Pipeline-Ergebnissen in strukturierter und schreibgeschützter Form ermöglicht","pt":"O Review Iteration é uma habilidade que fornece análise estruturada e somente leitura dos resultados do pipeline","ru":"ИИ Агент Review Iteration предоставляет структурированный анализ результатов pipeline","ar":"الIteration Review هو مهارة توفر تحليلًا منظمًا وقراءة فقط للنتائج الأنابيب"},"seo":{"title":{"en":"review-iteration: Structured Pipeline Analysis for AI Age...","zh":"Review Iteration Skill Setup Guide - AI工具","ja":"Review Iteration Skill ベストプラクティス - AIエージェント","ko":"Review Iteration Skill 구현 가이드 - AI 에이전트","es":"Guía de configuración de review-iteration para análisis d...","fr":"Guide d''installation de review-iteration pour l''analyse d...","de":"Einrichtungsleitfaden für review-iteration zur Analyse vo...","pt":"Guia de Configuração do Review Iteration para Análise de ...","ru":"Настройка ИИ Агента Review Iteration для Анализа Результатов","ar":"دليل إعداد Iteration Review لتحليل أنابيب"},"description":{"en":"Unlock the full potential of your pipeline results with review-iteration. Learn how to analyze and understand what happened in your workflow. Get started today!","zh":"了解Review Iteration Skill的功能和用途，掌握结构化分析和结果解读的技巧，提升AI工具的使用效率","ja":"Review Iteration Skillの機能と使い方をマスターし、パイプライン結果の分析と解釈を効率化する","ko":"Review Iteration Skill의 기능과 사용 방법을 익히고 구조화된 분석과 결과 해석의 효율성을 높여보세요","es":"Aprende a utilizar review-iteration para analizar resultados de pipelines y mejorar la comprensión del usuario","fr":"Découvrez comment utiliser review-iteration pour analyser les résultats de pipelines et améliorer la compréhension de l''utilisateur","de":"Erfahren Sie, wie Sie review-iteration verwenden, um Pipeline-Ergebnisse zu analysieren und das Benutzerverständnis zu verbessern","pt":"Aprenda a configurar o Review Iteration para análise de pipeline e melhorar a compreensão dos resultados","ru":"Узнайте, как настроить ИИ Агент Review Iteration для анализа результатов и улучшения понимания","ar":"تعلم كيفية إعداد Iteration Review لتحليل الأنابيب و تحسين الفهم"},"definition":{"en":"review-iteration is a skill that performs a read-only analysis of pipeline results, enabling users to understand what happened in their workflow before deciding what to do next.","zh":"Review Iteration Skill是一种AI工具，用于结构化读取和分析管道结果","ja":"Review Iteration Skillは、パイプライン結果を構造化して読み解くAIエージェントの機能です","ko":"Review Iteration Skill은 파이프라인 결과를 구조화하여 읽고 분석하는 AI 에이전트의 기능입니다","es":"Review-iteration es una habilidad de análisis de resultados que llena el vacío entre la existencia de resultados y la comprensión del usuario","fr":"Review-iteration est une compétence d''analyse de résultats qui comble le fossé entre l''existence de résultats et la compréhension de l''utilisateur","de":"Review-iteration ist eine Analysefähigkeit, die die Lücke zwischen der Existenz von Ergebnissen und dem Verständnis des Benutzers schließt","pt":"O que é Review Iteration? É uma habilidade que analisa resultados de pipeline de forma estruturada","ru":"Что такое ИИ Агент Review Iteration? Это способность анализировать результаты pipeline","ar":"ما هو Iteration Review? هو مهارة تقوم بتحليل النتائج الأنابيب بطريقة منسقة"},"features":{"en":["Performs read-only analysis of pipeline results","Supports workflow iteration using tar_make()","Enables distinction between result analysis and logging via /log-iteration","Typical workflow integration: tar_make() -> /review-iteration -> discuss with user -> /log-iteration","Provides a structured analysis of pipeline results"],"zh":["结构化读取和分析管道结果","支持tar_make()函数","与/log-iteration功能互补","典型工作流：tar_make() -> /review-iteration -> 讨论 -> /log-iteration","提高结果解读的效率"],"ja":["パイプライン結果を構造化して読み解く","tar_make()関数をサポート","/log-iteration機能と相補","典型的なワークフロー：tar_make() -> /review-iteration -> 議論 -> /log-iteration","結果の解釈の効率を向上"],"ko":["파이프라인 결과를 구조화하여 읽고 분석","tar_make() 함수를 지원","/log-iteration 기능과 상호 보완","표준적인 워크플ロー：tar_make() -> /review-iteration -> 토론 -> /log-iteration","결과의 해석 효율성을 높임"],"es":["Análisis estructurado de resultados de pipelines","Lectura y análisis de resultados antes de decidir qué hacer","Diferenciación de /log-iteration para escribir registros","Integración con tar_make() para un flujo de trabajo típico","Discusión con el usuario antes de /log-iteration"],"fr":["Analyse structurée des résultats de pipelines","Lecture et analyse des résultats avant de décider quoi faire","Différenciation de /log-iteration pour écrire des enregistrements","Intégration avec tar_make() pour un flux de travail typique","Discussion avec l''utilisateur avant /log-iteration"],"de":["Strukturierte Analyse von Pipeline-Ergebnissen","Lesen und Analysieren von Ergebnissen vor der Entscheidung","Abgrenzung von /log-iteration zum Schreiben von Aufzeichnungen","Integration mit tar_make() für einen typischen Arbeitsablauf","Diskussion mit dem Benutzer vor /log-iteration"],"pt":["Análise estruturada de resultados de pipeline","Leitura somente de resultados","Diferenciação de /log-iteration","Integração com tar_make()","Discussão com o usuário","Registro de resultados com /log-iteration"],"ru":["Структурированный анализ результатов pipeline","Только чтение результатов","Различие от /log-iteration","Интеграция с tar_make()","Обсуждение с пользователем","Запись результатов с /log-iteration"],"ar":["تحليل منظم للنتائج الأنابيب","قراءة فقط للنتائج","التمييز عن /log-iteration","التكامل مع tar_make()","مناقشة مع المستخدم","تسجيل النتائج مع /log-iteration"]},"keywords":{"en":["how to use review-iteration","what is review-iteration","review-iteration alternative","review-iteration vs log-iteration","review-iteration install","review-iteration setup guide","pipeline result analysis","workflow iteration","tar_make() workflow"],"zh":["Review Iteration Skill","AI工具","结构化分析","管道结果","tar_make()","log-iteration","结果解读","AIエージェント","パイプライン结果"],"ja":["Review Iteration Skill","AIエージェント","構造化分析","パイプライン結果","tar_make()","log-iteration","結果の解釈","AIツール","パイプラインの分析"],"ko":["Review Iteration Skill","AI 에이전트","구조화된 분석","파이프라인 결과","tar_make()","log-iteration","결과의 해석","AI 도구","파이프라인의 분석"],"es":["review-iteration","análisis de resultados","pipelines","tar_make()","log-iteration","herramientas de AI","agentes de IA","desarrollo de software","análisis de código"],"fr":["review-iteration","analyse de résultats","pipelines","tar_make()","log-iteration","outils d''IA","agents d''IA","développement de logiciels","analyse de code"],"de":["review-iteration","Ergebnisanalyse","Pipelines","tar_make()","log-iteration","KI-Tools","KI-Agenten","Software-Entwicklung","Code-Analyse"],"pt":["Review Iteration","análise de pipeline","tar_make","log-iteration","análise de resultados","desenvolvimento de software","ferramentas de AI","agentes de AI","configuração de Review Iteration"],"ru":["ИИ Агент Review Iteration","анализ результатов pipeline","tar_make","log-iteration","анализ результатов","разработка программного обеспечения","ИИ инструменты","ИИ агенты","настройка ИИ Агента Review Iteration"],"ar":["الIteration Review","تحليل الأنابيب","tar_make","log-iteration","تحليل النتائج","تطوير البرمجيات","أدوات الذكاء الاصطناعي","وكلاء الذكاء الاصطناعي","إعداد Iteration Review"]}},"owner":"estebandegetau","repo":"Fiscal-shocks","repoPath":"estebandegetau/Fiscal-shocks","stars":1,"forks":0,"updatedAt":"2026-02-25T20:19:58Z","topics":[],"category":"community","skillMd":{"name":"review-iteration","description":"Read-only structured analysis of pipeline results for human review. Diagnoses failures, maps error patterns, and suggests next steps without editing any files.","bodyPreview":"# Review Iteration Skill\n\nStructured, read-only analysis of pipeline results. This fills the gap between results existing and the user understanding what happened.\n\n**Key distinction from `/log-iteration`:**\n\n- `/review-iteration` = **read and analyze** results (before deciding what to do)\n- `/log-iteration` = **write a record** (after deciding what happened)\n\nTypical workflow: `tar_make()` -> `/review-iteration` -> discuss with user -> `/log-iteration`\n\n## When to Use\n\nInvoke `/review-iteration","body":"# Review Iteration Skill\n\nStructured, read-only analysis of pipeline results. This fills the gap between results existing and the user understanding what happened.\n\n**Key distinction from `/log-iteration`:**\n\n- `/review-iteration` = **read and analyze** results (before deciding what to do)\n- `/log-iteration` = **write a record** (after deciding what happened)\n\nTypical workflow: `tar_make()` -> `/review-iteration` -> discuss with user -> `/log-iteration`\n\n## When to Use\n\nInvoke `/review-iteration` after a pipeline stage completes and before deciding what to change. Use when you want to understand:\n\n- Which tests or metrics pass/fail and why\n- What error patterns dominate\n- Which codebook component is most likely responsible\n- What to investigate or change next\n\n## Procedure\n\n### Step 1: Ask the user\n\nAsk for two things:\n\n1. **Codebook**: Which codebook? (`c1`, `c2`, `c3`, or `c4`)\n2. **Stage**: Which stage was run? (`s1`, `s2`, or `s3`)\n\n### Step 2: Auto-gather context (read-only)\n\nCollect all relevant context without modifying anything:\n\n| Source | How |\n|--------|-----|\n| Codebook YAML | Read `prompts/c<N>_<name>.yml` |\n| Pipeline results | `Rscript -e ''library(targets); cat(jsonlite::toJSON(tar_read(<target>), auto_unbox = TRUE, digits = 4, pretty = TRUE))''` |\n| Iteration log | Read `prompts/iterations/c<N>.yml` (if exists, for comparison with previous iterations) |\n| Success criteria | Read `docs/strategy.md` and extract the relevant codebook''s target metrics |\n| Previous diagnosis | Check if `/review-iteration` was run before for this codebook+stage |\n\n**Target name mapping:**\n\n| Codebook + Stage | Target |\n|------------------|--------|\n| `c<N>` + `s1` | `c<N>_s1_results` |\n| `c<N>` + `s2` | `c<N>_s2_eval` (metrics) + `c<N>_s2_results` (raw predictions) |\n| `c<N>` + `s3` | `c<N>_s3_results` |\n\nIf `tar_read()` fails, tell the user and suggest running `tar_make(<target>)` first.\n\n### Step 3: Stage-specific analysis\n\n#### S1 Analysis (Behavioral Tests)\n\nFor each of the 4 tests (I-IV):\n\n1. **Pass/fail status** with value vs. threshold\n2. **For failures**: Show the specific inputs that failed\n   - Test I: Which chunks returned invalid JSON? Show the raw response.\n   - Test II: Which label definitions were misclassified? Show predicted vs. expected.\n   - Test III: Which examples were misclassified? Show the example text and predicted vs. expected.\n   - Test IV: Which chunk+ordering combinations changed? Show the prediction pairs.\n3. **Root cause mapping**: Which codebook component (definition, clarification, example, output_instructions) is likely responsible for each failure?\n\n#### S2 Analysis (LOOCV Evaluation)\n\n1. **Primary metrics** vs. targets (from `docs/strategy.md`)\n2. **Secondary metrics** for context\n3. **Worst-performing acts**: Which acts have the lowest recall/accuracy? List the bottom 5-10.\n4. **Error category distribution** using H&K categories:\n   - A: Retrieval augmentation errors\n   - B: Prompt construction errors\n   - C: Formatting/output errors\n   - D: Non-compliance (model ignores instructions)\n   - E: Semantics/reasoning errors (model misunderstands domain)\n   - F: Ambiguous ground truth\n5. **Confusion patterns**: For classification tasks, which label pairs are most confused?\n6. **Example deep-dives**: For the 3 worst errors, show:\n   - Act name, chunk text (truncated), predicted label, true label\n   - Model reasoning (if available in raw results)\n   - Why this is likely wrong (analysis)\n\n#### S3 Analysis (Error Analysis)\n\n1. **Test V (Exclusion Criteria)**: Which negative clarifications, when removed, cause the largest accuracy drops? Rank by impact.\n2. **Test VI (Generic Labels)**: How much does accuracy change with generic labels? High change = model relies on label names, not definitions.\n3. **Test VII (Swapped Labels)**: Does the model follow definitions or label names? Quantify.\n4. **Ablation ranking**: Which components have the largest accuracy drops when removed? Top 5.\n5. **Iteration priority**: Based on ablation + error patterns, what''s the highest-leverage change?\n\n### Step 4: Present structured diagnosis\n\nUse this format:\n\n```\n## Iteration Diagnosis: [Codebook] [Stage]\n\n### What Passed / What Failed\n\n| Test/Metric | Value | Target | Status |\n|-------------|-------|--------|--------|\n| [name] | [value] | [target] | PASS/FAIL |\n\n### Error Patterns (if applicable)\n\n- [N] errors in category [X]: [description]\n- Example: Act \"[name]\", chunk [id]: predicted [X], true [Y]\n  Model reasoning: \"[quoted from raw results]\"\n  Likely cause: [analysis]\n\n### Comparison with Previous Iteration (if applicable)\n\n| Metric | Previous | Current | Change |\n|--------|----------|---------|--------|\n| [name] | [value] | [value] | +/-[delta] |\n\n### Root Cause Hypothesis\n\n[One sentence: what codebook component is most likely responsible for the dominant failure pattern]\n\n### What I''d Investigate Next\n\n1. [Ranked suggestion with rationale]\n2. [Ranked suggestion with rationale]\n3. [Ranked suggestion with rationale]\n\n### Questions for You\n\n- [Ambiguities requiring user domain judgment]\n- [Design choices where multiple valid options exist]\n```\n\n### Step 5: Stop\n\nDo NOT propose code changes, edit files, or modify the codebook. This skill is strictly read-only analysis.\n\nEnd with: \"To iterate on the codebook, you can edit it directly or start a `codebook-developer` session. When ready to record this iteration, run `/log-iteration`.\"\n"},"lastSynced":"2026-03-06T07:12:08.457Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing structured pipeline result analysis and user understanding capabilities.","zh":"非常适合需要结构化管道结果分析和用户理解能力的开发代理。","ja":"構造化されたパイプライン結果分析とユーザー理解機能が必要な開発エージェントに最適です。","ko":"구조화된 파이프라인 결과 분석 및 사용자 이해 기능이 필요한 개발 에이전트에게 적합합니다.","es":"Ideal para Agentes de Desarrollo que necesitan un análisis de resultados de tuberías estructurados y capacidades de comprensión del usuario.","fr":"Parfait pour les agents de développement nécessitant une analyse de résultats de pipeline structurés et des capacités de compréhension de l''utilisateur.","de":"Perfekt für Entwicklungssagenten, die eine strukturierte Analyse von Pipeline-Ergebnissen und Benutzerverständigungsfähigkeiten benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de análise de resultados de pipeline estruturada e capacidades de compreensão do usuário.","ru":"Идеально подходит для агентов разработки, которым необходима структурированная аналитика результатов конвейера и возможности понимания пользователя.","ar":"مثالي لعميل التطوير الذي يحتاج إلى تحليل نتيجة أنابيب بنية وسمات فهم المستخدم."},"recommendation":{"en":"Empowers agents to perform read-only analysis of pipeline results, filling the gap between result generation and user comprehension through structured content analysis, leveraging protocols like tar_make() and skills like /log-iteration.","zh":"赋予代理执行管道结果的只读分析功能，通过结构化内容分析填补结果生成和用户理解之间的差距，利用tar_make()等协议和/log-iteration等技能。","ja":"エージェントがパイプライン結果の読み取り専用分析を実行できるようにし、tar_make()などのプロトコルや/log-iterationなどのスキルを利用して、結果生成とユーザー理解の間のギャップを埋める構造化されたコンテンツ分析を実現します。","ko":"에이전트가 파이프라인 결과의 읽기 전용 분석을 수행할 수 있도록 하며, tar_make()와 같은 프로토콜 및 /log-iteration과 같은 스킬을 활용하여 결과 생성과 사용자 이해 간의 격차를 메우는 구조화된 내용 분석을 가능하게 합니다.","es":"Habilita a los agentes a realizar análisis de solo lectura de los resultados de la tubería, llenando el vacío entre la generación de resultados y la comprensión del usuario a través del análisis de contenido estructurado, aprovechando protocolos como tar_make() y habilidades como /log-iteration.","fr":"Autorise les agents à effectuer une analyse en lecture seule des résultats de pipeline, comblant le fossé entre la génération de résultats et la compréhension de l''utilisateur grâce à l''analyse de contenu structuré, en exploitant des protocoles tels que tar_make() et des compétences comme /log-iteration.","de":"Ermächtigt Agenten, eine schreibgeschützte Analyse von Pipeline-Ergebnissen durchzuführen, schließt die Lücke zwischen Ergebnisgenerierung und Benutzerverständnis durch strukturierte Inhaltsanalyse, indem Protokolle wie tar_make() und Fähigkeiten wie /log-iteration genutzt werden.","pt":"Habilita os agentes a realizar análise somente leitura dos resultados do pipeline, preenchendo a lacuna entre a geração de resultados e a compreensão do usuário por meio da análise de conteúdo estruturada, aproveitando protocolos como tar_make() e habilidades como /log-iteration.","ru":"Наделяет агентов возможностью выполнять анализ только для чтения результатов конвейера, заполняя пробел между генерацией результатов и пониманием пользователя посредством структурированного контент-анализа, используя протоколы как tar_make() и навыки как /log-iteration.","ar":"يمنح الوكيل khảية إجراء تحليل للقراءة فقط لنتائج الأنابيب، وملء الفجوة بين توليد النتائج وفهم المستخدم من خلال تحليل المحتوى المنظم، واستخدام بروتوكولات مثل tar_make() ومهارات مثل /log-iteration."},"useCases":{"en":["Analyzing pipeline results for debugging purposes","Generating user-friendly reports from workflow outputs","Automating the review process for AI-generated content"],"zh":["用于调试目的的管道结果分析","从工作流输出生成用户友好的报告","自动化人工智能生成内容的审查过程"],"ja":["デバッグ目的のパイプライン結果分析","ワークフロー出力からユーザー向けのレポートを生成","AI生成コンテンツのレビュープロセスの自動化"],"ko":["디버깅 목적의 파이프라인 결과 분석","워크플로 출력에서 사용자 친화적인 보고서 생성","인공 지능 생성 콘텐츠의 검토 프로세스 자동화"],"es":["Análisis de resultados de tubería para fines de depuración","Generación de informes de usuario amigables a partir de salidas de flujo de trabajo","Automatización del proceso de revisión para contenido generado por IA"],"fr":["Analyse des résultats de pipeline à des fins de débogage","Génération de rapports conviviaux à partir de sorties de workflow","Automatisation du processus d''examen pour le contenu généré par l''IA"],"de":["Analyse von Pipeline-Ergebnissen zu Debug-Zwecken","Erzeugung von benutzerfreundlichen Berichten aus Workflow-Ausgaben","Automatisierung des Überprüfungsprozesses für von KI generierten Inhalt"],"pt":["Analisar resultados de pipeline para fins de depuração","Gerar relatórios amigáveis ao usuário a partir de saídas de fluxo de trabalho","Automatizar o processo de revisão para conteúdo gerado por IA"],"ru":["Анализ результатов конвейера для целей отладки","Генерация отчетов, дружественных к пользователю, из выходных данных рабочего процесса","Автоматизация процесса проверки контента, сгенерированного ИИ"],"ar":["تحليل نتائج الأنابيب لأغراض التصحيح","توليد تقارير سهلة الاستخدام من مخرجات سير العمل","تأتمة عملية مراجعة المحتوى المتولد بواسطة الذكاء الاصطناعي"]},"limitations":{"en":["Read-only analysis, does not support writing records","Requires integration with pipeline result generation workflows like tar_make()"],"zh":["只读分析，不支持写入记录","需要与tar_make()等管道结果生成工作流集成"],"ja":["読み取り専用分析。レコードの書き込みはサポートされていません","tar_make()などのパイプライン結果生成ワークフローとの統合が必要"],"ko":["읽기 전용 분석. 레코드 쓰기가 지원되지 않음","tar_make()와 같은 파이프라인 결과 생성 워크플로와의 통합이 필요"],"es":["Análisis de solo lectura, no admite la escritura de registros","Requiere integración con flujos de trabajo de generación de resultados de tubería como tar_make()"],"fr":["Analyse en lecture seule, ne prend pas en charge l''écriture d''enregistrements","Nécessite une intégration avec des flux de travail de génération de résultats de pipeline tels que tar_make()"],"de":["Schreibgeschützte Analyse, unterstützt keine Schreiboperationen für Aufzeichnungen","Erfordert Integration mit Pipeline-Ergebnisgenerierungs-Workflows wie tar_make()"],"pt":["Análise somente leitura, não suporta gravação de registros","Requer integração com fluxos de trabalho de geração de resultados de pipeline como tar_make()"],"ru":["Анализ только для чтения, не поддерживает запись записей","Требует интеграции с рабочими процессами генерации результатов конвейера, такими как tar_make()"],"ar":["تحليل للقراءة فقط، لا يدعم كتابة السجلات","يتطلب التكامل مع سير عمل توليد نتائج الأنابيب مثل tar_make()"]},"version":4},"contentHash":"afc9cb6f418165b7a41391effcc68e32f627aceaa85267f01fb58ec5a704c2a8","qualityScore":54}');
