INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('estebandegetau/Fiscal-shocks/review-iteration', 'review-iteration', 'estebandegetau', 'Fiscal-shocks', 'community', 'review-iteration estebandegetau Fiscal-shocks community The review-iteration skill provides a structured, read-only analysis of pipeline results, helping users understand what happened in their workflow. This skill is ideal for developers and AI agents looking to fill the gap between result generation and user understanding. Review Iteration Skill提供结构化的读取和分析管道结果的能力，填补了结果存在与用户理解之间的差距 Review Iteration Skillは、パイプライン結果を構造化して読み解く機能を提供し、結果の存在とユーザーの理解のギャップを埋めます Review Iteration Skill은 파이프라인 결과를 구조화하여 읽고 분석하는 기능을 제공하여 결과의 존재와 사용자의 이해 사이의 간격을 메웁니다 Review-iteration es una habilidad que permite analizar resultados de pipelines de manera estructurada y de solo lectura Review-iteration est une compétence qui permet d''analyser les résultats de pipelines de manière structurée et en lecture seule Review-iteration ist eine Fähigkeit, die die Analyse von Pipeline-Ergebnissen in strukturierter und schreibgeschützter Form ermöglicht O Review Iteration é uma habilidade que fornece análise estruturada e somente leitura dos resultados do pipeline ИИ Агент Review Iteration предоставляет структурированный анализ результатов pipeline الIteration Review هو مهارة توفر تحليلًا منظمًا وقراءة فقط للنتائج الأنابيب how to use review-iteration what is review-iteration review-iteration alternative review-iteration vs log-iteration review-iteration install review-iteration setup guide pipeline result analysis workflow iteration tar_make() workflow Review Iteration Skill AI工具 结构化分析 管道结果 tar_make() log-iteration 结果解读 AIエージェント パイプライン结果 Performs read-only analysis of pipeline results Supports workflow iteration using tar_make() Enables distinction between result analysis and logging via /log-iteration Typical workflow integration: tar_make() -> /review-iteration -> discuss with user -> /log-iteration Provides a structured analysis of pipeline results review-iteration is a skill that performs a read-only analysis of pipeline results, enabling users to understand what happened in their workflow before deciding what to do next.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('datastx/Feather-Flow/review-rust-all', 'community', 'datastx', 'Feather-Flow', 'datastx/Feather-Flow', 'review-rust-all', 1, 0, 54, '2026-02-27T00:52:40Z', '2026-03-06T07:13:27.841Z', '2a1680bd75c7dd4b1af88788e2b819c6b5ee3850b58dab5c012337a7d43a1224', '{"id":"datastx/Feather-Flow/review-rust-all","name":"review-rust-all","description":{"en":"The review-rust-all skill orchestrates SQL validation and static analysis for Rust code, benefiting developers working with Feather-Flow schema validation framework.","zh":"review-rust-all技能是一个SQL编排工具，用于自动化代码审查和验证","ja":"review-rust-all AIエージェントは、コードレビューと検証を自動化するSQLオーケストレーションツールです","ko":"review-rust-all은 코드 리뷰와 검증을 자동화하는 SQL 오케스트레이션 툴입니다","es":"Review-rust-all es una herramienta de orquestación SQL que simplifica la validación de esquemas con Feather-Flow","fr":"Review-rust-all est un outil d''orchestration SQL qui simplifie la validation de schémas avec Feather-Flow","de":"Review-rust-all ist ein SQL-Orchestrierungstool, das die Schemavalidierung mit Feather-Flow vereinfacht","pt":"O review-rust-all é uma ferramenta de orquestração SQL que revisa código Rust de forma eficaz, utilizando o Feather-Flow como framework de validação de esquema.","ru":"review-rust-all - это инструмент оркестровки SQL, который эффективно проверяет код Rust, используя Feather-Flow в качестве фреймворка валидации схемы для ИИ Агентов","ar":"review-rust-all هو أداة تحكم SQL تقوم بمراجعة رمز Rust بفعالية، باستخدام Feather-Flow كإطار تحقق من مخطط البيانات للوكلاء الذكية"},"seo":{"title":{"en":"review-rust-all: SQL Orchestration Setup Guide | AI Agent...","zh":"review-rust-all 技术集成指南","ja":"review-rust-all AIエージェントの設定方法","ko":"review-rust-all 개발자 설정 가이드","es":"Guía de configuración de review-rust-all: herramienta de ...","fr":"Guide d''installation de review-rust-all: outil d''orchestr...","de":"E