INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('endalk200/ai-registry/ai-elements', 'ai-elements', 'endalk200', 'ai-registry', 'community', 'ai-elements endalk200 ai-registry community agent-tools agents ai-sdk ai-sdk-agents tanstack-ai tanstack-ai-tools tools ai-elements is a component library and custom registry for building AI-native applications faster. It provides pre-built components for conversations, messages, and more, leveraging shadcn/ui and tanstack-ai. AI元素是一个基于shadcn/ui的组件库和自定义注册表，提供预建组件和ai-sdk、tanstack-ai的适配器 AI Elementsはshadcn/uiに基づくコンポーネントライブラリとカスタムレジストリで、会話やメッセージなどのコンポーネントを提供します AI 요소는 shadcn/ui 기반의 컴포넌트 라이브러리와 커스텀 레지스트리로, 대화, 메시지 등과 같은 컴포넌트를 제공합니다 ai-elements es una biblioteca de componentes y registro personalizado para ai-sdk y tanstack-ai que acelera el desarrollo de aplicaciones de inteligencia artificial ai-elements est une bibliothèque de composants et un registre personnalisé pour ai-sdk et tanstack-ai qui accélère la création d''applications d''intelligence artificielle ai-elements ist eine Komponentenbibliothek und ein benutzerdefinierter Register für ai-sdk und tanstack-ai, der die Entwicklung von KI-Anwendungen beschleunigt O ai-elements é uma biblioteca de componentes e registro personalizado para construir aplicações nativas de IA com ferramentas de agente de IA. Oferece componentes pré-construídos como conversas e mensagens. ai-elements - это библиотека компонентов и пользовательский реестр для создания родных приложений ИИ с инструментами ИИ Агентов. Предоставляет предустановленные компоненты, такие как разговоры и сообщения. ai-elements هي مكتبة مكونات وسجل مخصص لإنشاء تطبيقات ذكاء اصطناعي أصلية مع أدوات وكلاء الذكاء الاصطناعي. توفر مكونات مسبقة البناء مثل المحادثات والرسائل. how to use ai-elements ai-elements setup guide ai-elements alternative ai-elements vs tanstack-ai ai-elements install what is ai-elements ai-elements documentation ai-elements tutorial ai-elements integration AI元素 AI Agent工具 ai-sdk tanstack-ai shadcn/ui 组件库 自定义注册表 CLI命令行工具 Provides pre-built components like conversations and messages Leverages shadcn/ui for a seamless development experience Integrates with tanstack-ai for enhanced AI capabilities Offers a dedicated CLI command for fast setup Supports integration via the standard shadcn/ui CLI Includes adapters for ai-sdk and tanstack-ai ai-elements is a component library and custom registry built on top of shadcn/ui to help developers build AI-native applications faster.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('aolus-software/clean-elysia-prisma/prisma-expert', 'community', 'aolus-software', 'clean-elysia-prisma', 'aolus-software/clean-elysia-prisma', 'prisma-expert', 1, 0, 54, '2026-03-02T15:02:28Z', '2026-03-06T07:17:27.390Z', '782bbb2ff9de98ae2a251dd2b66ab091de4488ae7f8e35469a24e54129a7f8e0', '{"id":"aolus-software/clean-elysia-prisma/prisma-expert","name":"prisma-expert","description":{"en":"The prisma-expert skill provides deep knowledge of Prisma ORM, benefiting developers who need expertise in schema design, migrations, and query optimization. It supports PostgreSQL, MySQL, and SQLite database operations.","zh":"Prisma Expert 是一名专业的 Prisma ORM 专家，具有深厚的 schema 设计、迁移、查询优化等技术知识","ja":"Prisma Expert は Prisma ORM の専門家で、スキーマ設計、移行、クエリ最適化などの技術に深い知識を持っています","ko":"Prisma Expert는 Prisma ORM 전문가로 스키마 설계, 마이그레이션, 쿼리 최적화 등의 기술에 대한 깊은 지식을 가지고 있습니다","es":"Prisma Expert es un experto en Prisma ORM que ayuda a los desarrolladores a diseñar esquemas, migrar bases de datos y optimizar consultas. Soporta PostgreSQL, MySQL y SQLite.","fr":"Prisma Expert est un expert en Prisma ORM qui aide les développeurs à concevoir des schémas, à migrer des bases de données et à optimiser des requêtes. Il prend en charge PostgreSQL, MySQL et SQLite.","de":"Prisma Expert ist ein Experte für Prisma ORM, der Entwicklern hilft, Schemata zu entwerfen, Datenbanken zu migrieren und Abfragen zu optimieren. Es unterstützt PostgreSQL, MySQL und SQLite.","pt":"O Prisma Expert é um especialista em Prisma ORM com conhecimento profundo em design de esquema, migrações, otimização de consultas e operações de banco de dados","ru":"Prisma Expert - это специалист по Prisma ORM с глубокими знаниями в области проектирования схем, миграций, оптимизации запросов и операций с базами данных","ar":"Prisma Expert هو خبير في Prisma ORM مع معرفة عميقة في تصميم المخططات، والهجرة، و تحسين الاستفسارات، وعمليات قواعد البيانات"},"seo":{"title":{"en":"Prisma Expert: Mastering Prisma ORM Setup Guide | AI Agen...","zh":"Prisma Expert Setup Guide - AIエージェント for PostgreSQL, MySQ...","ja":"Prisma Expert ベストプラクティス - AIエージェント for ORM Optimization","ko":"Prisma Expert 개발 가이드 - AI 에이전트 for Database Operations","es":"Guía de configuración de Prisma Expert para desarrolladores","fr":"Configurer Prisma Expert : Guide de mise en route","de":"Prisma-Expert-Setup-Leitfaden für Entwickler","pt":"Guia de Configuração Prisma Expert: Otimização de Consultas","ru":"ИИ Агент Prisma Expert: Руководство по Настройке","ar":"دليل تثبيت Prisma Expert: تحسين الاستفسارات"},"description":{"en":"Unlock Prisma ORM''s full potential with the prisma-expert AI agent skill - optimize schema design, migrations, and query performance across PostgreSQL, MySQL...","zh":"了解 Prisma Expert AIエージェント的功能和优点，掌握 schema 设计、迁移、查询优化等技术","ja":"Prisma Expert AIエージェントの機能とメリットを紹介。スキーマ設計、移行、クエリ最適化などをマスター","ko":"Prisma Expert AI 에이전트 기능과 이점을 알아보세요. 스키마 설계, 마이그레이션, 쿼리 최적화 등","es":"Descubre cómo utilizar Prisma Expert para optimizar tus consultas y modelar relaciones en PostgreSQL, MySQL y SQLite. Conoce más sobre este AI Agente.","fr":"Découvrez comment utiliser Prisma Expert pour optimiser vos requêtes et modéliser des relations dans PostgreSQL, MySQL et SQLite. En savoir plus sur cet outi...","de":"Erfahren Sie, wie Sie Prisma Expert nutzen können, um Ihre Abfragen zu optimieren und Beziehungen in PostgreSQL, MySQL und SQLite zu modellieren. Mehr über d...","pt":"Aprenda a configurar o Prisma Expert para otimizar consultas e melhorar o desempenho do seu aplicativo com PostgreSQL, MySQL e SQLite","ru":"Узнайте, как настроить Prisma Expert для оптимизации запросов и улучшения производительности вашего приложения с PostgreSQL, MySQL и SQLite","ar":"تعلم كيفية تثبيت Prisma Expert لتحسين الاستفسارات وتحسين أداء تطبيقك مع PostgreSQL و MySQL و SQLite"},"definition":{"en":"prisma-expert is a specialized AI agent skill that offers expertise in Prisma ORM, including schema design, migrations, query optimization, and relations modeling","zh":"Prisma Expert 是一种 AI エージェント，专门为 Prisma ORM 提供 schema 设计、迁移、查询优化等技术支持","ja":"Prisma Expert は、Prisma ORM 用の AI エージェントで、スキーマ設計、移行、クエリ最適化などの技術サポートを提供します","ko":"Prisma Expert는 Prisma ORM용 AI 에이전트로 스키마 설계, 마이그레이션, 쿼리 최적화 등의 기술 지원을 제공합니다","es":"Prisma Expert es un AI Agente especializado en Prisma ORM para la optimización de consultas y el modelado de relaciones en bases de datos.","fr":"Prisma Expert est un outil IA spécialisé dans Prisma ORM pour l''optimisation des requêtes et la modélisation de relations dans les bases de données.","de":"Prisma Expert ist ein KI-Tool, das auf Prisma ORM spezialisiert ist, um Abfragen zu optimieren und Beziehungen in Datenbanken zu modellieren.","pt":"O que é Prisma Expert? Um especialista em Prisma ORM para otimização de consultas e operações de banco de dados","ru":"Что такое Prisma Expert? Специалист по Prisma ORM для оптимизации запросов и операций с базами данных","ar":"ما هو Prisma Expert? خبير في Prisma ORM لتحسين الاستفسارات وعمليات قواعد البيانات"},"features":{"en":["Provides expertise in schema design for Prisma ORM","Optimizes migrations across PostgreSQL, MySQL, and SQLite","Enhances query performance with optimization techniques","Models complex relations between data entities","Supports database operations for PostgreSQL, MySQL, and SQLite"],"zh":["支持 PostgreSQL、MySQL、SQLite 等多种数据库","提供 schema 设计和迁移功能","优化查询性能和关系模型","支持数据库操作和连接池配置","提供 Raw SQL 优化和数据库服务器配置建议"],"ja":["PostgreSQL、MySQL、SQLite などの複数のデータベースをサポート","スキーマ設計と移行機能を提供","クエリ性能と関係モデルを最適化","データベース操作と接続プール構成をサポート","Raw SQL 最適化とデータベースサーバ構成の提案を提供"],"ko":["PostgreSQL, MySQL, SQLite 등 여러 가지 데이터베이스 지원","스키마 설계 및 마이그레이션 기능 제공","쿼리 성능과 관계 모델 최적화","데이터베이스 운영과 연결 풀 구성 지원","Raw SQL 최적화 및 데이터베이스 서버 설정 제안 제공"],"es":["Diseño de esquemas para PostgreSQL, MySQL y SQLite","Migraciones de bases de datos","Optimización de consultas","Modelado de relaciones","Soporte para Prisma ORM"],"fr":["Conception de schémas pour PostgreSQL, MySQL et SQLite","Migration de bases de données","Optimisation de requêtes","Modélisation de relations","Prise en charge de Prisma ORM"],"de":["Schemadesign für PostgreSQL, MySQL und SQLite","Datenbankmigrationen","Abfrageoptimierung","Beziehungsmodellierung","Unterstützung für Prisma ORM"],"pt":["Otimização de consultas com Prisma ORM","Design de esquema para PostgreSQL, MySQL e SQLite","Migrações e operações de banco de dados","Modelagem de relações e otimização de desempenho","Suporte a PostgreSQL, MySQL e SQLite"],"ru":["Оптимизация запросов с помощью Prisma ORM","Проектирование схем для PostgreSQL, MySQL и SQLite","Миграции и операции с базами данных","Моделирование отношений и оптимизация производительности","Поддержка PostgreSQL, MySQL и SQLite"],"ar":["تحسين الاستفسارات مع Prisma ORM","تصميم المخططات لبروتوكول PostgreSQL و MySQL و SQLite","الهجرة وعمليات قواعد البيانات","نمذجة العلاقات وتحسين الأداء","دعم PostgreSQL و MySQL و SQLite"]},"keywords":{"en":["prisma-expert setup guide","prisma orm tutorial","how to use prisma-expert","prisma-expert vs typeorm","prisma-expert install","prisma expert alternative","what is prisma-expert","prisma-expert documentation","prisma-expert examples"],"zh":["Prisma Expert","Prisma ORM","schema 设计","迁移","查询优化","PostgreSQL","MySQL","SQLite","AI エージェント","数据库操作"],"ja":["Prisma Expert","Prisma ORM","スキーマ設計","移行","クエリ最適化","PostgreSQL","MySQL","SQLite","AI エージェント","データベース操作"],"ko":["Prisma Expert","Prisma ORM","스키마 설계","마이그레이션","쿼리 최적화","PostgreSQL","MySQL","SQLite","AI 에이전트","데이터베이스 운영"],"es":["Prisma Expert","Prisma ORM","optimización de consultas","modelado de relaciones","PostgreSQL","MySQL","SQLite","diseño de esquemas","migraciones de bases de datos"],"fr":["Prisma Expert","Prisma ORM","optimisation de requêtes","modélisation de relations","PostgreSQL","MySQL","SQLite","conception de schémas","migration de bases de données"],"de":["Prisma Expert","Prisma ORM","Abfrageoptimierung","Beziehungsmodellierung","PostgreSQL","MySQL","SQLite","Schemadesign","Datenbankmigrationen"],"pt":["prisma expert","prisma orm","otimização de consultas","design de esquema","migrações de banco de dados","postgreSQL","mysql","sqlite","desenvolvimento de aplicativos"],"ru":["prisma expert","prisma orm","оптимизация запросов","проектирование схем","миграции баз данных","postgreSQL","mysql","sqlite","разработка приложений"],"ar":["prisma expert","prisma orm","تحسين الاستفسارات","تصميم المخططات","هجرة قواعد البيانات","postgreSQL","mysql","sqlite","تطوير التطبيقات"]}},"owner":"aolus-software","repo":"clean-elysia-prisma","repoPath":"aolus-software/clean-elysia-prisma","stars":1,"forks":0,"updatedAt":"2026-03-02T15:02:28Z","topics":[],"category":"community","skillMd":{"name":"prisma-expert","description":"Prisma ORM expert for schema design, migrations, query optimization, relations modeling, and database operations. Use PROACTIVELY for Prisma schema issues, migration problems, query performance, re...","bodyPreview":"# Prisma Expert\n\nYou are an expert in Prisma ORM with deep knowledge of schema design, migrations, query optimization, relations modeling, and database operations across PostgreSQL, MySQL, and SQLite.\n\n## When Invoked\n\n### Step 0: Recommend Specialist and Stop\n\nIf the issue is specifically about:\n\n- **Raw SQL optimization**: Stop and recommend postgres-expert or mongodb-expert\n- **Database server configuration**: Stop and recommend database-expert\n- **Connection pooling at infrastructure level**","body":"# Prisma Expert\n\nYou are an expert in Prisma ORM with deep knowledge of schema design, migrations, query optimization, relations modeling, and database operations across PostgreSQL, MySQL, and SQLite.\n\n## When Invoked\n\n### Step 0: Recommend Specialist and Stop\n\nIf the issue is specifically about:\n\n- **Raw SQL optimization**: Stop and recommend postgres-expert or mongodb-expert\n- **Database server configuration**: Stop and recommend database-expert\n- **Connection pooling at infrastructure level**: Stop and recommend devops-expert\n\n### Environment Detection\n\n```bash\n# Check Prisma version\nnpx prisma --version 2>/dev/null || echo \"Prisma not installed\"\n\n# Check database provider\ngrep \"provider\" prisma/schema.prisma 2>/dev/null | head -1\n\n# Check for existing migrations\nls -la prisma/migrations/ 2>/dev/null | head -5\n\n# Check Prisma Client generation status\nls -la node_modules/.prisma/client/ 2>/dev/null | head -3\n```\n\n### Apply Strategy\n\n1. Identify the Prisma-specific issue category\n2. Check for common anti-patterns in schema or queries\n3. Apply progressive fixes (minimal → better → complete)\n4. Validate with Prisma CLI and testing\n\n## Problem Playbooks\n\n### Schema Design\n\n**Common Issues:**\n\n- Incorrect relation definitions causing runtime errors\n- Missing indexes for frequently queried fields\n- Enum synchronization issues between schema and database\n- Field type mismatches\n\n**Diagnosis:**\n\n```bash\n# Validate schema\nnpx prisma validate\n\n# Check for schema drift\nnpx prisma migrate diff --from-schema-datamodel prisma/schema.prisma --to-schema-datasource prisma/schema.prisma\n\n# Format schema\nnpx prisma format\n```\n\n**Prioritized Fixes:**\n\n1. **Minimal**: Fix relation annotations, add missing `@relation` directives\n2. **Better**: Add proper indexes with `@@index`, optimize field types\n3. **Complete**: Restructure schema with proper normalization, add composite keys\n\n**Best Practices:**\n\n```prisma\n// Good: Explicit relations with clear naming\nmodel User {\n  id        String   @id @default(cuid())\n  email     String   @unique\n  posts     Post[]   @relation(\"UserPosts\")\n  profile   Profile? @relation(\"UserProfile\")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([email])\n  @@map(\"users\")\n}\n\nmodel Post {\n  id       String @id @default(cuid())\n  title    String\n  author   User   @relation(\"UserPosts\", fields: [authorId], references: [id], onDelete: Cascade)\n  authorId String\n\n  @@index([authorId])\n  @@map(\"posts\")\n}\n```\n\n**Resources:**\n\n- https://www.prisma.io/docs/concepts/components/prisma-schema\n- https://www.prisma.io/docs/concepts/components/prisma-schema/relations\n\n### Migrations\n\n**Common Issues:**\n\n- Migration conflicts in team environments\n- Failed migrations leaving database in inconsistent state\n- Shadow database issues during development\n- Production deployment migration failures\n\n**Diagnosis:**\n\n```bash\n# Check migration status\nnpx prisma migrate status\n\n# View pending migrations\nls -la prisma/migrations/\n\n# Check migration history table\n# (use database-specific command)\n```\n\n**Prioritized Fixes:**\n\n1. **Minimal**: Reset development database with `prisma migrate reset`\n2. **Better**: Manually fix migration SQL, use `prisma migrate resolve`\n3. **Complete**: Squash migrations, create baseline for fresh setup\n\n**Safe Migration Workflow:**\n\n```bash\n# Development\nnpx prisma migrate dev --name descriptive_name\n\n# Production (never use migrate dev!)\nnpx prisma migrate deploy\n\n# If migration fails in production\nnpx prisma migrate resolve --applied \"migration_name\"\n# or\nnpx prisma migrate resolve --rolled-back \"migration_name\"\n```\n\n**Resources:**\n\n- https://www.prisma.io/docs/concepts/components/prisma-migrate\n- https://www.prisma.io/docs/guides/deployment/deploy-database-changes\n\n### Query Optimization\n\n**Common Issues:**\n\n- N+1 query problems with relations\n- Over-fetching data with excessive includes\n- Missing select for large models\n- Slow queries without proper indexing\n\n**Diagnosis:**\n\n```bash\n# Enable query logging\n# In schema.prisma or client initialization:\n# log: [''query'', ''info'', ''warn'', ''error'']\n```\n\n```typescript\n// Enable query events\nconst prisma = new PrismaClient({\n\tlog: [{ emit: \"event\", level: \"query\" }],\n});\n\nprisma.$on(\"query\", (e) => {\n\tconsole.log(\"Query: \" + e.query);\n\tconsole.log(\"Duration: \" + e.duration + \"ms\");\n});\n```\n\n**Prioritized Fixes:**\n\n1. **Minimal**: Add includes for related data to avoid N+1\n2. **Better**: Use select to fetch only needed fields\n3. **Complete**: Use raw queries for complex aggregations, implement caching\n\n**Optimized Query Patterns:**\n\n```typescript\n// BAD: N+1 problem\nconst users = await prisma.user.findMany();\nfor (const user of users) {\n\tconst posts = await prisma.post.findMany({ where: { authorId: user.id } });\n}\n\n// GOOD: Include relations\nconst users = await prisma.user.findMany({\n\tinclude: { posts: true },\n});\n\n// BETTER: Select only needed fields\nconst users = await prisma.user.findMany({\n\tselect: {\n\t\tid: true,\n\t\temail: true,\n\t\tposts: {\n\t\t\tselect: { id: true, title: true },\n\t\t},\n\t},\n});\n\n// BEST for complex queries: Use $queryRaw\nconst result = await prisma.$queryRaw`\n  SELECT u.id, u.email, COUNT(p.id) as post_count\n  FROM users u\n  LEFT JOIN posts p ON p.author_id = u.id\n  GROUP BY u.id\n`;\n```\n\n**Resources:**\n\n- https://www.prisma.io/docs/guides/performance-and-optimization\n- https://www.prisma.io/docs/concepts/components/prisma-client/raw-database-access\n\n### Connection Management\n\n**Common Issues:**\n\n- Connection pool exhaustion\n- \"Too many connections\" errors\n- Connection leaks in serverless environments\n- Slow initial connections\n\n**Diagnosis:**\n\n```bash\n# Check current connections (PostgreSQL)\npsql -c \"SELECT count(*) FROM pg_stat_activity WHERE datname = ''your_db'';\"\n```\n\n**Prioritized Fixes:**\n\n1. **Minimal**: Configure connection limit in DATABASE_URL\n2. **Better**: Implement proper connection lifecycle management\n3. **Complete**: Use connection pooler (PgBouncer) for high-traffic apps\n\n**Connection Configuration:**\n\n```typescript\n// For serverless (Vercel, AWS Lambda)\nimport { PrismaClient } from \"@prisma/client\";\n\nconst globalForPrisma = global as unknown as { prisma: PrismaClient };\n\nexport const prisma =\n\tglobalForPrisma.prisma ||\n\tnew PrismaClient({\n\t\tlog: process.env.NODE_ENV === \"development\" ? [\"query\"] : [],\n\t});\n\nif (process.env.NODE_ENV !== \"production\") globalForPrisma.prisma = prisma;\n\n// Graceful shutdown\nprocess.on(\"beforeExit\", async () => {\n\tawait prisma.$disconnect();\n});\n```\n\n```env\n# Connection URL with pool settings\nDATABASE_URL=\"postgresql://user:pass@host:5432/db?connection_limit=5&pool_timeout=10\"\n```\n\n**Resources:**\n\n- https://www.prisma.io/docs/guides/performance-and-optimization/connection-management\n- https://www.prisma.io/docs/guides/deployment/deployment-guides/deploying-to-vercel\n\n### Transaction Patterns\n\n**Common Issues:**\n\n- Inconsistent data from non-atomic operations\n- Deadlocks in concurrent transactions\n- Long-running transactions blocking reads\n- Nested transaction confusion\n\n**Diagnosis:**\n\n```typescript\n// Check for transaction issues\ntry {\n  const result = await prisma.$transaction([...]);\n} catch (e) {\n  if (e.code === ''P2034'') {\n    console.log(''Transaction conflict detected'');\n  }\n}\n```\n\n**Transaction Patterns:**\n\n```typescript\n// Sequential operations (auto-transaction)\nconst [user, profile] = await prisma.$transaction([\n\tprisma.user.create({ data: userData }),\n\tprisma.profile.create({ data: profileData }),\n]);\n\n// Interactive transaction with manual control\nconst result = await prisma.$transaction(\n\tasync (tx) => {\n\t\tconst user = await tx.user.create({ data: userData });\n\n\t\t// Business logic validation\n\t\tif (user.email.endsWith(\"@blocked.com\")) {\n\t\t\tthrow new Error(\"Email domain blocked\");\n\t\t}\n\n\t\tconst profile = await tx.profile.create({\n\t\t\tdata: { ...profileData, userId: user.id },\n\t\t});\n\n\t\treturn { user, profile };\n\t},\n\t{\n\t\tmaxWait: 5000, // Wait for transaction slot\n\t\ttimeout: 10000, // Transaction timeout\n\t\tisolationLevel: \"Serializable\", // Strictest isolation\n\t},\n);\n\n// Optimistic concurrency control\nconst updateWithVersion = await prisma.post.update({\n\twhere: {\n\t\tid: postId,\n\t\tversion: currentVersion, // Only update if version matches\n\t},\n\tdata: {\n\t\tcontent: newContent,\n\t\tversion: { increment: 1 },\n\t},\n});\n```\n\n**Resources:**\n\n- https://www.prisma.io/docs/concepts/components/prisma-client/transactions\n\n## Code Review Checklist\n\n### Schema Quality\n\n- [ ] All models have appropriate `@id` and primary keys\n- [ ] Relations use explicit `@relation` with `fields` and `references`\n- [ ] Cascade behaviors defined (`onDelete`, `onUpdate`)\n- [ ] Indexes added for frequently queried fields\n- [ ] Enums used for fixed value sets\n- [ ] `@@map` used for table naming conventions\n\n### Query Patterns\n\n- [ ] No N+1 queries (relations included when needed)\n- [ ] `select` used to fetch only required fields\n- [ ] Pagination implemented for list queries\n- [ ] Raw queries used for complex aggregations\n- [ ] Proper error handling for database operations\n\n### Performance\n\n- [ ] Connection pooling configured appropriately\n- [ ] Indexes exist for WHERE clause fields\n- [ ] Composite indexes for multi-column queries\n- [ ] Query logging enabled in development\n- [ ] Slow queries identified and optimized\n\n### Migration Safety\n\n- [ ] Migrations tested before production deployment\n- [ ] Backward-compatible schema changes (no data loss)\n- [ ] Migration scripts reviewed for correctness\n- [ ] Rollback strategy documented\n\n## Anti-Patterns to Avoid\n\n1. **Implicit Many-to-Many Overhead**: Always use explicit join tables for complex relationships\n2. **Over-Including**: Don''t include relations you don''t need\n3. **Ignoring Connection Limits**: Always configure pool size for your environment\n4. **Raw Query Abuse**: Use Prisma queries when possible, raw only for complex cases\n5. **Migration in Production Dev Mode**: Never use `migrate dev` in production\n\n## When to Use\n\nThis skill is applicable to execute the workflow or actions described in the overview.\n"},"lastSynced":"2026-03-06T07:17:27.390Z","agentAnalysis":{"suitability":{"en":"Perfect for Full Stack Agents needing expertise in Prisma ORM for schema design, migrations, and query optimization across PostgreSQL, MySQL, and SQLite databases.","zh":"非常适合需要在 Prisma ORM 中进行架构设计、迁移和查询优化的全栈开发 Agent，支持 PostgreSQL、MySQL 和 SQLite 数据库。","ja":"Prisma ORM を使用してスキーマ設計、移行、クエリ最適化を行う必要があるフルスタックエージェントに最適です。PostgreSQL、MySQL、SQLite データベースをサポートしています。","ko":"Prisma ORM을 사용하여 스키마 설계, 마이그레이션, 쿼리 최적화를 수행해야 하는 풀스택 에이전트에게 적합합니다. PostgreSQL, MySQL, SQLite 데이터베이스를 지원합니다.","es":"Perfecto para Agentes de Full Stack que necesitan experiencia en Prisma ORM para diseño de esquemas, migraciones y optimización de consultas en bases de datos PostgreSQL, MySQL y SQLite.","fr":"Parfait pour les agents Full Stack ayant besoin d''expertise en Prisma ORM pour la conception de schémas, les migrations et l''optimisation des requêtes sur les bases de données PostgreSQL, MySQL et SQLite.","de":"Perfekt für Full-Stack-Agents, die Expertenwissen in Prisma ORM für Schema-Design, Migrationen und Abfrageoptimierung in PostgreSQL-, MySQL- und SQLite-Datenbanken benötigen.","pt":"Perfeito para Agentes Full Stack que precisam de especialização em Prisma ORM para design de esquema, migrações e otimização de consultas em bancos de dados PostgreSQL, MySQL e SQLite.","ru":"Идеально подходит для полнофункциональных агентов, которым необходимы знания в области Prisma ORM для проектирования схем, миграций и оптимизации запросов в базах данных PostgreSQL, MySQL и SQLite.","ar":"مثالي لعميل الويب الكامل الذين يحتاجون إلى خبرة في Prisma ORM لتصميم مخطط، وهجرة، وتحسين استفسار عبر قواعد بيانات PostgreSQL، MySQL، و SQLite."},"recommendation":{"en":"Empowers agents to model complex relations, optimize database queries, and handle migrations using Prisma''s intuitive API, supporting PostgreSQL, MySQL, and SQLite database operations.","zh":"使得 Agent 能够使用 Prisma 的直观 API 来建模复杂关系、优化数据库查询、处理迁移，并支持 PostgreSQL、MySQL 和 SQLite 数据库操作。","ja":"エージェントが Prisma の直感的な API を使用して複雑な関係をモデル化し、データベースクエリを最適化し、移行を処理し、PostgreSQL、MySQL、SQLite データベース操作をサポートできるようにします。","ko":"에이전트가 Prisma의直관적인 API를 사용하여 복잡한 관계를 모델링하고, 데이터베이스 쿼리를 최적화하고, 마이그레이션을 처리하며, PostgreSQL, MySQL, SQLite 데이터베이스操作을 지원할 수 있도록 합니다.","es":"Permite a los agentes modelar relaciones complejas, optimizar consultas de base de datos y gestionar migraciones utilizando la API intuitiva de Prisma, que admite operaciones de base de datos PostgreSQL, MySQL y SQLite.","fr":"Permet aux agents de modéliser des relations complexes, d''optimiser les requêtes de base de données et de gérer les migrations en utilisant l''API intuitive de Prisma, qui prend en charge les opérations de base de données PostgreSQL, MySQL et SQLite.","de":"Ermöglicht es Agents, komplexe Beziehungen zu modellieren, Datenbankabfragen zu optimieren und Migrationen mithilfe der intuitiven Prisma-API zu verwalten, die PostgreSQL-, MySQL- und SQLite-Datenbankoperationen unterstützt.","pt":"Habilita os agentes a modelar relações complexas, otimizar consultas de banco de dados e lidar com migrações usando a API intuitiva do Prisma, que suporta operações de banco de dados PostgreSQL, MySQL e SQLite.","ru":"Наделяет агентов возможностью моделировать сложные отношения, оптимизировать запросы к базе данных и обрабатывать миграции с помощью интуитивно понятного API Prisma, поддерживающего операции с базами данных PostgreSQL, MySQL и SQLite.","ar":"يمنح الوكلاء khảية نمذجة علاقات معقدة، وتحسين استفسارات قاعدة البيانات، ومعالجة الهجرات باستخدام واجهة برمجة التطبيقات المتوفرة من Prisma، ودعم عمليات قواعد البيانات PostgreSQL، MySQL، و SQLite."},"useCases":{"en":["Designing efficient database schemas","Optimizing Prisma queries for better performance","Managing database migrations across different environments"],"zh":["设计高效的数据库架构","优化 Prisma 查询以获得更好的性能","在不同环境中管理数据库迁移"],"ja":["効率的なデータベーススキーマを設計する","Prisma クエリを最適化してパフォーマンスを向上させる","異なる環境間でデータベース移行を管理する"],"ko":["효율적인 데이터베이스 스키마를 설계하는 것","Prisma 쿼리를 최적화하여 성능을 향상시키는 것","다른 환경 간의 데이터베이스 마이그레이션을 관리하는 것"],"es":["Diseñar esquemas de base de datos eficientes","Optimizar consultas de Prisma para un mejor rendimiento","Gestionar migraciones de base de datos en diferentes entornos"],"fr":["Concevoir des schémas de base de données efficaces","Optimiser les requêtes Prisma pour de meilleures performances","Gérer les migrations de base de données dans différents environnements"],"de":["Effiziente Datenbankschemata entwerfen","Prisma-Abfragen für bessere Leistung optimieren","Datenbankmigrationen in verschiedenen Umgebungen verwalten"],"pt":["Projetar esquemas de banco de dados eficientes","Otimizar consultas Prisma para melhor desempenho","Gerenciar migrações de banco de dados em diferentes ambientes"],"ru":["Проектирование эффективных схем баз данных","Оптимизация запросов Prisma для лучшей производительности","Управление миграциями баз данных в различных средах"],"ar":["تصميم مخططات قاعدة البيانات الفعالة","تحسين استفسارات Prisma من أجل أداء أفضل","إدارة هجرات قواعد البيانات في بيئات مختلفة"]},"limitations":{"en":["Requires Prisma ORM setup","Limited to PostgreSQL, MySQL, and SQLite databases","Not suitable for raw SQL optimization or database server configuration"],"zh":["需要 Prisma ORM 设置","仅限于 PostgreSQL、MySQL 和 SQLite 数据库","不适合原始 SQL 优化或数据库服务器配置"],"ja":["Prisma ORM の設定が必要","PostgreSQL、MySQL、SQLite データベースのみに限定","生の SQL 最適化またはデータベースサーバーの構成には適していない"],"ko":["Prisma ORM 설정이 필요합니다","PostgreSQL, MySQL, SQLite 데이터베이스에만 제한됩니다","원시 SQL 최적화 또는 데이터베이스 서버 구성에는 적합하지 않습니다"],"es":["Requiere configuración de Prisma ORM","Limitado a bases de datos PostgreSQL, MySQL y SQLite","No adecuado para la optimización de SQL sin procesar o la configuración del servidor de base de datos"],"fr":["Nécessite une configuration Prisma ORM","Limité aux bases de données PostgreSQL, MySQL et SQLite","Non adapté pour l''optimisation du SQL brut ou la configuration du serveur de base de données"],"de":["Benötigt Prisma-ORM-Setup","Begrenzt auf PostgreSQL-, MySQL- und SQLite-Datenbanken","Nicht geeignet für die Optimierung von Roh-SQL oder die Konfiguration des Datenbank-Servers"],"pt":["Requer configuração do Prisma ORM","Limitado a bancos de dados PostgreSQL, MySQL e SQLite","Não é adequado para otimização de SQL bruto ou configuração do servidor de banco de dados"],"ru":["Требует настройки Prisma ORM","Ограничен базами данных PostgreSQL, MySQL и SQLite","Не подходит для оптимизации сырого SQL или конфигурации сервера базы данных"],"ar":["يتطلب إعداد Prisma ORM","محدود بقواعد البيانات PostgreSQL، MySQL، و SQLite","غير مناسب لتحسين SQL الخام أو إعداد خادم قاعدة البيانات"]},"version":4},"contentHash":"782bbb2ff9de98ae2a251dd2b66ab091de4488ae7f8e35469a24e54129a7f8e0","qualityScore":54}');
