INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bankielewicz/DevForgeAI/managing-finances', 'managing-finances', 'bankielewicz', 'DevForgeAI', 'community', 'managing-finances bankielewicz DevForgeAI community ai-agents ai-development-framework ai-orchestration architectural-constraints claude-code cli-tool code-quality developer-tools devops-automation quality-gates software-architecture spec-driven-development subagents tdd test-driven-development zero-technical-debt The managing-finances skill helps entrepreneurs develop financial plans, including pricing models and revenue projections, using AI-powered spec-driven development and automated quality gates. 管理财务技能使用AI驱动的规格驱动开发框架，实现零技术债务，帮助企业家开发财务计划 経営財務管理スキルは、AIエージェントを活用したテスト駆動開発と自動化された品質ゲートで財務計画を立てる 재정 관리 스킬은 AI 에이전트를 활용한 테스트 주도 개발과 자동화된 품질 게이트로 효율적인 재정 계획 수립을 지원 Nuestro marco de desarrollo de gestión de finanzas utiliza TDD y arquitectura inmutable para garantizar cero deuda técnica Notre cadre de développement de gestion des finances utilise le TDD et l''architecture immuable pour garantir zéro dette technique Unser Entwicklungsmuster für Finanzmanagement verwendet TDD und immutables Architektur, um null technische Schulden zu gewährleisten O skill de gerenciamento de finanças ajuda empreendedores a desenvolver planos financeiros, incluindo modelos de preços e projeções de receita, com AI Agents Навык управления финансами помогает предпринимателям разрабатывать финансовые планы, включая модели ценообразования и прогнозы доходов, с ИИ Агентами تساعد مهارة إدارة المالية رواد الأعمال على تطوير خطط مالية، بما في ذلك نماذج التسعير والتنبؤات الإيرادية، مع وكلاء الذكاء الاصطناعي how to use managing-finances for financial planning what is managing-finances AI agent managing-finances alternative for entrepreneurs managing-finances vs traditional financial modeling managing-finances install and setup guide ai-driven financial planning with managing-finances AI驱动的财务管理 规格驱动开发框架 测试驱动开发 自动化质量门 零技术债务 AI 에이전트集成 财务计划开发 Gathers business context through Phase 1: Financial Context Discovery Utilizes Test-Driven Development (TDD) for mandatory quality assurance Enforces immutable architectural constraints for robust software architecture Supports automated quality gates for zero technical debt Provides workflow phases for financial modeling and cost structure analysis managing-finances is a spec-driven development framework for financial planning, utilizing 26+ specialized subagents and enforcing zero technical debt from ideation to release.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mi-erasmusmc/ema-authorised-to-rxnorm-mappings/map-latvia-drugs', 'community', 'mi-erasmusmc', 'ema-authorised-to-rxnorm-mappings', 'mi-erasmusmc/ema-authorised-to-rxnorm-mappings', 'map-latvia-drugs', 1, 0, 54, '2026-03-06T19:53:28Z', '2026-03-07T01:55:40.705Z', 'd96889cc08aacad955afb71e4052b90e64b1e3a557bccbe12a63e697eb03f5fc', '{"id":"mi-erasmusmc/ema-authorised-to-rxnorm-mappings/map-latvia-drugs","name":"map-latvia-drugs","description":{"en":"The map-latvia-drugs skill maps European Medicines Agency authorised medicinal products to RxNorm standard concepts, benefiting developers working with Latvian national medicinal products.","zh":"Map-Latvia-Drugs是一种将拉脱维亚国家药品映射到RxNorm标准概念的工具，用于提高药品数据的一致性和准确性","ja":"Map-Latvia-Drugsはラトビアの医薬品をRxNorm標準概念にマッピングするツールです","ko":"Map-Latvia-Drugs는 라트비아 약품을 RxNorm 표준 개념으로 매핑하는 도구로 약품 데이터의 일관성과 정확성을 높입니다","es":"Map-latvia-drugs es una herramienta que mapea productos medicinales letones autorizados por la EMA a conceptos standard de RxNorm.","fr":"Map-latvia-drugs est un outil qui mappe des produits médicaux lettons autorisés par l''EMA à des concepts standard de RxNorm.","de":"Map-latvia-drugs ist ein Tool, das lettische Arzneimittel, die von der EMA zugelassen sind, auf RxNorm-Standardkonzepte mappt.","pt":"O map-latvia-drugs é uma habilidade que mapeia produtos medicinais letões para conceitos RxNorm. Ele é usado para criar ou revisar arquivos de mapeamento","ru":"Map-latvia-drugs - это навык, который сопоставляет лекарственные препараты Латвии с концепциями RxNorm. Он используется для создания или проверки файлов сопоставления","ar":"map-latvia-drugs هو مهارة لتحويل المنتجات الطبية اللاتفية إلى مفاهيم RxNorm. يستخدم لإنشاء أو مراجعة ملفات التحويل"},"seo":{"title":{"en":"map-latvia-drugs: RxNorm Mapping Guide for AI Agents","zh":"Latvia药品映射指南 - Map-Latvia-Drugs Setup Guide","ja":"ラトビア医薬品マッピングツール - Map-Latvia-Drugs AIエージェント","ko":"라트비아 약품 매핑 가이드 - Map-Latvia-Drugs Setup Guide","es":"Guía de configuración para map-latvia-drugs: Mapeo de Med...","fr":"Guide de mise en place de map-latvia-drugs: Mapping de mé...","de":"Einrichtungsleitfaden für map-latvia-drugs: Medikamenten-...","pt":"Guia de Configuração do map-latvia-drugs para Mapeamento ...","ru":"Настройка map-latvia-drugs: ИИ Агенты для Сопоставления Л...","ar":"دليل الإعداد ل map-latvia-drugs لتحويل المنتجات الطبية"},"description":{"en":"Discover how to map Latvian medicinal products to RxNorm concepts with the map-latvia-drugs skill. Learn how to create and review mapping.tsv files today!","zh":"了解如何使用Map-Latvia-Drugs将拉脱维亚国家药品映射到RxNorm标准概念，提高药品数据的一致性和准确性","ja":"ラトビアの医薬品をRxNorm標準概念にマッピングする方法を学び、薬品データのの一貫性と正確性を高める","ko":"라트비아 약품을 RxNorm 표준 개념으로 매핑하는 방법을 알아보고 약품 데이터의 일관성과 정확성을 높여보세요","es":"Aprende a mapear productos medicinales letones a conceptos estándar de RxNorm con map-latvia-drugs, una herramienta de agente de inteligencia artificial","fr":"Découvrez comment mapper des produits médicaux lettons à des concepts standard RxNorm avec map-latvia-drugs, un outil d''agent d''intelligence artificielle","de":"Erfahren Sie, wie Sie lettische Arzneimittel auf RxNorm-Standardkonzepte mit map-latvia-drugs, einem KI-Tool, mappen","pt":"Aprenda a configurar o map-latvia-drugs para mapear produtos medicinais letões para conceitos RxNorm","ru":"Узнайте, как настроить map-latvia-drugs для сопоставления лекарственных препаратов Латвии с концепциями RxNorm","ar":"تعرف على كيفية ضبط map-latvia-drugs لتحويل المنتجات الطبية اللاتفية إلى مفاهيم RxNorm"},"definition":{"en":"map-latvia-drugs is a skill that enables mapping of Latvian national medicinal products to RxNorm standard concepts, utilizing input files from product folders.","zh":"Map-Latvia-Drugs是一种将拉脱维亚国家药品映射到RxNorm标准概念的AI工具","ja":"Map-Latvia-Drugsはラトビアの医薬品をRxNorm標準概念にマッピングするAIエージェントです","ko":"Map-Latvia-Drugs는 라트비아 약품을 RxNorm 표준 개념으로 매핑하는 AI 도구입니다","es":"Map-latvia-drugs es un agente de inteligencia artificial que mapea productos medicinales letones a conceptos de RxNorm","fr":"Map-latvia-drugs est un agent d''intelligence artificielle qui mappe des produits médicaux lettons à des concepts de RxNorm","de":"Map-latvia-drugs ist ein KI-Agent, der lettische Arzneimittel auf RxNorm-Konzepte mappt","pt":"O map-latvia-drugs é uma habilidade de mapeamento de medicamentos que relaciona produtos medicinais letões com conceitos RxNorm","ru":"Map-latvia-drugs - это навык сопоставления лекарств, который связывает лекарственные препараты Латвии с концепциями RxNorm","ar":"map-latvia-drugs هو مهارة لتحويل الأدوية التي تربط المنتجات الطبية اللاتفية بمفاهيم RxNorm"},"features":{"en":["Maps Latvian national medicinal products to RxNorm standard concepts","Utilizes input files from product folders under data/latvia/products/<active_substance>/<product_name>/","Creates and reviews mapping.tsv files","Follows general mapping principles from the map-drugs skill","Searches for RxNorm concepts using the find-concepts skill","Supports mapping of medicinal products to RxNorm concepts for Latvia"],"zh":["支持拉脱维亚国家药品到RxNorm标准概念的映射","使用RxNorm概念进行药品数据的一致性和准确性检查","集成find-concepts技能进行RxNorm概念搜索","支持mapping.tsv文件的创建和审查"],"ja":["ラトビアの医薬品をRxNorm標準概念にマッピングする機能","RxNorm概念を使用した薬品データの一貫性と正確性のチェック","find-conceptsスキルとの統合によるRxNorm概念検索","mapping.tsvファイルの作成とレビューのサポート"],"ko":["라트비아 약품을 RxNorm 표준 개념으로 매핑하는 기능","RxNorm 개념을 사용한 약품 데이터의 일관성과 정확성 확인","find-concepts 스킬과의 통합으로 RxNorm 개념 검색","mapping.tsv 파일의 생성과審查를 지원"],"es":["Mapeo de productos medicinales letones a conceptos standard de RxNorm","Compatibilidad con la búsqueda de conceptos de RxNorm","Generación de archivos de mapeo en formato TSV","Integración con la habilidad de búsqueda de conceptos","Soporte para la creación y revisión de archivos de mapeo"],"fr":["Mapping de produits médicaux lettons à des concepts standard de RxNorm","Compatibilité avec la recherche de concepts de RxNorm","Génération de fichiers de mappage au format TSV","Intégration avec la compétence de recherche de concepts","Prise en charge de la création et de la révision de fichiers de mappage"],"de":["Mappen von lettischen Arzneimitteln auf RxNorm-Standardkonzepte","Kompatibilität mit der Suche nach RxNorm-Konzepten","Erstellung von Mappings-Dateien im TSV-Format","Integration mit der Fähigkeit zur Suche nach Konzepten","Unterstützung für die Erstellung und Überprüfung von Mappings-Dateien"],"pt":["Mapeamento de produtos medicinais letões para conceitos RxNorm","Criação e revisão de arquivos de mapeamento","Utilização da habilidade find-concepts para buscar conceitos RxNorm","Utilização da habilidade map-drugs para princípios gerais de mapeamento","Suporte a pastas de produtos em data/latvia/products/<active_substance>/<product_name>/"],"ru":["Сопоставление лекарственных препаратов Латвии с концепциями RxNorm","Создание и проверка файлов сопоставления","Использование навыка find-concepts для поиска концепций RxNorm","Использование навыка map-drugs для общих принципов сопоставления","Поддержка папок продуктов в data/latvia/products/<active_substance>/<product_name>/"],"ar":["تحويل المنتجات الطبية اللاتفية إلى مفاهيم RxNorm","إنشاء ومراجعة ملفات التحويل","استخدام مهارة find-concepts للبحث عن مفاهيم RxNorm","استخدام مهارة map-drugs لمبادئ عامة للتحويل","دعم مجلدات المنتجات في data/latvia/products/<active_substance>/<product_name>/"]},"keywords":{"en":["how to use map-latvia-drugs","map-latvia-drugs setup guide","RxNorm mapping for Latvian medicinal products","map-latvia-drugs alternative","map-latvia-drugs vs EMA mapping","install map-latvia-drugs","what is map-latvia-drugs","map-latvia-drugs tutorial","mapping Latvian medicinal products to RxNorm"],"zh":["Map-Latvia-Drugs","拉脱维亚药品映射","RxNorm标准概念","药品数据一致性","AI工具","find-concepts技能","mapping.tsv文件"],"ja":["Map-Latvia-Drugs","ラトビア医薬品マッピング","RxNorm標準概念","薬品データの一貫性","AIエージェント","find-conceptsスキル","mapping.tsvファイル"],"ko":["Map-Latvia-Drugs","라트비아 약품 매핑","RxNorm 표준 개념","약품 데이터 일관성","AI 도구","find-concepts 스킬","mapping.tsv 파일"],"es":["map-latvia-drugs","mapeo de medicamentos","RxNorm","EMA","agente de inteligencia artificial","herramientas de desarrollo","mapeo de conceptos","buscar conceptos de RxNorm","generar archivos de mapeo"],"fr":["map-latvia-drugs","mapping de médicaments","RxNorm","EMA","agent d''intelligence artificielle","outils de développement","mapping de concepts","rechercher des concepts de RxNorm","générer des fichiers de mappage"],"de":["map-latvia-drugs","Medikamenten-Mapping","RxNorm","EMA","KI-Tool","Entwickler-Tools","Konzept-Mapping","RxNorm-Konzepte suchen","Mappen-Dateien erstellen"],"pt":["map-latvia-drugs","mapeamento de medicamentos","conceitos RxNorm","habilidade find-concepts","habilidade map-drugs","pastas de produtos","data/latvia/products/","RxNorm","medicamentos letões"],"ru":["map-latvia-drugs","сопоставление лекарств","концепции RxNorm","навык find-concepts","навык map-drugs","папки продуктов","data/latvia/products/","RxNorm","лекарственные препараты Латвии"],"ar":["map-latvia-drugs","تحويل الأدوية","مفاهيم RxNorm","مهارة find-concepts","مهارة map-drugs","مجلدات المنتجات","data/latvia/products/","RxNorm","المنتجات الطبية اللاتفية"]}},"owner":"mi-erasmusmc","repo":"ema-authorised-to-rxnorm-mappings","repoPath":"mi-erasmusmc/ema-authorised-to-rxnorm-mappings","stars":1,"forks":0,"updatedAt":"2026-03-06T19:53:28Z","topics":[],"category":"community","skillMd":{"name":"map-latvia-drugs","description":"Map Latvian national medicinal products to RxNorm standard concepts. Use when asked to map a Latvian product or create/review a mapping.tsv in a Latvia product folder.","bodyPreview":"# Map Drugs: Latvian Products\r\n\r\nMap Latvian national medicinal products to RxNorm standard concepts.\r\n\r\n## When to Use\r\n\r\nWhen asked to map a Latvian product to RxNorm, or create/review a `mapping.tsv` in a Latvia product folder.\r\n\r\n## Prerequisites\r\n\r\nRefer to the `find-concepts` skill for how to search for RxNorm concepts, and the `map-drugs` skill for general mapping principles.\r\n\r\n## Input Files\r\n\r\nEach product folder under `data/latvia/products/<active_substance>/<product_name>/` contains:","body":"# Map Drugs: Latvian Products\r\n\r\nMap Latvian national medicinal products to RxNorm standard concepts.\r\n\r\n## When to Use\r\n\r\nWhen asked to map a Latvian product to RxNorm, or create/review a `mapping.tsv` in a Latvia product folder.\r\n\r\n## Prerequisites\r\n\r\nRefer to the `find-concepts` skill for how to search for RxNorm concepts, and the `map-drugs` skill for general mapping principles.\r\n\r\n## Input Files\r\n\r\nEach product folder under `data/latvia/products/<active_substance>/<product_name>/` contains:\r\n- **`data_<date>.tsv`**: Presentation-level data with `product_id`, `original_name`, `strength`, `pharmaceutical_form`, `product_strength` (total dose/volume), `package_en`, and `package_size`. **This is the primary input — read it first.**\r\n- **`info.txt`**: Product metadata with `short_name`, `active_substance`, `marketing_authorisation_holder`, `manufacturer`, `atc_code`, and links to PIL and SmPC\r\n\r\nThe parent folder name is the active substance (Latin name), and the product folder name is the brand name.\r\n\r\n## Output Format\r\n\r\nCreate `mapping.tsv` in the product folder following the schema in the `map-drugs` skill. The source ID column is `product_id` (Latvian product registry ID).\r\n\r\n## Mapping Workflow\r\n\r\n1. **Read `data_*.tsv`** to get all presentations — this has `product_id`, `strength`, `pharmaceutical_form`, and `product_strength` (total dose/volume) for every registered package\r\n2. **Read `info.txt`** to get the active substance (English name from Latin folder name) and brand name\r\n3. **Only check the SmPC link** if `data_*.tsv` does not provide enough detail to make an informed mapping decision (e.g., ambiguous dose form, unclear concentration basis)\r\n4. **Search broadly** using the `find-concepts` skill:\r\n   ```\r\n   python3 .claude/skills/find-concepts/scripts/find_concepts.py \"warfarin sodium 3 MG Oral Tablet\" \"warfarin 3 mg\" \"warfarin oral tablet\"\r\n   ```\r\n5. **Verify the match** - confirm ingredient and strength match exactly\r\n6. **Validate** the mapping:\r\n   ```\r\n   python3 .claude/skills/map-drugs/validate_mapping.py data/latvia/products/<substance>/<product>/mapping.tsv\r\n   ```\r\n7. **Regenerate combined files** after all mappings are complete:\r\n   ```\r\n   python3 scripts/generate_mapping_overviews.py\r\n   ```\r\n\r\n## Latvia-specific Pitfalls\r\n\r\n- **Latin vs English substance names**: Folders use Latin names (e.g., `warfarinum_natricum`) but RxNorm uses English (e.g., `warfarin sodium`)\r\n- **Products without RxNorm equivalent**: Leave concept fields empty, populate `suggestion`\r\n"},"lastSynced":"2026-03-07T01:55:40.705Z","agentAnalysis":{"suitability":{"en":"Perfect for Pharmaceutical Agents needing to map Latvian medicinal products to RxNorm standard concepts.","zh":"非常适合需要将拉脱维亚药品与RxNorm标准概念映射的药品代理人。","ja":"ラトビアの医薬品をRxNorm標準概念にマッピングする必要がある医薬品エージェントに最適。","ko":"라트비아의 약품을 RxNorm 표준 개념으로 매핑해야 하는 의약품 에이전트에게 적합합니다.","es":"Perfecto para agentes farmacéuticos que necesitan asignar productos medicinales letones a conceptos estándar de RxNorm.","fr":"Parfait pour les agents pharmaceutiques ayant besoin de mapper les produits médicinaux lettons aux concepts standards RxNorm.","de":"Perfekt für pharmazeutische Agenten, die lettische Arzneimittel zu RxNorm-Standardkonzepten zuordnen müssen.","pt":"Perfeito para Agentes Farmacêuticos que precisam mapear produtos medicinais letões para conceitos padrão RxNorm.","ru":"Идеально подходит для фармацевтических агентов, которым необходимо сопоставить латвийские лекарственные препараты со стандартными понятиями RxNorm.","ar":"مثالي للوكلاء الصيدلانيين الذين يحتاجون إلى تخطيط منتجات الأدوية اللاتفية إلى مفاهيم معيارية RxNorm."},"recommendation":{"en":"Empowers agents to accurately map European Medicines Agency authorised medicinal products to RxNorm standard concepts, leveraging `mapping.tsv` files and RxNorm concepts for seamless integration, utilizing the `find-concepts` and `map-drugs` skills for comprehensive medicinal product analysis.","zh":"赋予代理人准确映射欧洲药品管理局批准的药品到RxNorm标准概念的能力，利用`mapping.tsv`文件和RxNorm概念实现无缝集成，使用`find-concepts`和`map-drugs`技能进行全面药品分析。","ja":"欧州医薬品庁が認可した医薬品をRxNorm標準概念に正確にマッピングするエージェントの能力を提供し、`mapping.tsv`ファイルとRxNorm概念を利用してシームレスな統合を実現し、包括的な医薬品分析のために`find-concepts`と`map-drugs`スキルを使用します。","ko":"의약품 에이전트에게 유럽 의약품 기구가 승인한 의약품을 RxNorm 표준 개념으로 정확하게 매핑할 수 있는 능력을 부여하고, `mapping.tsv` 파일과 RxNorm 개념을 활용하여 무縫 통합을 구현하며, 포괄적인 의약품 분석을 위해 `find-concepts`와 `map-drugs` 스킬을 사용합니다.","es":"Habilita a los agentes a asignar productos medicinales autorizados por la Agencia Europea de Medicamentos a conceptos estándar de RxNorm, aprovechando archivos `mapping.tsv` y conceptos de RxNorm para una integración sin problemas, utilizando las habilidades `find-concepts` y `map-drugs` para un análisis integral de productos medicinales.","fr":"Permet aux agents de mapper avec précision les produits médicinaux autorisés par l''Agence européenne des médicaments aux concepts standards RxNorm, en exploitant les fichiers `mapping.tsv` et les concepts RxNorm pour une intégration transparente, en utilisant les compétences `find-concepts` et `map-drugs` pour une analyse complète des produits médicinaux.","de":"Ermächtigt Agenten, Arzneimittel, die von der Europäischen Arzneimittelagentur zugelassen sind, genau auf RxNorm-Standardkonzepte abzubilden, indem es `mapping.tsv`-Dateien und RxNorm-Konzepte für eine nahtlose Integration nutzt und die Fähigkeiten `find-concepts` und `map-drugs` für eine umfassende Analyse von Arzneimitteln verwendet.","pt":"Habilita os agentes a mapear com precisão os produtos medicinais autorizados pela Agência Europeia de Medicamentos para conceitos padrão RxNorm, utilizando arquivos `mapping.tsv` e conceitos RxNorm para integração sem problemas, utilizando as habilidades `find-concepts` e `map-drugs` para análise abrangente de produtos medicinais.","ru":"Наделяет агентов возможностью точно сопоставить лекарственные препараты, авторизованные Европейским агентством по лекарственным средствам, со стандартными понятиями RxNorm, используя файлы `mapping.tsv` и понятия RxNorm для бесшовной интеграции, используя навыки `find-concepts` и `map-drugs` для всестороннего анализа лекарственных препаратов.","ar":"يُمكن للوكلاء بشكل دقيق ربط منتجات الأدوية المعتمدة من قبل وكالة الأدوية الأوروبية بمفاهيم معيارية RxNorm، مستخدمين ملفات `mapping.tsv` ومفاهيم RxNorm من أجل التكامل السلس، مستخدمين مهارات `find-concepts` و `map-drugs` من أجل تحليل شامل لمنتجات الأدوية."},"useCases":{"en":["Mapping Latvian national medicinal products to RxNorm standard concepts","Creating and reviewing `mapping.tsv` files for Latvia product folders","Searching for RxNorm concepts using the `find-concepts` skill"],"zh":["将拉脱维亚国家药品映射到RxNorm标准概念","为拉脱维亚产品文件夹创建和审查`mapping.tsv`文件","使用`find-concepts`技能搜索RxNorm概念"],"ja":["ラトビア国薬品をRxNorm標準概念にマッピングする","ラトビア製品フォルダーの`mapping.tsv`ファイルを作成およびレビューする","`find-concepts`スキルを使用してRxNorm概念を検索する"],"ko":["라트비아 국립 약품을 RxNorm 표준 개념으로 매핑하는 것","라트비아 제품 폴더를 위한 `mapping.tsv` 파일을 생성하고 검토하는 것","`find-concepts` 스킬을 사용하여 RxNorm 개념을 검색하는 것"],"es":["Asignar productos medicinales nacionales letones a conceptos estándar de RxNorm","Crear y revisar archivos `mapping.tsv` para carpetas de productos letones","Buscar conceptos de RxNorm utilizando la habilidad `find-concepts`"],"fr":["Mapper les produits médicinaux nationaux lettons aux concepts standards RxNorm","Créer et examiner les fichiers `mapping.tsv` pour les dossiers de produits lettons","Rechercher des concepts RxNorm en utilisant la compétence `find-concepts`"],"de":["Lettische nationale Arzneimittel zu RxNorm-Standardkonzepten zuordnen","Erstellen und Überprüfen von `mapping.tsv`-Dateien für lettische Produktordner","RxNorm-Konzepte mit der Fähigkeit `find-concepts` suchen"],"pt":["Mapear produtos medicinais nacionais letões para conceitos padrão RxNorm","Criar e revisar arquivos `mapping.tsv` para pastas de produtos letões","Procurar conceitos RxNorm usando a habilidade `find-concepts`"],"ru":["Сопоставить латвийские национальные лекарственные препараты со стандартными понятиями RxNorm","Создать и просмотреть файлы `mapping.tsv` для папок продуктов Латвии","Искать понятия RxNorm с помощью навыка `find-concepts`"],"ar":["ربط منتجات الأدوية الوطنية اللاتفية بمفاهيم معيارية RxNorm","إنشاء ومراجعة ملفات `mapping.tsv` لمجلدات منتجات لاتفيا","بحث مفاهيم RxNorm باستخدام مهارة `find-concepts`"]},"limitations":{"en":["Requires knowledge of RxNorm standard concepts","Limited to Latvian national medicinal products","Dependent on `find-concepts` and `map-drugs` skills for prerequisites"],"zh":["需要RxNorm标准概念的知识","仅限拉脱维亚国家药品","依赖`find-concepts`和`map-drugs`技能作为先决条件"],"ja":["RxNorm標準概念の知識が必要","ラトビア国薬品のみ","先行条件として`find-concepts`および`map-drugs`スキルに依存"],"ko":["RxNorm 표준 개념에 대한 지식이 필요함","라트비아 국립 약품에만 제한됨","`find-concepts`와 `map-drugs` 스킬을 전제 조건으로 사용하여 의존함"],"es":["Requiere conocimiento de los conceptos estándar de RxNorm","Limitado a productos medicinales nacionales letones","Dependiente de las habilidades `find-concepts` y `map-drugs` para los requisitos previos"],"fr":["Nécessite une connaissance des concepts standards RxNorm","Limité aux produits médicinaux nationaux lettons","Dépend des compétences `find-concepts` et `map-drugs` pour les prérequis"],"de":["Benötigt Kenntnisse der RxNorm-Standardkonzepte","Begrenzt auf nationale lettische Arzneimittel","Abhängig von den Fähigkeiten `find-concepts` und `map-drugs` für die Voraussetzungen"],"pt":["Exige conhecimento de conceitos padrão RxNorm","Limitado a produtos medicinais nacionais letões","Dependente das habilidades `find-concepts` e `map-drugs` para pré-requisitos"],"ru":["Требует знания стандартных понятий RxNorm","Ограничен латвийскими национальными лекарственными препаратами","Зависит от навыков `find-concepts` и `map-drugs` для предварительных требований"],"ar":["يتطلب معرفة بمفاهيم معيارية RxNorm","محدود بمنتجات الأدوية الوطنية اللاتفية","يعتمد على مهارات `find-concepts` و `map-drugs` للشروط المسبقة"]},"version":4},"contentHash":"d96889cc08aacad955afb71e4052b90e64b1e3a557bccbe12a63e697eb03f5fc","qualityScore":54}');
