INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mi-erasmusmc/ema-authorised-to-rxnorm-mappings/map-latvia-drugs', 'map-latvia-drugs', 'mi-erasmusmc', 'ema-authorised-to-rxnorm-mappings', 'community', 'map-latvia-drugs mi-erasmusmc ema-authorised-to-rxnorm-mappings community The map-latvia-drugs skill maps European Medicines Agency authorised medicinal products to RxNorm standard concepts, benefiting developers working with Latvian national medicinal products. Map-Latvia-Drugs是一种将拉脱维亚国家药品映射到RxNorm标准概念的工具，用于提高药品数据的一致性和准确性 Map-Latvia-Drugsはラトビアの医薬品をRxNorm標準概念にマッピングするツールです Map-Latvia-Drugs는 라트비아 약품을 RxNorm 표준 개념으로 매핑하는 도구로 약품 데이터의 일관성과 정확성을 높입니다 Map-latvia-drugs es una herramienta que mapea productos medicinales letones autorizados por la EMA a conceptos standard de RxNorm. Map-latvia-drugs est un outil qui mappe des produits médicaux lettons autorisés par l''EMA à des concepts standard de RxNorm. Map-latvia-drugs ist ein Tool, das lettische Arzneimittel, die von der EMA zugelassen sind, auf RxNorm-Standardkonzepte mappt. O map-latvia-drugs é uma habilidade que mapeia produtos medicinais letões para conceitos RxNorm. Ele é usado para criar ou revisar arquivos de mapeamento Map-latvia-drugs - это навык, который сопоставляет лекарственные препараты Латвии с концепциями RxNorm. Он используется для создания или проверки файлов сопоставления map-latvia-drugs هو مهارة لتحويل المنتجات الطبية اللاتفية إلى مفاهيم RxNorm. يستخدم لإنشاء أو مراجعة ملفات التحويل how to use map-latvia-drugs map-latvia-drugs setup guide RxNorm mapping for Latvian medicinal products map-latvia-drugs alternative map-latvia-drugs vs EMA mapping install map-latvia-drugs what is map-latvia-drugs map-latvia-drugs tutorial mapping Latvian medicinal products to RxNorm Map-Latvia-Drugs 拉脱维亚药品映射 RxNorm标准概念 药品数据一致性 AI工具 find-concepts技能 mapping.tsv文件 Maps Latvian national medicinal products to RxNorm standard concepts Utilizes input files from product folders under data/latvia/products/<active_substance>/<product_name>/ Creates and reviews mapping.tsv files Follows general mapping principles from the map-drugs skill Searches for RxNorm concepts using the find-concepts skill Supports mapping of medicinal products to RxNorm concepts for Latvia map-latvia-drugs is a skill that enables mapping of Latvian national medicinal products to RxNorm standard concepts, utilizing input files from product folders.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('D7460N/starter/d7460n-css-only', 'community', 'D7460N', 'starter', 'D7460N/starter', 'd7460n-css-only', 1, 0, 54, '2026-03-07T12:12:32Z', '2026-03-07T12:51:32.752Z', '178aa6ac255fdb9489776509de111bfedb4d6d3ec47c7e67b52475a7d8d583f1', '{"id":"D7460N/starter/d7460n-css-only","name":"d7460n-css-only","description":{"en":"The d7460n-css-only skill ensures compliance with the zero-dependency, CSS-only, browser-native architecture for the D7460N Project Starter. It benefits developers working on CSS3, grid, and HTML projects.","zh":"D7460N CSS-only 架构是一种零依赖、浏览器原生、CSS-only 的开发架构，用于创建快速、安全、可维护的 Web 应用","ja":"D7460N CSS-only アーキテクチャは、ゼロ依存、ブラウザネイティブ、CSS-only の開発アーキテクチャであり、高速、安全、維持可能な Web アプリケーションを作成するために使用される","ko":"D7460N CSS-only 아키텍처는 제로 의존성, 브라우저 네이티브, CSS-only 개발 아키텍처이며, 빠른, 안전한, 유지 보수가 가능한 Web 애플리케이션을 생성하는 데 사용된다","es":"D7460N CSS-only es una arquitectura de proyecto que utiliza CSS puro y separación de concerns para crear aplicaciones web mínimas y eficientes","fr":"D7460N CSS-only est une architecture de projet qui utilise du CSS pur et une séparation de préoccupations pour créer des applications web minimales et efficaces","de":"D7460N CSS-only ist eine Projektarchitektur, die reinen CSS und Trennung von Bedenken verwendet, um minimale und effiziente Webanwendungen zu erstellen","pt":"O D7460N CSS-only é uma arquitetura de projeto que utiliza CSS nativo do navegador e zero dependências. Ele é ideal para projetos web que requerem uma estrutura leve e flexível.","ru":"D7460N CSS-only — это архитектура проекта, использующая браузерный CSS и не имеющая зависимостей. Она идеальна для веб-проектов, требующих лёгкой и гибкой структуры.","ar":"D7460N CSS-only هو هندسة مشروع تستخدم السي إس إس الأصلي للمتصفح وبدون تبعيات. وهي مثالية لمشاريع الويب التي تتطلب هيكلا خفيفا ومرونا"},"seo":{"title":{"en":"d7460n-css-only: CSS-only Architecture Setup Guide | AI A...","zh":"D7460N CSS-only 架构设置指南","ja":"D7460N CSS-only アーキテクチャのベストプラクティス","ko":"D7460N CSS-only 아키텍처 설정 가이드","es":"Guía de configuración de D7460N CSS-only para arquitectur...","fr":"Guide de mise en place de D7460N CSS-only pour les archit...","de":"Einrichtungsleitfaden für D7460N CSS-only-Architekturen","pt":"Guia de Configuração do D7460N CSS-only","ru":"Настройка D7460N CSS-only: ИИ Агенты для веб-разработки","ar":"دليل إعداد D7460N CSS-only لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to implement zero-dependency, CSS-only architecture with d7460n-css-only. Learn best practices and get started with the D7460N Project Starter t...","zh":"了解如何使用 D7460N CSS-only 架构，实现零依赖、浏览器原生、CSS-only 的开发","ja":"D7460N CSS-only アーキテクチャを使用して、ゼロ依存、ブラウザネイティブ、CSS-only の開発を実現する","ko":"D7460N CSS-only 아키텍처를 사용하여 제로 의존성, 브라우저 네이티브, CSS-only 개발을 구현하는 방법","es":"Aprende a utilizar D7460N CSS-only para crear aplicaciones web con arquitectura de separación de concerns y sin dependencias","fr":"Découvrez comment utiliser D7460N CSS-only pour créer des applications web avec une architecture de séparation de préoccupations et sans dépendances","de":"Erfahren Sie, wie Sie D7460N CSS-only verwenden, um Webanwendungen mit Architektur der Trennung von Bedenken und ohne Abhängigkeiten zu erstellen","pt":"Aprenda a configurar o D7460N CSS-only para projetos web com arquitetura zero-dependência e CSS nativo do navegador","ru":"Изучите настройку D7460N CSS-only для веб-проектов с архитектурой без зависимостей и браузерным CSS","ar":"تعرف على كيفية إعداد D7460N CSS-only لمشاريع الويب ذات الهندسة المعمارية بدون تبعيات والسي إس إس الأصلي للمتصفح"},"definition":{"en":"d7460n-css-only is a CSS-only architecture skill for the D7460N Project Starter, ensuring zero-dependency and browser-native compliance.","zh":"D7460N CSS-only 架构是一种开发架构，使用 CSS3 和 HTML 实现零依赖、浏览器原生、CSS-only 的开发","ja":"D7460N CSS-only アーキテクチャは、CSS3 と HTML を使用してゼロ依存、ブラウザネイティブ、CSS-only の開発を実現する開発アーキテクチャである","ko":"D7460N CSS-only 아키텍처는 CSS3와 HTML을 사용하여 제로 의존성, 브라우저 네이티브, CSS-only 개발을 구현하는 개발 아키텍처이다","es":"D7460N CSS-only es una arquitectura de proyecto que utiliza CSS puro y separación de concerns","fr":"D7460N CSS-only est une architecture de projet qui utilise du CSS pur et une séparation de préoccupations","de":"D7460N CSS-only ist eine Projektarchitektur, die reinen CSS und Trennung von Bedenken verwendet","pt":"O que é D7460N CSS-only? É uma arquitetura de projeto que utiliza CSS nativo do navegador e zero dependências para criar projetos web leves e flexíveis.","ru":"Что такое D7460N CSS-only? Это архитектура проекта, использующая браузерный CSS и не имеющая зависимостей для создания лёгких и гибких веб-проектов.","ar":"ما هو D7460N CSS-only؟ هو هندسة مشروع تستخدم السي إس إس الأصلي للمتصفح وبدون تبعيات لإنشاء مشاريع الويب الخفيفة والمرونة"},"features":{"en":["Implements CSS-only architecture for the D7460N Project Starter","Ensures zero-dependency and browser-native compliance","Supports CSS3, grid, and HTML development","Requires reading SESSION-HANDOFF.md before implementation decisions","Enforces Session Continuity with Constraint Lock"],"zh":["使用 CSS3 和 HTML 实现零依赖、浏览器原生、CSS-only 的开发","支持 Grid 和 PWA 的开发","实现 Session Continuity 和 Constraint Lock","使用 SESSION-HANDOFF.md 文件进行开发指导","支持多种开发技术，包括 Baselines、Separation-of-Concerns 和 Standards"],"ja":["CSS3 と HTML を使用してゼロ依存、ブラウザネイティブ、CSS-only の開発を実現","Grid と PWA の開発をサポート","Session Continuity と Constraint Lock を実現","SESSION-HANDOFF.md ファイルを使用して開発をガイド","Baselines、Separation-of-Concerns、Standards などの開発技術をサポート"],"ko":["CSS3와 HTML을 사용하여 제로 의존성, 브라우저 네이티브, CSS-only 개발을 구현","Grid와 PWA의 개발을 지원","Session Continuity와 Constraint Lock를 구현","SESSION-HANDOFF.md 파일을 사용하여 개발을 가이드","Baselines, Separation-of-Concerns, Standards 등의 개발 기술을 지원"],"es":["Arquitectura de separación de concerns","Uso de CSS puro y sin dependencias","Compatibilidad con aplicaciones web mínimas y eficientes","Soporte para PWA y SPA","Cumplimiento de los estándares web","Grid y diseño de cuadrícula"],"fr":["Architecture de séparation de préoccupations","Utilisation de CSS pur et sans dépendances","Compatibilité avec des applications web minimales et efficaces","Prise en charge de PWA et SPA","Respect des normes web","Grille et conception de grille"],"de":["Architektur der Trennung von Bedenken","Verwendung von reinem CSS und ohne Abhängigkeiten","Kompatibilität mit minimalen und effizienten Webanwendungen","Unterstützung für PWA und SPA","Einhaltung der Webstandards","Gitter und Gitterdesign"],"pt":["Arquitetura zero-dependência","CSS nativo do navegador","Projetos web leves e flexíveis","Compatibilidade com padrões web","Separação de preocupações entre HTML, CSS e JavaScript"],"ru":["Архитектура без зависимостей","Браузерный CSS","Лёгкие и гибкие веб-проекты","Совместимость с веб-стандартами","Разделение проблем между HTML, CSS и JavaScript"],"ar":["هندسة بدون تبعيات","السي إس إس الأصلي للمتصفح","مشاريع الويب الخفيفة والمرونة","التوافق مع معايير الويب","فصل المشاكل بين HTML و CSS و JavaScript"]},"keywords":{"en":["how to use d7460n-css-only","d7460n-css-only setup guide","css-only architecture benefits","d7460n-css-only vs other frameworks","d7460n-css-only install","what is d7460n-css-only","d7460n-css-only alternative","d7460n-css-only best practices"],"zh":["D7460N CSS-only","AIエージェント","零依赖开发","浏览器原生开发","CSS-only 开发","Grid 开发","PWA 开发","Session Continuity","Constraint Lock"],"ja":["D7460N CSS-only","AIエージェント","ゼロ依存開発","ブラウザネイティブ開発","CSS-only 開発","Grid 開発","PWA 開発","Session Continuity","Constraint Lock"],"ko":["D7460N CSS-only","AI 에이전트","제로 의존성 개발","브라우저 네이티브 개발","CSS-only 개발","Grid 개발","PWA 개발","Session Continuity","Constraint Lock"],"es":["D7460N CSS-only","arquitectura de proyecto","separación de concerns","CSS puro","aplicaciones web mínimas","PWA","SPA","estándares web","grid","diseño de cuadrícula"],"fr":["D7460N CSS-only","architecture de projet","séparation de préoccupations","CSS pur","applications web minimales","PWA","SPA","normes web","grille","conception de grille"],"de":["D7460N CSS-only","Projektarchitektur","Trennung von Bedenken","reiner CSS","minimale Webanwendungen","PWA","SPA","Webstandards","Gitter","Gitterdesign"],"pt":["D7460N CSS-only","arquitetura de projeto","CSS nativo do navegador","projetos web leves","zero dependências","padrões web","separação de preocupações"],"ru":["D7460N CSS-only","архитектура проекта","браузерный CSS","лёгкие веб-проекты","без зависимостей","веб-стандарты","разделение проблем"],"ar":["D7460N CSS-only","هندسة مشروع","السي إس إس الأصلي للمتصفح","مشاريع الويب الخفيفة","بدون تبعيات","معايير الويب","فصل المشاكل"]}},"owner":"D7460N","repo":"starter","repoPath":"D7460N/starter","stars":1,"forks":0,"updatedAt":"2026-03-07T12:12:32Z","topics":["baslines","css","css3","d7460n","grid","html","minimal","pwa","separation-of-concerns","spa","standards","starter","starter-project"],"category":"community","skillMd":{"name":"d7460n-css-only","description":"D7460N Architecture — zero-dependency, CSS-only, JAMstack-based, browser-native starter template. Use when modifying HTML, CSS, or JS files in this project. Enforces CSS-driven UI state, semantic HTML, no frameworks, no dependencies, and strict separation of concerns between presentation and data layers.","bodyPreview":"# D7460N CSS-only Architecture\n\n## When to use this skill\n\nUse this skill when working on any file in the D7460N Architecture starter template. This ensures all changes comply with the zero-dependency, CSS-only, browser-native architecture.\n\n## Session Continuity (Non-Negotiable)\n\n- At the start of every session, ALWAYS read `SESSION-HANDOFF.md` before making implementation decisions.\n- ALWAYS re-assert the handoff \"Constraint Lock\" before coding changes.\n- If `SESSION-HANDOFF.md` conflicts with","body":"# D7460N CSS-only Architecture\n\n## When to use this skill\n\nUse this skill when working on any file in the D7460N Architecture starter template. This ensures all changes comply with the zero-dependency, CSS-only, browser-native architecture.\n\n## Session Continuity (Non-Negotiable)\n\n- At the start of every session, ALWAYS read `SESSION-HANDOFF.md` before making implementation decisions.\n- ALWAYS re-assert the handoff \"Constraint Lock\" before coding changes.\n- If `SESSION-HANDOFF.md` conflicts with canonical architecture rules, STOP and ask for clarification.\n- NEVER skip handoff review due to time pressure.\n\n## Non-Negotiable Rules\n\n1. Unless otherwise indicated, this code base shall NEVER default to, NEVER consider, NEVER refer to, NEVER suggest, and NEVER use third party dependencies.\n2. Third party dependencies are defined as any packaged code or system that is not able render natively (without assistance) or must be compiled and or pre-built to run in an evergreen web browser.\n3. Unless otherwise indicated, this code base shall ALWAYS default to, ALWAYS consider, ALWAYS refer to, ALWAYS suggest, and ALWAYS use modern, advanced, vanilla, W3C/WCAG standards compliant, accessibility-first, syntax, techniques, approaches, strategies for all project design and development.\n4. Established standards can ALWAYS be found here, (https://www.w3.org/TR/) and here (https://developer.mozilla.org/en-US/docs/Web).\n5. Unless otherwise indicated, this code base shall ALWAYS default to Single Page Application (SPA) navigational architecture.\n6. Unless otherwise indicated, this code base shall ALWAYS default to being a Progressive Web Application (PWA).\n7. Unless otherwise indicated, JS shall NEVER be used for anything (exception: modular `assets/js/*.js` runtime files for API transport, `oninput` lifecycle orchestration, storage, and startup wiring). Modern HTML and CSS must be used for all development.\n8. Unless otherwise indicated, CSS shall ALWAYS default to and ALWAYS replace JS equivalent functionality.\n9. Unless otherwise indicated, JS shall ALWAYS default to and ALWAYS use `document.querySelector('''');` for targeting all selectors.\n10. Unless otherwise indicated, JS shall ALWAYS default to and ALWAYS use `oninput` for ALL API CRUD operations through a shared lifecycle utility.\n11. Unless otherwise indicated, JS shall NEVER default to and NEVER use any user initiated event for any API CRUD operations.\n12. Unless otherwise indicated, JS shall NEVER default to and NEVER set or use any event listeners.\n13. Unless otherwise indicated, JS shall NEVER default to and NEVER set or use any listeners at all - ever.\n14. Unless otherwise indicated, HTML shall ALWAYS default to and ALWAYS use `<label>`.\n15. Unless otherwise indicated, HTML markup shall ALWAYS default to and ALWAYS be semantic, minimally nested, and intuitive to developers.\n16. Unless otherwise indicated, the principal of Separation of Concerns between presentation and data layers shall ALWAYS be maintained.\n17. Unless otherwise indicated, the principal of Least Power shall ALWAYS be maintained.\n18. Unless otherwise indicated, CSS shall ALWAYS default to and ALWAYS determine DOM element visibility via `:empty` and `:has()` pseudo selectors.\n19. Unless otherwise indicated, CSS shall ALWAYS default to and ALWAYS use modern CSS style queries and other CSS only combinations of modern CSS techniques to design and build functionality without requiring hard or static values that would otherwise need to be maintained.\n20. Unless otherwise indicated, CSS shall ALWAYS default to and ALWAYS manage light and dark mode color-scheme syntax and variables in `:root{}`.\n21. Unless otherwise indicated, CSS shall ALWAYS default to and ALWAYS use a11y selectors when possible.\n22. Unless otherwise indicated, CSS shall ALWAYS default to and ALWAYS use checkboxes inside `<label>`s with `role=\"button\"` combined with `:has()`, `:not`, and `:empty()` for state machines.\n23. Unless otherwise indicated, CSS shall ALWAYS default to and ALWAYS use a radio buttons inside a `<label>` with `role=\"button\"` combined with `:has()`, `:not`, and `:empty()` inside `<nav>` for global navigation.\n24. Unless otherwise indicated, HTML shall ALWAYS default to and ALWAYS use one single file, `index.html` at project root.\n25. Unless otherwise indicated, HTML shall ALWAYS default to and ALWAYS be a full-bleed Holy Grail layout using the skeletal layout markup found in the `index.html` file.\n26. Unless otherwise indicated, `<div>` and `<span>` shall NEVER be used. ALWAYS use semantic HTML equivalents that address the intent of the element.\n27. Unless otherwise indicated, wrapper elements shall NEVER be nested for layout purposes. ALWAYS use CSS Grid solutions instead (e.g., `grid-template-columns` and `justify-content: space-between`).\n\n## Architecture\n\n- **index.html** (root): Complete DOM structure, pre-built\n- **assets/css/layout.css**: The only active CSS file; CSS Grid Holy Grail structure and all current layout\n- **assets/js/app.js**: JS entrypoint; startup checks, console reset, and initialization wiring\n- **assets/js/oninput.js**: Shared `oninput` lifecycle; binds nav inputs, routes API calls, and injects data\n- **assets/js/api.js**: API transport utilities; base URL, endpoint suffix resolution, fetch/parse, and logging helpers\n- **assets/js/storage.js**: Generic storage utilities (localStorage primary, cookie fallback)\n- **assets/js/tour.js**: Safe placeholder module for future onboarding/tour logic\n- **assets/images/**: Static assets\n\n### Ignored (inactive for now)\n\n- **assets/js/pipeline/**: Inactive; ignore for now\n- **assets/css/*.css** (other than `layout.css`): Inactive; ignore for now\n\n## When modifying this project\n\n- All UI states, including loading states, use CSS and HTML checkboxes as state machines\n- Keep JS focused on fetch/CRUD only\n- Always only ever use semantic HTML markup\n- Never use `<div>`, `<span>`, `class`, `data-*`, or `id` — `<div>` and `<span>` shall NEVER be used; ALWAYS use semantic HTML equivalents that address the intent of the element\n- NEVER nest wrapper elements for layout — ALWAYS use CSS Grid instead (e.g., `grid-template-columns` and `justify-content: space-between`)\n- NEVER create new coding patterns — all patterns are already established; use what exists\n- Adding code increases entropy — NEVER add new code or files unless the user explicitly states to\n- Follow user instructions in detail — no more, no less\n\n## JS Runtime Conventions (Non-Negotiable)\n\n- API base address is declared once; only endpoint suffix varies (for example `shell`, `home`, `about`, `products`, `events`, `contact`)\n- Initial page load MUST enter the same `oninput` lifecycle path via programmatic nav radio `.click()`\n- Shell content (`header`, `nav`, `footer`, `meta`) is fetched/injected once per runtime session, not on every page call\n- Nav radio index maps to page endpoint suffix; same DOM targets are reused for injection\n- Console reporting policy: minimal timestamped success reports, verbose timestamped failure reports, and `console.clear()` on startup and each lifecycle run\n\n## HTML Layout Pattern\n\nThe full-bleed Holy Grail layout from `index.html`. This is the canonical structure — ALWAYS follow this pattern unless otherwise stated or a more efficient way is discovered.\n\n```html\n<app-container>\n  <header>\n    <app-logo></app-logo>\n    <app-user></app-user>\n  </header>\n  <nav>\n    <label>\n      <input type=\"radio\" aria-hidden=\"true\" name=\"nav\">\n    </label>\n  </nav>\n  <main>\n    <article>\n      <h1></h1>\n      <section></section>\n    </article>\n  </main>\n  <aside></aside>\n  <footer>\n    <app-legal></app-legal>\n    <app-version></app-version>\n  </footer>\n</app-container>\n```\n\n### Layout Regions\n\n- **`<app-container>`** — Root layout wrapper; CSS Grid Holy Grail structure\n- **`<header>`** — Contains `<app-logo>` and `<app-user>` custom elements\n- **`<nav>`** — Global navigation; radio button `<label>` state machines (see State Machine Pattern below)\n- **`<main>`** — Primary content area; contains `<article>` with `<h1>`, `<p>`, `<section>` elements\n- **`<aside>`** — Sidebar/supplementary content\n- **`<footer>`** — Contains `<app-legal>` and `<app-version>` custom elements\n- **`<script type=\"module\">`** — Single script tag at end of `<body>`, outside `<app-container>`\n\n## State Machines\n\nConsist of four parts . . .\n\n- HTML `<label>` element\n- HTML `<input type=\"checkbox\">` or `<input type=\"radio\">` - nested inside the `<label>`\n- CSS `:has()` for UI change\n- JS `oninput` for API CRUD operations\n\n. . . and are built with this vanilla HTML design pattern.\n\n```html\n<label role=\"button\">\n  label text\n  <input type=\"checkbox\">\n</label>\n```\n\nGlobal nav items will be exactly the same but use `<input type=\"radio\" name=\"nav\">`\n\n```html\n<nav>\n  <label role=\"button\">\n    global nav item 01\n    <input type=\"radio\" name=\"nav\">\n  </label>\n  <label role=\"button\">\n    global nav item 02\n    <input type=\"radio\" name=\"nav\">\n  </label>\n  <label role=\"button\">\n    global nav item 03\n    <input type=\"radio\" name=\"nav\">\n  </label>\n  <label role=\"button\">\n    global nav item 04\n    <input type=\"radio\" name=\"nav\">\n  </label>\n  <label role=\"button\">\n    global nav item 05\n    <input type=\"radio\" name=\"nav\">\n  </label>\n<nav>\n```\n"},"lastSynced":"2026-03-07T12:51:32.752Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Agents specializing in CSS3, grid, and HTML projects, ensuring compliance with zero-dependency, browser-native architectures.","zh":"适用于专注于CSS3、grid和HTML项目的前端代理，确保遵守零依赖、浏览器原生架构。","ja":"CSS3、グリッド、HTMLプロジェクトを専門とするフロントエンドエージェントに最適で、ゼロ依存、ブラウザネイティブアーキテクチャへの準拠を保証します。","ko":"CSS3, 그리드, HTML 프로젝트를 전문으로 하는 프론트엔드 에이전트에 적합하며, 제로 의존성, 브라우저 네이티브 아키텍처의 준수를 보장합니다.","es":"Ideal para agentes de frontend especializados en CSS3, grid y proyectos HTML, garantizando el cumplimiento de arquitecturas nativas del navegador con cero dependencias.","fr":"Idéal pour les agents de frontend spécialisés dans CSS3, grid et les projets HTML, garantissant le respect des architectures natives du navigateur avec zéro dépendance.","de":"Ideal für Frontend-Agenten, die auf CSS3, grid und HTML-Projekte spezialisiert sind, um die Einhaltung von browsernativen Architekturen mit null Abhängigkeiten zu gewährleisten.","pt":"Ideal para Agentes de Frontend especializados em CSS3, grid e projetos HTML, garantindo a conformidade com arquiteturas nativas do navegador e sem dependências.","ru":"Идеально подходит для агентов Frontend, специализирующихся на CSS3, grid и проектах HTML, обеспечивающих соблюдение требований к архитектурам, не зависящим от браузера и не имеющим зависимостей.","ar":"مثالي لعميل واجهة المستخدم المتخصص في CSS3 و grid و مشاريع HTML، مما يضمن امتثالها للمعماريات الأصلية للمتصفح بدون تبعيات."},"recommendation":{"en":"Empowers agents to enforce CSS-only, zero-dependency compliance, leveraging browser-native capabilities for D7460N Project Starter templates, ensuring adherence to session continuity constraints via SESSION-HANDOFF.md.","zh":"赋予代理人强制执行CSS-only、零依赖性合规性，利用浏览器原生功能来实现D7460N项目启动模板，通过SESSION-HANDOFF.md确保会话连续性约束。","ja":"エージェントがCSSのみ、ゼロ依存性のコンプライアンスを強制することを可能にし、D7460Nプロジェクトスターター テンプレートのブラウザネイティブ機能を利用してセッション連続性の制約をSESSION-HANDOFF.md経由で確保します。","ko":"에이전트가 CSS만, 제로 의존성 컴플라이언스를 강제할 수 있도록 하며, D7460N 프로젝트 스타터 템플릿의 브라우저 네이티브 기능을 활용하여 SESSION-HANDOFF.md를 통해 세션 연속성 제약을 보장합니다.","es":"Habilita a los agentes a aplicar el cumplimiento de solo CSS, con cero dependencias, aprovechando las capacidades nativas del navegador para las plantillas de inicio del proyecto D7460N, garantizando el cumplimiento de las restricciones de continuidad de sesión a través de SESSION-HANDOFF.md.","fr":"Permet aux agents d''appliquer le respect de l''architecture CSS uniquement, avec zéro dépendance, en exploitant les capacités natives du navigateur pour les modèles de démarrage de projet D7460N, en garantissant le respect des contraintes de continuité de session via SESSION-HANDOFF.md.","de":"Ermächtigt die Agenten, die Einhaltung von CSS-only, null-Abhängigkeits-Compliance durchzusetzen, indem sie die browsernativen Fähigkeiten für die D7460N-Projekt-Starter-Vorlagen nutzen, um die Einhaltung der Sitzungsfortsetzungsbeschränkungen über SESSION-HANDOFF.md sicherzustellen.","pt":"Habilita os agentes a impor a conformidade apenas com CSS, sem dependências, aproveitando as capacidades nativas do navegador para os modelos de inicialização do projeto D7460N, garantindo a adesão às restrições de continuidade da sessão via SESSION-HANDOFF.md.","ru":"Наделяет агентов возможностью обеспечивать соблюдение требований только для CSS, без зависимостей, используя возможности браузера для шаблонов проекта D7460N, обеспечивая соблюдение ограничений на непрерывность сессии через SESSION-HANDOFF.md.","ar":"يمكّن الوكلاء من فرض امتثال CSS فقط، بدون تبعيات، مستفيداً من قدرات المتصفح الأصلية لقوالب مشروع D7460N، وضمان الامتثال لقيود استمرارية الجلسة عبر SESSION-HANDOFF.md."},"useCases":{"en":["Enforcing CSS-only architecture in D7460N projects","Validating HTML and CSS3 compliance in grid-based layouts","Maintaining session continuity through SESSION-HANDOFF.md"],"zh":["在D7460N项目中强制执行CSS-only架构","验证基于网格布局的HTML和CSS3合规性","通过SESSION-HANDOFF.md保持会话连续性"],"ja":["D7460NプロジェクトでCSSのみアーキテクチャを強制する","グリッドベースのレイアウトでのHTMLとCSS3のコンプライアンスを検証する","SESSION-HANDOFF.md経由でセッション連続性を維持する"],"ko":["D7460N 프로젝트에서 CSS만 아키텍처를 강제한다","그리드 기반 레이아웃의 HTML 및 CSS3 컴플라이언스를 검증한다","SESSION-HANDOFF.md를 통해 세션 연속성을 유지한다"],"es":["Aplicar la arquitectura de solo CSS en proyectos D7460N","Validar el cumplimiento de HTML y CSS3 en diseños basados en grid","Mantener la continuidad de la sesión a través de SESSION-HANDOFF.md"],"fr":["Appliquer l''architecture CSS uniquement dans les projets D7460N","Valider le respect de HTML et CSS3 dans les dispositions basées sur grid","Maintenir la continuité de session via SESSION-HANDOFF.md"],"de":["Die CSS-only-Architektur in D7460N-Projekten durchsetzen","Die Einhaltung von HTML und CSS3 in gridbasierten Layouts überprüfen","Die Sitzungsfortsetzung über SESSION-HANDOFF.md aufrechterhalten"],"pt":["Impor arquitetura apenas com CSS em projetos D7460N","Validar conformidade HTML e CSS3 em layouts baseados em grid","Manter a continuidade da sessão através do SESSION-HANDOFF.md"],"ru":["Обеспечивать соблюдение архитектуры только для CSS в проектах D7460N","Проверять соблюдение требований для HTML и CSS3 в макетах на основе сетки","Сохранять непрерывность сессии через SESSION-HANDOFF.md"],"ar":["فرض هيكل CSS فقط في مشاريع D7460N","التحقق من امتثال HTML و CSS3 في تخطيطات قائم على الشبكة","الحفاظ على استمرارية الجلسة عبر SESSION-HANDOFF.md"]},"limitations":{"en":["Requires adherence to D7460N Architecture starter template","Mandatory session continuity via SESSION-HANDOFF.md","Limited to CSS3, grid, and HTML projects"],"zh":["需要遵守D7460N架构启动模板","必须通过SESSION-HANDOFF.md保持会话连续性","仅限CSS3、grid和HTML项目"],"ja":["D7460Nアーキテクチャスターター テンプレートへの準拠が必要","SESSION-HANDOFF.md経由でのセッション連続性が必須","CSS3、グリッド、HTMLプロジェクトのみに制限"],"ko":["D7460N 아키텍처 스타터 템플릿의 준수가 필요하다","SESSION-HANDOFF.md를 통해 세션 연속성이 필수다","CSS3, 그리드, HTML 프로젝트만으로 제한된다"],"es":["Requiere la adhesión a la plantilla de arquitectura de inicio del proyecto D7460N","Continuidad de sesión obligatoria a través de SESSION-HANDOFF.md","Limitado a proyectos CSS3, grid y HTML"],"fr":["Nécessite l''adhesion au modèle d''architecture de démarrage de projet D7460N","Continuité de session obligatoire via SESSION-HANDOFF.md","Limité aux projets CSS3, grid et HTML"],"de":["Erfordert die Einhaltung der D7460N-Architektur-Starter-Vorlage","Verpflichtende Sitzungsfortsetzung über SESSION-HANDOFF.md","Begrenzt auf CSS3-, grid- und HTML-Projekte"],"pt":["Exige adesão ao modelo de arquitetura inicial do projeto D7460N","Continuidade da sessão obrigatória via SESSION-HANDOFF.md","Limitado a projetos CSS3, grid e HTML"],"ru":["Требует соблюдения стартового шаблона архитектуры проекта D7460N","Обязательная непрерывность сессии через SESSION-HANDOFF.md","Ограничен проектами CSS3, grid и HTML"],"ar":["يتطلب الالتزام_by TEMPLATE لمشروع D7460N","استمرارية الجلسة الإلزامية عبر SESSION-HANDOFF.md","محدود بمشاريع CSS3 و grid و HTML"]},"version":4},"contentHash":"178aa6ac255fdb9489776509de111bfedb4d6d3ec47c7e67b52475a7d8d583f1","qualityScore":54}');
