INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('D7460N/starter/d7460n-css-only', 'd7460n-css-only', 'D7460N', 'starter', 'community', 'd7460n-css-only D7460N starter community baslines css css3 d7460n grid html minimal pwa separation-of-concerns spa standards starter starter-project The d7460n-css-only skill ensures compliance with the zero-dependency, CSS-only, browser-native architecture for the D7460N Project Starter. It benefits developers working on CSS3, grid, and HTML projects. D7460N CSS-only 架构是一种零依赖、浏览器原生、CSS-only 的开发架构，用于创建快速、安全、可维护的 Web 应用 D7460N CSS-only アーキテクチャは、ゼロ依存、ブラウザネイティブ、CSS-only の開発アーキテクチャであり、高速、安全、維持可能な Web アプリケーションを作成するために使用される D7460N CSS-only 아키텍처는 제로 의존성, 브라우저 네이티브, CSS-only 개발 아키텍처이며, 빠른, 안전한, 유지 보수가 가능한 Web 애플리케이션을 생성하는 데 사용된다 D7460N CSS-only es una arquitectura de proyecto que utiliza CSS puro y separación de concerns para crear aplicaciones web mínimas y eficientes D7460N CSS-only est une architecture de projet qui utilise du CSS pur et une séparation de préoccupations pour créer des applications web minimales et efficaces D7460N CSS-only ist eine Projektarchitektur, die reinen CSS und Trennung von Bedenken verwendet, um minimale und effiziente Webanwendungen zu erstellen O D7460N CSS-only é uma arquitetura de projeto que utiliza CSS nativo do navegador e zero dependências. Ele é ideal para projetos web que requerem uma estrutura leve e flexível. D7460N CSS-only — это архитектура проекта, использующая браузерный CSS и не имеющая зависимостей. Она идеальна для веб-проектов, требующих лёгкой и гибкой структуры. D7460N CSS-only هو هندسة مشروع تستخدم السي إس إس الأصلي للمتصفح وبدون تبعيات. وهي مثالية لمشاريع الويب التي تتطلب هيكلا خفيفا ومرونا how to use d7460n-css-only d7460n-css-only setup guide css-only architecture benefits d7460n-css-only vs other frameworks d7460n-css-only install what is d7460n-css-only d7460n-css-only alternative d7460n-css-only best practices D7460N CSS-only AIエージェント 零依赖开发 浏览器原生开发 CSS-only 开发 Grid 开发 PWA 开发 Session Continuity Constraint Lock Implements CSS-only architecture for the D7460N Project Starter Ensures zero-dependency and browser-native compliance Supports CSS3, grid, and HTML development Requires reading SESSION-HANDOFF.md before implementation decisions Enforces Session Continuity with Constraint Lock d7460n-css-only is a CSS-only architecture skill for the D7460N Project Starter, ensuring zero-dependency and browser-native compliance.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('gnestor/claude-workflow-plugin/recap', 'community', 'gnestor', 'claude-workflow-plugin', 'gnestor/claude-workflow-plugin', 'recap', 0, 0, 54, '2026-02-22T18:41:03Z', '2026-03-07T03:39:29.919Z', '01cfe294f1dfc87cdbe3d2e8a0b3f997f0b28d287a82dba1eae495916d50b105', '{"id":"gnestor/claude-workflow-plugin/recap","name":"recap","description":{"en":"The recap skill summarizes sessions and improves skills based on feedback, ideal for developers and businesses using Claude Code for workflows and agent skills.","zh":"Recap 技术是基于 Claude Code 的会话总结和技能改进工具，用于业务运营","ja":"Recap 技術は、会話をまとめ、スキルを改善する Claude Code ベースのツールです","ko":"Recap 기술은 Claude Code 기반의 세션 요약 및 스킬 개선 도구로, 비즈니스 운영에 사용됩니다","es":"Recap es un resumen de conversaciones para mejorar habilidades con Claude Code. Se utiliza para resumir sesiones y mejorar habilidades.","fr":"Recap est un résumé de conversations pour améliorer les compétences avec Claude Code. Il est utilisé pour résumer les sessions et améliorer les compétences.","de":"Recap ist eine Zusammenfassung von Gesprächen, um Fähigkeiten mit Claude Code zu verbessern. Es wird verwendet, um Sitzungen zusammenzufassen und Fähigkeiten zu verbessern.","pt":"O Recap é uma habilidade de AI que resume sessões e melhora habilidades com base em feedback, utilizando Claude Code para melhorar a eficiência dos processos de negócios","ru":"Recap - это навык ИИ, который суммирует сессии и улучшает навыки на основе обратной связи, используя Claude Code для повышения эффективности бизнес-процессов","ar":"Recap هي مهارة الذكاء الاصطناعي التي تلخص الجلسات وتحسن المهارات بناءً على ملاحظات الجلسة، باستخدام Claude Code لتحسين كفاءة عمليات الأعمال"},"seo":{"title":{"en":"recap: Conversation Summarization Setup Guide | AI Agent ...","zh":"Recap 技术指南：会话总结和技能改进","ja":"Recap セットアップガイド：会話のまとめとスキルの改善","ko":"Recap 설정 가이드: 세션 요약 및 스킬 개