INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('gnestor/claude-workflow-plugin/recap', 'recap', 'gnestor', 'claude-workflow-plugin', 'community', 'recap gnestor claude-workflow-plugin community The recap skill summarizes sessions and improves skills based on feedback, ideal for developers and businesses using Claude Code for workflows and agent skills. Recap 技术是基于 Claude Code 的会话总结和技能改进工具，用于业务运营 Recap 技術は、会話をまとめ、スキルを改善する Claude Code ベースのツールです Recap 기술은 Claude Code 기반의 세션 요약 및 스킬 개선 도구로, 비즈니스 운영에 사용됩니다 Recap es un resumen de conversaciones para mejorar habilidades con Claude Code. Se utiliza para resumir sesiones y mejorar habilidades. Recap est un résumé de conversations pour améliorer les compétences avec Claude Code. Il est utilisé pour résumer les sessions et améliorer les compétences. Recap ist eine Zusammenfassung von Gesprächen, um Fähigkeiten mit Claude Code zu verbessern. Es wird verwendet, um Sitzungen zusammenzufassen und Fähigkeiten zu verbessern. O Recap é uma habilidade de AI que resume sessões e melhora habilidades com base em feedback, utilizando Claude Code para melhorar a eficiência dos processos de negócios Recap - это навык ИИ, который суммирует сессии и улучшает навыки на основе обратной связи, используя Claude Code для повышения эффективности бизнес-процессов Recap هي مهارة الذكاء الاصطناعي التي تلخص الجلسات وتحسن المهارات بناءً على ملاحظات الجلسة، باستخدام Claude Code لتحسين كفاءة عمليات الأعمال how to use recap recap setup guide conversation summarization techniques recap vs other AI agents recap install for Claude Code what is recap skill recap for business operations auto-invoke recap recap feedback mechanism Recap 技术 AI 工作空间 会话总结 技能改进 Claude Code 自动调用 Todo 列表 压缩对话 Auto-invoke capability when all planned steps are done Supports skipping for Q&A or quick fix conversations Handles compacted conversations for efficient summarization Improves skills based on feedback from completed sessions Integrates with Claude Code for agent skills and workflows recap is an AI workspace skill for summarizing conversations and enhancing skills through feedback, utilized in business operations');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MMorit00/fund-portfolio-bot/roadmap-guide', 'community', 'MMorit00', 'fund-portfolio-bot', 'MMorit00/fund-portfolio-bot', 'roadmap-guide', 0, 0, 54, '2025-12-26T10:28:36Z', '2026-03-07T03:41:11.427Z', 'ca2fd5a5acdbdead9d878ae5f0d88963ed30e033b3b4ee5595bd3d16fcfa532c', '{"id":"MMorit00/fund-portfolio-bot/roadmap-guide","name":"roadmap-guide","description":{"en":"The roadmap-guide skill provides a technical framework for Discord bot development, benefiting developers by outlining core principles and best practices for efficient roadmap creation","zh":"Roadmap 指南是一份导航图，强调简洁性原则和信息密度，帮助开发者优化 Discord 机器人开发","ja":"ロードマップガイドはナビゲーション図で、簡潔性の原則と情報密度を強調して、Discord ボットの開発を最適化する - AIエージェント","ko":"로드맵 가이드는 네비게이션 图로서 간결성 원칙과 정보 밀도를 강조하여 디스코드 봇 개발을 최적화한다 - AI 도구","es":"La guía de roadmap es una herramienta esencial para los desarrolladores de agentes de inteligencia artificial. Proporciona una visión general clara de los objetivos y funcionalidades.","fr":"Le guide de feuille de route est un outil essentiel pour les développeurs d''outils d''intelligence artificielle. Il fournit une vue d''ensemble claire des objectifs et des fonctionnalités.","de":"Der Roadmap-Leitfaden ist ein wichtiges Werkzeug für Entwickler von KI-Agents. Er bietet eine klare Übersicht über die Ziele und Funktionalitäten.","pt":"O roadmap é uma ferramenta essencial para o sucesso do seu Discord Bot. Aprenda a criá-lo de forma eficaz","ru":"Дорожная карта является важнейшим инструментом для успеха ИИ Агентов. Узнайте, как ее создать эффективно","ar":"خريطة الطريق هي أداة أساسية لنجاح عميل ديسكورد. تعلم كيفية إنشائها بفعالية"},"seo":{"title":{"en":"roadmap-guide: Discord Bot Setup Guide | AI Agent Skill","zh":"Roadmap 指南设置：简洁性原则和 Discord 机器人集成","ja":"ロードマップガイド設定: 簡潔性の原則とDiscord ボットの統合 - AIエージェント","ko":"로드맵 가이드 설정: 간결성 원칙과 디스코드 봇 통합 - AI 도구","es":"Guía de Configuración de Roadmap para Agentes de Intelige...","fr":"Guide de Configuration de la Feuille de Route pour les Ou...","de":"Einrichtungsleitfaden für Roadmaps von KI-Agents","pt":"Guia de Configuração do Roadmap para Discord Bot","ru":"Настройка дорожной карты для ИИ Агентов: лучшие практики","ar":"دليل إعداد خريطة الطريق لعميل ديسكورد"},"description":{"en":"Discover how to optimize your Discord bot with the roadmap-guide skill, featuring core principles and technical guidelines for efficient development","zh":"了解 Roadmap 指南的核心原则和最佳实践，优化您的 Discord 机器人开发，提高信息密度和简洁性","ja":"ロードマップガイドの核心原則とベストプラクティスを学び、Discord ボットの開発を最適化して情報密度と簡潔性を高める - AIエージェント","ko":"로드맵 가이드의 핵심 원칙과最佳实践을 배우고 디스코드 봇 개발을 최적화하여 정보 밀도와 간결성을 높여라 - AI 도구","es":"Aprende a configurar una guía de roadmap efectiva para tus agentes de inteligencia artificial con nuestros mejores consejos y prácticas.","fr":"Découvrez comment configurer un guide de feuille de route efficace pour vos outils d''intelligence artificielle avec nos meilleures pratiques.","de":"Erfahren Sie, wie Sie einen effektiven Roadmap-Leitfaden für Ihre KI-Agents einrichten können, mit unseren besten Tipps und Tricks.","pt":"Aprenda a criar uma roadmap eficaz para o seu Discord Bot com essas dicas e melhores práticas","ru":"Узнайте, как создать эффективную дорожную карту для ИИ Агентов и улучшить производительность вашего бота","ar":"تعلم كيفية إنشاء خريطة طريق فعالة لعميل ديسكورد الخاص بك مع هذه الإرشادات والأساليب المثلى"},"definition":{"en":"roadmap-guide is a Discord bot development framework emphasizing concise and informative roadmaps, prioritizing information density over detailed explanations","zh":"Roadmap 指南是一份用于导航和优化 Discord 机器人开发的文档，强调简洁性和信息密度","ja":"ロードマップガイドは、Discord ボットの開発をナビゲートして最適化するためのドキュメントで、簡潔性と情報密度を強調する - AIエージェント","ko":"로드맵 가이드는 디스코드 봇 개발을 네비게이트하고 최적화하는 문서로서 간결성과 정보 밀도를 강조한다 - AI 도구","es":"Un roadmap es un plan de acción que describe los objetivos y funcionalidades de un agente de inteligencia artificial.","fr":"Un guide de feuille de route est un plan d''action qui décrit les objectifs et les fonctionnalités d''un outil d''intelligence artificielle.","de":"Ein Roadmap ist ein Aktionsplan, der die Ziele und Funktionalitäten eines KI-Agents beschreibt.","pt":"Uma roadmap é um guia que ajuda a navegar pelo desenvolvimento de um projeto, como um Discord Bot","ru":"Дорожная карта - это руководство, которое помогает ориентироваться в разработке проекта, такого как ИИ Агент","ar":"خريطة الطريق هي دليل يساعد في التنقل خلال تطوير مشروع، مثل عميل ديسكورد"},"features":{"en":["Enforces simplicity through the elimination of redundant information","Prohibits unnecessary example code, promoting concise documentation","Supports version tracking and status updates in docs/roadmap.md","Facilitates the recording of architectural decisions and their rationales","Allows for the notation of prohibited items and data source limitations"],"zh":["简洁性原则：避免冗余信息和示例代码","信息密度：优化 Roadmap 指南的内容和结构","Discord 机器人集成：使用 React 和 Python 开发高效的机器人","版本管理：使用 docs/roadmap.md 管理版本和功能","架构决策：记录理由和数据源限制"],"ja":["簡潔性の原則: 冗長な情報とコード例を避ける","情報密度: ロードマップガイドの内容と構造を最適化する","Discord ボットの統合: React と Python を使用して効率的なボットを開発する - AIエージェント","バージョン管理: docs/roadmap.md を使用してバージョンと機能を管理する","アーキテクチャの決定: 理由とデータソースの制限を記録する"],"ko":["간결성 원칙:冗長한 정보와 코드 예를 피함","정보 밀도: 로드맵 가이드의 내용과 구조를 최적화함","디스코드 봇 통합: React와 Python을 사용하여 효율적인 봇을 개발함 - AI 도구","버전 관리: docs/roadmap.md를 사용하여 버전과 기능을 관리함","아키텍처 결정: 이유와 데이터 소스 제한을 기록함"],"es":["Implementación de la función de chat con loop de React","Uso de Python para el desarrollo de la lógica del agente","Eliminación de información redundante en la documentación","Uso de markdown para la documentación de la roadmap"],"fr":["Mise en œuvre de la fonction de chat avec une boucle React","Utilisation de Python pour le développement de la logique de l''agent","Élimination des informations redondantes dans la documentation","Utilisation de markdown pour la documentation de la feuille de route"],"de":["Implementierung der Chat-Funktion mit React-Loop","Verwendung von Python für die Entwicklung der Agentenlogik","Entfernung redundanter Informationen in der Dokumentation","Verwendung von Markdown für die Dokumentation der Roadmap"],"pt":["Criação de uma roadmap concisa e eficaz","Uso de React para desenvolvimento de bots","Implementação de loops de ReAct para melhorar a performance","Documentação de decisões arquiteturais","Marcação de restrições de dados e fontes"],"ru":["Создание краткой и эффективной дорожной карты","Использование React для разработки ботов","Реализация циклов ReAct для улучшения производительности","Документирование архитектурных решений","Маркировка ограничений данных и источников"],"ar":["إنشاء خريطة طريق موجزة وفعالة","استخدام React لتطوير العميل","تنفيذ دورات ReAct لتحسين الأداء","توثيق القرارات المعمارية","تحديد قيود البيانات والمصادر"]},"keywords":{"en":["how to use roadmap-guide","roadmap-guide discord bot setup","roadmap-guide vs discord.py","roadmap-guide install guide","what is roadmap-guide","roadmap-guide alternative","roadmap-guide documentation best practices","roadmap-guide for AI agents","roadmap-guide technical guidelines"],"zh":["Roadmap 指南","Discord 机器人开发","简洁性原则","信息密度","React","Python","版本管理","架构决策","AI 机器人"],"ja":["ロードマップガイド","Discord ボット開発","簡潔性の原則","情報密度","React","Python","バージョン管理","アーキテクチャの決定","AI エージェント","AI ボット"],"ko":["로드맵 가이드","디스코드 봇 개발","간결성 원칙","정보 밀도","React","Python","버전 관리","아키텍처 결정","AI 도구","AI 봇"],"es":["roadmap de inteligencia artificial","guía de configuración de roadmap","desarrollo de agentes de inteligencia artificial","Python para inteligencia artificial","React para inteligencia artificial","documentación de roadmap"],"fr":["feuille de route d''intelligence artificielle","guide de configuration de la feuille de route","développement d''outils d''intelligence artificielle","Python pour l''intelligence artificielle","React pour l''intelligence artificielle","documentation de la feuille de route"],"de":["Roadmap für KI","Einrichtungsleitfaden für Roadmaps","Entwicklung von KI-Agents","Python für KI","React für KI","Dokumentation der Roadmap"],"pt":["roadmap discord bot","desenvolvimento de bots","React para bots","ReAct loops","documentação de decisões arquiteturais","marcação de restrições de dados","guias de configuração"],"ru":["дорожная карта ИИ Агентов","разработка ботов","React для ботов","циклы ReAct","документирование архитектурных решений","маркировка ограничений данных","구ид по настройке"],"ar":["خريطة الطريق عميل ديسكورد","تطوير العميل","استخدام React","دورات ReAct","توثيق القرارات المعمارية","تحديد قيود البيانات","دليل الإعداد"]}},"owner":"MMorit00","repo":"fund-portfolio-bot","repoPath":"MMorit00/fund-portfolio-bot","stars":0,"forks":0,"updatedAt":"2025-12-26T10:28:36Z","topics":[],"category":"community","skillMd":{"name":"roadmap-guide","description":"在编写、更新、维护 roadmap.md 的时候触发","bodyPreview":"# Roadmap 编写指南\n\n> **核心原则**：roadmap 是导航图，不是教科书。信息密度 > 详细程度。\n\n## When to use\n\n**必须应用**此规范的场景：\n\n- 向 `docs/roadmap.md` 添加新版本/功能\n- 更新已有版本的状态\n- 记录架构决策的理由\n- 标记禁止事项和数据源限制\n---\n\n## 1. 简洁性原则（CRITICAL）\n\n### ❌ 禁止冗余\n\n**删除这些内容：**\n\n1. **示例代码**（除非必需理解问题）\n   ```markdown\n   ❌ 错误：\n   **实现方案：**\n   ```python\n   # 20 行完整代码示例\n   async def chat_with_loop(self, query: str) -> str:\n       for i in range(15):\n           ...\n   ```\n\n   ✅ 正确：\n   **实现方案：** `chat_with_loop()` 方法，最多 15 轮 ReAct 循环\n   ```\n\n2. **重复信息**（已在其他文档详述）","body":"# Roadmap 编写指南\n\n> **核心原则**：roadmap 是导航图，不是教科书。信息密度 > 详细程度。\n\n## When to use\n\n**必须应用**此规范的场景：\n\n- 向 `docs/roadmap.md` 添加新版本/功能\n- 更新已有版本的状态\n- 记录架构决策的理由\n- 标记禁止事项和数据源限制\n---\n\n## 1. 简洁性原则（CRITICAL）\n\n### ❌ 禁止冗余\n\n**删除这些内容：**\n\n1. **示例代码**（除非必需理解问题）\n   ```markdown\n   ❌ 错误：\n   **实现方案：**\n   ```python\n   # 20 行完整代码示例\n   async def chat_with_loop(self, query: str) -> str:\n       for i in range(15):\n           ...\n   ```\n\n   ✅ 正确：\n   **实现方案：** `chat_with_loop()` 方法，最多 15 轮 ReAct 循环\n   ```\n\n2. **重复信息**（已在其他文档详述）\n   ```markdown\n   ❌ 错误：详细解释 T+1/T+2 确认规则\n   ✅ 正确：确认规则见 `docs/settlement-rules.md`\n   ```\n\n3. **过长段落**\n   ```markdown\n   ❌ 错误：超过 3 行的描述段落\n   ✅ 正确：每段 ≤ 3 行，优先使用列表/表格\n   ```\n\n---\n\n## 2. 版本条目结构\n\n每个版本条目遵循固定结构：\n\n```markdown\n## vX.Y.Z 版本标题（状态标记）\n\n### 核心目标\n一句话说明此版本解决什么问题。\n\n### 实现范围\n- [x] 已完成项\n- [ ] 待完成项\n\n### 不做\n- ❌ 明确排除的功能（防止范围蔓延）\n```\n\n**状态标记**：\n- `✅` 已完成\n- `🚧` 进行中\n- `🔮` 规划中\n\n---\n\n## 3. 对比表格\n\n版本间对比使用表格，清晰展示差异：\n\n```markdown\n| 维度 | v0.5.0 | v0.5.1 |\n|------|--------|--------|\n| 调用轮数 | 固定 1-2 轮 | 动态 N 轮 |\n| 决策模式 | 一次性决定 | 边做边决策 |\n```\n\n---\n\n## 4. 禁止事项 & 限制\n\n使用统一格式记录：\n\n```markdown\n## 禁止事项\n- ❌ AI 执行交易操作（只给建议）\n- ❌ 修改数据库 Schema\n\n## 已知限制\n**限制名称**（记录日期）：\n- 问题描述（1-2 行）\n- 未来方案（可选）\n```\n\n---\n\n## 5. ASCII 图表\n\n架构/数据流优先使用 ASCII 图：\n\n```markdown\n导入阶段：\n  CSV → 算法 → BillFacts → AI 判断 → 回填 ActionLog\n\n分析阶段：\n  用户提问 → AI → Tools → 分析 → 建议\n```\n\n---\n\n## 6. 触发机制\n\n**自动触发：** 当检测到以下操作时，自动应用此 skill\n\n- 文件路径包含 `roadmap.md`\n- 提交信息包含 \"roadmap\" / \"版本\" / \"规划\"\n- 用户明确要求更新 roadmap\n\n**提醒文案：**\n```\n正在编辑 roadmap.md\n请遵循简洁性原则：\n- 每段 ≤ 3 行\n- 代码示例 ≤ 5 行或删除\n- 无重复信息\n- 优先使用列表/表格\n```\n\n---\n"},"lastSynced":"2026-03-07T03:41:11.427Z","agentAnalysis":{"suitability":{"en":"Perfect for Technical Writing Agents needing structured roadmap development guidelines.","zh":"非常适合需要结构化路线图开发指南的技术写作代理","ja":"テクニカルライティングエージェントが構造化されたロードマップ開発ガイドラインを必要とする場合に最適","ko":"구조화된 로드맵 개발 가이드라인이 필요한 기술 작성 에이전트에 적합","es":"Perfecto para Agentes de Escritura Técnica que necesitan pautas de desarrollo de hojas de ruta estructuradas.","fr":"Parfait pour les agents de rédaction technique ayant besoin de lignes directrices de développement de feuilles de route structurées.","de":"Perfekt für technische Schreibagenten, die Richtlinien für die Entwicklung strukturierter Roadmaps benötigen.","pt":"Perfeito para Agentes de Escrita Técnica que precisam de diretrizes de desenvolvimento de estradas estruturadas.","ru":"Идеально для агентов технической документации, которым требуются структурированные рекомендации по разработке дорожных карт.","ar":"مثالي للوكلاء الكتابة الفنية الذين يحتاجون إلى إرشادات تطوير خريطة طريق منظمة."},"recommendation":{"en":"Empowers agents to create concise and informative roadmaps using Markdown formatting, eliminating redundant information and focusing on core principles like information density and simplicity, while adhering to specific documentation standards like updating docs/roadmap.md.","zh":"赋予代理创建使用Markdown格式的简洁且信息丰富的路线图的能力，消除冗余信息，关注信息密度和简单性等核心原则，同时遵守特定的文档标准，如更新docs/roadmap.md","ja":"エージェントがMarkdown形式を使用して簡潔で情報の豊富なロードマップを作成する能力を付与し、冗長な情報を排除し、情報密度やシンプリシティなどの核となる原則に焦点を当て、同時にdocs/roadmap.mdの更新などの特定のドキュメント標準に従う","ko":"에이전트가 Markdown 형식을 사용하여 간결하고 정보가 풍부한 로드맵을 생성할 수 있는 능력을 부여하며,冗余 정보를 제거하고, 정보 밀도 및 단순성과 같은 핵심 원칙에 중점을 두고,同時에 docs/roadmap.md 更新などの 특정 문서 표준을 준수","es":"Habilita a los agentes a crear hojas de ruta concisas e informativas utilizando la formación Markdown, eliminando la información redundante y centrándose en principios básicos como la densidad y la simplicidad de la información, mientras se adhiere a normas de documentación específicas como la actualización de docs/roadmap.md.","fr":"Habilite les agents à créer des feuilles de route concises et informatives en utilisant la mise en forme Markdown, en éliminant les informations redondantes et en se concentrant sur des principes fondamentaux tels que la densité et la simplicité de l''information, tout en respectant des normes de documentation spécifiques comme la mise à jour de docs/roadmap.md.","de":"Ermächtigt Agenten, präzise und informative Roadmaps unter Verwendung von Markdown-Formatierung zu erstellen, redundante Informationen zu eliminieren und sich auf grundlegende Prinzipien wie Informationsdichte und Einfachheit zu konzentrieren, während sie bestimmten Dokumentationsstandards wie der Aktualisierung von docs/roadmap.md entsprechen.","pt":"Habilita os agentes a criar estradas concisas e informativas usando formatação Markdown, eliminando informações redundantes e se concentrando nos princípios básicos como densidade de informações e simplicidade, enquanto adere a padrões de documentação específicos como atualizar docs/roadmap.md.","ru":"Наделяет агентов возможностью создавать краткие и информативные дорожные карты с использованием форматирования Markdown, исключая избыточную информацию и фокусируясь на основных принципах, таких как плотность информации и простота, при этом соблюдая определенные стандарты документации, такие как обновление docs/roadmap.md.","ar":"تمكّن الوكلاء من إنشاء خريطة طريق موجزة وواضحة باستخدام تنسيق Markdown، من خلال القضاء على المعلومات الزائدة والتركيز على المبادئ الأساسية مثل كثافة المعلومات والبساطة، مع الالتزام بمعايير توثيق محددة مثل تحديث docs/roadmap.md."},"useCases":{"en":["Generating roadmap documentation for new features","Updating existing roadmap versions with status changes","Recording architectural decisions and their rationales","Marking deprecated features and data source limitations"],"zh":["为新功能生成路线图文档","更新现有路线图版本的状态更改","记录架构决策及其理由","标记弃用功能和数据源限制"],"ja":["新機能のロードマップドキュメントを生成する","既存のロードマップバージョンのステータス変更を更新する","アーキテクチャの決定とその理由を記録する","非推奨の機能とデータソースの制限をマークする"],"ko":["새로운 기능을 위한 로드맵 문서 생성","기존 로드맵 버전의 상태 변경을 更新","아키텍처 결정과 그 이유를 기록","사용되지 않는 기능과 데이터 소스 제한을 표시"],"es":["Generar documentación de hoja de ruta para nuevas características","Actualizar versiones de hoja de ruta existentes con cambios de estado","Grabar decisiones arquitectónicas y sus rationales","Marcar características obsoletas y limitaciones de fuentes de datos"],"fr":["Générer la documentation de la feuille de route pour les nouvelles fonctionnalités","Mettre à jour les versions de feuille de route existantes avec des changements d''état","Enregistrer les décisions architecturales et leurs rationnels","Marquer les fonctionnalités obsolètes et les limites des sources de données"],"de":["Erstellen von Roadmap-Dokumentation für neue Funktionen","Aktualisieren bestehender Roadmap-Versionen mit Statusänderungen","Aufzeichnen architektonischer Entscheidungen und deren Begründungen","Markieren veralteter Funktionen und Datenquellenbeschränkungen"],"pt":["Gerar documentação de estrada para recursos novos","Atualizar versões existentes da estrada com alterações de status","Gravar decisões arquiteturais e suas razões","Marcar recursos obsoletos e limitações de fontes de dados"],"ru":["Генерировать документацию дорожной карты для новых функций","Обновлять существующие версии дорожной карты с изменениями статуса","Записывать архитектурные решения и их обоснования","Помечать устаревшие функции и ограничения источников данных"],"ar":["توليد توثيق خريطة الطريق لِميزات جديدة","تحديث إصدارات موجودة من خريطة الطريق مع تغييرات الحالة","تسجيل قرارات الهندسة المعمارية وأسبابها","تأشير الميزات المعفاة والقيود المحددة لمصادر البيانات"]},"limitations":{"en":["Requires adherence to specified documentation standards","Intended for technical roadmapping, not general knowledge bases","Markdown formatting knowledge required"],"zh":["需要遵守指定的文档标准","仅适用于技术路线图，不适用于一般知识库","需要Markdown格式的知识"],"ja":["指定されたドキュメント標準に従う必要がある","一般的な知識ベースではなく、テクニカルロードマップのみに適している","Markdown形式の知識が必要"],"ko":["지정된 문서 표준을 준수해야함","일반적인 지식베이스가 아닌 기술 로드맵에만 적합","Markdown 형식의 지식이 필요"],"es":["Requiere adherencia a normas de documentación especificadas","Está destinado a la creación de hojas de ruta técnica, no a bases de conocimiento generales","Se requiere conocimiento de formación Markdown"],"fr":["Nécessite une adhésion aux normes de documentation spécifiées","Est conçu pour la création de feuilles de route techniques, et non pour les bases de connaissances générales","Connaissances de la mise en forme Markdown requises"],"de":["Erfordert die Einhaltung bestimmter Dokumentationsstandards","Ist für die technische Roadmap-Erstellung und nicht für allgemeine Wissensbasen gedacht","Kenntnisse in Markdown-Formatierung erforderlich"],"pt":["Exige aderência a padrões de documentação especificados","Destinado à criação de estradas técnicas, não a bases de conhecimento gerais","Conhecimento de formatação Markdown é necessário"],"ru":["Требует соблюдения определенных стандартов документации","Предназначен для технического планирования, а не для общих баз знаний","Требуется знание форматирования Markdown"],"ar":["يتطلب الالتزام بمعايير توثيق محددة","مصمم لإنشاء خريطة طريق تقنية، وليس لقواعد المعرفة العامة","مطلوب معرفة تنسيق Markdown"]},"version":4},"contentHash":"ca2fd5a5acdbdead9d878ae5f0d88963ed30e033b3b4ee5595bd3d16fcfa532c","qualityScore":54}');
