INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('MMorit00/fund-portfolio-bot/roadmap-guide', 'roadmap-guide', 'MMorit00', 'fund-portfolio-bot', 'community', 'roadmap-guide MMorit00 fund-portfolio-bot community The roadmap-guide skill provides a technical framework for Discord bot development, benefiting developers by outlining core principles and best practices for efficient roadmap creation Roadmap 指南是一份导航图，强调简洁性原则和信息密度，帮助开发者优化 Discord 机器人开发 ロードマップガイドはナビゲーション図で、簡潔性の原則と情報密度を強調して、Discord ボットの開発を最適化する - AIエージェント 로드맵 가이드는 네비게이션 图로서 간결성 원칙과 정보 밀도를 강조하여 디스코드 봇 개발을 최적화한다 - AI 도구 La guía de roadmap es una herramienta esencial para los desarrolladores de agentes de inteligencia artificial. Proporciona una visión general clara de los objetivos y funcionalidades. Le guide de feuille de route est un outil essentiel pour les développeurs d''outils d''intelligence artificielle. Il fournit une vue d''ensemble claire des objectifs et des fonctionnalités. Der Roadmap-Leitfaden ist ein wichtiges Werkzeug für Entwickler von KI-Agents. Er bietet eine klare Übersicht über die Ziele und Funktionalitäten. O roadmap é uma ferramenta essencial para o sucesso do seu Discord Bot. Aprenda a criá-lo de forma eficaz Дорожная карта является важнейшим инструментом для успеха ИИ Агентов. Узнайте, как ее создать эффективно خريطة الطريق هي أداة أساسية لنجاح عميل ديسكورد. تعلم كيفية إنشائها بفعالية how to use roadmap-guide roadmap-guide discord bot setup roadmap-guide vs discord.py roadmap-guide install guide what is roadmap-guide roadmap-guide alternative roadmap-guide documentation best practices roadmap-guide for AI agents roadmap-guide technical guidelines Roadmap 指南 Discord 机器人开发 简洁性原则 信息密度 React Python 版本管理 架构决策 AI 机器人 Enforces simplicity through the elimination of redundant information Prohibits unnecessary example code, promoting concise documentation Supports version tracking and status updates in docs/roadmap.md Facilitates the recording of architectural decisions and their rationales Allows for the notation of prohibited items and data source limitations roadmap-guide is a Discord bot development framework emphasizing concise and informative roadmaps, prioritizing information density over detailed explanations');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('taewook486/real-estate-mcp/worklog', 'community', 'taewook486', 'real-estate-mcp', 'taewook486/real-estate-mcp', 'worklog', 0, 0, 54, '2026-02-28T00:44:48Z', '2026-03-07T03:41:43.501Z', '682e9e38108b4b931bbeec44898d70ae7ed1c4ba327993d5d6317561beb2bb54', '{"id":"taewook486/real-estate-mcp/worklog","name":"worklog","description":{"en":"The worklog skill updates task state in worklog files, supporting explicit arguments for task management. It benefits developers and teams by organizing tasks into backlog, in-progress, and completed categories.","zh":"Worklog 是一个用于更新任务状态和跟踪的工具。它支持将任务状态更新为 done，并将任务记录在相应的日志文件中","ja":"Worklog はタスク状態を更新し、追跡するためのツールです。done 状態への更新をサポートし、タスクを対応するログファイルに記録します","ko":"Worklog는 작업 상태를 업데이트하고 추적하는 데 사용되는 도구입니다. 완료된 상태로 업데이트를 지원하며 작업을 해당 로그 파일에 기록합니다","es":"Worklog es una herramienta para actualizar el estado de tareas en archivos de trabajo. Requiere argumentos explícitos para funcionar","fr":"Worklog est un outil pour mettre à jour l''état de tâches dans des fichiers de travail. Il nécessite des arguments explicites pour fonctionner","de":"Worklog ist ein Tool, um den Status von Aufgaben in Arbeitsdateien zu aktualisieren. Es benötigt explizite Argumente, um zu funktionieren","pt":"O worklog é uma ferramenta para atualizar o estado das tarefas em arquivos de trabalho, permitindo o rastreamento de tarefas em andamento e concluídas.","ru":"Worklog — это инструмент для обновления состояния задач в файлах работы, позволяющий отслеживать задачи в процессе и завершенные.","ar":"سجل العمل هو أداة لتحديث حالة المهام في الملفات، مما يسمح بتتبع المهام قيد التنفيذ والمنتهية."},"seo":{"title":{"en":"worklog: Update Task State Management for AI Agents | AI ...","zh":"Worklog 设置指南：任务状态更新和跟踪","ja":"Worklog セットアップガイド：タスク状態の更新と追跡","ko":"Worklog 설정 가이드: 작업 상태 업데이트 및 추적","es":"Guía de configuración de worklog para seguimiento de tareas","fr":"Guide de mise en place de worklog pour la gestion de tâches","de":"Worklog Einrichtungsleitfaden für Aufgabenverfolgung","pt":"Guia de Configuração do Worklog: Ferramenta de Rastreamen...","ru":"ИИ Агент Worklog: Настройка и Отслеживание Задач","ar":"دليل إعداد وتحديث سجل العمل: أداة تتبع المهام"},"description":{"en":"Discover how to efficiently manage task states with worklog. Learn to update task states in worklog files and streamline your workflow. Get started now!","zh":"了解 Worklog 的功能和用途，包括任务状态更新和跟踪。使用 Worklog 实现高效的任务管理","ja":"Worklog の機能と用途を学ぶ、タスク状態の更新と追跡を含む。Worklog を使用して効率的なタスク管理を実現する","ko":"Worklog 기능 및 용도를 알아보세요. 작업 상태 업데이트 및 추적을 포함합니다. Worklog를 사용하여 효율적인 작업 관리를 구현하세요","es":"Aprende a utilizar worklog para actualizar el estado de tus tareas en archivos de trabajo. Descubre cómo funciona y cómo integrarlo en tu flujo de trabajo","fr":"Découvrez comment utiliser worklog pour mettre à jour l''état de vos tâches dans des fichiers de travail. Apprenez à l''intégrer dans votre flux de travail","de":"Erfahren Sie, wie Sie worklog verwenden, um den Status Ihrer Aufgaben in Arbeitsdateien zu aktualisieren. Entdecken Sie, wie es in Ihren Arbeitsablauf integr...","pt":"Aprenda a configurar e utilizar o worklog para atualizar o estado das tarefas em arquivos de trabalho. Descubra como otimizar sua produtividade","ru":"Узнайте, как настроить и использовать worklog для обновления состояния задач в файлах работы. Повысьте свою производительность","ar":"تعرف على كيفية إعداد وتشغيل سجل العمل لتحديث حالة المهام في الملفات. تحسين الإنتاجية"},"definition":{"en":"worklog is a task state management system that updates worklog files, including localdocs/worklog.todo.md, localdocs/worklog.doing.md, and localdocs/worklog.done.md, to track task progress.","zh":"Worklog 是一个任务状态更新和跟踪工具，用于记录任务的进度和状态","ja":"Worklog はタスク状態の更新と追跡ツールで、タスクの進度と状態を記録するために使用されます","ko":"Worklog는 작업 상태 업데이트와 추적을 위한 도구로 작업의 진행 상황과 상태를 기록하는 데 사용됩니다","es":"Worklog es una herramienta de seguimiento de tareas que actualiza el estado de las tareas en archivos de trabajo","fr":"Worklog est un outil de suivi de tâches qui met à jour l''état des tâches dans des fichiers de travail","de":"Worklog ist ein Tool zur Aufgabenverfolgung, das den Status von Aufgaben in Arbeitsdateien aktualisiert","pt":"O worklog é uma ferramenta de rastreamento de tarefas que atualiza o estado das tarefas em arquivos de trabalho.","ru":"Worklog — это инструмент отслеживания задач, который обновляет состояние задач в файлах работы.","ar":"سجل العمل هو أداة تتبع المهام التي تحديث حالة المهام في الملفات."},"features":{"en":["Updates task state in worklog files using explicit arguments","Supports three worklog file types: backlog, in-progress, and completed","Uses append-only mode for completed tasks in localdocs/worklog.done.md","Requires specific argument format: [state] [description]","Allows marking tasks as done using the ''done [description]'' command"],"zh":["支持任务状态更新为 done","将任务记录在 localdocs/worklog.done.md 文件中","支持在 localdocs/worklog.todo.md 和 localdocs/worklog.doing.md 中管理任务","采用 append-only 模式记录完成的任务","支持使用 CLI 更新任务状态"],"ja":["done 状態への更新をサポート","タスクを localdocs/worklog.done.md ファイルに記録","localdocs/worklog.todo.md と localdocs/worklog.doing.md でタスクを管理","append-only モードで完了したタスクを記録","CLI を使用してタスク状態を更新"],"ko":["완료된 상태로 업데이트를 지원","작업을 localdocs/worklog.done.md 파일에 기록","localdocs/worklog.todo.md 및 localdocs/worklog.doing.md에서 작업을 관리","추가 전용 모드로 완료된 작업을 기록","CLI를 사용하여 작업 상태를 업데이트"],"es":["Actualiza el estado de tareas en archivos de trabajo","Requiere argumentos explícitos para funcionar","Soporta archivos de trabajo para tareas pendientes, en progreso y completadas","Permite agregar descripciones a las tareas","Soporta la creación de archivos de trabajo para temas específicos","Integra con herramientas de línea de comandos para una mayor flexibilidad"],"fr":["Mettre à jour l''état de tâches dans des fichiers de travail","Nécessite des arguments explicites pour fonctionner","Prend en charge des fichiers de travail pour les tâches en attente, en cours et terminées","Permet d''ajouter des descriptions aux tâches","Prend en charge la création de fichiers de travail pour des sujets spécifiques","Intègre avec des outils de ligne de commande pour une plus grande flexibilité"],"de":["Aktualisiert den Status von Aufgaben in Arbeitsdateien","Benötigt explizite Argumente, um zu funktionieren","Unterstützt Arbeitsdateien für Aufgaben, die ausstehen, in Bearbeitung sind und abgeschlossen sind","Ermöglicht das Hinzufügen von Beschreibungen zu den Aufgaben","Unterstützt die Erstellung von Arbeitsdateien für spezifische Themen","Integriert mit Kommandozeilen-Tools für eine größere Flexibilität"],"pt":["Atualização do estado das tarefas em arquivos de trabalho","Rastreamento de tarefas em andamento e concluídas","Utilização de arquivos `localdocs/worklog.todo.md`, `localdocs/worklog.doing.md` e `localdocs/worklog.done.md`","Suporte a argumentos explícitos para atualizar o estado das tarefas","Compatibilidade com CLI para execução de comandos"],"ru":["Обновление состояния задач в файлах работы","Отслеживание задач в процессе и завершенные","Использование файлов `localdocs/worklog.todo.md`, `localdocs/worklog.doing.md` и `localdocs/worklog.done.md`","Поддержка явных аргументов для обновления состояния задач","Совместимость с CLI для выполнения команд"],"ar":["تحديث حالة المهام في الملفات","تتبع المهام قيد التنفيذ والمنتهية","استخدام الملفات `localdocs/worklog.todo.md`, `localdocs/worklog.doing.md` و `localdocs/worklog.done.md`","دعم الحجج الصريحة لتحديث حالة المهام","التوافق مع CLI لتنفيذ الأوامر"]},"keywords":{"en":["how to use worklog","worklog setup guide","worklog alternative","worklog vs trello","worklog install","what is worklog","worklog for AI agents","task state management with worklog","worklog file format"],"zh":["Worklog","任务状态更新","任务跟踪","CLI 工具","任务管理","AI 工具","AIエージェント","工作流管理"],"ja":["Worklog","タスク状態の更新","タスク追跡","CLI ツール","タスク管理","AI ツール","AIエージェント","ワークフロー管理"],"ko":["Worklog","작업 상태 업데이트","작업 추적","CLI 도구","작업 관리","AI 도구","AI 에이전트","작업 흐름 관리"],"es":["worklog","seguimiento de tareas","actualización de estado de tareas","archivos de trabajo","tareas pendientes","tareas en progreso","tareas completadas","herramientas de línea de comandos","integración con herramientas de desarrollo"],"fr":["worklog","suivi de tâches","mise à jour de l''état de tâches","fichiers de travail","tâches en attente","tâches en cours","tâches terminées","outils de ligne de commande","intégration avec des outils de développement"],"de":["worklog","Aufgabenverfolgung","Aktualisierung des Status von Aufgaben","Arbeitsdateien","Aufgaben, die ausstehen","Aufgaben in Bearbeitung","abgeschlossene Aufgaben","Kommandozeilen-Tools","Integration mit Entwicklungstools"],"pt":["worklog","rastreamento de tarefas","ferramenta de produtividade","atualização de estado de tarefas","arquivos de trabalho","CLI","argumentos explícitos","otimização de produtividade"],"ru":["worklog","отслеживание задач","инструмент производительности","обновление состояния задач","файлы работы","CLI","явные аргументы","повышение производительности"],"ar":["سجل العمل","تتبع المهام","أداة الإنتاجية","تحديث حالة المهام","الملفات","CLI","الحجج الصريحة","تحسين الإنتاجية"]}},"owner":"taewook486","repo":"real-estate-mcp","repoPath":"taewook486/real-estate-mcp","stars":0,"forks":0,"updatedAt":"2026-02-28T00:44:48Z","topics":[],"category":"community","skillMd":{"name":"worklog","description":"Update worklog files by moving tasks between todo/doing/done states. Use when recording task progress, starting new work, or marking tasks complete. Requires explicit arguments: worklog [done|doing|todo] [description].","bodyPreview":"# Worklog\n\nUpdate task state in worklog files. Requires explicit arguments.\n\n## Worklog Files\n\n- `localdocs/worklog.todo.md` — backlog\n- `localdocs/worklog.doing.md` — in progress\n- `localdocs/worklog.done.md` — completed (grouped by date, append-only)\n\n`worklog` is for current phase/session execution tracking.\nFor future items not yet included in an approved plan, use `localdocs/backlog.<topic>.md`.\n\n## Arguments\n\n`$ARGUMENTS` must be: `[state] [description]`\n\n- `done [description]` — mark task","body":"# Worklog\n\nUpdate task state in worklog files. Requires explicit arguments.\n\n## Worklog Files\n\n- `localdocs/worklog.todo.md` — backlog\n- `localdocs/worklog.doing.md` — in progress\n- `localdocs/worklog.done.md` — completed (grouped by date, append-only)\n\n`worklog` is for current phase/session execution tracking.\nFor future items not yet included in an approved plan, use `localdocs/backlog.<topic>.md`.\n\n## Arguments\n\n`$ARGUMENTS` must be: `[state] [description]`\n\n- `done [description]` — mark task complete\n- `doing [description]` — start working on a task\n- `todo [description]` — add to backlog\n\nIf no arguments, stop and output:\n\n```\nError: worklog requires explicit arguments.\nUsage: worklog [done|doing|todo] [description]\n\nExamples:\n  worklog done config/settings.py setup complete\n  worklog doing collectors/data_go_kr.py implementation\n  worklog todo parsers/xml_parser.py implementation\n```\n\n## What to Read (by command)\n\n**`done`**: Read `worklog.doing.md` only — to find and remove the matching item.\n**`doing`**: Read `worklog.todo.md` only — to find and remove the matching item.\n**`todo`**: No need to read any file — just append.\n\nNever read `worklog.done.md` — it is append-only and grows over time.\n\n## Update Rules\n\n### `done [description]`\n1. Read `worklog.doing.md`; find matching item (keyword match, not exact)\n2. Remove the item from doing\n3. Append to `worklog.done.md` under today''s date section (`## YYYY-MM-DD`), creating the section if absent\n4. If no match in doing, append directly to done without removing anything\n\n### `doing [description]`\n1. Read `worklog.todo.md`; find matching item\n2. Remove the item from todo\n3. Append to `worklog.doing.md`\n4. If no match in todo, append directly to doing\n\n### `todo [description]`\n1. Append item to end of `worklog.todo.md`\n\n## Writing Style\n\n- Concise bullet points — focus on *what* was done, not *how*\n- Use filenames and concrete task names over vague descriptions\n- No tables or heavy formatting\n- Done items must be under a date section (`## YYYY-MM-DD`)\n\n## Output\n\n```\nWorklog updated:\n- [action taken]: [description]\n```\n"},"lastSynced":"2026-03-07T03:41:43.501Z","agentAnalysis":{"suitability":{"en":"Ideal for Task Management Agents requiring organized workflow tracking and explicit state updates in Markdown files.","zh":"适合需要组织化工作流跟踪和在 Markdown 文件中显式状态更新的任务管理代理。","ja":"タスク管理エージェントが整理されたワークフローの追跡と Markdown ファイルでの明示的な状態更新を必要とする場合に適しています。","ko":"작업 관리 에이전트가 구성된 워크플로 추적과 Markdown 파일에서 명시적 상태 업데이트를 필요로 할 때 적합합니다.","es":"Ideal para Agentes de Gestión de Tareas que requieren un seguimiento de flujo de trabajo organizado y actualizaciones de estado explícitas en archivos Markdown.","fr":"Idéal pour les Agents de Gestion de Tâches nécessitant un suivi de workflow organisé et des mises à jour d''état explicites dans des fichiers Markdown.","de":"Ideal für Task-Management-Agents, die ein organisiertes Workflow-Tracking und explizite Statusaktualisierungen in Markdown-Dateien erfordern.","pt":"Ideal para Agentes de Gerenciamento de Tarefas que exigem rastreamento de fluxo de trabalho organizado e atualizações de estado explícitas em arquivos Markdown.","ru":"Идеально подходит для агентов управления задачами, требующих организованного отслеживания рабочего процесса и явных обновлений состояния в файлах Markdown.","ar":"مثالي لعميل إدارة المهام الذي يتطلب تتبع تدفق عمل منظم وتنقيحات حالة صريحة في ملفات Markdown."},"recommendation":{"en":"Empowers agents to manage tasks efficiently by updating state in worklog files, utilizing explicit arguments for task management, and organizing tasks into backlog, in-progress, and completed categories using Markdown files like `worklog.todo.md`, `worklog.doing.md`, and `worklog.done.md`.","zh":"通过在工作日志文件中更新状态、利用显式参数进行任务管理以及使用 Markdown 文件（如 `worklog.todo.md`、`worklog.doing.md` 和 `worklog.done.md`）将任务组织到待办、进行中和已完成类别来使代理高效地管理任务。","ja":"タスクを効率的に管理できるようにするために、ワークログファイルの状態を更新し、タスク管理のために明示的な引数を利用し、`worklog.todo.md`、`worklog.doing.md`、`worklog.done.md` などの Markdown ファイルを使用してタスクをバックログ、進行中、完了のカテゴリに整理する。","ko":"작업 로그 파일의 상태를 업데이트하고, 작업 관리를 위한 명시적 인수를 활용하고, `worklog.todo.md`, `worklog.doing.md`, `worklog.done.md`와 같은 Markdown 파일을 사용하여 작업을 백로그, 진행 중, 완료된 카테고리로 구성하여 에이전트가 작업을 효율적으로 관리하도록 합니다.","es":"Habilita a los agentes a gestionar tareas de manera eficiente actualizando el estado en archivos de trabajo, utilizando argumentos explícitos para la gestión de tareas y organizando tareas en categorías de backlog, en progreso y completadas utilizando archivos Markdown como `worklog.todo.md`, `worklog.doing.md` y `worklog.done.md`.","fr":"Permet aux agents de gérer les tâches de manière efficace en mettant à jour l''état dans les fichiers de travail, en utilisant des arguments explicites pour la gestion des tâches et en organisant les tâches en catégories de backlog, en cours et terminées en utilisant des fichiers Markdown comme `worklog.todo.md`, `worklog.doing.md` et `worklog.done.md`.","de":"Ermöglicht es Agenten, Aufgaben effizient zu verwalten, indem sie den Status in Arbeitslog-Dateien aktualisieren, explizite Argumente für die Aufgabenverwaltung verwenden und Aufgaben in Backlog-, in Bearbeitung- und abgeschlossene Kategorien organisieren, indem sie Markdown-Dateien wie `worklog.todo.md`, `worklog.doing.md` und `worklog.done.md` verwenden.","pt":"Habilita os agentes a gerenciar tarefas de forma eficiente atualizando o estado em arquivos de registro de trabalho, utilizando argumentos explícitos para gerenciamento de tarefas e organizando tarefas em categorias de backlog, em andamento e concluídas usando arquivos Markdown como `worklog.todo.md`, `worklog.doing.md` e `worklog.done.md`.","ru":"Наделяет агентов возможностью эффективно управлять задачами, обновляя состояние в файлах журнала работы, используя явные аргументы для управления задачами и организуя задачи в категории бэклога, в процессе и завершенные с помощью файлов Markdown, таких как `worklog.todo.md`, `worklog.doing.md` и `worklog.done.md`.","ar":"یمکن एजنت من إدارة المهام بفعالية من خلال تحديث الحالة في ملفات سجل العمل، واستخدام حجة صريحة لإدارة المهام، وتنظيم المهام في فئات قائمة الانتظار، قيد التقدم، والمنتهية باستخدام ملفات Markdown مثل `worklog.todo.md` و `worklog.doing.md` و `worklog.done.md`."},"useCases":{"en":["Updating task states in worklog files for project tracking","Organizing tasks into backlog, in-progress, and completed categories for team management","Marking tasks as done using the `done` argument for progress tracking"],"zh":["更新工作日志文件中的任务状态以进行项目跟踪","将任务组织到待办、进行中和已完成类别以进行团队管理","使用 `done` 参数标记任务为已完成以进行进度跟踪"],"ja":["プロジェクト追跡のためにワークログファイルのタスク状態を更新する","チーム管理のためにタスクをバックログ、進行中、完了のカテゴリに整理する","進度追跡のために `done` 引数を使用してタスクを完了としてマークする"],"ko":["프로젝트 추적을 위해 작업 로그 파일의 작업 상태를 업데이트합니다.","팀 관리를 위해 작업을 백로그, 진행 중, 완료된 카테고리로 구성합니다.","진행 상황 추적을 위해 `done` 인수를 사용하여 작업을 완료로 표시합니다."],"es":["Actualizar estados de tareas en archivos de trabajo para el seguimiento de proyectos","Organizar tareas en categorías de backlog, en progreso y completadas para la gestión de equipos","Marcar tareas como finalizadas utilizando el argumento `done` para el seguimiento del progreso"],"fr":["Mettre à jour les états de tâches dans les fichiers de travail pour le suivi de projet","Organiser les tâches en catégories de backlog, en cours et terminées pour la gestion d''équipe","Marquer les tâches comme terminées en utilisant l''argument `done` pour le suivi des progrès"],"de":["Aktualisieren von Aufgabenstatus in Arbeitslog-Dateien für das Projekt-Tracking","Organisieren von Aufgaben in Backlog-, in Bearbeitung- und abgeschlossene Kategorien für das Team-Management","Markieren von Aufgaben als erledigt unter Verwendung des `done`-Arguments für das Fortschritts-Tracking"],"pt":["Atualizar estados de tarefas em arquivos de registro de trabalho para rastreamento de projetos","Organizar tarefas em categorias de backlog, em andamento e concluídas para gerenciamento de equipe","Marcar tarefas como concluídas usando o argumento `done` para rastreamento de progresso"],"ru":["Обновление состояний задач в файлах журнала работы для отслеживания проектов","Организация задач в категории бэклога, в процессе и завершенные для управления командой","Помечание задач как выполненных с помощью аргумента `done` для отслеживания прогресса"],"ar":["تحديث حالات المهام في ملفات سجل العمل لتتبع المشاريع","تنظيم المهام في فئات قائمة الانتظار، قيد التقدم، والمنتهية لإدارة الفريق","تحديد المهام على أنها منتهية باستخدام حجة `done` لتتبع التقدم"]},"limitations":{"en":["Requires explicit arguments for task management","Limited to local file system access for worklog files","Append-only for completed tasks in `worklog.done.md`"],"zh":["需要显式参数进行任务管理","仅限于本地文件系统访问工作日志文件","仅允许在 `worklog.done.md` 中追加已完成任务"],"ja":["タスク管理のために明示的な引数が必要","ワークログファイルへのアクセスはローカルファイルシステムに限定される","完了したタスクは `worklog.done.md` にのみ追加可能"],"ko":["작업 관리를 위해 명시적 인수가 필요합니다.","작업 로그 파일에 대한 액세스는 로컬 파일 시스템에만 제한됩니다.","완료된 작업은 `worklog.done.md`에만追加할 수 있습니다."],"es":["Requiere argumentos explícitos para la gestión de tareas","Limitado al acceso al sistema de archivos local para archivos de trabajo","Sólo anexos para tareas completadas en `worklog.done.md`"],"fr":["Nécessite des arguments explicites pour la gestion des tâches","Limité à l''accès au système de fichiers local pour les fichiers de travail","Append-only pour les tâches terminées dans `worklog.done.md`"],"de":["Erfordert explizite Argumente für die Aufgabenverwaltung","Begrenzt auf den lokalen Dateisystem-Zugriff für Arbeitslog-Dateien","Nur Anhang für abgeschlossene Aufgaben in `worklog.done.md`"],"pt":["Exige argumentos explícitos para gerenciamento de tarefas","Limitado ao acesso ao sistema de arquivos local para arquivos de registro de trabalho","Apenas anexação para tarefas concluídas em `worklog.done.md`"],"ru":["Требует явных аргументов для управления задачами","Ограничен доступом к локальной файловой системе для файлов журнала работы","Только добавление для выполненных задач в `worklog.done.md`"],"ar":["يتطلب حججًا صريحة لإدارة المهام","محدود بالوصول إلى نظام الملفات المحلي لملفات سجل العمل","الاستضافة فقط للمهام المنتهية في `worklog.done.md`"]},"version":4},"contentHash":"682e9e38108b4b931bbeec44898d70ae7ed1c4ba327993d5d6317561beb2bb54","qualityScore":54}');
