INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('taewook486/real-estate-mcp/worklog', 'worklog', 'taewook486', 'real-estate-mcp', 'community', 'worklog taewook486 real-estate-mcp community The worklog skill updates task state in worklog files, supporting explicit arguments for task management. It benefits developers and teams by organizing tasks into backlog, in-progress, and completed categories. Worklog 是一个用于更新任务状态和跟踪的工具。它支持将任务状态更新为 done，并将任务记录在相应的日志文件中 Worklog はタスク状態を更新し、追跡するためのツールです。done 状態への更新をサポートし、タスクを対応するログファイルに記録します Worklog는 작업 상태를 업데이트하고 추적하는 데 사용되는 도구입니다. 완료된 상태로 업데이트를 지원하며 작업을 해당 로그 파일에 기록합니다 Worklog es una herramienta para actualizar el estado de tareas en archivos de trabajo. Requiere argumentos explícitos para funcionar Worklog est un outil pour mettre à jour l''état de tâches dans des fichiers de travail. Il nécessite des arguments explicites pour fonctionner Worklog ist ein Tool, um den Status von Aufgaben in Arbeitsdateien zu aktualisieren. Es benötigt explizite Argumente, um zu funktionieren O worklog é uma ferramenta para atualizar o estado das tarefas em arquivos de trabalho, permitindo o rastreamento de tarefas em andamento e concluídas. Worklog — это инструмент для обновления состояния задач в файлах работы, позволяющий отслеживать задачи в процессе и завершенные. سجل العمل هو أداة لتحديث حالة المهام في الملفات، مما يسمح بتتبع المهام قيد التنفيذ والمنتهية. how to use worklog worklog setup guide worklog alternative worklog vs trello worklog install what is worklog worklog for AI agents task state management with worklog worklog file format Worklog 任务状态更新 任务跟踪 CLI 工具 任务管理 AI 工具 AIエージェント 工作流管理 Updates task state in worklog files using explicit arguments Supports three worklog file types: backlog, in-progress, and completed Uses append-only mode for completed tasks in localdocs/worklog.done.md Requires specific argument format: [state] [description] Allows marking tasks as done using the ''done [description]'' command worklog is a task state management system that updates worklog files, including localdocs/worklog.todo.md, localdocs/worklog.doing.md, and localdocs/worklog.done.md, to track task progress.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Gen-AI4/Personal-AI-Employee/ralph-loop', 'community', 'Gen-AI4', 'Personal-AI-Employee', 'Gen-AI4/Personal-AI-Employee', 'ralph-loop', 0, 0, 54, '2026-02-25T04:13:04Z', '2026-03-07T03:45:54.579Z', '8fc88bda7e9f8476187c15dd78f723f4c83b6636b0d09f1f19c44d0c1392a2f7', '{"id":"Gen-AI4/Personal-AI-Employee/ralph-loop","name":"ralph-loop","description":{"en":"The ralph-loop skill enables autonomous task management by keeping Claude working on a task until it reaches a defined completion state, benefiting developers and AI agents.","zh":"Ralph-Loop是一种自动任务循环工具，使用循环状态文件和Stop hook检查任务完成状态","ja":"Ralph-Loopは自動タスクループツールで，ループ状態ファイルとStop hookを使用してタスクの完了状態をチェック","ko":"Ralph-Loop는 자동 작업 루프 도구로, 루프 상태 파일과 Stop hook를 사용하여 작업 완료 상태를 확인","es":"Ralph-loop es un bucle de tarea autónoma que mantiene a Claude trabajando en una tarea hasta alcanzar un estado de completado definido","fr":"Ralph-loop est une boucle de tâche autonome qui maintient Claude en travail sur une tâche jusqu''à atteindre un état de complétion défini","de":"Ralph-loop ist eine autonome Aufgabenschleife, die Claude auf einer Aufgabe arbeiten lässt, bis ein definierter Abschlusszustand erreicht ist","pt":"O ralph-loop é uma ferramenta que permite que Claude trabalhe em tarefas autonomamente até alcançar um estado de conclusão definido.","ru":"ralph-loop - это инструмент, который позволяет Claude работать над задачами автономно до достижения определенного состояния завершения.","ar":"رالف-لووب هو أداة تمكن كلود من العمل على المهام ذاتيًا حتى يصل إلى حالة إكمال محددة."},"seo":{"title":{"en":"ralph-loop: Autonomous Task Loop Setup Guide | AI Agent S...","zh":"Ralph-Loop 自动任务循环设置指南","ja":"Ralph-Loop 自動タスクループのベストプラクティス","ko":"Ralph-Loop 자동 작업 루프 구축 가이드","es":"Guía de configuración de ralph-loop para tareas autónomas","fr":"Configurer ralph-loop pour des tâches autonomes - Guide d...","de":"Ralph-Loop-Setup-Anleitung für autonome Aufgaben","pt":"Guia de Configuração do ralph-loop: Loop de Tarefas Auton...","ru":"Настройка ralph-loop: Автономный Цикл Задач ИИ Агентов","ar":"دليل إعداد رالف-لووب: حلقة المهام الذاتية لآي إيه"},"description":{"en":"Discover how ralph-loop keeps Claude working on tasks until completion. Learn to set up and utilize this autonomous loop for efficient task management.","zh":"了解Ralph-Loop的工作原理和优势，实现AIエージェント的自动任务循环","ja":"Ralph-Loopの機能とメリットを解説，AIエージェントの自動タスクループを実現","ko":"Ralph-Loop의 자동 작업 루프 기능과 이점을 알아보세요, AI 도구의 자동화된 작업 흐름을 구축하세요","es":"Aprende a configurar ralph-loop para mantener a Claude trabajando en tareas de manera autónoma hasta alcanzar un estado de completado definido","fr":"Découvrez comment configurer ralph-loop pour maintenir Claude en travail autonome sur des tâches jusqu''à atteindre un état de complétion défini","de":"Erfahren Sie, wie Sie ralph-loop konfigurieren, um Claude autonome Aufgaben ausführen zu lassen, bis ein definierter Abschlusszustand erreicht ist","pt":"Aprenda a configurar o ralph-loop para manter Claude trabalhando em tarefas autonomamente até alcançar um estado de conclusão definido.","ru":"Узнайте, как настроить ralph-loop, чтобы giữать Claude работая над задачами автономно до достижения определенного состояния завершения.","ar":"تعرف على كيفية إعداد رالف-لووب للاحتفاظ بكلود يعمل على المهام ذاتيًا حتى يصل إلى حالة إكمال محددة."},"definition":{"en":"ralph-loop is an autonomous task loop that keeps Claude working on a task until it reaches a defined completion state.","zh":"Ralph-Loop是一种自动任务循环工具，用于保持AIエージェント的工作状态","ja":"Ralph-LoopはAIエージェントの自動タスクループを実現するツール","ko":"Ralph-Loop는 AI 도구의 자동 작업 루프를 구현하는 도구","es":"Ralph-loop es una herramienta de agente de inteligencia artificial que permite crear un bucle de tarea autónoma","fr":"Ralph-loop est un outil d''agent d''intelligence artificielle qui permet de créer une boucle de tâche autonome","de":"Ralph-loop ist ein Werkzeug für künstliche Intelligenz-Agenten, mit dem eine autonome Aufgabenschleife erstellt werden kann","pt":"O ralph-loop é um loop de tarefas autonomas que mantém Claude trabalhando até alcançar um estado de conclusão definido.","ru":"ralph-loop - это автономный цикл задач, который поддерживает работу Claude до достижения определенного состояния завершения.","ar":"رالف-لووب هو حلقة مهام ذاتية تتيح لคลود العمل حتى يصل إلى حالة إكمال محددة."},"features":{"en":["Creates a loop state file with task prompt and completion criteria","Iterates through tasks using Claude","Checks task completion using the Stop hook","Re-injects prompts for incomplete tasks up to max iterations","Allows Claude to exit when task is complete or max iterations are reached"],"zh":["循环状态文件创建","Stop hook检查任务完成状态","自动任务循环","最大迭代次数设置","CLI集成"],"ja":["ループ状態ファイルの作成","Stop hookによるタスク完了状態のチェック","自動タスクループ","最大イテレーション回数の設定","CLIとの統合"],"ko":["루프 상태 파일 생성","Stop hook를 통한 작업 완료 상태 확인","자동 작업 루프","최대 반복 횟수 설정","CLI 통합"],"es":["Crea un archivo de estado de bucle con el prompt de la tarea y los criterios de completado","Permite a Claude trabajar en la tarea de manera autónoma","Verifica el estado de completado al salir","Reinjeta el prompt si la tarea no está completa","Permite hasta un máximo de iteraciones"],"fr":["Crée un fichier d''état de boucle avec le prompt de la tâche et les critères de complétion","Permet à Claude de travailler sur la tâche de manière autonome","Vérifie l''état de complétion à la sortie","Réinjecte le prompt si la tâche n''est pas complète","Permet jusqu''à un maximum d''itérations"],"de":["Erstellt eine Schleifenstatusdatei mit dem Aufgaben-Prompt und den Abschlusskriterien","Lässt Claude autonome Aufgaben ausführen","Überprüft den Abschlusszustand beim Ausgang","Reinjiziert den Prompt, wenn die Aufgabe nicht abgeschlossen ist","Ermöglicht bis zu einer maximalen Anzahl von Iterationen"],"pt":["Criação de um arquivo de estado de loop com o prompt da tarefa e critérios de conclusão","Iteração contínua até alcançar o estado de conclusão definido","Verificação do estado de conclusão após cada iteração","Reinjeção do prompt se a tarefa não estiver concluída","Suporte a até max iterações"],"ru":["Создание файла состояния цикла с задачей и критериями завершения","Постоянная итерация до достижения определенного состояния завершения","Проверка состояния завершения после каждой итерации","Переинъекция задачи, если она не завершена","Поддержка до максимального количества итераций"],"ar":["إنشاء ملف حالة الحلقة مع محفز المهمة و معايير الإكمال","التكرار المستمر حتى الوصول إلى حالة إكمال محددة","التحقق من حالة الإكمال بعد كل تكرار","إعادة حقن المحفز إذا لم تكن المهمة مكتملة","دعم حتى الحد الأقصى من التكرارات"]},"keywords":{"en":["how to use ralph-loop","ralph-loop setup guide","autonomous task loop","ralph-loop alternative","ralph-loop vs Claude","install ralph-loop","what is ralph-loop","ralph-loop tutorial","ralph-loop documentation"],"zh":["Ralph-Loop","AIエージェント","自动任务循环","循环状态文件","Stop hook","CLI","Python","自动化"],"ja":["Ralph-Loop","AIエージェント","自動タスクループ","ループ状態ファイル","Stop hook","CLI","Python","自動化"],"ko":["Ralph-Loop","AI 도구","자동 작업 루프","루프 상태 파일","Stop hook","CLI","Python","자동화"],"es":["ralph-loop","agente de inteligencia artificial","tareas autónomas","bucle de tarea","configuración de ralph-loop","guía de inicio de ralph-loop","herramientas de inteligencia artificial"],"fr":["ralph-loop","agent d''intelligence artificielle","tâches autonomes","boucle de tâche","configuration de ralph-loop","guide de démarrage de ralph-loop","outils d''intelligence artificielle"],"de":["ralph-loop","künstliche Intelligenz-Agenten","autonome Aufgaben","Aufgabenschleife","Konfiguration von ralph-loop","Anleitung zur Einrichtung von ralph-loop","Werkzeuge für künstliche Intelligenz"],"pt":["ralph-loop","loop de tarefas autonomas","ferramenta de automação","configuração de tarefas","estado de conclusão","iteração contínua","verificação de estado","reinjeção de prompt"],"ru":["ralph-loop","автономный цикл задач","инструмент автоматизации","настройка задач","состояние завершения","постоянная итерация","проверка состояния","переинъекция задачи","ИИ Агенты"],"ar":["رالف-لووب","حلقة مهام ذاتية","أداة تلقائية","إعداد المهام","حالة إكمال","تكرار مستمر","التحقق من حالة","إعادة حقن المحفز","آي إيه"]}},"owner":"Gen-AI4","repo":"Personal-AI-Employee","repoPath":"Gen-AI4/Personal-AI-Employee","stars":0,"forks":0,"updatedAt":"2026-02-25T04:13:04Z","topics":[],"category":"community","skillMd":{"name":"ralph-loop","description":"|","bodyPreview":"# Ralph Wiggum Autonomous Task Loop\n\nKeep Claude working on a task autonomously until it reaches a defined completion state.\n\n## How It Works\n\n1. **Start**: Create a loop state file with the task prompt and completion criteria\n2. **Iterate**: Claude works on the task\n3. **Check**: At exit, the Stop hook checks if the task is complete\n4. **Continue**: If not complete, the prompt is re-injected (up to max iterations)\n5. **Done**: When complete (or max iterations hit), Claude is allowed to exit\n\n##","body":"# Ralph Wiggum Autonomous Task Loop\n\nKeep Claude working on a task autonomously until it reaches a defined completion state.\n\n## How It Works\n\n1. **Start**: Create a loop state file with the task prompt and completion criteria\n2. **Iterate**: Claude works on the task\n3. **Check**: At exit, the Stop hook checks if the task is complete\n4. **Continue**: If not complete, the prompt is re-injected (up to max iterations)\n5. **Done**: When complete (or max iterations hit), Claude is allowed to exit\n\n## Two Completion Strategies\n\n### Strategy 1: Promise-Based (Simple)\nClaude outputs `<promise>TASK_COMPLETE</promise>` in its response to signal completion.\n\n```\nExample task prompt:\n\"Process all files in /Needs_Action.\nWhen all items are processed and moved to /Done, output: <promise>TASK_COMPLETE</promise>\"\n```\n\n### Strategy 2: File-Movement-Based (Gold Tier)\nThe Stop hook watches for a specific task file to move to `/Done`.\nMore reliable because completion is a natural part of the workflow.\n\n```\nExample: Start a loop watching for \"TASK_20260223_inbox_sweep\" in /Done\nWhen the file appears in /Done, the loop exits naturally.\n```\n\n## Usage\n\n### Start a Ralph Loop (Promise Strategy)\n```python\nfrom ralph_loop import RalphLoop\n\nloop = RalphLoop(vault_path=\"./vault\")\nstate = loop.start(\n    prompt=\"Process all pending items in /Needs_Action. \"\n           \"For each item, create a plan and move to /Done. \"\n           \"When ALL items are processed, output: <promise>TASK_COMPLETE</promise>\",\n    completion_promise=\"TASK_COMPLETE\",\n    max_iterations=10,\n)\nprint(f\"Loop started: {state.task_id}\")\n```\n\n### Start a Ralph Loop (File Movement Strategy)\n```python\nfrom ralph_loop import RalphLoop\n\nloop = RalphLoop(vault_path=\"./vault\")\nstate = loop.start(\n    prompt=\"Generate this week''s CEO briefing and save to vault/Briefings/. \"\n           \"Move the trigger file to /Done when complete.\",\n    completion_file=\"TASK_briefing_trigger.md\",\n    max_iterations=5,\n)\n```\n\n### Check Active Loops\n```python\nfrom ralph_loop import RalphLoop\n\nloop = RalphLoop(vault_path=\"./vault\")\nactive = loop.get_active_loops()\nfor state in active:\n    print(f\"Loop {state.task_id}: iteration {state.current_iteration}/{state.max_iterations}\")\n```\n\n## Stop Hook Configuration\n\nTo use the Ralph Wiggum loop, configure the Stop hook in Claude Code settings.\nThe stop hook script at `src/ralph_loop.py` is called when Claude attempts to exit:\n\n```bash\n# In Claude Code settings (settings.json or CLAUDE.md):\n# Add stop hook:\n# python src/ralph_loop.py ./vault\n```\n\nThe hook:\n- Reads Claude''s output from stdin\n- Checks for completion promise OR looks for completion file in /Done\n- Returns exit code 0 (allow exit) or 1 (block and re-inject prompt)\n\n## Security Notes\n- Max iterations prevent infinite loops (default: 10)\n- All loop state stored in `vault/Logs/ralph_*.json` — visible audit trail\n- Loop state files are deleted when loops complete\n- Never loops on destructive operations without human approval first\n\n## Example: Complete Inbox Processing Loop\n```\n/ralph-loop \"Process all items in vault/Needs_Action in priority order (high → medium → low).\nFor each item:\n1. Read the item''s frontmatter\n2. Create a Plan.md in vault/Plans/\n3. If approval needed, create approval request in vault/Pending_Approval/\n4. Otherwise, process and move to vault/Done/\nWhen ALL items in vault/Needs_Action have been moved to vault/Done,\noutput: <promise>TASK_COMPLETE</promise>\"\n--max-iterations 15\n```\n"},"lastSynced":"2026-03-07T03:45:54.579Z","agentAnalysis":{"suitability":{"en":"Perfect for Autonomous Agents like Claude, needing advanced task management capabilities with defined completion states.","zh":"非常适合像 Claude 这样的自主代理，需要具有定义的完成状态的高级任务管理功能。","ja":"Claude のような高度なタスク管理機能と定義された完了状態を必要とする自律エージェントに最適です。","ko":"Claude와 같은 자율 에이전트에게 적합하며, 미리 정의된 완료 상태를 갖춘 고급 태스크 관리 기능이 필요합니다.","es":"Perfecto para Agentes Autónomos como Claude, que necesitan capacidades de gestión de tareas avanzadas con estados de finalización definidos.","fr":"Parfait pour les Agents Autonomes comme Claude, nécessitant des capacités de gestion de tâches avancées avec des états d''achèvement définis.","de":"Perfekt für autonome Agenten wie Claude, die erweiterte Aufgabenmanagementfunktionen mit definierten Abschlusszuständen benötigen.","pt":"Perfeito para Agentes Autônomos como Claude, necessitando de capacidades de gerenciamento de tarefas avançadas com estados de conclusão definidos.","ru":"Идеально подходит для автономных агентов, таких как Claude, которым необходимы продвинутые возможности управления задачами с определенными состояниями завершения.","ar":"مثالي للوكلاء المستقلين مثل Claude ، الذي يحتاج إلى إمكانيات إدارة مهام متقدمة مع حالات إكمال محددة."},"recommendation":{"en":"Empowers agents to work autonomously on tasks until reaching a defined completion state, utilizing loop state files and iterative prompting with protocols like Stop hooks and max iterations criteria.","zh":"赋予代理在任务上自主工作的能力，直到达到定义的完成状态，利用循环状态文件和迭代提示，以 Stop hooks 和最大迭代标准等协议。","ja":"Stop hooks や最大反復基準などのプロトコルを使用して、ループ状態ファイルとイテレーティブ・プロンプティングを利用し、定義された完了状態に到達するまで、エージェントがタスクで自律的に作業できるようにします。","ko":"스톱 후크나 최대 반복 기준과 같은 프로토콜을 사용하여, 루프 상태 파일과 반복적인 프롬프트를 통해 에이전트가 작업을 수행할 수 있도록 하며, 미리 정의된 완료 상태에 도달할 때까지 작업을 자동화합니다.","es":"Habilita a los agentes a trabajar de forma autónoma en tareas hasta llegar a un estado de finalización definido, utilizando archivos de estado de bucle y protocolos de solicitud iterativa como ganchos de parada y criterios de iteraciones máximas.","fr":"Permet aux agents de travailler de manière autonome sur des tâches jusqu''à atteindre un état d''achèvement défini, en utilisant des fichiers d''état de boucle et des protocoles de sollicitation itérative comme des crochets d''arrêt et des critères d''itérations maximales.","de":"Ermöglicht es Agenten, autonom auf Aufgaben zu arbeiten, bis ein definierter Abschlusszustand erreicht ist, unter Verwendung von Schleifenstatusdateien und iterativer Aufforderungsprotokollen wie Stopp-Hooks und Max-Iterationskriterien.","pt":"Habilita os agentes a trabalhar de forma autônoma em tarefas até atingir um estado de conclusão definido, utilizando arquivos de estado de loop e solicitação iterativa com protocolos como ganchos de parada e critérios de iterações máximas.","ru":"Наделяет агентов возможностью работать автономно над задачами до достижения определенного состояния завершения, используя файлы состояния цикла и итеративный запрос с протоколами, такими как крючки остановки и критерии максимального количества итераций.","ar":"يمنح الوكلاء القدرة على العمل بشكل مستقل في المهام حتى الوصول إلى حالة إكمال محددة، باستخدام ملفات حالة الحلقة والاستعلام التكراري بروتوكولات مثل مشابك الإيقاف ومعايير الحدود الأقصى للتحولات."},"useCases":{"en":["Automating task completion with iterative prompting","Managing tasks with defined completion criteria","Enhancing agent productivity with autonomous loop management"],"zh":["使用迭代提示实现任务自动完成","使用定义的完成标准管理任务","通过自主循环管理提高代理的生产力"],"ja":["イテレーティブ・プロンプティングを使用したタスクの自動完了","定義された完了基準を使用したタスクの管理","自律的なループ管理を使用したエージェントの生産性の向上"],"ko":["반복적인 프롬프트를 사용하여 태스크 자동 완성을 구현하는 것","정의된 완료 기준을 사용하여 태스크를 관리하는 것","자율적인 루프 관리를 통해 에이전트의 생산성을 향상시키는 것"],"es":["Automatización de la finalización de tareas con solicitud iterativa","Gestión de tareas con criterios de finalización definidos","Mejora de la productividad del agente con gestión autónoma de bucle"],"fr":["Automatisation de l''achèvement des tâches avec sollicitation itérative","Gestion des tâches avec des critères d''achèvement définis","Amélioration de la productivité de l''agent avec une gestion autonome de boucle"],"de":["Automatisierung der Aufgabenabschluss mit iterativer Aufforderung","Aufgabenmanagement mit definierten Abschlusskriterien","Steigerung der Agentenproduktivität mit autonomer Schleifenverwaltung"],"pt":["Automatizar a conclusão de tarefas com solicitação iterativa","Gerenciar tarefas com critérios de conclusão definidos","Aumentar a produtividade do agente com gerenciamento de loop autônomo"],"ru":["Автоматизация завершения задач с итеративным запросом","Управление задачами с определенными критериями завершения","Повышение производительности агента с помощью автономного управления циклом"],"ar":["توفير إكمال المهام مع الطلب التكراري","إدارة المهام مع معايير إكمال محددة","تعزيز إنتاجية الوكيل مع إدارة الحلقة المستقلة"]},"limitations":{"en":["Requires loop state file creation","Dependent on max iterations setting","Limited to Claude or similar agent architectures"],"zh":["需要创建循环状态文件","依赖于最大迭代设置","仅限于 Claude 或类似的代理架构"],"ja":["ループ状態ファイルの作成が必要","最大反復設定に依存する","Claude または同様のエージェント・アーキテクチャのみに限定される"],"ko":["루프 상태 파일 생성이 필요","최대 반복 설정에 의존","Claude 또는 유사한 에이전트 아키텍처에만 제한"],"es":["Requiere la creación de archivos de estado de bucle","Dependiente de la configuración de iteraciones máximas","Limitado a Claude o arquitecturas de agentes similares"],"fr":["Nécessite la création de fichiers d''état de boucle","Dépendante de la configuration d''itérations maximales","Limité à Claude ou des architectures d''agents similaires"],"de":["Erfordert die Erstellung von Schleifenstatusdateien","Abhängig von der Einstellung der Max-Iterations","Begrenzt auf Claude oder ähnliche Agentenarchitekturen"],"pt":["Requer a criação de arquivos de estado de loop","Depende da configuração de iterações máximas","Limitado a Claude ou arquiteturas de agente semelhantes"],"ru":["Требует создания файлов состояния цикла","Зависит от настройки максимального количества итераций","Ограничен агентом Claude или подобными архитектурами агентов"],"ar":["يتطلب إنشاء ملفات حالة الحلقة","اعتمادًا على إعداد الحدود الأقصى للتحولات","محدود بـ Claude أو هياكل وكلاء مماثلة"]},"version":4},"contentHash":"8fc88bda7e9f8476187c15dd78f723f4c83b6636b0d09f1f19c44d0c1392a2f7","qualityScore":54}');
