INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Gen-AI4/Personal-AI-Employee/ralph-loop', 'ralph-loop', 'Gen-AI4', 'Personal-AI-Employee', 'community', 'ralph-loop Gen-AI4 Personal-AI-Employee community The ralph-loop skill enables autonomous task management by keeping Claude working on a task until it reaches a defined completion state, benefiting developers and AI agents. Ralph-Loop是一种自动任务循环工具，使用循环状态文件和Stop hook检查任务完成状态 Ralph-Loopは自動タスクループツールで，ループ状態ファイルとStop hookを使用してタスクの完了状態をチェック Ralph-Loop는 자동 작업 루프 도구로, 루프 상태 파일과 Stop hook를 사용하여 작업 완료 상태를 확인 Ralph-loop es un bucle de tarea autónoma que mantiene a Claude trabajando en una tarea hasta alcanzar un estado de completado definido Ralph-loop est une boucle de tâche autonome qui maintient Claude en travail sur une tâche jusqu''à atteindre un état de complétion défini Ralph-loop ist eine autonome Aufgabenschleife, die Claude auf einer Aufgabe arbeiten lässt, bis ein definierter Abschlusszustand erreicht ist O ralph-loop é uma ferramenta que permite que Claude trabalhe em tarefas autonomamente até alcançar um estado de conclusão definido. ralph-loop - это инструмент, который позволяет Claude работать над задачами автономно до достижения определенного состояния завершения. رالف-لووب هو أداة تمكن كلود من العمل على المهام ذاتيًا حتى يصل إلى حالة إكمال محددة. how to use ralph-loop ralph-loop setup guide autonomous task loop ralph-loop alternative ralph-loop vs Claude install ralph-loop what is ralph-loop ralph-loop tutorial ralph-loop documentation Ralph-Loop AIエージェント 自动任务循环 循环状态文件 Stop hook CLI Python 自动化 Creates a loop state file with task prompt and completion criteria Iterates through tasks using Claude Checks task completion using the Stop hook Re-injects prompts for incomplete tasks up to max iterations Allows Claude to exit when task is complete or max iterations are reached ralph-loop is an autonomous task loop that keeps Claude working on a task until it reaches a defined completion state.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pinoshe/real-estate-app/db', 'community', 'pinoshe', 'real-estate-app', 'pinoshe/real-estate-app', 'db', 0, 0, 54, '2026-03-05T20:16:57Z', '2026-03-07T03:51:20.751Z', '083174a3b816c13a21f11ef569a097e91b66f5515db7627f1728c6f059b00f66', '{"id":"pinoshe/real-estate-app/db","name":"db","description":{"en":"The db skill manages PostgreSQL databases via Prisma, targeting the backend at C:/Users/pi/projects/rea/main/backend. It benefits developers working with real estate apps.","zh":"db 技术允许您使用 Prisma 管理 PostgreSQL 数据库，支持迁移和部署等操作","ja":"db 技術は、Prisma を使用して PostgreSQL データベースを管理し、移行やデプロイなどをサポートします","ko":"db 설정은 Prisma를 사용하여 PostgreSQL 데이터베이스를 관리하며, 마이그레이션 및 배포를 지원합니다","es":"El skill db permite gestionar la base de datos PostgreSQL con Prisma para aplicaciones de Real Estate. Incluye acciones como migrar y crear migraciones durante el desarrollo.","fr":"Le skill db permet de gérer la base de données PostgreSQL avec Prisma pour les applications immobilières. Il inclut des actions telles que la migration et la création de migrations pendant le développement.","de":"Das db-Skill ermöglicht die Verwaltung der PostgreSQL-Datenbank mit Prisma für Immobilien-Anwendungen. Es umfasst Aktionen wie Migrationen und die Erstellung von Migrationen während der Entwicklung.","pt":"A skill db é uma ferramenta para gerenciar bancos de dados PostgreSQL com Prisma. Ela executa comandos no backend e gerencia migrações de dados.","ru":"ИИ Агенты db - это инструмент для управления базами данных PostgreSQL с помощью Prisma. Он выполняет команды в backend и управляет миграциями данных.","ar":"أداة db هي أداة لإدارة قواعد بيانات PostgreSQL باستخدام Prisma. وهي تنفذ أوامر في الخلفية وتدير هجرات البيانات."},"seo":{"title":{"en":"db: PostgreSQL Database Management for AI Agents | AI Age...","zh":"db 技术指南：PostgreSQL 数据库管理","ja":"db セットアップガイド：PostgreSQL データベース操作","ko":"db 설정 가이드: PostgreSQL 데이터베이스 관리","es":"Guía de configuración de db para aplicaciones de Real Estate","fr":"Guide de configuration de db pour applications immobilières","de":"Konfigurationsleitfaden für db in Immobilien-Anwendungen","pt":"Guia de Configuração db para Desenvolvedores","ru":"ИИ Агенты: Настройка db для PostgreSQL","ar":"إعداد أداة db للبرمجيات الحرة"},"description":{"en":"Discover how to manage your PostgreSQL database with the db skill, featuring Prisma and Docker. Learn how to run migrations and optimize your database setup ...","zh":"了解 db 技术，使用 Prisma 管理 PostgreSQL 数据库，包括迁移和部署","ja":"db 技術の概要：Prisma を使用して PostgreSQL データベースを管理します","ko":"db 설정 방법: Prisma를 사용하여 PostgreSQL 데이터베이스를 관리합니다","es":"Aprende a configurar y gestionar la base de datos PostgreSQL con Prisma para tu aplicación de Real Estate. Descubre cómo ejecutar migraciones y más.","fr":"Découvrez comment configurer et gérer la base de données PostgreSQL avec Prisma pour votre application immobilière. Apprenez à exécuter des migrations et plu...","de":"Erfahren Sie, wie Sie die PostgreSQL-Datenbank mit Prisma für Ihre Immobilien-Anwendung konfigurieren und verwalten. Erhalten Sie Informationen über die Ausf...","pt":"Aprenda a configurar a skill db para gerenciar bancos de dados PostgreSQL com Prisma e Docker","ru":"Настройте ИИ Агенты db для управления базами данных PostgreSQL с помощью Prisma и Docker","ar":"تعلم كيفية إعداد أداة db لإدارة قواعد بيانات PostgreSQL باستخدام Prisma و Docker"},"definition":{"en":"db is a skill that enables PostgreSQL database management via Prisma, supporting actions like migration and deployment.","zh":"db 是一种使用 Prisma 管理 PostgreSQL 数据库的技术","ja":"db は、Prisma を使用して PostgreSQL データベースを管理する技術です","ko":"db는 Prisma를 사용하여 PostgreSQL 데이터베이스를 관리하는 기술입니다","es":"El skill db es una herramienta de gestión de bases de datos para aplicaciones de Real Estate que utiliza Prisma y PostgreSQL.","fr":"Le skill db est un outil de gestion de bases de données 