INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pinoshe/real-estate-app/db', 'db', 'pinoshe', 'real-estate-app', 'community', 'db pinoshe real-estate-app community The db skill manages PostgreSQL databases via Prisma, targeting the backend at C:/Users/pi/projects/rea/main/backend. It benefits developers working with real estate apps. db 技术允许您使用 Prisma 管理 PostgreSQL 数据库，支持迁移和部署等操作 db 技術は、Prisma を使用して PostgreSQL データベースを管理し、移行やデプロイなどをサポートします db 설정은 Prisma를 사용하여 PostgreSQL 데이터베이스를 관리하며, 마이그레이션 및 배포를 지원합니다 El skill db permite gestionar la base de datos PostgreSQL con Prisma para aplicaciones de Real Estate. Incluye acciones como migrar y crear migraciones durante el desarrollo. Le skill db permet de gérer la base de données PostgreSQL avec Prisma pour les applications immobilières. Il inclut des actions telles que la migration et la création de migrations pendant le développement. Das db-Skill ermöglicht die Verwaltung der PostgreSQL-Datenbank mit Prisma für Immobilien-Anwendungen. Es umfasst Aktionen wie Migrationen und die Erstellung von Migrationen während der Entwicklung. A skill db é uma ferramenta para gerenciar bancos de dados PostgreSQL com Prisma. Ela executa comandos no backend e gerencia migrações de dados. ИИ Агенты db - это инструмент для управления базами данных PostgreSQL с помощью Prisma. Он выполняет команды в backend и управляет миграциями данных. أداة db هي أداة لإدارة قواعد بيانات PostgreSQL باستخدام Prisma. وهي تنفذ أوامر في الخلفية وتدير هجرات البيانات. how to use db db setup guide PostgreSQL database management Prisma tutorial db vs Prisma db install what is db db alternative db documentation db 技术 PostgreSQL 数据库管理 Prisma 迁移和部署 Docker 数据库操作 AI エージェント AI 技术 Runs pending migrations against the local database using `npx prisma migrate deploy` Creates new migrations during development with `npx prisma mi` Supports Docker execution with `docker exec rea-backend sh -c` Targets the backend at `C:/Users/pi/projects/rea/main/backend` Parses `$ARGUMENTS` for the action Deploys migrations using Prisma db is a skill that enables PostgreSQL database management via Prisma, supporting actions like migration and deployment.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jenkinsm13/resolve-mcp/review-cut', 'community', 'jenkinsm13', 'resolve-mcp', 'jenkinsm13/resolve-mcp', 'review-cut', 0, 0, 54, '2026-02-22T21:30:50Z', '2026-03-07T03:52:13.974Z', '7bb2eac8db13552f2793122a0f3fec4aca87d5c3370d1cfc794182c155618b89', '{"id":"jenkinsm13/resolve-mcp/review-cut","name":"review-cut","description":{"en":"The review-cut skill enables developers to automate video review processes, generating lightweight review exports and uploading them to Gemini for AI-powered feedback. This benefits developers and video editors seeking to streamline their review workflows.","zh":"Review Cut AI 工具允许开发者渲染轻量级审查导出并上传到 Gemini，以获取 AI 视觉反馈","ja":"Review Cut AI エージェントは、開発者が軽量のレビュー Export をレンダリングし、Gemini にアップロードして AI の視覚的なフィードバックを取得できるようにします","ko":"리뷰 컷 AI 도구는 개발자가 경량 리뷰 익스ポート를 렌더링하고 Gemini에 업로드하여 AI 시각적 피드백을 받을 수 있도록 합니다","es":"review-cut es una habilidad que renderiza una exportación de revisión ligera y la sube a Gemini para obtener retroalimentación de IA","fr":"review-cut est une compétence qui rend une exportation de révision légère et la télécharge à Gemini pour obtenir une rétroaction de l''IA","de":"review-cut ist eine Fähigkeit, die eine leichte Überprüfungsexport rendert und an Gemini überträgt, um eine KI-Rückmeldung zu erhalten","pt":"O Review-Cut é uma ferramenta que renderiza exportações leves de revisão e as envia para o Gemini para feedback do AI","ru":"Review-Cut - это инструмент, который рендерит легкие экспорты ревью и отправляет их в Gemini для обратной связи ИИ","ar":"Review-Cut هو أداة لتصدير المراجعات الخفيفة و إرسالها إلى Gemini للحصول على ملاحظات الإي"},"seo":{"title":{"en":"review-cut: AI-Powered Video Review Setup Guide | AI Agen...","zh":"Review Cut AI 工具 Setup Guide - 使用 Gemini 进行智能审查","ja":"Review Cut AI エージェントの設定方法 - Gemini を使用したタイムラインのフィードバック","ko":"리뷰 컷 AI 도구 설정 가이드 - Gemini 를 사용한 타임라인 피드백","es":"Configuración de review-cut: Guía de implementación de AI...","fr":"Paramétrage de review-cut: Guide d''intégration d''outils d''IA","de":"Einrichtung von review-cut: Leitfaden für die Implementie...","pt":"Guia de Configuração do Review-Cut: Ferramentas de AI par...","ru":"Настройка Review-Cut: Руководство по использованию ИИ Аге...","ar":"دليل إعداد Review-Cut: أدوات الإي الأبتكارية للمطورين"},"description":{"en":"Unlock efficient video review workflows with review-cut. Learn how to render lightweight review exports, upload to Gemini, and get AI visual feedback. Get st...","zh":"了解如何使用 Review Cut AI 工具来渲染轻量级审查导出并上传到 Gemini，获取 AI 视觉反馈","ja":"Review Cut AI エージェントを使用して軽量のレビュー Export をレンダリングし、Gemini にアップロードして AI の視覚的なフィードバックを取得する方法","ko":"리뷰 컷 AI 도구를 사용하여 경량 리뷰 익스ポート를 렌더링하고 Gemini에 업로드하여 AI 시각적 피드백을 받는 방법","es":"Aprende a configurar review-cut para renderizar y subir exportaciones de revisión a Gemini y obtener retroalimentación de IA","fr":"Découvrez comment paramétrer review-cut pour rendre et télécharger des exportations de révision à Gemini et obtenir une rétroaction de l''IA","de":"Erfahren Sie, wie Sie review-cut einrichten, um Überprüfungsexporte an Gemini zu rendern und zu übertragen und eine KI-Rückmeldung zu erhalten","pt":"Aprenda a configurar o Review-Cut para renderizar exportações leves de revisão e obter feedback visual do AI com Gemini","ru":"Узнайте, как настроить Review-Cut для рендеринга легких экспортов ревью и получения визуальной обратной связи от ИИ с Gemini","ar":"تعلم كيفية إعداد Review-Cut لتصدير مراجعات خفيفة و الحصول على ملاحظات بصرية من الإي مع Gemini"},"definition":{"en":"review-cut is a skill that renders lightweight review exports and uploads them to Gemini for AI visual feedback, optionally saving the review file for client distribution.","zh":"Review Cut AI 工具是一种使用 Gemini 进行智能审查的工具","ja":"Review Cut AI エージェントは、Gemini を使用したタイムラインのフィードバックを提供するツール","ko":"리뷰 컷 AI 도구는 Gemini 를 사용한 타임라인 피드백을 제공하는 도구","es":"review-cut es una habilidad de AI Agent que permite renderizar y subir exportaciones de revisión a Gemini","fr":"review-cut est une compétence d''outil d''IA qui permet de rendre et de télécharger des exportations de révision à Gemini","de":"review-cut ist eine Fähigkeit von KI-Tools, die das Rendern und Übertragen von Überprüfungsexporten an Gemini ermöglicht","pt":"O que é Review-Cut? É uma ferramenta de AI que auxilia desenvolvedores a renderizar e enviar revisões para feedback","ru":"Что такое Review-Cut? Это инструмент ИИ, помогающий разработчикам рендерить и отправлять ревью на обратную связь","ar":"ما هو Review-Cut؟ هو أداة الإي التي تساعد المطورين على تصدير و إرسال المراجعات للحصول على ملاحظات"},"features":{"en":["Renders lightweight review exports for efficient video review","Uploads review exports to Gemini for AI-powered visual feedback","Optionally saves review renders to disk for client distribution","Supports rendering with watermark text for client reviews","Provides specific feedback on pacing through Gemini integration"],"zh":["渲染轻量级审查导出","上传到 Gemini 以获取 AI 视觉反馈","可选保存审查文件","支持添加水印文本","支持指定反馈类型，例如节奏反馈"],"ja":["軽量のレビュー Export をレンダリング","Gemini にアップロードして AI の視覚的なフィードバックを取得","レビュー ファイルを保存することができる","ウォーターマーク テキストを追加することができる","フィードバックのタイプを指定することができる、たとえばペースのフィードバック"],"ko":["경량 리뷰 익스ポート 렌더링","Gemini에 업로드하여 AI 시각적 피드백 받기","리뷰 파일 저장 지원","워터마크 텍스트 추가 지원","피드백 유형 지정 지원, 예를 들어 페이스 피드백"],"es":["Renderización de exportaciones de revisión ligeras","Subida de exportaciones a Gemini para obtener retroalimentación de IA","Opción para guardar la exportación de revisión en disco","Posibilidad de agregar texto de marca de agua para clientes","Retroalimentación de IA sobre el ritmo de la revisión"],"fr":["Rendu d''exportations de révision légères","Téléchargement d''exportations à Gemini pour obtenir une rétroaction de l''IA","Option pour enregistrer l''exportation de révision sur disque","Possibilité d''ajouter un texte de filigrane pour les clients","Rétroaction de l''IA sur le rythme de la révision"],"de":["Rendern von leichten Überprüfungsexporten","Übertragung von Exporten an Gemini für eine KI-Rückmeldung","Option zum Speichern der Überprüfungsexport auf Datenträger","Möglichkeit, Wasserzeichen-Text für Kunden hinzuzufügen","KI-Rückmeldung über den Rhythmus der Überprüfung"],"pt":["Renderização de exportações leves de revisão","Envio de revisões para o Gemini para feedback do AI","Opção de salvar o arquivo de revisão para envio aos clientes","Suporte a renderização com texto de marca d''água","Opção de solicitar feedback do AI sobre o ritmo da revisão"],"ru":["Рендеринг легких экспортов ревью","Отправка ревью в Gemini для обратной связи ИИ","Возможность сохранить файл ревью для отправки клиентам","Поддержка рендеринга с текстом водяного знака","Возможность запросить обратную связь ИИ по темпу ревью"],"ar":["تصدير المراجعات الخفيفة","إرسال المراجعات إلى Gemini للحصول على ملاحظات الإي","خيار الحفظ الملف المراجعة لإرساله إلى العملاء","دعم التصدير مع نص العلامة المائية","خيار طلب ملاحظات الإي حول إيقاع المراجعة"]},"keywords":{"en":["how to use review-cut","review-cut setup guide","review-cut alternative","review-cut vs manual video review","Gemini AI integration","video review automation","lightweight review export","AI-powered video feedback","review-cut install"],"zh":["Review Cut AI 工具","Gemini AI","轻量级审查导出","AI 视觉反馈","审查文件保存","水印文本添加","节奏反馈"],"ja":["Review Cut AI エージェント","Gemini AI","軽量のレビュー Export","AI の視覚的なフィードバック","レビュー ファイルの保存","ウォーターマーク テキストの追加","ペースのフィードバック"],"ko":["리뷰 컷 AI 도구","Gemini AI","경량 리뷰 익스ポート","AI 시각적 피드백","리뷰 파일 저장","워터마크 텍스트 추가","페이스 피드백"],"es":["review-cut","AI Agents","Herramientas de IA","Gemini","Retroalimentación de IA","Renderización de video","Subida de archivos","Clientes de desarrollo"],"fr":["review-cut","Outils d''IA","Agents d''IA","Gemini","Rétroaction de l''IA","Rendu de vidéo","Téléchargement de fichiers","Clients de développement"],"de":["review-cut","KI-Tools","KI-Agents","Gemini","KI-Rückmeldung","Videorendering","Dateiübertragung","Entwicklungsclients"],"pt":["Review-Cut","Ferramentas de AI para desenvolvedores","Gemini","Renderização de revisão","Feedback do AI","Desenvolvimento de software","Ferramentas de desenvolvimento","AI para desenvolvedores","Review-Cut tutorial"],"ru":["Review-Cut","ИИ Агенты для разработчиков","Gemini","Рендеринг ревью","Обратная связь ИИ","Разработка программного обеспечения","Инструменты разработки","ИИ для разработчиков","Review-Cut руководство"],"ar":["Review-Cut","أدوات الإي للمطورين","Gemini","تصدير المراجعة","ملاحظات الإي","تطوير البرمجيات","أدوات التطوير","الإي للمطورين","دليل Review-Cut"]}},"owner":"jenkinsm13","repo":"resolve-mcp","repoPath":"jenkinsm13/resolve-mcp","stars":0,"forks":0,"updatedAt":"2026-02-22T21:30:50Z","topics":[],"category":"community","skillMd":{"name":"review-cut","description":"Render a quick review cut with burned-in timecode and watermark, then feed it to Gemini so the AI can see the current state of the timeline and give editorial feedback.","bodyPreview":"# /review-cut — Review Cut + AI Visual Feedback\n\nRender a lightweight review export, then upload it to Gemini so the AI can actually watch the timeline and give feedback. Optionally save the review file for sending to clients.\n\n## Arguments\n\n- No arguments: render review, upload to Gemini, get AI feedback\n- `save to /path/`: also save the review render to disk\n- `for client`: render with watermark text (e.g., \"REVIEW COPY — NOT FOR DISTRIBUTION\")\n- `feedback on pacing`: give Gemini a specific fo","body":"# /review-cut — Review Cut + AI Visual Feedback\n\nRender a lightweight review export, then upload it to Gemini so the AI can actually watch the timeline and give feedback. Optionally save the review file for sending to clients.\n\n## Arguments\n\n- No arguments: render review, upload to Gemini, get AI feedback\n- `save to /path/`: also save the review render to disk\n- `for client`: render with watermark text (e.g., \"REVIEW COPY — NOT FOR DISTRIBUTION\")\n- `feedback on pacing`: give Gemini a specific focus area\n\n## Workflow\n\n### 1. Get timeline info\n\nUse `resolve_get_timeline_info` to get the timeline name, duration, frame rate, and resolution.\n\n### 2. Render a low-res review cut\n\nSet up a lightweight render specifically for AI review and client screening:\n\n- Use `resolve_set_render_format_and_codec` → MP4 / H.264\n- Use `resolve_set_render_settings` with:\n  ```json\n  {\n    \"SelectAllFrames\": true,\n    \"FormatWidth\": \"1280\",\n    \"FormatHeight\": \"720\",\n    \"VideoQuality\": \"10000000\"\n  }\n  ```\n  (720p, low bitrate — fast to render, small enough to upload to Gemini)\n\n**Burned-in timecode:** Check if a burn-in preset exists with `resolve_get_render_presets`. If there''s one with \"burn\" or \"timecode\" in the name, load it. Otherwise, set render settings to enable data burn-in if the API supports it, or inform the user to enable it manually in the Deliver page.\n\n**Watermark:** If the user requested `for client`, note that the watermark text should be set manually in Resolve''s burn-in settings (the scripting API has limited burn-in control). Mention this to the user.\n\n- Use `resolve_add_render_job` to queue\n- Use `resolve_start_render` to begin\n- Poll with `resolve_get_render_status` until complete\n\n### 3. Upload to Gemini for visual analysis\n\nThis is the key differentiator — the AI actually watches the edit.\n\n- Use `resolve_analyze_timeline` which uploads the timeline''s source proxies to Gemini and runs a full editorial critique\n- This gives Gemini visual context of what''s actually on the timeline\n\nIf `resolve_analyze_timeline` is not available (no Gemini key), skip this step and just deliver the rendered file.\n\n### 4. Return feedback\n\nCombine the Gemini critique with practical next steps:\n\n- **Pacing notes** — which sections drag, which feel rushed\n- **Cut quality** — jump cuts, bad match cuts, continuity issues\n- **Audio** — gaps in dialogue, music drops, levels\n- **Story** — does the narrative track? Are the best moments featured?\n- **Technical** — any obvious issues (black frames, flash frames, out-of-sync)\n\nIf the user specified a focus area (e.g., \"feedback on pacing\"), tell Gemini to prioritize that.\n\n### 5. Save if requested\n\nIf the user asked to save, report the render output path. If they asked `for client`, remind them to verify the watermark/burn-in before sending.\n\n## Example Interactions\n\nUser: `/review-cut`\n→ Render 720p H.264, run resolve_analyze_timeline for AI feedback, report critique.\n\nUser: `/review-cut save to ~/Desktop/`\n→ Same + save the rendered file.\n\nUser: `/review-cut for client`\n→ Render with TC burn-in note about watermark, save for sending.\n\nUser: `/review-cut feedback on pacing and music sync`\n→ Render, upload, ask Gemini to focus on pacing and music sync specifically.\n"},"lastSynced":"2026-03-07T03:52:13.974Z","agentAnalysis":{"suitability":{"en":"Ideal for Video Editing Agents seeking to automate review processes with AI-powered feedback","zh":"适合视频编辑代理寻求使用AI驱动的反馈自动化审查过程","ja":"ビデオ編集エージェントがAIパワーのフィードバックでレビュー过程を自動化するために最適","ko":"비디오 편집 에이전트가 AI 파워의 피드백을 사용하여 검토 프로세스를 자동화하기에 적합","es":"Ideal para Agentes de Edición de Vídeo que buscan automatizar procesos de revisión con comentarios impulsados por IA","fr":"Idéal pour les Agents de Montage Vidéo cherchant à automatiser les processus de révision avec des commentaires alimentés par l''IA","de":"Ideal für Video-Bearbeitungsagenten, die Prozesse zur Überprüfung mit künstlicher Intelligenz-gesteuertem Feedback automatisieren möchten","pt":"Ideal para Agentes de Edição de Vídeo que buscam automatizar processos de revisão com feedback impulsionado por IA","ru":"Идеально для агентов видеомонтажа, стремящихся автоматизировать процессы проверки с помощью отзывов, работающих на ИИ","ar":"مثالي لعميلة تحرير الفيديو الذين يبحثون عن تعزيز العمليات التلقائية لمراجعة مع تقديم ملاحظات مدعومة بالذكاء الاصطناعي"},"recommendation":{"en":"Empowers agents to render lightweight review exports, upload them to Gemini for AI visual feedback, and optionally save review files for client distribution, utilizing protocols like video rendering and upload APIs, and supporting file formats for review exports","zh":"赋予代理渲染轻量级审查导出、将其上传到Gemini进行AI视觉反馈，并可选择保存审查文件用于客户分发，利用诸如视频渲染和上传API的协议，并支持审查导出的文件格式","ja":"エージェントが軽量のレビューexportをレンダリングし、それをGeminiにアップロードしてAIビジュアルフィードバックを受け取り、レビューファイルをクライアントに配布するために保存することを選択的に行うことができるようにし、ビデオレンダリングやアップロードAPIなどのプロトコルを利用し、レビューexportのファイル形式をサポート","ko":"에이전트가 경량의 검토 내보내기 렌더링을 수행하고 이를 Gemini에 업로드하여 AI 시각적 피드백을 받고 검토 파일을 클라이언트에 배포하기 위해 저장하는 것을 선택적으로 수행할 수 있도록 하며 비디오 렌더링 및 업로드 API와 같은 프로토콜을 사용하며 검토 내보내기의 파일 형식을 지원","es":"Permite a los agentes renderizar exportaciones de revisión ligeras, subirlas a Gemini para comentarios visuales de IA y, opcionalmente, guardar archivos de revisión para distribución a clientes, utilizando protocolos como APIs de renderizado de video y subida, y admitiendo formatos de archivo para exportaciones de revisión","fr":"Permet aux agents de rendre des exportations de révision légères, de les télécharger sur Gemini pour des commentaires visuels par IA et, facultativement, d''enregistrer des fichiers de révision pour distribution à la clientèle, en utilisant des protocoles tels que les API de rendu vidéo et de téléchargement, et en prenant en charge les formats de fichiers pour les exportations de révision","de":"Ermöglicht es Agenten, leichte Überprüfungsexporte zu rendern, diese bei Gemini für visuelles IA-Feedback hochzuladen und optional Überprüfungsdateien für die Kundenverteilung zu speichern, wobei Protokolle wie Video-Rendering- und Upload-APIs verwendet und Dateiformate für Überprüfungsexporte unterstützt werden","pt":"Permite que os agentes criem exportações de revisão leves, as carreguem no Gemini para feedback visual de IA e, opcionalmente, salvem arquivos de revisão para distribuição ao cliente, utilizando protocolos como APIs de renderização e upload de vídeo e suportando formatos de arquivo para exportações de revisão","ru":"Позволяет агентам создавать лёгкие экспорты проверки, загружать их в Gemini для визуальной обратной связи ИИ и, при необходимости, сохранять файлы проверки для распространения среди клиентов, используя протоколы, такие как видео-рендеринг и загрузка API, и поддерживая форматы файлов для экспорта проверки","ar":"تمكّن العميل من إنشاء استيرادات مراجعة خفيفة، وتحميلها إلى Gemini لتلقي ملاحظات بصرية مدعومة بالذكاء الاصطناعي، وحفظ ملفات المراجعة بشكل اختياري لتوزيعها على العملاء، مستخدمين بروتوكولات مثل واجهات برمجة التطبيقات لتصيير الفيديو ورفعه، ودعم تنسيقات الملفات لاستيرادات المراجعة"},"useCases":{"en":["Automating video review workflows","Generating AI-powered feedback on video pacing","Creating watermarked review copies for client distribution"],"zh":["自动化视频审查工作流程","生成AI驱动的视频节奏反馈","为客户分发创建水印审查副本"],"ja":["ビデオレビューのワークフローを自動化する","ビデオのペースに関するAIパワーのフィードバックを生成する","クライアントに配布するためのウォーターマーク付きレビューコピーを作成する"],"ko":["비디오 검토 워크플로우를 자동화하는 것","비디오의 페이스에 관한 AI 파워의 피드백을 생성하는 것","클라이언트에 배포하기 위한 워터마크가 있는 검토 복사본을 생성하는 것"],"es":["Automatizar flujos de trabajo de revisión de video","Generar comentarios impulsados por IA sobre el ritmo del video","Crear copias de revisión con marca de agua para distribución a clientes"],"fr":["Automatiser les flux de travail de révision de vidéo","Générer des commentaires alimentés par l''IA sur le rythme de la vidéo","Créer des copies de révision avec filigrane pour distribution aux clients"],"de":["Automatisierung von Videobearbeitungs-Workflows","Erzeugen von künstlicher Intelligenz-gesteuertem Feedback über die Videogeschwindigkeit","Erstellen von überprüften Kopien mit Wasserzeichen für die Kundenverteilung"],"pt":["Automatizar fluxos de trabalho de revisão de vídeo","Gerar feedback impulsionado por IA sobre o ritmo do vídeo","Criar cópias de revisão com marca d''água para distribuição ao cliente"],"ru":["Автоматизация рабочих процессов проверки видео","Генерация отзывов, работающих на ИИ, о темпе видео","Создание водяных знаков проверки для распространения среди клиентов"],"ar":["تأتميم سير عمل مراجعة الفيديو","توليد ملاحظات مدعومة بالذكاء الاصطناعي حول وتيره الفيديو","إنشاء نسخ مراجعة محمية بمعرف مائي لتوزيعها على العملاء"]},"limitations":{"en":["Requires Gemini upload capability","Dependent on AI feedback availability","Optional save to disk functionality requires filesystem access"],"zh":["需要Gemini上传能力","依赖于AI反馈的可用性","可选保存到磁盘的功能需要文件系统访问"],"ja":["Geminiアップロード機能が必要","AIフィードバックの可用性に依存","ディスクへの保存をオプションとする機能はファイルシステムアクセスを必要とする"],"ko":["Gemini 업로드 능력이 필요","AI 피드백의 가용성에 종속","디스크에 저장하는 것을 옵션으로 하는 기능은 파일 시스템 액세스가 필요"],"es":["Requiere capacidad de carga de Gemini","Dependiente de la disponibilidad de comentarios de IA","Funcionalidad opcional de guardar en disco requiere acceso al sistema de archivos"],"fr":["Nécessite la capacité de téléchargement de Gemini","Dépend de la disponibilité des commentaires de l''IA","Fonctionnalité facultative d''enregistrement sur disque nécessite un accès au système de fichiers"],"de":["Benötigt Gemini-Upload-Fähigkeit","Abhängig von der Verfügbarkeit von IA-Feedback","Optionale Festplattenspeicherfunktion erfordert Dateisystemzugriff"],"pt":["Exige capacidade de upload do Gemini","Depende da disponibilidade de feedback de IA","Função de salvamento opcional no disco exige acesso ao sistema de arquivos"],"ru":["Требует возможности загрузки в Gemini","Зависит от наличия обратной связи ИИ","Необязательная функция сохранения на диск требует доступа к файловой системе"],"ar":["يتطلب القدرة على تحميل الملفات إلى Gemini","يعتمد على توافر ملاحظات الذكاء الاصطناعي","ت đòi وظيفة الحفظ الاختيارية على القرص الوصول إلى نظام الملفات"]},"version":4},"contentHash":"7bb2eac8db13552f2793122a0f3fec4aca87d5c3370d1cfc794182c155618b89","qualityScore":54}');
