INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jenkinsm13/resolve-mcp/review-cut', 'review-cut', 'jenkinsm13', 'resolve-mcp', 'community', 'review-cut jenkinsm13 resolve-mcp community The review-cut skill enables developers to automate video review processes, generating lightweight review exports and uploading them to Gemini for AI-powered feedback. This benefits developers and video editors seeking to streamline their review workflows. Review Cut AI 工具允许开发者渲染轻量级审查导出并上传到 Gemini，以获取 AI 视觉反馈 Review Cut AI エージェントは、開発者が軽量のレビュー Export をレンダリングし、Gemini にアップロードして AI の視覚的なフィードバックを取得できるようにします 리뷰 컷 AI 도구는 개발자가 경량 리뷰 익스ポート를 렌더링하고 Gemini에 업로드하여 AI 시각적 피드백을 받을 수 있도록 합니다 review-cut es una habilidad que renderiza una exportación de revisión ligera y la sube a Gemini para obtener retroalimentación de IA review-cut est une compétence qui rend une exportation de révision légère et la télécharge à Gemini pour obtenir une rétroaction de l''IA review-cut ist eine Fähigkeit, die eine leichte Überprüfungsexport rendert und an Gemini überträgt, um eine KI-Rückmeldung zu erhalten O Review-Cut é uma ferramenta que renderiza exportações leves de revisão e as envia para o Gemini para feedback do AI Review-Cut - это инструмент, который рендерит легкие экспорты ревью и отправляет их в Gemini для обратной связи ИИ Review-Cut هو أداة لتصدير المراجعات الخفيفة و إرسالها إلى Gemini للحصول على ملاحظات الإي how to use review-cut review-cut setup guide review-cut alternative review-cut vs manual video review Gemini AI integration video review automation lightweight review export AI-powered video feedback review-cut install Review Cut AI 工具 Gemini AI 轻量级审查导出 AI 视觉反馈 审查文件保存 水印文本添加 节奏反馈 Renders lightweight review exports for efficient video review Uploads review exports to Gemini for AI-powered visual feedback Optionally saves review renders to disk for client distribution Supports rendering with watermark text for client reviews Provides specific feedback on pacing through Gemini integration review-cut is a skill that renders lightweight review exports and uploads them to Gemini for AI visual feedback, optionally saving the review file for client distribution.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dacy/architect-skill/tech-stack-skill', 'community', 'dacy', 'architect-skill', 'dacy/architect-skill', 'tech-stack-skill', 0, 0, 54, '2026-03-02T07:20:36Z', '2026-03-07T04:06:30.876Z', '26c105dfd134b6ba6e952cb83cb73c5368d66e8319d75724b46fc484f7018e30', '{"id":"dacy/architect-skill/tech-stack-skill","name":"tech-stack-skill","description":{"en":"The tech-stack-skill guides technology selection aligned to the company''s opinionated tech stack, defining approved technologies by layer. It benefits developers and architects by providing a framework for creating architecture design","zh":"tech-stack-skill是一种技术栈选择框架，用于创建架构设计。它定义了公司的意见化技术栈，指导技术选择","ja":"tech-stack-skillは、テクノロジー選択を支援するフレームワークです。会社の意見化されたテクノロジー・スタックに基づいて、技術選択を導きます","ko":"tech-stack-skill은 기술 스택 선택을 위한 프레임워크입니다. 회사의 의견화된 기술 스택을 정의하여 기술 선택을 지원합니다","es":"tech-stack-skill es un marco de habilidades para la creación de arquitecturas de diseño, que guía la selección de tecnologías según la pila de tecnologías de la empresa","fr":"tech-stack-skill est un cadre de compétences pour la conception d''architecture, qui guide la sélection de technologies selon la pile de technologies de l''entreprise","de":"tech-stack-skill ist ein Fähigkeitsrahmen für die Architektur-Design, der die Technologieauswahl nach dem Technologie-Stack des Unternehmens leitet","pt":"O Tech Stack Skill é um framework para criar arquiteturas de design, com tecnologias aprovadas e exceções formais","ru":"Tech Stack Skill — это фреймворк для создания архитектур дизайна, с утвержденными технологиями и формальными исключениями","ar":"مهارة Tech Stack هي إطار عمل لإنشاء تصميمات معمارية، مع تقنيات معتمدة واستثناءات رسمية"},"seo":{"title":{"en":"tech-stack-skill: Architecture Design Setup Guide | AI Ag...","zh":"tech-stack-skill 技术栈选择指南","ja":"tech-stack-skill AIエージェントによるテクノロジー選択","ko":"tech-s