INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dacy/architect-skill/tech-stack-skill', 'tech-stack-skill', 'dacy', 'architect-skill', 'community', 'tech-stack-skill dacy architect-skill community The tech-stack-skill guides technology selection aligned to the company''s opinionated tech stack, defining approved technologies by layer. It benefits developers and architects by providing a framework for creating architecture design tech-stack-skill是一种技术栈选择框架，用于创建架构设计。它定义了公司的意见化技术栈，指导技术选择 tech-stack-skillは、テクノロジー選択を支援するフレームワークです。会社の意見化されたテクノロジー・スタックに基づいて、技術選択を導きます tech-stack-skill은 기술 스택 선택을 위한 프레임워크입니다. 회사의 의견화된 기술 스택을 정의하여 기술 선택을 지원합니다 tech-stack-skill es un marco de habilidades para la creación de arquitecturas de diseño, que guía la selección de tecnologías según la pila de tecnologías de la empresa tech-stack-skill est un cadre de compétences pour la conception d''architecture, qui guide la sélection de technologies selon la pile de technologies de l''entreprise tech-stack-skill ist ein Fähigkeitsrahmen für die Architektur-Design, der die Technologieauswahl nach dem Technologie-Stack des Unternehmens leitet O Tech Stack Skill é um framework para criar arquiteturas de design, com tecnologias aprovadas e exceções formais Tech Stack Skill — это фреймворк для создания архитектур дизайна, с утвержденными технологиями и формальными исключениями مهارة Tech Stack هي إطار عمل لإنشاء تصميمات معمارية، مع تقنيات معتمدة واستثناءات رسمية how to use tech-stack-skill what is tech-stack-skill tech-stack-skill alternative tech-stack-skill vs competing frameworks tech-stack-skill install tech-stack-skill setup guide architecture design with tech-stack-skill approved tech catalog exception process for tech-stack-skill tech-stack-skill 技术栈选择 架构设计 意见化技术栈 技术选择 Markdown输出 标准化流程 Guides technology selection aligned to the company''s opinionated tech stack Defines approved technologies by layer Requires formal exception for technologies outside the approved list Generates Tech Stack section for Solution Intent in Markdown (.md) format References approved technology catalog, tier definitions, and exception process in references/tech-stack.md tech-stack-skill is a framework for creating architecture design, guiding technology selection aligned to the company''s opinionated tech stack');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dzhechko/2026-jan-pu-Intercom-clone-01/goap-research-ed25519', 'community', 'dzhechko', '2026-jan-pu-Intercom-clone-01', 'dzhechko/2026-jan-pu-Intercom-clone-01', 'goap-research-ed25519', 0, 0, 54, '2026-03-02T22:48:50Z', '2026-03-07T04:07:41.473Z', '26a49c671d15c1b94b02381bb09eaff98731b64d86b6274e5440a241ceeb80c9', '{"id":"dzhechko/2026-jan-pu-Intercom-clone-01/goap-research-ed25519","name":"goap-research-ed25519","description":{"en":"goap-research-ed25519 combines Goal-Oriented Action Planning with Ed25519 cryptographic verification for advanced research and maximum anti-hallucination protection, benefiting AI agent developers","zh":"GOAP Research Skill With Ed25519 Verification 是一个高级研究系统，结合 Goal-Oriented Action Planning 和 Ed25519 加密验证","ja":"GOAP Research Skill With Ed25519 Verification は、Goal-Oriented Action Planning と Ed25519 暗号検証を組み合わせた高度な研究システムです","ko":"GOAP Research Skill With Ed25519 Verification는 Goal-Oriented Action Planning과 Ed25519 암호화 검증을 결합한 고급 연구 시스템입니다","es":"goap-research-ed25519 combina la planificación de acciones orientadas a objetivos con verificación criptográfica Ed25519 para una protección anti-hallucinación avanzada","fr":"goap-research-ed25519 combine la planification d''actions orientées objet avec la vérification cryptographique Ed25519 pour une protection anti-hallucination avancée","de":"goap-research-ed25519 kombiniert die zielorientierte Handlungsplanung mit Ed25519-Kryptographie-Verifizierung für einen erweiterten Anti-Hallucinations-Schutz","pt":"O goap-research-ed25519 é um sistema de pesquisa avançado que combina Planejamento de Ações Orientado a Objetivos (GOAP) com verificação criptográfica Ed25519","ru":"ИИ Агенты goap-research-ed25519 представляют собой передовую систему исследования, сочетающую Целевое Планирование Действий (GOAP) с криптографической верификацией Ed25519","ar":"goap-research-ed25519 هو نظام بحث متقدم ي結ب بين التخطيط الإجرائي الهادف (GOAP) والتحقق المعماري Ed25519"},"seo":{"title":{"en":"goap-research-ed25519: Advanced Anti-Hallucination Protec...","zh":"GOAP Research Skill With Ed25519 Verification 设置指南","ja":"GOAP Research Skill With Ed25519 Verification のベストプラクティス","ko":"GOAP Research Skill With Ed25519 Verification 구축 가이드","es":"Guía de configuración de goap-research-ed25519 para Agent...","fr":"Configurer goap-research-ed25519 pour les Outils d''IA","de":"Einrichtungsleitfaden für goap-research-ed25519 in KI-Age...","pt":"Guia de Configuração do goap-research-ed25519 com Verific...","ru":"Настройка ИИ Агентов goap-research-ed25519 с Верификацией...","ar":"دليل إعداد goap-research-ed25519 مع التحقق Ed25519 للآلات..."},"description":{"en":"Unlock robust anti-hallucination protection with goap-research-ed25519. Learn how to integrate Ed25519 verification with Goal-Oriented Action Planning for en...","zh":"了解 GOAP Research Skill With Ed25519 Verification 的技术优势，结合 Goal-Oriented Action Planning 和 Ed25519 加密验证","ja":"GOAP Research Skill With Ed25519 Verification の特徴と利点を紹介。AIエージェントの信頼性を高めるためのソリューション","ko":"GOAP Research Skill With Ed25519 Verification의 기능과 장점을 살펴보세요. 개발자들을 위한 안티홀루션 보호 솔루션","es":"Aprende a implementar goap-research-ed25519 para protección anti-hallucinación en Agentes de IA con firmas criptográficas Ed25519","fr":"Découvrez comment mettre en œuvre goap-research-ed25519 pour la protection anti-hallucination dans les Outils d''IA avec des signatures cryptographiques Ed25519","de":"Erfahren Sie, wie Sie goap-research-ed25519 für Anti-Hallucinations-Schutz in KI-Agenten mit Ed25519-Kryptographie-Signaturen implementieren","pt":"Aprenda a configurar o goap-research-ed25519 com verificação Ed25519 para maximizar a proteção anti-hallucinação em sistemas de planejamento de ações","ru":"Узнайте, как настроить ИИ Агенты goap-research-ed25519 с верификацией Ed25519 для максимальной защиты от анти-холлюцинаци