INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dzhechko/2026-jan-pu-Intercom-clone-01/goap-research-ed25519', 'goap-research-ed25519', 'dzhechko', '2026-jan-pu-Intercom-clone-01', 'community', 'goap-research-ed25519 dzhechko 2026-jan-pu-Intercom-clone-01 community goap-research-ed25519 combines Goal-Oriented Action Planning with Ed25519 cryptographic verification for advanced research and maximum anti-hallucination protection, benefiting AI agent developers GOAP Research Skill With Ed25519 Verification 是一个高级研究系统，结合 Goal-Oriented Action Planning 和 Ed25519 加密验证 GOAP Research Skill With Ed25519 Verification は、Goal-Oriented Action Planning と Ed25519 暗号検証を組み合わせた高度な研究システムです GOAP Research Skill With Ed25519 Verification는 Goal-Oriented Action Planning과 Ed25519 암호화 검증을 결합한 고급 연구 시스템입니다 goap-research-ed25519 combina la planificación de acciones orientadas a objetivos con verificación criptográfica Ed25519 para una protección anti-hallucinación avanzada goap-research-ed25519 combine la planification d''actions orientées objet avec la vérification cryptographique Ed25519 pour une protection anti-hallucination avancée goap-research-ed25519 kombiniert die zielorientierte Handlungsplanung mit Ed25519-Kryptographie-Verifizierung für einen erweiterten Anti-Hallucinations-Schutz O goap-research-ed25519 é um sistema de pesquisa avançado que combina Planejamento de Ações Orientado a Objetivos (GOAP) com verificação criptográfica Ed25519 ИИ Агенты goap-research-ed25519 представляют собой передовую систему исследования, сочетающую Целевое Планирование Действий (GOAP) с криптографической верификацией Ed25519 goap-research-ed25519 هو نظام بحث متقدم ي結ب بين التخطيط الإجرائي الهادف (GOAP) والتحقق المعماري Ed25519 how to use goap-research-ed25519 goap-research-ed25519 alternative goap-research-ed25519 install what is goap-research-ed25519 goap-research-ed25519 vs standard GOAP goap-research-ed25519 setup guide Ed25519 verification for AI agents Goal-Oriented Action Planning with cryptographic verification GOAP Research Skill Ed25519 加密验证 Goal-Oriented Action Planning AI 研究系统 抗幻觉保护 加密签名 声明验证 Utilizes Ed25519 cryptographic signatures for source trust and claim verification Employs cross-reference and signature chain for enhanced anti-hallucination protection Combines reliability scoring with cryptographic verification for robust security Supports advanced research systems with Goal-Oriented Action Planning Provides maximum anti-hallucination protection for AI agents Integrates cryptographic verification with standard GOAP features goap-research-ed25519 is an advanced research system integrating Goal-Oriented Action Planning with Ed25519 cryptographic verification for secure and reliable operation');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('akourmaz/translate2/workflow-feature', 'community', 'akourmaz', 'translate2', 'akourmaz/translate2', 'workflow-feature', 0, 0, 54, '2026-03-02T10:07:05Z', '2026-03-07T04:08:36.121Z', '83b078c287235d621d4062d584b10088ec830d33c6440f6d55d5978bc5d05fa2', '{"id":"akourmaz/translate2/workflow-feature","name":"workflow-feature","description":{"en":"The workflow-feature skill enables developers to add new functionality to existing projects. It applies to projects of any complexity, supporting triggers like new feature/modules and API endpoint additions.","zh":"工作流特性用于向现有项目添加新功能，包括触发器和用例，适用于任何复杂度的项目","ja":"ワークフロー機能は、トリガーとユースケースを含む新しい機能を既存のプロジェクトに追加するために使用されます","ko":"워크플로 기능은 트리거와 사용 사례를 포함하여 새로운 기능을 기존 프로젝트에 추가하는 데 사용됩니다","es":"El flujo de trabajo de funcionalidad permite agregar nueva funcionalidad a proyectos existentes de cualquier complejidad","fr":"Le flux de travail de fonctionnalité permet d''ajouter de nouvelles fonctionnalités aux projets existants de toute complexité","de":"Das Workflow-Feature ermöglicht das Hinzufügen neuer Funktionalitäten zu bestehenden Projekten beliebiger Komplexität","pt":"O fluxo de trabalho de recursos é um protocolo para adicionar novas funcionalidades a projetos existentes","ru":"Поток работы функций - это протокол добавления новой функциональности в существующие проекты","ar":"سير عمل ميزة هي بروتوكول لإضافة وظائف جديدة الى المشاريع الحالية"},"seo":{"title":{"en":"workflow-feature: Protocol Setup Guide for AI Agents","zh":"AIエージェント工作流特性设置指南","ja":"AIエージェントのワークフロー機能ベストプラクティス","ko":"AI 에이전트 워크플로 기능 설정 가이드","es":"Guía de Configuración de Flujo de Trabajo de Funcionalidad","fr":"Guide de Mise en Place du Flux de Travail de Fonctionnalité","de":"Einrichtungsleitfaden für Workflow-Feature","pt":"Guia de Configuração do Fluxo de Trabalho de Recursos","ru":"Руководство по настройке потока работы функций ИИ Агентов","ar":"دليل إعداد سير عمل ميزة الوكيل الذكي"},"description":{"en":"Discover how to add new functionality to existing projects with workflow-feature. Learn triggers, use cases, and best practices for seamless integration.","zh":"了解如何使用AIエージェント工作流特性为现有项目添加新功能，包括触发器和用例","ja":"AIエージェントのワークフロー機能を使用して新しい機能を追加する方法を学びます","ko":"AI 에이전트 워크플로 기능을 사용하여 새로운 기능을 추가하는 방법을 알아보세요","es":"Aprende a integrar nuevas funcionalidades en proyectos existentes con nuestro flujo de trabajo de funcionalidad","fr":"Découvrez comment intégrer de nouvelles fonctionnalités dans les projets existants avec notre flux de travail de fonctionnalité","de":"Erfahren Sie, wie Sie neue Funktionalitäten in bestehende Projekte integrieren können, mit unserem Workflow-Feature","pt":"Aprenda a configurar o fluxo de trabalho de recursos para adicionar funcionalidades a projetos existentes com nosso guia passo a passo","ru":"Ознакомьтесь с руководством по настройке потока работы функций для добавления новой функциональности в существующие проекты с помощью ИИ Агентов","ar":"تعرف على دليل إعداد سير عمل ميزة الوكيل الذكي لاضافة وظائف جديدة الى المشاريع الحالية"},"definition":{"en":"workflow-feature is a protocol for adding new functionality to existing projects, applicable to any complexity level.","zh":"工作流特性是一种协议，用于向现有项目添加新功能，适用于任何复杂度的项目","ja":"ワークフロー機能は、既存のプロジェクトに新しい機能を追加するためのプロトコルです","ko":"워크플로 기능은 기존 프로젝트에 새로운 기능을 추가하는 데 사용되는 프로토콜입니다","es":"Un protocolo para agregar funcionalidad a proyectos existentes","fr":"Un protocole pour ajouter des fonctionnalités aux projets existants","de":"Ein Protokoll zum Hinzufügen von Funktionalitäten zu bestehenden Projekten","pt":"O que é fluxo de trabalho de recursos? É um protocolo para adicionar funcionalidades a projetos existentes","ru":"Что такое поток работы функций? Это протокол добавления новой функциональности в существующие проекты","ar":"ما هو سير عمل ميزة؟ هو بروتوكول لإضافة وظائف جديدة الى المشاريع الحالية"},"features":{"en":["Supports addition of new features/modules to existing projects","Enables extension of existing functionality","Facilitates integration with external services","Allows for addition of API endpoints","Provides guidance on when to use and when not to use the workflow-feature protocol"],"zh":["支持添加新功能/模块","支持扩展现有功能","支持集成外部服务","支持添加API端点"],"ja":["新しい機能/モジュールの追加をサポート","既存の機能の拡張をサポート","外部サービスとの統合をサポート","APIエンドポイントの追加をサポート"],"ko":["새로운 기능/모듈 추가 지원","기존 기능 확장 지원","외부 서비스 통합 지원","API 엔드포인트 추가 지원"],"es":["Integración de nuevas funcionalidades en proyectos existentes","Compatibilidad con proyectos de cualquier complejidad","Soporte para la integración con servicios externos","Capacidad para agregar nuevos puntos de terminación de API","Aplicación de protocolos de trabajo para agregar funcionalidad"],"fr":["Intégration de nouvelles fonctionnalités dans les projets existants","Compatibilité avec les projets de toute complexité","Prise en charge de l''intégration avec les services externes","Capacité à ajouter de nouveaux points de terminaison d''API","Application de protocoles de travail pour ajouter des fonctionnalités"],"de":["Integration neuer Funktionalitäten in bestehende Projekte","Kompatibilität mit Projekten beliebiger Komplexität","Unterstützung für die Integration mit externen Diensten","Fähigkeit, neue API-Endpunkte hinzuzufügen","Anwendung von Arbeitsprotokollen zum Hinzufügen von Funktionalitäten"],"pt":["Adiciona novas funcionalidades a projetos existentes","Suporta integração com serviços externos","Permite adicionar endpoints de API","Não é utilizado para novos projetos ou depuração","É aplicável a projetos de qualquer complexidade"],"ru":["Добавляет новые функциональности в существующие проекты","Поддерживает интеграцию с внешними сервисами","Позволяет добавлять точки API","Не используется для новых проектов или отладки","Применяется к проектам любой сложности"],"ar":["يضيف وظائف جديدة الى المشاريع الحالية","يدعم التكامل مع الخدمات الخارجية","يسمح بإضافة نقاط النهاية API","لا يستخدم ل المشاريع الجديدة أو تصحيح الأخطاء","يتم تطبيقه على المشاريع من أي تعقيد"]},"keywords":{"en":["how to use workflow-feature","workflow-feature protocol","adding new functionality to existing projects","workflow-feature vs new-project","workflow-feature setup guide","workflow-feature alternative","workflow-feature install","what is workflow-feature"],"zh":["AIエージェント工作流","工作流特性","添加新功能","扩展现有功能","集成外部服务","添加API端点","项目管理","软件开发"],"ja":["AIエージェントのワークフロー","ワークフロー機能","新しい機能の追加","既存の機能の拡張","外部サービスの統合","APIエンドポイントの追加","プロジェクト管理","ソフトウェア開発"],"ko":["AI 에이전트 워크플로","워크플로 기능","새로운 기능 추가","기존 기능 확장","외부 서비스 통합","API 엔드포인트 추가","프로젝트 관리","소프트웨어 개발"],"es":["flujo de trabajo de funcionalidad","integración de funcionalidades","proyectos existentes","complexidad de proyectos","integración con servicios externos","puntos de terminación de API","protocolos de trabajo","desarrollo de software","ingeniería de software"],"fr":["flux de travail de fonctionnalité","intégration de fonctionnalités","projets existants","complexité de projets","intégration avec les services externes","points de terminaison d''API","protocoles de travail","développement de logiciels","ingénierie de logiciels"],"de":["Workflow-Feature","Integration von Funktionalitäten","bestehende Projekte","Komplexität von Projekten","Integration mit externen Diensten","API-Endpunkte","Arbeitsprotokolle","Software-Entwicklung","Software-Ingenieurwesen"],"pt":["fluxo de trabalho de recursos","adicionar funcionalidades","projetos existentes","integração com serviços externos","endpoints de API","desenvolvimento de software","guias de configuração"],"ru":["поток работы функций","добавление функциональности","существующие проекты","интеграция с внешними сервисами","точки API","разработка программного обеспечения","руководства по настройке","ИИ Агенты"],"ar":["سير عمل ميزة","إضافة وظائف جديدة","المشاريع الحالية","التكامل مع الخدمات الخارجية","نقاط النهاية API","تطوير البرمجيات","دلائل الإعداد","الوكلاء الذكيين"]}},"owner":"akourmaz","repo":"translate2","repoPath":"akourmaz/translate2","stars":0,"forks":0,"updatedAt":"2026-03-02T10:07:05Z","topics":[],"category":"community","skillMd":{"name":"workflow-feature","description":"|","bodyPreview":"# 🚀 Feature Workflow — Добавление Функциональности\n\n<purpose>\nПротокол добавления новой функциональности в существующий проект.\nПрименяется для любой сложности: 🟢 🟡 🔴\n</purpose>\n\n---\n\n## Когда Использовать\n\n**Триггеры:**\n\n- Новая функция/модуль в существующем проекте\n- Расширение существующей функциональности\n- Интеграция с внешним сервисом\n- Добавление API endpoint\n\n**НЕ использовать для:**\n\n- Нового проекта с нуля → `new-project.md`\n- Фикса багов → `debugging.md`\n- Рефакторинга без изменен","body":"# 🚀 Feature Workflow — Добавление Функциональности\n\n<purpose>\nПротокол добавления новой функциональности в существующий проект.\nПрименяется для любой сложности: 🟢 🟡 🔴\n</purpose>\n\n---\n\n## Когда Использовать\n\n**Триггеры:**\n\n- Новая функция/модуль в существующем проекте\n- Расширение существующей функциональности\n- Интеграция с внешним сервисом\n- Добавление API endpoint\n\n**НЕ использовать для:**\n\n- Нового проекта с нуля → `new-project.md`\n- Фикса багов → `debugging.md`\n- Рефакторинга без изменения поведения → `refactoring.md`\n- Архитектурных изменений (миграции, масштабирование) → `architecture-change.md`\n\n---\n\n## Фаза 1: Анализ Требований\n\n### Шаг 1.1: Сбор Информации\n\n**Действия:**\n\n1. Уточни у пользователя:\n   - Что именно должна делать функция?\n   - Кто будет использовать? (роли, permissions)\n   - Какие входы/выходы?\n   - Есть ли edge cases?\n\n2. Проверь существующий контекст:\n   - `/docs/Requirements.md` — есть ли связанные требования?\n   - `/docs/Architecture.md` — какие модули затронуты?\n   - `/docs/Rules.md` — какие ограничения?\n\n**Выход:** Понимание scope + список уточняющих вопросов (если есть).\n\n### Шаг 1.2: Оценка Сложности\n\n| Критерий | 🟢 Simple | 🟡 Medium | 🔴 Complex |\n|----------|-----------|-----------|------------|\n| Файлы | 1-2 файла | 3-5 файлов | >5 файлов |\n| Модули | Один модуль | Несколько модулей | Cross-cutting |\n| БД | Нет изменений | Новые поля | Новые таблицы / миграции |\n| API | Нет / Minor | Новый endpoint | Публичный API / Breaking |\n| Auth | Нет | Новые права | Новые роли / RBAC изменения |\n| Зависимости | Нет | Новый пакет | Новый сервис / интеграция |\n| Риск | Минимальный | Средний | Высокий / необратимый |\n\n**Правило:** При сомнении выбирай более высокий уровень сложности.\n\n---\n\n## Фаза 2: Маршрутизация по Сложности\n\n### 🟢 Simple Path\n\n**Критерии:**\n\n- ≤2 файла\n- Один модуль\n- Нет изменений БД\n- Нет архитектурных решений\n\n**Протокол:**\n\n```\n1. Анализ → понял scope, нет неясностей\n         ↓\n2. Сформировать промпт для @coder (templates/prompts/coder/implement.md)\n         ↓\n3. Делегировать @coder\n         ↓\n4. Делегировать @reviewer\n         ↓\n5. PASS → обновить /docs/* если нужно → DONE\n   FAIL → анализ → исправление\n```\n\n**Не требуется:** Plan.md, Research.md, STOP-gate.\n\n---\n\n### 🟡 Medium Path\n\n**Критерии:**\n\n- 3-5 файлов ИЛИ\n- Несколько модулей ИЛИ\n- Изменения БД (новые поля) ИЛИ\n- Новый API endpoint\n\n**Протокол:**\n\n```\n1. Анализ → понял scope\n         ↓\n2. Создать /docs/Plan.md\n   - Архитектурное решение\n   - Список файлов + изменения\n   - Порядок выполнения\n   - Acceptance Criteria\n         ↓\n3. 🛑 STOP — запросить утверждение плана\n         ↓\n4. [После утверждения] Сформировать промпт для @coder\n         ↓\n5. Делегировать @coder\n         ↓\n6. Делегировать @reviewer\n         ↓\n7. PASS → обновить /docs/* → DONE\n   FAIL → анализ → исправление\n```\n\n**Требуется:** Plan.md + STOP-gate перед реализацией.\n\n---\n\n### 🔴 Complex Path\n\n**Критерии:**\n>\n- >5 файлов ИЛИ\n- Cross-cutting concerns ИЛИ\n- Новые таблицы / сложные миграции ИЛИ\n- Изменения auth/authz ИЛИ\n- Публичный API / breaking changes ИЛИ\n- Интеграция с новым сервисом\n\n**Протокол:**\n\n```\n1. Анализ → понял scope, выявил unknowns\n         ↓\n2. [Если unknowns] Вызвать @coder-expert для исследования\n         ↓\n3. Создать /docs/Research.md\n   - Анализ текущей архитектуры\n   - Зависимости и ограничения\n   - Риски\n         ↓\n4. Создать /docs/Plan.md\n   - Архитектурное решение + альтернативы\n   - Почему выбран этот подход\n   - Поэтапный план\n   - Rollback strategy\n   - Acceptance Criteria\n         ↓\n5. [Если арх. решение] Создать /docs/adr/ADR-NNN.md\n         ↓\n6. 🛑 STOP — запросить утверждение плана\n         ↓\n7. [После утверждения] Поэтапная реализация:\n   Для каждой фазы:\n   - Промпт для @coder\n   - @reviewer после каждой фазы\n         ↓\n8. PASS all phases → обновить /docs/* → DONE\n   FAIL → анализ → возможно @coder-expert → исправление\n```\n\n**Требуется:** Research.md + Plan.md + ADR (если арх. решение) + STOP-gate.\n\n---\n\n## Фаза 3: Создание Плана\n\n### Структура Plan.md\n\n```markdown\n# Plan: [Название фичи]\n*Created: YYYY-MM-DD*\n\n## Цель\n[Что делаем и зачем]\n\n## Архитектурное Решение\n\n### Подход\n[Описание выбранного решения]\n\n### Альтернативы (🟡🔴)\n| Вариант | Pros | Cons |\n|---------|------|------|\n| A | ... | ... |\n| B | ... | ... |\n\n**Выбор:** Вариант A, потому что [обоснование]\n\n## Изменения\n\n### Файлы\n| Файл | Действие | Описание |\n|------|----------|----------|\n| `path/to/file.ts` | CREATE/MODIFY | Что делаем |\n\n### База Данных (если применимо)\n- Миграция: [описание]\n- Rollback: [как откатить]\n\n## Порядок Выполнения\n1. [Шаг 1]\n2. [Шаг 2]\n3. ...\n\n## Acceptance Criteria\n- [ ] [Критерий 1 — измеримый]\n- [ ] [Критерий 2 — измеримый]\n- [ ] Тесты проходят\n- [ ] @reviewer PASS\n\n## Риски и Ограничения\n| Риск | Митигация |\n|------|-----------|\n| ... | ... |\n\n---\n🛑 **STOP: Требуется утверждение плана перед реализацией**\n```\n\n---\n\n## Фаза 4: Делегирование\n\n### Промпт для @coder\n\nИспользуй шаблон из `prompts/coder/implement.md`:\n\n```markdown\n# Task: [Конкретное название]\n\n## Context\n[Почему важно, как вписывается в систему]\n\n## Scope\n[Точные шаги. Никакой лишней работы.]\n\n## Requirements\n1. [Измеримое требование]\n2. [Измеримое требование]\n\n## Constraints (Что НЕ делать)\n❌ Не расширять scope\n❌ Не менять контракты/зависимости без явного указания\n❌ Не оставлять console.log/debug код\n\n## Acceptance Criteria\n✅ [Тесты проходят]\n✅ [Build/Lint чистые]\n✅ [Конкретный результат]\n\n## Files to Work With\n- `path/to/file` — [что изменить]\n\n## Output Format\nТолько код. Объяснения не нужны.\n```\n\n### После @coder\n\n**ОБЯЗАТЕЛЬНО:** Вызвать @reviewer.\n\n```markdown\n## 🤖 Delegation\n**Agent:** @reviewer\n**Purpose:** Проверить качество реализации [название фичи]\n**Expected Output:** PASS / FAIL с комментариями\n**Input Documents:** /docs/Plan.md, /docs/Rules.md\n🛑 STOP after completion. Return control to @meta-architect.\n```\n\n---\n\n## Фаза 5: Обработка Результатов\n\n### @reviewer PASS\n\n1. Обновить `/docs/*`:\n   - `Architecture.md` — если добавлены модули\n   - `Requirements.md` — если новые требования зафиксированы\n   - `Tasks.md` — отметить задачу выполненной\n\n2. Сообщить пользователю о завершении\n\n### @reviewer FAIL\n\n1. Проанализировать причину:\n   - Ошибка в плане → исправить Plan.md\n   - Ошибка @coder → уточнить промпт, повторить\n   - Сложнее чем ожидалось → пересмотреть 🟢→🟡 или 🟡→🔴\n\n2. Если >2 итерации без прогресса:\n   - STOP → Two Steps Back\n   - Вызвать @coder-expert\n   - Пересмотреть подход\n\n---\n\n## Чеклист Feature Workflow\n\n### Перед Началом\n\n- [ ] Scope понятен (нет неясностей)\n- [ ] Сложность оценена (🟢/🟡/🔴)\n- [ ] Контекст загружен (Architecture.md, Rules.md)\n\n### Для 🟡/🔴\n\n- [ ] Plan.md создан\n- [ ] Альтернативы рассмотрены\n- [ ] STOP-gate пройден (утверждение получено)\n\n### После Реализации\n\n- [ ] @reviewer вызван\n- [ ] PASS получен\n- [ ] `/docs/*` обновлены\n\n---\n\n## Quick Reference\n\n```\nFeature Request\n      ↓\nАнализ scope → Оценка 🟢🟡🔴\n      ↓\n🟢 → @coder → @reviewer → docs → DONE\n🟡 → Plan.md → STOP → @coder → @reviewer → docs → DONE  \n🔴 → Research.md → Plan.md (+ADR) → STOP → phased @coder → @reviewer per phase → docs → DONE\n```\n\n---\n\n**Связанные файлы:**\n\n- `references/feature-spec-template.md` — шаблон спецификации фичи\n- `references/feature-context-snapshot.md` — шаблон контекстного снапшота\n- `references/requirements-template.md` — шаблон требований\n- `.claude/skills/checklist-code-review/SKILL.md` — чеклист ревью\n- `.claude/skills/role-coder-expert/references/ai-failure-modes.md` — если @coder зацикливается\n\n---\n\n**END OF WORKFLOW**\n"},"lastSynced":"2026-03-07T04:08:36.121Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing streamlined project extension capabilities with triggers like new feature/modules and API endpoint additions.","zh":"非常适合需要简化项目扩展功能的开发代理，例如新功能/模块和API端点添加等触发器。","ja":"開発エージェントがプロジェクトの拡張機能を簡素化する必要がある場合に最適です。新しい機能/モジュールやAPIエンドポイントの追加などのトリガーが含まれます。","ko":"개발 에이전트가 프로젝트 확장 기능을 간소화해야 하는 경우에 적합합니다. 새로운 기능/모듈 및 API 엔드포인트 추가와 같은 트리거가 포함됩니다.","es":"Perfecto para Agentes de Desarrollo que necesitan capacidad de extensión de proyectos simplificada con activadores como nuevos recursos/módulos y adiciones de puntos de conexión de API.","fr":"Parfait pour les agents de développement qui ont besoin de capacités d''extension de projet rationalisées avec des déclencheurs tels que de nouvelles fonctionnalités/modules et des ajouts de points de terminaison d''API.","de":"Perfekt für Entwicklungsmittel benötigende Entwicklungsagenten mit gestreamten Projekt-Erweiterungsfunktionen und Auslösern wie neuen Funktionen/Modulen und API-Endpunkt-Erweiterungen.","pt":"Perfeito para Agentes de Desenvolvimento que precisam de capacidades de extensão de projeto otimizadas com gatilhos como novos recursos/módulos e adições de endpoints de API.","ru":"Идеально подходит для агентов разработки, которым требуются оптимизированные возможности расширения проекта с триггерами, такими как новые функции/модули и добавления конечных точек API.","ar":"مثالي لعميل التطوير الذين يحتاجون إلى возможات تمديد المشروع المتسارعة مع مسارات مثل الميزات/الوحدات الجديدة وإضافات نقاط النهاية API."},"recommendation":{"en":"Empowers agents to integrate new functionality into existing projects through comprehensive content analysis, supporting triggers such as new feature or module additions and API endpoint integrations using protocols like API endpoint management.","zh":"通过全面内容分析，赋予代理在现有项目中集成新功能的能力，支持诸如新功能或模块添加和使用API端点管理等协议的API端点集成。","ja":"包括APIエンドポイント管理などのプロトコルを使用した新しい機能またはモジュールの追加やAPIエンドポイントの統合などのトリガーをサポートするための包括的なコンテンツ分析を通じて、エージェントに既存のプロジェクトに新しい機能を統合する能力を付与します。","ko":"포괄적인 콘텐츠 분석을 통해 에이전트에게 기존 프로젝트에 새로운 기능을 통합할 수 있는 능력을 부여하며, 새로운 기능 또는 모듈 추가 및 API 엔드포인트 관리와 같은 프로토콜을 사용하는 API 엔드포인트 통합과 같은 트리거를 지원합니다.","es":"Habilita a los agentes a integrar nueva funcionalidad en proyectos existentes a través de un análisis de contenido integral, que admite activadores como adiciones de nuevas funcionalidades o módulos y integraciones de puntos de conexión de API utilizando protocolos como la gestión de puntos de conexión de API.","fr":"Permet aux agents d''intégrer de nouvelles fonctionnalités dans des projets existants grâce à une analyse de contenu complète, prenant en charge des déclencheurs tels que des ajouts de nouvelles fonctionnalités ou de modules et des intégrations de points de terminaison d''API en utilisant des protocoles tels que la gestion des points de terminaison d''API.","de":"Ermächtigt Agenten, neue Funktionalitäten in bestehende Projekte durch umfassende Inhaltsanalyse zu integrieren, die Auslöser wie neue Funktionalitäten- oder Modulerweiterungen und API-Endpunktintegrationen unter Verwendung von Protokollen wie API-Endpunkverwaltung unterstützt.","pt":"Habilita os agentes a integrar novas funcionalidades em projetos existentes por meio de análise abrangente de conteúdo, apoiando gatilhos como adições de novas funcionalidades ou módulos e integrações de endpoints de API usando protocolos como gerenciamento de endpoints de API.","ru":"Наделяет агентов возможностью интегрировать новые функции в существующие проекты посредством всестороннего анализа контента, поддерживая триггеры, такие как добавления новых функций или модулей и интеграции конечных точек API с использованием протоколов, таких как управление конечными точками API.","ar":"تمكن العملاء من دمج وظائف جديدة في المشاريع الحالية من خلال تحليل المحتوى الشامل، ودعم المسارات مثل إضافات الميزات أو الوحدات وجهاً لجهاً لتنسيق نقاط النهاية API باستخدام بروتوكولات مثل إدارة نقاط النهاية API."},"useCases":{"en":["Automating new feature integration","Extending existing project functionality","Integrating external services through API endpoints"],"zh":["自动化新功能集成","扩展现有项目功能","通过API端点集成外部服务"],"ja":["新機能の統合の自動化","既存のプロジェクト機能の拡張","APIエンドポイントを使用した外部サービスの統合"],"ko":["新的 기능 통합 자동화","기존 프로젝트 기능 확장","API 엔드포인트를 통한 외부 서비스 통합"],"es":["Automatización de la integración de nuevas funcionalidades","Ampliación de la funcionalidad de proyectos existentes","Integración de servicios externos a través de puntos de conexión de API"],"fr":["Automatisation de l''intégration de nouvelles fonctionnalités","Extension de la fonctionnalité de projets existants","Intégration de services externes via des points de terminaison d''API"],"de":["Automatisierung der Integration neuer Funktionen","Erweiterung der Funktionalität bestehender Projekte","Integration externer Dienste über API-Endpunkte"],"pt":["Automatizar a integração de novos recursos","Estender a funcionalidade do projeto existente","Integrar serviços externos por meio de endpoints de API"],"ru":["Автоматизация интеграции новых функций","Расширение функциональности существующих проектов","Интеграция внешних сервисов через конечные точки API"],"ar":["أتمتة دمج الميزات الجديدة","توسيع وظائف المشروع الحالي","دمج الخدمات الخارجية من خلال نقاط النهاية API"]},"limitations":{"en":["Not intended for new project creation","Excludes bug fixing and debugging","Inapplicable for refactoring without functional changes"],"zh":["不适用于新项目创建","排除错误修复和调试","不适用于无功能更改的重构"],"ja":["新規プロジェクトの作成には使用できません","バグの修正やデバッグは除外されます","機能変更がないリファクタリングには適用されません"],"ko":["새로운 프로젝트 생성에는 적합하지 않음","버그 수정 및 디버깅은 제외","기능 변경 없이 리팩토링에는 적용되지 않음"],"es":["No está destinado a la creación de nuevos proyectos","Excluye la corrección y depuración de errores","No es aplicable para la reestructuración sin cambios funcionales"],"fr":["N''est pas destiné à la création de nouveaux projets","Exclut la correction et le débogage","N''est pas applicable pour la réorganisation sans changements fonctionnels"],"de":["Nicht für die Erstellung neuer Projekte vorgesehen","Schließt Fehlerbehebung und Debugging aus","Nicht anwendbar für Refactoring ohne funktionale Änderungen"],"pt":["Não destinado à criação de novos projetos","Exclui a correção de erros e depuração","Inaplicável para refatoração sem alterações funcionais"],"ru":["Не предназначен для создания новых проектов","Исключает исправление ошибок и отладку","Не применим для рефакторинга без функциональных изменений"],"ar":["غير مخصص لإنشاء مشاريع جديدة","استبعاد تصحيح الأخطاء وتصحيح الأخطاء","غير قابل للتطبيق لتحديث البرمجيات بدون تغييرات وظيفية"]},"version":4},"contentHash":"83b078c287235d621d4062d584b10088ec830d33c6440f6d55d5978bc5d05fa2","qualityScore":54}');
