INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('akourmaz/translate2/workflow-feature', 'workflow-feature', 'akourmaz', 'translate2', 'community', 'workflow-feature akourmaz translate2 community The workflow-feature skill enables developers to add new functionality to existing projects. It applies to projects of any complexity, supporting triggers like new feature/modules and API endpoint additions. 工作流特性用于向现有项目添加新功能，包括触发器和用例，适用于任何复杂度的项目 ワークフロー機能は、トリガーとユースケースを含む新しい機能を既存のプロジェクトに追加するために使用されます 워크플로 기능은 트리거와 사용 사례를 포함하여 새로운 기능을 기존 프로젝트에 추가하는 데 사용됩니다 El flujo de trabajo de funcionalidad permite agregar nueva funcionalidad a proyectos existentes de cualquier complejidad Le flux de travail de fonctionnalité permet d''ajouter de nouvelles fonctionnalités aux projets existants de toute complexité Das Workflow-Feature ermöglicht das Hinzufügen neuer Funktionalitäten zu bestehenden Projekten beliebiger Komplexität O fluxo de trabalho de recursos é um protocolo para adicionar novas funcionalidades a projetos existentes Поток работы функций - это протокол добавления новой функциональности в существующие проекты سير عمل ميزة هي بروتوكول لإضافة وظائف جديدة الى المشاريع الحالية how to use workflow-feature workflow-feature protocol adding new functionality to existing projects workflow-feature vs new-project workflow-feature setup guide workflow-feature alternative workflow-feature install what is workflow-feature AIエージェント工作流 工作流特性 添加新功能 扩展现有功能 集成外部服务 添加API端点 项目管理 软件开发 Supports addition of new features/modules to existing projects Enables extension of existing functionality Facilitates integration with external services Allows for addition of API endpoints Provides guidance on when to use and when not to use the workflow-feature protocol workflow-feature is a protocol for adding new functionality to existing projects, applicable to any complexity level.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('c4kar/Kukufi/m365-agents-dotnet', 'community', 'c4kar', 'Kukufi', 'c4kar/Kukufi', 'm365-agents-dotnet', 0, 0, 54, '2026-03-02T14:58:45Z', '2026-03-07T04:08:43.456Z', 'e11ae46abff6bccbae5d8e2a5afb0a70b6121c4914cd258d3da9cc8bd4deb0e1', '{"id":"c4kar/Kukufi/m365-agents-dotnet","name":"m365-agents-dotnet","description":{"en":"The m365-agents-dotnet skill enables developers to build enterprise agents for Microsoft 365, Teams, and Copilot Studio using the Microsoft.Agents SDK. It benefits developers looking to integrate AI agents with Microsoft services.","zh":"m365-agents-dotnet SDK 提供了使用 ASP.NET Core 搭建企业级 AI 代理的能力，实现与 Microsoft 365 和 Teams 的无缝集成","ja":"m365-agents-dotnet SDK は、ASP.NET Core を使用した企業向け AI エージェントの構築と Microsoft 365、Teams との統合を実現します","ko":"m365-agents-dotnet SDK는 ASP.NET Core를 사용하여 엔터프라이즈급 AI 에이전트를 구축하고 Microsoft 365 및 Teams와 통합할 수 있습니다","es":"El SDK de Microsoft.Agents para .NET permite crear agentes empresariales para Microsoft 365, Teams y Copilot Studio con ASP.NET Core","fr":"Le SDK Microsoft.Agents pour .NET permet de créer des agents d''entreprise pour Microsoft 365, Teams et Copilot Studio avec ASP.NET Core","de":"Das Microsoft.Agents-SDK für .NET ermöglicht die Erstellung von Unternehmensagenten für Microsoft 365, Teams und Copilot Studio mit ASP.NET Core","pt":"O m365-agents-dotnet permite o desenvolvimento de agentes empresariais para Microsoft 365, Teams e Copilot Studio com ASP.NET Core e autenticação MSAL","ru":"ИИ Агенты m365-agents-dotnet позволяет разработать предприятские агенты для Microsoft 365, Teams и Copilot Studio с помощью ASP.NET Core и аутентификации MSAL","ar":"م365-وكلاء-dotnet يتيح تطوير وكلاء مؤسسية لمنصة Microsoft 365 و Teams و Copilot Studio باستخدام ASP.NET Core و مصادقة MSAL"},"seo":{"title":{"en":"m365-agents-dotnet: Setup Guide for AI Agents | AI Agent ...","zh":"m365-agents-dotnet 设置指南：使用 ASP.NET Core 搭建企业级 AI 代理","ja":"m365-agents-dotnet のベストプラクティス：AIエージェントの構築と Microsoft 365 の統合","ko":"m365-agents-dotnet 시작 가이드: ASP.NET Core와의 통합을 통한 엔터프라이즈 A...","es":"Guía de configuración de m365-agents-dotnet para desarrol...","fr":"Guide de démarrage rapide pour m365-agents-dotnet","de":"Einrichtungsleitfaden für m365-agents-dotnet-Entwickler","pt":"Guia de Configuração para m365-agents-dotnet: Desenvolvim...","ru":"ИИ Агенты: Настройка m365-agents-dotnet для Microsoft 365","ar":"إعداد م365-وكلاء-dotnet: دليل لتطوير وكلاء الإي أيه"},"description":{"en":"Discover how to build enterprise agents for Microsoft 365 with m365-agents-dotnet. Get started with ASP.NET Core hosting and MSAL-based authentication today!","zh":"了解如何使用 m365-agents-dotnet SDK 构建企业级 AI 代理，并将其集成到 Microsoft 365 和 Teams 中","ja":"Microsoft 365 と Teams に AI エージェントを構築して統合するための m365-agents-dotnet SDK の使い方を学ぶ","ko":"m365-agents-dotnet SDK를 사용하여 엔터프라이즈급 AI 에이전트를 구축하고 Microsoft 365 및 Teams와 통합하는 방법을 알아보세요","es":"Aprende a crear agentes empresariales para Microsoft 365 con el SDK de Microsoft.Agents y ASP.NET Core","fr":"Découvrez comment développer des agents d''entreprise pour Microsoft 365 avec le SDK Microsoft.Agents et ASP.NET Core","de":"Erfahren Sie, wie Sie Unternehmensagenten für Microsoft 365 mit dem Microsoft.Agents-SDK und ASP.NET Core erstellen","pt":"Aprenda a criar agentes empresariais para Microsoft 365, Teams e Copilot Studio com o SDK Microsoft.Agents e ASP.NET Core","ru":"Разработайте предприятские агенты для Microsoft 365, Teams и Copilot Studio с помощью SDK Microsoft.Agents и ASP.NET Core","ar":"تعلم كيفية إنشاء وكلاء مؤسسية لمنصة Microsoft 365 و Teams و Copilot Studio باستخدام SDK Microsoft.Agents و ASP.NET Core"},"definition":{"en":"m365-agents-dotnet is a .NET-based SDK for building enterprise agents with ASP.NET Core hosting, agent routing, and MSAL-based authentication for Microsoft 365, Teams, and Copilot Studio.","zh":"m365-agents-dotnet 是一种使用 ASP.NET Core 搭建企业级 AI 代理的 SDK","ja":"m365-agents-dotnet は、ASP.NET Core を使用した企業向け AI エージェントの構築を可能にする SDK です","ko":"m365-agents-dotnet은 ASP.NET Core를 사용하여 엔터프라이즈급 AI 에이전트를 구축할 수 있는 SDK입니다","es":"m365-agents-dotnet es un SDK para crear agentes empresariales para Microsoft 365 con ASP.NET Core","fr":"m365-agents-dotnet est un SDK pour créer des agents d''entreprise pour Microsoft 365 avec ASP.NET Core","de":"m365-agents-dotnet ist ein SDK für die Erstellung von Unternehmensagenten für Microsoft 365 mit ASP.NET Core","pt":"m365-agents-dotnet é um SDK para desenvolvimento de agentes empresariais para Microsoft 365","ru":"ИИ Агенты m365-agents-dotnet - это SDK для разработки предприятских агентов для Microsoft 365","ar":"م365-وكلاء-dotnet هو SDK لتطوير وكلاء مؤسسية لمنصة Microsoft 365"},"features":{"en":["Builds enterprise agents for Microsoft 365, Teams, and Copilot Studio using the Microsoft.Agents SDK","Utilizes ASP.NET Core hosting for scalable and secure agent deployment","Supports MSAL-based authentication for secure agent authorization","Provides agent routing for efficient communication between agents and services","Requires verification of latest APIs using the microsoft-docs MCP","Depends on specific package versions in NuGet for the Microsoft.Agents.* packages"],"zh":["使用 ASP.NET Core 搭建企业级 AI 代理","实现与 Microsoft 365 和 Teams 的无缝集成","支持 MSAL 基于的认证","提供 agent 路由和 AddAgent API"],"ja":["ASP.NET Core を使用した企業向け AI エージェントの構築","Microsoft 365 と Teams との統合","MSAL ベースの認証のサポート","エージェント ルーティングと AddAgent API の提供"],"ko":["ASP.NET Core를 사용하여 엔터프라이즈급 AI 에이전트를 구축","Microsoft 365 및 Teams와의 통합","MSAL 기반 인증 지원","에이전트 라우팅 및 AddAgent API 제공"],"es":["Creación de agentes empresariales para Microsoft 365","Integración con ASP.NET Core","Autenticación basada en MSAL","Enrutamiento de agentes","Compatibilidad con Microsoft 365, Teams y Copilot Studio"],"fr":["Création d''agents d''entreprise pour Microsoft 365","Intégration avec ASP.NET Core","Authentification basée sur MSAL","Routing des agents","Compatibilité avec Microsoft 365, Teams et Copilot Studio"],"de":["Erstellung von Unternehmensagenten für Microsoft 365","Integration mit ASP.NET Core","Authentifizierung basierend auf MSAL","Agenten-Weiterleitung","Kompatibilität mit Microsoft 365, Teams und Copilot Studio"],"pt":["ASP.NET Core hosting","Agent routing","MSAL-based authentication","Integração com Microsoft 365 e Teams","Desenvolvimento de agentes empresariais","Suporte a NuGet packages"],"ru":["ASP.NET Core хостинг","Маршрутизация агентов","Аутентификация на основе MSAL","Интеграция с Microsoft 365 и Teams","Разработка предприятских агентов","Поддержка NuGet пакетов"],"ar":["استضافة ASP.NET Core","توجيه الوكلاء","مصادقة مبنية على MSAL","التكامل مع منصة Microsoft 365 و Teams","تطوير وكلاء مؤسسية","دعم حزم NuGet"]},"keywords":{"en":["how to use m365-agents-dotnet","what is m365-agents-dotnet","m365-agents-dotnet alternative","m365-agents-dotnet vs Microsoft.Bot.Framework","m365-agents-dotnet install","m365-agents-dotnet setup guide","m365-agents-dotnet asp.net core","m365-agents-dotnet msal authentication","m365-agents-dotnet nuget packages"],"zh":["m365-agents-dotnet","ASP.NET Core","AI 代理","Microsoft 365","Teams","MSAL 认证","agent 路由","AddAgent API"],"ja":["m365-agents-dotnet","ASP.NET Core","AIエージェント","Microsoft 365","Teams","MSAL 認証","エージェント ルーティング","AddAgent API"],"ko":["m365-agents-dotnet","ASP.NET Core","AI 에이전트","Microsoft 365","Teams","MSAL 인증","에이전트 라우팅","AddAgent API"],"es":["m365-agents-dotnet","SDK de Microsoft.Agents","ASP.NET Core","agentes empresariales","Microsoft 365","Teams","Copilot Studio","autenticación MSAL","enrutamiento de agentes"],"fr":["m365-agents-dotnet","SDK Microsoft.Agents","ASP.NET Core","agents d''entreprise","Microsoft 365","Teams","Copilot Studio","authentification MSAL","routing des agents"],"de":["m365-agents-dotnet","Microsoft.Agents-SDK","ASP.NET Core","Unternehmensagenten","Microsoft 365","Teams","Copilot Studio","Authentifizierung MSAL","Agenten-Weiterleitung"],"pt":["m365-agents-dotnet","Desenvolvimento de agentes de IA","Microsoft 365","ASP.NET Core","MSAL","NuGet packages","Agentes empresariais","Microsoft Teams","Copilot Studio"],"ru":["ИИ Агенты m365-agents-dotnet","Разработка агентов ИИ","Microsoft 365","ASP.NET Core","MSAL","NuGet пакеты","Предприятские агенты","Microsoft Teams","Copilot Studio"],"ar":["م365-وكلاء-dotnet","تطوير وكلاء الإي أيه","منصة Microsoft 365","ASP.NET Core","MSAL","حزم NuGet","وكلاء مؤسسية","Microsoft Teams","Copilot Studio"]}},"owner":"c4kar","repo":"Kukufi","repoPath":"c4kar/Kukufi","stars":0,"forks":0,"updatedAt":"2026-03-02T14:58:45Z","topics":[],"category":"community","skillMd":{"name":"m365-agents-dotnet","description":"|","bodyPreview":"# Microsoft 365 Agents SDK (.NET)\n\n## Overview\nBuild enterprise agents for Microsoft 365, Teams, and Copilot Studio using the Microsoft.Agents SDK with ASP.NET Core hosting, agent routing, and MSAL-based authentication.\n\n## Before implementation\n- Use the microsoft-docs MCP to verify the latest APIs for AddAgent, AgentApplication, and authentication options.\n- Confirm package versions in NuGet for the Microsoft.Agents.* packages you plan to use.\n\n## Installation\n\n```bash\ndotnet add package Micro","body":"# Microsoft 365 Agents SDK (.NET)\n\n## Overview\nBuild enterprise agents for Microsoft 365, Teams, and Copilot Studio using the Microsoft.Agents SDK with ASP.NET Core hosting, agent routing, and MSAL-based authentication.\n\n## Before implementation\n- Use the microsoft-docs MCP to verify the latest APIs for AddAgent, AgentApplication, and authentication options.\n- Confirm package versions in NuGet for the Microsoft.Agents.* packages you plan to use.\n\n## Installation\n\n```bash\ndotnet add package Microsoft.Agents.Hosting.AspNetCore\ndotnet add package Microsoft.Agents.Authentication.Msal\ndotnet add package Microsoft.Agents.Storage\ndotnet add package Microsoft.Agents.CopilotStudio.Client\ndotnet add package Microsoft.Identity.Client.Extensions.Msal\n```\n\n## Configuration (appsettings.json)\n\n```json\n{\n  \"TokenValidation\": {\n    \"Enabled\": true,\n    \"Audiences\": [\n      \"{{ClientId}}\"\n    ],\n    \"TenantId\": \"{{TenantId}}\"\n  },\n  \"AgentApplication\": {\n    \"StartTypingTimer\": false,\n    \"RemoveRecipientMention\": false,\n    \"NormalizeMentions\": false\n  },\n  \"Connections\": {\n    \"ServiceConnection\": {\n      \"Settings\": {\n        \"AuthType\": \"ClientSecret\",\n        \"ClientId\": \"{{ClientId}}\",\n        \"ClientSecret\": \"{{ClientSecret}}\",\n        \"AuthorityEndpoint\": \"https://login.microsoftonline.com/{{TenantId}}\",\n        \"Scopes\": [\n          \"https://api.botframework.com/.default\"\n        ]\n      }\n    }\n  },\n  \"ConnectionsMap\": [\n    {\n      \"ServiceUrl\": \"*\",\n      \"Connection\": \"ServiceConnection\"\n    }\n  ],\n  \"CopilotStudioClientSettings\": {\n    \"DirectConnectUrl\": \"\",\n    \"EnvironmentId\": \"\",\n    \"SchemaName\": \"\",\n    \"TenantId\": \"\",\n    \"AppClientId\": \"\",\n    \"AppClientSecret\": \"\"\n  }\n}\n```\n\n## Core Workflow: ASP.NET Core agent host\n\n```csharp\nusing Microsoft.Agents.Builder;\nusing Microsoft.Agents.Hosting.AspNetCore;\nusing Microsoft.Agents.Storage;\nusing Microsoft.AspNetCore.Builder;\nusing Microsoft.AspNetCore.Http;\nusing Microsoft.Extensions.DependencyInjection;\nusing Microsoft.Extensions.Hosting;\n\nvar builder = WebApplication.CreateBuilder(args);\n\nbuilder.Services.AddHttpClient();\nbuilder.AddAgentApplicationOptions();\nbuilder.AddAgent<MyAgent>();\nbuilder.Services.AddSingleton<IStorage, MemoryStorage>();\n\nbuilder.Services.AddControllers();\nbuilder.Services.AddAgentAspNetAuthentication(builder.Configuration);\n\nWebApplication app = builder.Build();\n\napp.UseAuthentication();\napp.UseAuthorization();\n\napp.MapGet(\"/\", () => \"Microsoft Agents SDK Sample\");\n\nvar incomingRoute = app.MapPost(\"/api/messages\",\n    async (HttpRequest request, HttpResponse response, IAgentHttpAdapter adapter, IAgent agent, CancellationToken ct) =>\n    {\n        await adapter.ProcessAsync(request, response, agent, ct);\n    });\n\nif (!app.Environment.IsDevelopment())\n{\n    incomingRoute.RequireAuthorization();\n}\nelse\n{\n    app.Urls.Add(\"http://localhost:3978\");\n}\n\napp.Run();\n```\n\n## AgentApplication routing\n\n```csharp\nusing Microsoft.Agents.Builder;\nusing Microsoft.Agents.Builder.App;\nusing Microsoft.Agents.Builder.State;\nusing Microsoft.Agents.Core.Models;\nusing System;\nusing System.Threading;\nusing System.Threading.Tasks;\n\npublic sealed class MyAgent : AgentApplication\n{\n    public MyAgent(AgentApplicationOptions options) : base(options)\n    {\n        OnConversationUpdate(ConversationUpdateEvents.MembersAdded, WelcomeAsync);\n        OnActivity(ActivityTypes.Message, OnMessageAsync, rank: RouteRank.Last);\n        OnTurnError(OnTurnErrorAsync);\n    }\n\n    private static async Task WelcomeAsync(ITurnContext turnContext, ITurnState turnState, CancellationToken ct)\n    {\n        foreach (ChannelAccount member in turnContext.Activity.MembersAdded)\n        {\n            if (member.Id != turnContext.Activity.Recipient.Id)\n            {\n                await turnContext.SendActivityAsync(\n                    MessageFactory.Text(\"Welcome to the agent.\"),\n                    ct);\n            }\n        }\n    }\n\n    private static async Task OnMessageAsync(ITurnContext turnContext, ITurnState turnState, CancellationToken ct)\n    {\n        await turnContext.SendActivityAsync(\n            MessageFactory.Text($\"You said: {turnContext.Activity.Text}\"),\n            ct);\n    }\n\n    private static async Task OnTurnErrorAsync(\n        ITurnContext turnContext,\n        ITurnState turnState,\n        Exception exception,\n        CancellationToken ct)\n    {\n        await turnState.Conversation.DeleteStateAsync(turnContext, ct);\n\n        var endOfConversation = Activity.CreateEndOfConversationActivity();\n        endOfConversation.Code = EndOfConversationCodes.Error;\n        endOfConversation.Text = exception.Message;\n        await turnContext.SendActivityAsync(endOfConversation, ct);\n    }\n}\n```\n\n## Copilot Studio direct-to-engine client\n\n### DelegatingHandler for token acquisition (interactive flow)\n\n```csharp\nusing System.Net.Http.Headers;\nusing Microsoft.Agents.CopilotStudio.Client;\nusing Microsoft.Identity.Client;\n\ninternal sealed class AddTokenHandler : DelegatingHandler\n{\n    private readonly SampleConnectionSettings _settings;\n\n    public AddTokenHandler(SampleConnectionSettings settings) : base(new HttpClientHandler())\n    {\n        _settings = settings;\n    }\n\n    protected override async Task<HttpResponseMessage> SendAsync(\n        HttpRequestMessage request,\n        CancellationToken cancellationToken)\n    {\n        if (request.Headers.Authorization is null)\n        {\n            string[] scopes = [CopilotClient.ScopeFromSettings(_settings)];\n\n            IPublicClientApplication app = PublicClientApplicationBuilder\n                .Create(_settings.AppClientId)\n                .WithAuthority(AadAuthorityAudience.AzureAdMyOrg)\n                .WithTenantId(_settings.TenantId)\n                .WithRedirectUri(\"http://localhost\")\n                .Build();\n\n            AuthenticationResult authResponse;\n            try\n            {\n                var account = (await app.GetAccountsAsync()).FirstOrDefault();\n                authResponse = await app.AcquireTokenSilent(scopes, account).ExecuteAsync(cancellationToken);\n            }\n            catch (MsalUiRequiredException)\n            {\n                authResponse = await app.AcquireTokenInteractive(scopes).ExecuteAsync(cancellationToken);\n            }\n\n            request.Headers.Authorization = new AuthenticationHeaderValue(\"Bearer\", authResponse.AccessToken);\n        }\n\n        return await base.SendAsync(request, cancellationToken);\n    }\n}\n```\n\n### Console host with CopilotClient\n\n```csharp\nusing Microsoft.Agents.CopilotStudio.Client;\nusing Microsoft.Extensions.DependencyInjection;\nusing Microsoft.Extensions.Hosting;\n\nHostApplicationBuilder builder = Host.CreateApplicationBuilder(args);\n\nvar settings = new SampleConnectionSettings(\n    builder.Configuration.GetSection(\"CopilotStudioClientSettings\"));\n\nbuilder.Services.AddHttpClient(\"mcs\").ConfigurePrimaryHttpMessageHandler(() =>\n{\n    return new AddTokenHandler(settings);\n});\n\nbuilder.Services\n    .AddSingleton(settings)\n    .AddTransient<CopilotClient>(sp =>\n    {\n        var logger = sp.GetRequiredService<ILoggerFactory>().CreateLogger<CopilotClient>();\n        return new CopilotClient(settings, sp.GetRequiredService<IHttpClientFactory>(), logger, \"mcs\");\n    });\n\nIHost host = builder.Build();\nvar client = host.Services.GetRequiredService<CopilotClient>();\n\nawait foreach (var activity in client.StartConversationAsync(emitStartConversationEvent: true))\n{\n    Console.WriteLine(activity.Type);\n}\n\nawait foreach (var activity in client.AskQuestionAsync(\"Hello!\", null))\n{\n    Console.WriteLine(activity.Type);\n}\n```\n\n## Best Practices\n\n1. Use AgentApplication subclasses to centralize routing and error handling.\n2. Use MemoryStorage only for development; use persisted storage in production.\n3. Enable TokenValidation in production and require authorization on /api/messages.\n4. Keep auth secrets in configuration providers (Key Vault, managed identity, env vars).\n5. Reuse HttpClient from IHttpClientFactory and cache MSAL tokens.\n6. Prefer async handlers and pass CancellationToken to SDK calls.\n\n## Reference Files\n\n| File | Contents |\n| --- | --- |\n| references/acceptance-criteria.md | Import paths, hosting pipeline, Copilot Studio client patterns, anti-patterns |\n\n## Reference Links\n\n| Resource | URL |\n| --- | --- |\n| Microsoft 365 Agents SDK | https://learn.microsoft.com/en-us/microsoft-365/agents-sdk/ |\n| AddAgent API | https://learn.microsoft.com/en-us/dotnet/api/microsoft.agents.hosting.aspnetcore.servicecollectionextensions.addagent?view=m365-agents-sdk |\n| AgentApplication API | https://learn.microsoft.com/en-us/dotnet/api/microsoft.agents.builder.app.agentapplication?view=m365-agents-sdk |\n| Auth configuration options | https://learn.microsoft.com/en-us/microsoft-365/agents-sdk/microsoft-authentication-library-configuration-options |\n| Copilot Studio integration | https://learn.microsoft.com/en-us/microsoft-365/agents-sdk/integrate-with-mcs |\n| GitHub samples | https://github.com/microsoft/agents |\n\n## When to Use\nThis skill is applicable to execute the workflow or actions described in the overview.\n"},"lastSynced":"2026-03-07T04:08:43.456Z","agentAnalysis":{"suitability":{"en":"Perfect for Microsoft 365 Agents needing integrated enterprise functionality with ASP.NET Core hosting and MSAL-based authentication.","zh":"非常适合需要集成企业功能的Microsoft 365 Agents，支持ASP.NET Core托管和MSAL基于的身份验证。","ja":"Microsoft 365エージェントが統合されたエンタープライズ機能を必要とする場合に最適です。ASP.NET CoreホスティングとMSALベースの認証が可能です。","ko":"통합된 엔터프라이즈 기능이 필요한 Microsoft 365 에이전트에 적합합니다. ASP.NET Core 호스팅 및 MSAL 기반 인증을 지원합니다.","es":"Perfecto para agentes de Microsoft 365 que necesitan funcionalidad empresarial integrada con hosting de ASP.NET Core y autenticación basada en MSAL.","fr":"Parfait pour les agents Microsoft 365 qui nécessitent une fonctionnalité d''entreprise intégrée avec un hébergement ASP.NET Core et une authentification basée sur MSAL.","de":"Perfekt für Microsoft 365-Agenten, die integrierte Unternehmensfunktionen mit ASP.NET Core-Hosting und MSAL-basierter Authentifizierung benötigen.","pt":"Perfeito para Agents do Microsoft 365 que necessitam de funcionalidade empresarial integrada com hospedagem do ASP.NET Core e autenticação baseada no MSAL.","ru":"Идеально подходит для агентов Microsoft 365, которым требуется интегрированная функциональность предприятия с размещением в ASP.NET Core и аутентификацией на основе MSAL.","ar":"مثالي لعميل Microsoft 365 الذين يحتاجون إلى وظائف مؤسسية متكاملة مع استضافة ASP.NET Core وتأكيدي هوية باستخدام MSAL."},"recommendation":{"en":"Empowers agents to build comprehensive Microsoft 365, Teams, and Copilot Studio integrations using the Microsoft.Agents SDK, complete with agent routing and secure authentication via MSAL, leveraging NuGet packages like Microsoft.Agents.","zh":"赋予代理构建全面的Microsoft 365、Teams和Copilot Studio集成，使用Microsoft.Agents SDK，包括代理路由和通过MSAL的安全身份验证，利用NuGet包如Microsoft.Agents。","ja":"エージェントはMicrosoft.Agents SDKを使用して、Microsoft 365、Teams、およびCopilot Studioの包括的な統合を構築できます。エージェント ルーティングとMSALによるセキュアな認証を含み、NuGetパッケージのMicrosoft.Agentsを利用します。","ko":"에이전트가 Microsoft.Agents SDK를 사용하여 Microsoft 365, Teams 및 Copilot Studio의 포괄적인 통합을 구축할 수 있도록 합니다. 에이전트 라우팅 및 MSAL을 통한 보안 인증을 포함하며, NuGet 패키지인 Microsoft.Agents를 활용합니다.","es":"Habilita a los agentes a crear integraciones de Microsoft 365, Teams y Copilot Studio completas utilizando el SDK de Microsoft.Agents, completo con enrutamiento de agentes y autenticación segura a través de MSAL, aprovechando paquetes NuGet como Microsoft.Agents.","fr":"Permet aux agents de créer des intégrations de Microsoft 365, Teams et Copilot Studio complètes en utilisant le SDK Microsoft.Agents, complet avec un routage d''agents et une authentification sécurisée via MSAL, en exploitant des packages NuGet comme Microsoft.Agents.","de":"Ermächtigt Agenten, umfassende Microsoft 365-, Teams- und Copilot Studio-Integrationen mithilfe des Microsoft.Agents-SDK zu erstellen, komplett mit Agenten-Weiterleitung und sicherer Authentifizierung über MSAL, unter Nutzung von NuGet-Paketen wie Microsoft.Agents.","pt":"Habilita os agentes a construir integrações abrangentes do Microsoft 365, Teams e Copilot Studio usando o SDK do Microsoft.Agents, completo com roteamento de agentes e autenticação segura via MSAL, aproveitando pacotes NuGet como o Microsoft.Agents.","ru":"Позволяет агентам создавать комплексные интеграции с Microsoft 365, Teams и Copilot Studio с помощью SDK Microsoft.Agents, включая маршрутизацию агентов и безопасную аутентификацию через MSAL, используя пакеты NuGet, такие как Microsoft.Agents.","ar":"يمكن للعميل بناء تكاملات شاملة لـ Microsoft 365 و Teams و Copilot Studio باستخدام SDK Microsoft.Agents، مع توجيه عميل وتأكيدي هوية آمن عبر MSAL، واستخدام حزم NuGet مثل Microsoft.Agents."},"useCases":{"en":["Building enterprise agents for Microsoft 365 and Teams","Implementing ASP.NET Core hosting for agent applications","Authenticating agents with MSAL for secure Microsoft services integration"],"zh":["为Microsoft 365和Teams构建企业代理","为代理应用程序实现ASP.NET Core托管","使用MSAL对代理进行身份验证以实现安全的Microsoft服务集成"],"ja":["Microsoft 365とTeams用のエンタープライズ エージェントを構築する","エージェント アプリケーション用のASP.NET Coreホスティングを実装する","MSALを使用してエージェントを認証し、セキュアなMicrosoftサービス統合を実現する"],"ko":["Microsoft 365 및 Teams를 위한 엔터프라이즈 에이전트 구축","에이전트 애플리케이션을 위한 ASP.NET Core 호스팅 구현","MSAL을 사용하여 에이전트를 인증하고 보안 Microsoft 서비스 통합을 구현"],"es":["Creación de agentes empresariales para Microsoft 365 y Teams","Implementación de hosting de ASP.NET Core para aplicaciones de agentes","Autenticación de agentes con MSAL para una integración segura de servicios de Microsoft"],"fr":["Création d''agents d''entreprise pour Microsoft 365 et Teams","Mise en œuvre d''un hébergement ASP.NET Core pour des applications d''agents","Authentification d''agents avec MSAL pour une intégration sécurisée des services Microsoft"],"de":["Erstellung von Unternehmensagenten für Microsoft 365 und Teams","Implementierung von ASP.NET Core-Hosting für Agentenanwendungen","Authentifizierung von Agenten mit MSAL für eine sichere Integration von Microsoft-Diensten"],"pt":["Construir agentes empresariais para Microsoft 365 e Teams","Implementar hospedagem do ASP.NET Core para aplicações de agentes","Autenticar agentes com MSAL para integração segura de serviços do Microsoft"],"ru":["Создание агентов предприятия для Microsoft 365 и Teams","Реализация размещения в ASP.NET Core для приложений агентов","Аутентификация агентов с помощью MSAL для безопасной интеграции с сервисами Microsoft"],"ar":["بناء عملاء مؤسسي لـ Microsoft 365 و Teams","تنفيذ استضافة ASP.NET Core لتطبيقات العملاء","تأكيدي هوية العملاء باستخدام MSAL لدمج خدمات Microsoft آمن"]},"limitations":{"en":["Requires Microsoft 365 and Teams setup","Dependent on Microsoft.Agents SDK and NuGet package versions","ASP.NET Core hosting required"],"zh":["需要Microsoft 365和Teams设置","依赖于Microsoft.Agents SDK和NuGet包版本","需要ASP.NET Core托管"],"ja":["Microsoft 365とTeamsの設定が必要","Microsoft.Agents SDKおよびNuGetパッケージのバージョンに依存","ASP.NET Coreホスティングが必要"],"ko":["Microsoft 365 및 Teams 설정이 필요","Microsoft.Agents SDK 및 NuGet 패키지 버전에 따라 달라짐","ASP.NET Core 호스팅이 필요"],"es":["Requiere configuración de Microsoft 365 y Teams","Dependiente de las versiones del SDK y del paquete NuGet de Microsoft.Agents","Se requiere hosting de ASP.NET Core"],"fr":["Nécessite une configuration de Microsoft 365 et Teams","Dépendante des versions du SDK et du package NuGet de Microsoft.Agents","Hébergement ASP.NET Core requis"],"de":["Erfordert Microsoft 365- und Teams-Setup","Abhängig von den Versionen des Microsoft.Agents-SDK und des NuGet-Pakets","ASP.NET Core-Hosting erforderlich"],"pt":["Requer configuração do Microsoft 365 e Teams","Dependente das versões do SDK e pacote NuGet do Microsoft.Agents","Hospedagem do ASP.NET Core necessária"],"ru":["Требуется настройка Microsoft 365 и Teams","Зависит от версий SDK и пакета NuGet Microsoft.Agents","Требуется размещение в ASP.NET Core"],"ar":["يتطلب إعداد Microsoft 365 و Teams","يعتمد على إصدارات SDK و حزمة NuGet من Microsoft.Agents","استضافة ASP.NET Core ضرورية"]},"version":4},"contentHash":"e11ae46abff6bccbae5d8e2a5afb0a70b6121c4914cd258d3da9cc8bd4deb0e1","qualityScore":54}');
